// ── Admin PIN — admin o'zi Sozlamalar orqali o'zgartirishi mumkin (4-10 raqam) ──
// Tezkor tekshiruv uchun qurilmada (localStorage) saqlanadi, bulutga ham (S.settings.appPin) yoziladi
function getAppPin() {
  return localStorage.getItem('koma_admin_pin') || '';
}
function fwPinValid(p) { return typeof p === 'string' && p.length >= 4 && p.length <= 10; }
function syncAppPinFromCloud() {
  if (S.settings && S.settings.appPin && S.settings.appPin !== localStorage.getItem('koma_admin_pin')) {
    localStorage.setItem('koma_admin_pin', S.settings.appPin);
  }
}

// ── Filial parollari (Baza / 729) — har biri mustaqil; standart parol yo'q (birinchi kirishda o'rnatiladi) ──
// Filiallar endi DINAMIK va CHEKSIZ: Baza va 729-filial standart bo'lib qoladi (o'zgarmaydi),
// admin "Sozlamalar"dan istalgancha yangi filial qo'sha oladi. Yangi qo'shilgan
// filiallar ro'yxati S.settings.extraBranches (bulutda) + localStorage'da keshlanadi, shu bilan
// login/PIN ekranlari ma'lumot yuklanishidan OLDIN ham to'g'ri filial ro'yxatini biladi.
const BRANCHES = { baza: { name:'Baza', icon:'🏢' }, f729: { name:'729-filial', icon:'🏬' } };
function loadExtraBranchesCache() {
  try { return JSON.parse(localStorage.getItem('bp_extra_branches')||'[]'); } catch(e) { return []; }
}
function rebuildBranches(list) {
  // avval faqat standart 2 tasini qoldirib, qolganini tozalaymiz
  Object.keys(BRANCHES).forEach(k=>{ if (k!=='baza' && k!=='f729') delete BRANCHES[k]; });
  (list||[]).forEach(b=>{ if (b && b.key) BRANCHES[b.key] = { name:b.name||b.key, icon:b.icon||'🏪' }; });
}
rebuildBranches(loadExtraBranchesCache()); // sahifa ochilganda darhol (bulutdan oldin) to'g'ri ro'yxat bo'lishi uchun
function syncExtraBranchesFromCloud() {
  const list = (S.settings && S.settings.extraBranches) || [];
  localStorage.setItem('bp_extra_branches', JSON.stringify(list));
  rebuildBranches(list);
}
function addBranch(name) {
  name = (name||'').trim();
  if (!name) { toast("Filial nomini kiriting!",'error'); return false; }
  const extra = (S.settings.extraBranches || []).slice();
  // Cheksiz filial: miqdor cheklovi yo'q — faqat mantiqiy nom talab qilinadi
  if (!S.settings.branchCounter) S.settings.branchCounter = 1;
  const key = 'f' + (++S.settings.branchCounter + 700);
  extra.push({ key, name, icon:'🏪' });
  S.settings.extraBranches = extra;
  syncExtraBranchesFromCloud();
  if (!S._store[key]) S._store[key] = _emptyBranchDefaults();
  if (!S.branchDebt) S.branchDebt = {};
  if (S.branchDebt[key]===undefined) S.branchDebt[key] = 0;
  save();
  auditLog(`🏪 Yangi filial qo'shildi: ${name}`);
  toast(`✅ "${name}" filiali qo'shildi!`);
  return key;
}

// ── Filial FAOL/NOFAOL holati — filial HECH QACHON o'chirilmaydi, faqat faolligi o'zgaradi ──
function isBranchActive(key) {
  if (!S.settings || !S.settings.branchActive) return true; // sozlanmagan bo'lsa — standart holat: faol
  const v = S.settings.branchActive[key];
  return v === undefined ? true : !!v;
}
function setBranchActive(key, active) {
  if (key==='baza' && !active) { toast("Bazani nofaol qilib bo'lmaydi — bu asosiy filial.", 'error'); return; }
  if (!S.settings.branchActive) S.settings.branchActive = {};
  S.settings.branchActive[key] = active;
  save();
  auditLog(`Filial ${active?'faollashtirildi':'nofaol qilindi'}: ${branchName(key)}`);
  toast(active ? `✅ "${branchName(key)}" faollashtirildi` : `⏸ "${branchName(key)}" nofaol qilindi (ma'lumotlari saqlanadi)`);
}
function confirmDeactivateBranch(key) {
  if (!confirm(`"${branchName(key)}" filialini nofaol qilasizmi? Ma'lumotlari saqlanib qoladi, faqat login/tanlov ro'yxatidan chiqadi. Istalgan vaqt qayta faollashtirish mumkin.`)) return;
  setBranchActive(key, false);
  openBranchSwitch();
  if (S.page==='sozlamalar') pgSozlamalar();
}
function reactivateBranch(key) {
  setBranchActive(key, true);
  openBranchSwitch();
  if (S.page==='sozlamalar') pgSozlamalar();
}

function getBranchPin(key) {
  return (S.settings && S.settings.branchPin && S.settings.branchPin[key]) || '';
}
// Kirish ekrani ma'lumot yuklanishidan OLDIN ishlashi kerak, shuning uchun
// filial parollari ham appPin kabi localStorage'da keshlanadi.
function getBranchPinCached(key) {
  return localStorage.getItem('bp_branch_pin_'+key) || '';
}
// Kirish ekranida (ma'lumot yuklanishidan oldin) o'rnatilgan yangi parol — yuklangach bulutga yoziladi
function fwSetPendingBranchPin(key, pin) {
  let m = {}; try { m = JSON.parse(sessionStorage.getItem('bp_pin_pending') || '{}') || {}; } catch (_) { m = {}; }
  m[key] = pin; sessionStorage.setItem('bp_pin_pending', JSON.stringify(m));
}
function fwApplyPendingBranchPins() {
  let m = {}; try { m = JSON.parse(sessionStorage.getItem('bp_pin_pending') || '{}') || {}; } catch (_) { m = {}; }
  const keys = Object.keys(m).filter(k => fwPinValid(m[k]));
  if (!keys.length) return false;
  if (!S.settings) S.settings = {};
  if (!S.settings.branchPin) S.settings.branchPin = {};
  let changed = false;
  keys.forEach(k => { if (!S.settings.branchPin[k]) { S.settings.branchPin[k] = m[k]; changed = true; auditLog(`${branchName(k)} uchun birinchi parol oʻrnatildi`); } });
  sessionStorage.removeItem('bp_pin_pending');
  return changed;
}
// Filial NOMI — sozlanadigan (standart nomdan farqli bo'lishi mumkin)
// v23.6: egasining yopiq kassasi (type='qobiljon') — doim shu nom (Bosh kassa bilan adashmasin)
const QOBILJON_BOX_NAME = 'Shaxsiy kassa';
function branchName(key) {
  const nm = (S.settings && S.settings.branchNames && S.settings.branchNames[key])
    || localStorage.getItem('bp_branch_name_'+key)
    || BRANCHES[key]?.name || key;
  // v10 (J12): filial nomi 30+ joyda HTML ichiga qo'yiladi — HTML/JS uchun xavfli
  // belgilar nomdan olib tashlanadi (oddiy nomlarda ular uchramaydi)
  return String(nm).replace(/[<>"'`&\\]/g, '');
}
function getBranchNameCached(key) {
  return localStorage.getItem('bp_branch_name_'+key) || BRANCHES[key]?.name || key;
}
function renameBranch(key, newName) {
  newName = (newName||'').trim();
  if (!newName) { toast("Nom bo'sh bo'lishi mumkin emas!",'error'); return; }
  if (!S.settings.branchNames) S.settings.branchNames = {};
  S.settings.branchNames[key] = newName;
  localStorage.setItem('bp_branch_name_'+key, newName); // shu qurilmada darhol yangilanadi
  save();
  auditLog(`Filial nomi oʻzgartirildi: ${key} → ${newName}`);
  toast('✅ Nom yangilandi!');
  renderBranchBadge();
  openBranchSwitch();
}
function syncBranchNamesFromCloud() {
  Object.keys(BRANCHES).forEach(key=>{
    const n = S.settings && S.settings.branchNames && S.settings.branchNames[key];
    if (n) localStorage.setItem('bp_branch_name_'+key, n);
  });
}
function syncBranchPinsFromCloud() {
  Object.keys(BRANCHES).forEach(key=>{
    const p = S.settings && S.settings.branchPin && S.settings.branchPin[key];
    if (p) localStorage.setItem('bp_branch_pin_'+key, p);
  });
}

// ── Har bir filialga tegishli (mustaqil hisoblanadigan) ma'lumot kalitlari.
//    Diqqat: products/partners/partnerPeriods/settings — UMUMIY (ikkala filial ham bir xil ko'radi).
//    dealers/dealerStock/dealerTxns — bu maydonlar `app_data` blokida hali ham
//    yozib turiladi (orqaga moslik uchun, zarar keltirmaydi), LEKIN haqiqiy,
//    xavfsiz manba EMAS: ular har doim initData() ichida dlLoadDealerData()
//    orqali alohida, filial bo'yicha RLS+requireStaffAuth bilan himoyalangan
//    Supabase jadvallaridan (dealers/dealer_stock/dealer_sales/dealer_payments/
//    dealer_stock_moves — dealer-data-load.js) QAYTA YUKLANADI va USTIGA YOZILADI
//    — shuning uchun filial-xavfsizligi Function darajasida allaqachon TO'LIQ
//    ta'minlangan (P1, docs/ERP_REQUIREMENTS.md). staffList — alohida, RBAC
//    orqali (staff-list.js) filial bilan cheklangan holda yuklanadi. ──
const BRANCH_KEYS = ['batches','batchCounter','sales','customers','suppliers','expenses','dailyClosings','revisions','cashTxns','cashboxes','salaryPeople','shop','writeoffs','branchSettings'];

function _emptyBranchDefaults() {
  return {
    batches:[], batchCounter:0, sales:[], customers:[], suppliers:[], expenses:[],
    dailyClosings:[], revisions:[], cashTxns:[], salaryPeople:[],
    cashboxes: [
      {id:1, name:"Naqd So'm",     icon:'💵', cur:'UZS', type:'cash',   bal:0},
      {id:2, name:'Karta',          icon:'💳', cur:'UZS', type:'card',   bal:0},
      {id:3, name:'Dollar ($)',     icon:'💲', cur:'USD', type:'usd',    bal:0},
      {id:4, name:'Diller kassasi', icon:'🚚', cur:'USD', type:'dealer', bal:0},
      {id:5, name:'Shaxsiy kassa', icon:'🔒', cur:'USD', type:'qobiljon', bal:0},
    ]
  };
}

// Joriy faol filialning ma'lumotlarini S dan olib, oddiy obyekt sifatida qaytaradi
function _snapshotBranch() {
  const out = {};
  BRANCH_KEYS.forEach(k => out[k] = S[k]);
  return out;
}

// Berilgan filial-ma'lumotini S ga (faol holatga) joylaydi — yo'q maydonlar standart bo'sh holat bilan to'ldiriladi
function _applyBranchSnapshot(snap) {
  const def = _emptyBranchDefaults();
  BRANCH_KEYS.forEach(k => { S[k] = (snap && snap[k]!==undefined) ? snap[k] : def[k]; });
  if (typeof fwqMergePending === 'function' && S.branch) S.sales = fwqMergePending(S.sales || [], S.branch);   // v25: oflayn navbatdagi savdolar
}

