let _db = null;
let _cloudEnabled = false;
let _sessionExpiredNotified = false; // "Sessiya tugadi" xabari faqat bir marta chiqishi uchun
// v11 (F4): server kassa qoldiqlarini bazadan beradimi (24-migratsiya qo'llangan) — app-data-load javobidan
let _cashAuthority = false;

function _initCloud() {
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) return;
  try {
    // Sessiya/token boshqaruvini ANIQ ko'rsatamiz (avval sukut bo'yicha edi, endi
    // aniq yozib qo'yildi — kelajakda tasodifan o'zgarib ketmasligi uchun):
    //  - autoRefreshToken: token eskirishidan oldin avtomatik yangilaydi
    //  - persistSession: sessiya localStorage'da saqlanadi (sahifa yangilansa yo'qolmasin)
    //  - detectSessionInUrl: kerak emas (magic link/OAuth ishlatilmaydi)
    _db = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      auth: { autoRefreshToken: true, persistSession: true, detectSessionInUrl: false }
    });
    _cloudEnabled = true;
    console.log('✅ Supabase ulandi');

    // Sessiya holatini KUZATISH — token yangilansa/sessiya tugasa, ilova buni BILADI
    // (avval bu umuman kuzatilmagan, shuning uchun uzoq muddat ochiq turgan sessiyalarda
    // sabab aniqlanmasdan "xato" ko'rinishlar chiqardi).
    _db.auth.onAuthStateChange((event, session) => {
      if (event === 'TOKEN_REFRESHED') {
        console.log('🔄 Sessiya tokeni yangilandi');
        _sessionExpiredNotified = false;
      }
      if (event === 'SIGNED_OUT') {
        // Sessiya haqiqatan ham tugagan (masalan boshqa tab tokenni "aylantirib" yuborgan,
        // yoki refresh token eskirgan). Foydalanuvchi hozir faol ishlayotgan bo'lsa —
        // aniq xabar beramiz, aks holda hech narsa qilmaymiz (login ekranida bo'lishi mumkin).
        if (sessionStorage.getItem('bp_auth_ok') === '1' && !_sessionExpiredNotified) {
          _sessionExpiredNotified = true;
          console.warn('⚠️ Sessiya tugadi — qayta kirish talab qilinadi');
          try { toast("⚠️ Sessiyangiz tugadi. Iltimos, qayta kiring.", 'warning'); } catch(e) {}
        }
      }
    });

    // MUHIM (audit, 2026-08-12): avval bu yerda `app_data` jadvaliga Postgres
    // Realtime orqali to'g'ridan-to'g'ri obuna bo'lingan edi ("boshqa qurilma
    // o'zgartirsa, avtomatik yangilanadi"). Lekin RLS xavfsizlik-migratsiyasidan
    // (P1, migratsiya 22) keyin bu jadval endi FAQAT `service_role`ga ochiq —
    // anon/authenticated klient (shu yerdagi _db) bu jadvalni umuman o'qiy
    // olmaydi. Shuning uchun bu Realtime obunasi HECH QACHON muvaffaqiyatli
    // bo'lolmaydi — brauzer konsolidagi "WebSocket connection failed" xatosi
    // aynan shundan (vaqtinchalik tarmoq nosozligi emas, doimiy, kutilgan holat).
    //
    // Yechim: RLS'ni ochish — XAVFSIZLIKKA QAYTISH bo'lardi, shuning uchun BU
    // QILINMAYDI. Buning o'rniga — ishlamaydigan urinish olib tashlandi.
    // Ko'p-qurilmali sinxronizatsiya — allaqachon har bir saqlash (`save()`)
    // va sahifa yuklanishida (`initData()`) Function orqali ishlaydi, faqat
    // "kutilmasdan, avtomatik" yangilanish endi yo'q (foydalanuvchi sahifani
    // yangilasa yoki keyingi saqlashda yangi holatni ko'radi).
  } catch(e) { console.warn('Supabase ulashilmadi:', e); }
}

// ── #2: "YUGURIB TURUVCHI" RAQAMLAR (kassa balansi, sotilgan miqdor, qarzlar) ──
// Bular sof qo'shish/ayirish orqali o'zgaradi, shuning uchun ID-birlashtirish yetarli emas.
// Yechim: har sessiya boshida "boshlang'ich nuqta" (baseline) saqlanadi, saqlashda
// "men shu sessiyada qancha o'zgartirdim" (delta) hisoblanadi va bulutdagi eng so'nggi
// qiymatga QO'SHILADI — shu bilan ikkala qurilmaning ta'siri ham yo'qolmaydi.
function _numericBaselineSnapshot() {
  const branchNums = {};
  Object.keys(S._store).forEach(bk=>{
    const st = (bk===S.branch) ? _snapshotBranch() : (S._store[bk]||{});
    branchNums[bk] = {
      cashboxes: Object.fromEntries((st.cashboxes||[]).map(b=>[b.id, b.bal||0])),
      batches:   Object.fromEntries((st.batches||[]).map(b=>[b.id, b.sold||0])),
      customers: Object.fromEntries((st.customers||[]).map(c=>[c.id, c.debt||0])),
      suppliers: Object.fromEntries((st.suppliers||[]).map(s=>[s.id, s.debt||0])),
    };
  });
  return {
    branch: branchNums,
    branchDebt: { ...(S.branchDebt||{}) },
    dealers: Object.fromEntries((S.dealers||[]).map(d=>[d.id, d.debt||0])),
    dealerStock: Object.fromEntries((S.dealerStock||[]).map(r=>[r.id, r.qty||0])),
    // 2026-09-28: hamkor hisobi (invested) ham "yugurib turuvchi" raqam — oylik
    // taqsimot, bekor qilish va hamkor xarajati uni o'zgartiradi. Avval eski
    // qurilma saqlaganda bu qiymat eski holatiga qaytib qolardi.
    partners: Object.fromEntries((S.partners||[]).map(p=>[p.id, p.invested||0])),
  };
}
// oldMap/newMap: {id: number} — faqat o'zgargan (yoki yangi) kalitlar uchun farq qaytaradi
function _deltaMap(oldMap, newMap) {
  const out = {};
  Object.keys(newMap||{}).forEach(k=>{
    const d = (newMap[k]||0) - (oldMap?.[k]||0);
    if (d !== 0) out[k] = d;
  });
  return out;
}
function _applyDelta(baseMap, deltaMap) {
  const out = { ...(baseMap||{}) };
  Object.keys(deltaMap||{}).forEach(k=>{ out[k] = (out[k]||0) + deltaMap[k]; });
  return out;
}

// ── Server rad etgan (ruxsatsiz) o'zgarishlar — 2026-09-28 ──
// Server ruxsat bo'lmagan kalitni YOZMAYDI va o'zidagi haqiqiy qiymatni
// qaytaradi. Klient o'z nusxasini shu bilan tuzatadi — aks holda ekranda
// "saqlangan" ko'rinib, keyin yo'qolib qolardi va har saqlashda ogohlantirardi.
const _shownSaveWarnings = new Set();
function _applyServerCorrections(r, branchValues) {
  if (!r || typeof r !== 'object') return;
  const top = r.serverValues || {};
  Object.keys(top).forEach(k => { if (k !== 'branchStore' && k !== 'activeBranch') S[k] = top[k]; });
  const bv = branchValues || {};
  Object.keys(bv).forEach(k => {
    S[k] = bv[k];
    if (S._store && S._store[S.branch]) S._store[S.branch][k] = bv[k];
  });
  const blocked = [...(r.ignoredKeys||[]), ...(r.blockedMassDelete||[])];
  if (blocked.length) {
    console.warn('Server quyidagi o\'zgarishlarni saqlamadi (ruxsat yo\'q yoki ommaviy o\'chirish):', blocked);
    const msg = (r.blockedMassDelete||[]).length
      ? "⛔ Ko'p yozuvni birdaniga o'chirish faqat administratorga ruxsat etilgan: " + r.blockedMassDelete.join(', ')
      : "⚠️ Ba'zi o'zgarishlar saqlanmadi — bu bo'lim uchun ruxsatingiz yo'q: " + (r.ignoredKeys||[]).join(', ');
    if (!_shownSaveWarnings.has(msg)) { _shownSaveWarnings.add(msg); toast(msg, 'warning'); }
  }
}

// v24.8 (37): serverdagi versiyalar (app_data va filial qatorlari) — saqlashda yuboriladi; eskirgan bo'lsa server 409 beradi
let _fwVer = { main: null, branches: {} };
async function _cloudSave(payload) {
  if (!_cloudEnabled || !_db) return;
  const cashSeq0 = fwCashSeq;
  const ledgerSeq0 = fwLedgerSeq;

  // 1-USTUVORLIK / 1.3-QADAM: avval yangi, autentifikatsiya bilan himoyalangan
  // Function orqali yozishga urinamiz. Ma'lumot STRUKTURASI o'zgarmaydi — xuddi
  // shu "payload" object, xuddi shu app_data.data ustuniga yoziladi (faqat
  // TASHISH usuli — anon to'g'ridan-to'g'ri so'rov emas, Function orqali).
  let savedViaFunction = false;
  try {
    const res = await authFetch('/.netlify/functions/app-data-save', {
      method: 'POST', body: JSON.stringify({ data: payload, ...(Number.isSafeInteger(_fwVer.main) ? { baseVersion: _fwVer.main } : {}) })
    });
    if (res.status === 409) {
      const cj = await res.clone().json().catch(() => ({}));
      if (cj && cj.code === 'VERSION_CONFLICT') { const err = new Error(cj.error || 'Versiya ziddiyati'); err.fwVersionConflict = true; err.fwSaveStatus = 409; throw err; }
    }
    if (res.ok) {
      savedViaFunction = true;
      // Server ruxsatsiz o'zgarishlarni (masalan huquqi yo'q modul yoki ommaviy
      // o'chirish) yozmaydi — foydalanuvchi buni bilishi kerak.
      const r = await res.json().catch(()=>({}));
      if (r.versions) { if (Number.isSafeInteger(r.versions.main)) _fwVer.main = r.versions.main; Object.assign(_fwVer.branches, r.versions.branches || {}); }
      _applyServerCorrections(r, r.ownBranch === S.branch ? r.serverBranchValues : null);
      // v11 (F4): kassa qoldig'i — bazadagi haqiqiy qiymat (brauzer yuborgani e'tiborga olinmaydi)
      if (r.cashAuthority && r.cashAuthority.on) {
        _cashAuthority = true;
        const own = r.cashAuthority.branches && r.cashAuthority.branches[S.branch];
        if (own) fwApplyServerCashboxes(own, cashSeq0);
      }
      // v23.2 (F4b): qarz va partiya qoldiqlari — bazadagi haqiqiy qiymat
      if (r.ledgerAuthority && r.ledgerAuthority.on) {
        FWL.on = true;
        const lb = r.ledgerAuthority.branches || {};
        if (lb[S.branch]) fwApplyLedgerSnapshot(lb[S.branch], S.branch, ledgerSeq0);
        if (r.ledgerAuthority.branchDebt && ledgerSeq0 === fwLedgerSeq) fwApplyLedger({ filial: S.branch, branchDebt: r.ledgerAuthority.branchDebt });
      }
    } else {
      const errData = await res.json().catch(()=>({}));
      // v24: eski to'g'ridan-to'g'ri yo'l (app_data upsert) 21-migratsiyadan beri anon/authenticated uchun
      // YOPIQ — server javob bergan bo'lsa, unga o'tish faqat «permission denied» beradi va asl sababni
      // yashiradi («Saqlanmadi!»). Shuning uchun faqat funksiya umuman yo'q bo'lsa (404) eski yo'lga o'tamiz,
      // qolgan holatda — serverning haqiqiy (xavfsiz) xabarini foydalanuvchiga ko'rsatamiz.
      if (res.status !== 404) {
        const reason = fwSaveErrorText(res.status, errData.error);
        console.warn(`app-data-save rad etdi (${res.status}):`, errData.error || '');
        const err = new Error(reason); err.fwSaveStatus = res.status; throw err;
      }
      console.warn('app-data-save funksiyasi topilmadi (404) — eski yo\'lga o\'tildi');
    }
  } catch(e) {
    if (e && e.fwSaveStatus) throw e; // server rad etdi — yuqoriga (save()) haqiqiy sabab bilan
    console.warn('app-data-save Function chaqirishda xato — eski yo\'lga o\'tildi:', e);
  }

  // ESKI, to'g'ridan-to'g'ri yo'l — FAQAT Function muvaffaqiyatsiz bo'lsa (zaxira,
  // orqaga moslik). Bu — hozirgi xatti-harakat bilan bir xil, hech narsa buzilmaydi.
  if (!savedViaFunction) {
    try {
      const { error } = await _db.from('app_data').upsert({ id:'main', data:payload, updated_at:new Date().toISOString() });
      if (error) {
        console.error('Cloud saqlash XATOSI:', JSON.stringify(error));
        toast('⚠️ Saqlashda xatolik: '+(error.message||error.hint||'nomalum'), 'error');
        // ikkalasi ham (yangi va eski) muvaffaqiyatsiz — bu haqiqiy xatolikni endi
        // yashirmasdan, chaqiruvchiga (save()) uzatamiz, aks holda foydalanuvchi
        // ma'lumot bulutga yozilmaganini hech qachon bilmay qoladi
        throw new Error('Cloud saqlash xatosi (upsert): '+(error.message||error.hint||'nomalum'));
      }
    } catch(e) {
      console.warn('Cloud saqlash xatosi:', e);
      toast('⚠️ Saqlashda xatolik: '+(e.message||e), 'error');
      throw e; // yuqoriga (save()) uzatamiz — jimgina yo'qolib ketmasin
    }
  }

  // 4b-bosqich / 4-qadam: PARALLEL yozish — eski (yuqorida, ALLAQACHON muvaffaqiyatli
  // yakunlangan) tuzilmaga qo'shimcha ravishda, yangi app_data_branches jadvaliga ham
  // yozamiz va darhol taqqoslaymiz. Bu yerdagi HAR QANDAY xatolik faqat shu funksiya
  // ichida qoladi — asosiy (eski) saqlash allaqachon muvaffaqiyatli, foydalanuvchi
  // hech narsani sezmaydi, ma'lumot yo'qolmaydi.
  _parallelBranchSave(payload).catch(()=>{});
  _batchesShadowSync().catch(()=>{}); // P3-3: yangi batches SQL jadvaliga fon-rejimda parallel sinxronizatsiya (bloklamaydi)
}

// ════════════════════════════════════════════════════════════
// P3-3 — SHADOW-MODE: yangi "batches" SQL jadvaliga fon-rejimda parallel
// sinxronlaydi. Bu — HECH QANDAY mavjud funksiyani (deductFIFO, kirimSave,
// doSaleReturn va h.k.) o'zgartirmaydi — faqat save() muvaffaqiyatli
// yakunlangandan KEYIN, orqa fonda, joriy filialning JORIY S.batches holatini
// yangi jadvalga "moslashtiradi" (upsert). Xato bo'lsa — jimgina o'tkazib
// yuboriladi, asosiy saqlashga (app_data) HECH QANDAY ta'sir qilmaydi.
async function _batchesShadowSync() {
  if (!_cloudEnabled || !_db || !S.batches?.length) return;
  if (FWL.on) return;   // v23.2 (F4b): partiya qoldig'i serverda (ombor jurnali) — brauzer nusxasi yuborilmaydi
  const filial = S.branch;
  // Har bir batchni alohida so'rov bilan yubormaslik uchun — faqat OXIRGI
  // saqlashdan beri o'zgargan (yoki hali sinxronlanmagan) batchlarni yuboramiz.
  // Soddalik va xavfsizlik uchun, hozircha barcha faol batchlarni yuboramiz —
  // (shadow-mode uchun bu yetarli, ishlash tezligiga sezilarli ta'sir qilmaydi,
  // chunki fon-rejimda, foydalanuvchini kutishga majbur qilmaydi).
  for (const b of S.batches) {
    try {
      await authFetch('/.netlify/functions/batches-shadow-sync', {
        method: 'POST',
        body: JSON.stringify({
          localId: b.id, filial, pid: b.pid, bno: b.bno, origin: b.origin,
          cur: b.cur, qty: b.qty, sold: b.sold, costUsd: b.costUsd,
          bankFeeUsd: b.bankFeeUsd, suppId: b.suppId, consignment: !!b.consignment,
          rateUsdUzs: b.rates?.usdUzs, rateUsdCny: b.rates?.usdCny,
          date: b.date, status: b.status, performedBy: b.performedBy
        })
      });
    } catch (e) { /* shadow-mode — xato jim o'tkazib yuboriladi, asosiy saqlashga ta'sir qilmaydi */ }
  }
  // Yozishdan keyin — solishtirish (shadow-check). Farq topilsa audit jurnaliga
  // yoziladi (BLOKLAMAYDI, faqat texnik kuzatuv uchun). Har bir save()da emas,
  // 1/10 ehtimol bilan (tasodifiy tanlov) — ortiqcha tarmoq yukini kamaytirish uchun.
  if (Math.random() < 0.1) {
    try {
      const res = await authFetch('/.netlify/functions/batches-shadow-check', {
        method: 'POST',
        body: JSON.stringify({ filial, localBatches: S.batches.map(b=>({id:b.id, qty:b.qty, sold:b.sold, costUsd:b.costUsd})) })
      });
      const result = await res.json();
      if (res.ok && !result.matched) {
        console.warn('🔶 [P3-3 shadow] Farq aniqlandi:', result.diffs);
        auditLog(`⚠️ [Texnik/P3-3] Ombor shadow-tekshiruvida ${result.diffCount} ta farq aniqlandi — batafsili konsolida (F12)`);
      }
    } catch (e) { /* shadow-check ham xatoga chidamli, jim o'tkaziladi */ }
  }
}

async function _parallelBranchSave(payload) {
  if (!_cloudEnabled || !_db) return;
  const branchKey = S.branch;
  const branchData = payload.branchStore ? payload.branchStore[branchKey] : null;
  if (!branchData) return;
  const cashSeq0 = fwCashSeq;
  const ledgerSeq0 = fwLedgerSeq;

  // 1.4.5-QADAM: avval yangi, autentifikatsiya + filial-chegarasi bilan
  // himoyalangan Function orqali urinamiz.
  try {
    const bv = _fwVer.branches[branchKey];
    const res = await authFetch('/.netlify/functions/app-data-branch-save', {
      method:'POST', body: JSON.stringify({ branchKey, data: branchData, ...(Number.isSafeInteger(bv) ? { baseVersion: bv } : {}) })
    });
    // v24.8 (37): filial qatori boshqa yozuv bilan yangilangan — asosiy saqlash (app-data-save) allaqachon yozgan; eski yo'lga o'tilmaydi
    if (res.status === 409) return;
    if (res.ok) {
      const result = await res.json();
      if (Number.isSafeInteger(result.version)) _fwVer.branches[result.branchKey] = result.version;
      _applyServerCorrections({ ignoredKeys: result.ignoredKeys, blockedMassDelete: result.blockedMassDelete }, result.branchKey === S.branch ? result.serverValues : null);
      if (result.cashAuthority && result.cashAuthority.on && result.branchKey === S.branch) { _cashAuthority = true; fwApplyServerCashboxes(result.cashAuthority.cashboxes, cashSeq0); }
      if (result.ledgerAuthority && result.ledgerAuthority.on && result.branchKey === S.branch) { FWL.on = true; fwApplyLedgerSnapshot(result.ledgerAuthority, S.branch, ledgerSeq0); }
      if (!result.matched) {
        console.error(`🔴 [4b/4-qadam] FARQ ANIQLANDI — "${branchKey}" filiali uchun yangi va eski tuzilma MOS KELMADI.`);
        auditLog(`⚠️ [Texnik] Migratsiya nomosligi qayd etildi: "${branchName(branchKey)}" — batafsili brauzer konsolida (F12)`);
      } else {
        console.log(`✅ [4b/4-qadam] "${branchKey}" — yangi va eski tuzilma mos keldi`);
      }
      return; // muvaffaqiyatli — eski to'g'ridan-to'g'ri yo'lga o'tilmaydi
    }
    console.warn(`app-data-branch-save Function xato qaytardi (${res.status}) — eski yo'lga o'tildi`);
  } catch(e) {
    console.warn('app-data-branch-save Function chaqirishda xato — eski yo\'lga o\'tildi:', e);
  }

  // ESKI, to'g'ridan-to'g'ri yo'l — FAQAT Function muvaffaqiyatsiz bo'lsa (zaxira)
  try {
    const { error: upErr } = await _db.from('app_data_branches').upsert({
      branch_key: branchKey, data: branchData, updated_at: new Date().toISOString()
    }, { onConflict: 'branch_key' });
    if (upErr) {
      console.error(`⚠️ [4b/4-qadam] "${branchKey}" — yangi tuzilmaga yozishda xatolik (eski tizim ta'sirlanmadi):`, JSON.stringify(upErr));
      return;
    }
    const { data: check, error: checkErr } = await _db.from('app_data_branches').select('data').eq('branch_key', branchKey).maybeSingle();
    if (checkErr) {
      console.error(`⚠️ [4b/4-qadam] "${branchKey}" — taqqoslash uchun qayta o'qib bo'lmadi:`, JSON.stringify(checkErr));
      return;
    }
    const matched = JSON.stringify(check?.data) === JSON.stringify(branchData);
    if (!matched) {
      console.error(`🔴 [4b/4-qadam] FARQ ANIQLANDI — "${branchKey}" filiali uchun yangi va eski tuzilma MOS KELMADI. Eski tizim (app_data) — asosiy manba bo'lib davom etmoqda.`, { yozmoqchi_boldik: branchData, yangi_jadvalda_bor: check?.data });
      auditLog(`⚠️ [Texnik] Migratsiya nomosligi qayd etildi: "${branchName(branchKey)}" — batafsili brauzer konsolida (F12)`);
    } else {
      console.log(`✅ [4b/4-qadam] "${branchKey}" — yangi va eski tuzilma mos keldi`);
    }
  } catch(e) {
    console.error(`⚠️ [4b/4-qadam] "${branchKey}" — parallel saqlashda kutilmagan xatolik (eski tizim ta'sirlanmadi):`, e);
  }
}

// ── XAVFSIZ SAQLASH — bir necha qurilma/sotuvchi bir vaqtda ishlaganda yozuvlar yo'qolmasin ──
// ID bo'yicha birlashtiradi: bulutdagi eng so'nggi holatni o'qib, mahalliy YANGI yozuvlarni
// ustiga qo'shadi (o'chirmaydi). Diqqat: bu faqat RO'YXAT (sales, customers, batches...) uchun
// ishlaydi — "yugurib turuvchi" raqamlar (kassa balansi, ombor qoldig'i, qarz) hali ham
// eski (oxirgi yozgan g'olib) tarzda ishlaydi, bu alohida bosqichda hal qilinadi.
function mergeById(remoteArr, localArr) {
  remoteArr = Array.isArray(remoteArr) ? remoteArr : [];
  localArr = Array.isArray(localArr) ? localArr : [];
  const map = new Map();
  remoteArr.forEach(x=>{ if (x && x.id!==undefined) map.set(x.id, x); });
  localArr.forEach(x=>{ if (x && x.id!==undefined) map.set(x.id, x); }); // mahalliy versiya ustunlik qiladi (shu qurilmada tahrirlangan bo'lsa)
  return Array.from(map.values());
}

// ── TOMBSTONE — FAQAT FOYDALANUVCHI 🗑 TUGMASINI BOSIB, TASDIQLAB O'CHIRGAN
// yozuvlar shu yerga yoziladi. mergeById() endi shu ro'yxatdagi ID'larni bulutdagi
// eski nusxadan qaytadan qo'shib qo'ymaydi — o'chirish boshqa qurilmada ham, eski
// bulut nusxasidan ham "tirilib" qolmaydi. TASHQI QOIDA: bu yerga yozuv FAQAT aniq
// deleteXxx() funksiyalaridan (foydalanuvchi tasdiqidan keyin) qo'shiladi — hech
// qanday sync/merge/migratsiya jarayoni bu yerga o'zi yozmaydi.
// ── TOMBSTONE — FAQAT FOYDALANUVCHI 🗑 TUGMASINI BOSIB, TASDIQLAB O'CHIRGAN
// yozuvlar shu yerga yoziladi. mergeById() endi shu ro'yxatdagi ID'larni bulutdagi
// eski nusxadan qaytadan qo'shib qo'ymaydi — o'chirish boshqa qurilmada ham, eski
// bulut nusxasidan ham "tirilib" qolmaydi. TASHQI QOIDA: bu yerga yozuv FAQAT aniq
// deleteXxx() funksiyalaridan (foydalanuvchi tasdiqidan keyin) qo'shiladi — hech
// qanday sync/merge/migratsiya jarayoni bu yerga o'zi yozmaydi.
function markDeleted(kind, id) {
  if (!S.deletedIds) S.deletedIds = {};
  if (!S.deletedIds[kind]) S.deletedIds[kind] = [];
  if (!S.deletedIds[kind].some(d=>d.id===id)) {
    S.deletedIds[kind].push({ id, ts: Date.now() });
  }
  // 90 kundan eski tombstone yozuvlarini tozalaymiz (ro'yxat abadiy o'smasligi uchun —
  // bu vaqtga kelib barcha qurilmalar allaqachon sinxronlashgan bo'ladi deb hisoblanadi)
  const cutoff = Date.now() - 90*86400000;
  S.deletedIds[kind] = S.deletedIds[kind].filter(d=>d.ts>=cutoff);
}
function isDeleted(kind, id) {
  return (S.deletedIds?.[kind]||[]).some(d=>d.id===id);
}
// mergeById bilan bir xil, lekin avval "tombstone"dagi (foydalanuvchi tasdiqlab
// o'chirgan) ID'larni HAM bulut nusxasidan, HAM shu qurilmaning o'z (ehtimol eski,
// hali tombstone'ni "bilmagan" sessiyadagi) mahalliy nusxasidan chiqarib tashlaydi.
// `combinedDeleted` — bulut va mahalliy tombstone ro'yxatlarining BIRLASHMASI bo'lishi
// shart (shu save chaqiruvida hisoblanadi) — aks holda: agar shu qurilma A qurilmaning
// o'chirishini hali "bilmasa" (masalan uzoq vaqt tab yopilmagan bo'lsa), o'zining eski,
// hali o'chirilgan-deb-belgilanmagan mahalliy nusxasi o'chirishni bekor qilib qo'yishi mumkin edi.
function mergeByIdSafe(remoteArr, localArr, kind, combinedDeleted) {
  const del = (x) => x && (combinedDeleted?.[kind]||[]).some(d=>d.id===x.id);
  const cleanRemote = (Array.isArray(remoteArr)?remoteArr:[]).filter(x => !del(x));
  const cleanLocal  = (Array.isArray(localArr)?localArr:[]).filter(x => !del(x));
  return mergeById(cleanRemote, cleanLocal);
}
// Ikkala qurilmaning tombstone ro'yxatlarini birlashtiradi (hech qachon kamaymaydi,
// faqat qo'shiladi — bitta qurilmada o'chirilgan narsa boshqasida ham "bilinadi")
function mergeDeletedIds(remoteDeleted, localDeleted) {
  const kinds = new Set([...Object.keys(remoteDeleted||{}), ...Object.keys(localDeleted||{})]);
  const out = {};
  kinds.forEach(k=>{
    const map = new Map();
    (remoteDeleted?.[k]||[]).forEach(d=>{ if(d && d.id!==undefined) map.set(d.id, d); });
    (localDeleted?.[k]||[]).forEach(d=>{ if(d && d.id!==undefined) map.set(d.id, d); });
    out[k] = Array.from(map.values());
  });
  return out;
}

// v24.8 (37): versiya ziddiyatida (409) — yangi holatni olib, o'zgarishlarimizni ID bo'yicha ustiga qo'yib qayta saqlaymiz
// (3 martagacha). Qoldiq/qarz kabi sonlar — serverda (bazadan), shuning uchun qayta urinishda ikki marta qo'shilmaydi.
async function _safeCloudSave(payload) {
  for (let attempt = 0; ; attempt++) {
    try { return await _safeCloudSaveOnce(payload); }
    catch (e) {
      if (!(e && e.fwVersionConflict) || attempt >= 3) throw e;
      S._store[S.branch] = _snapshotBranch();
      payload = { ...payload, products: S.products, partners: S.partners, partnerPeriods: S.partnerPeriods, settings: S.settings, auditLogs: S.auditLogs,
        branchStore: S._store, branchDebt: S.branchDebt, deletedIds: S.deletedIds };
    }
  }
}
async function _safeCloudSaveOnce(payload) {
  if (!_cloudEnabled || !_db) return;
  let merged = payload;
  try {
    const remote = await _cloudLoad();
    if (remote) {
      // Bulut va shu qurilmaning tombstone ro'yxatlarini ENG AVVAL birlashtiramiz —
      // shu birlashgan ro'yxat butun merge davomida ishlatiladi (shu qurilma hali
      // "bilmagan" boshqa qurilmadagi o'chirishni ham to'g'ri qo'llash uchun)
      const combinedDeleted = mergeDeletedIds(remote.deletedIds, payload.deletedIds);
      const remoteStore = remote.branchStore || {};
      const localBranchSnap = payload.branchStore[S.branch] || {};
      const remoteBranchSnap = remoteStore[S.branch] || {};
      const mergedBranchSnap = { ...remoteBranchSnap };
      // Ro'yxat-shaklidagi maydonlarni ID bo'yicha birlashtiramiz — yangi yozuvlar yo'qolmaydi,
      // lekin foydalanuvchi tasdiqlab o'chirgan ID'lar (tombstone) qaytadan tiklanmaydi
      ['sales','customers','suppliers','expenses','dailyClosings','revisions','cashTxns','salaryPeople','batches','cashboxes','writeoffs']
        .forEach(k => { mergedBranchSnap[k] = mergeByIdSafe(remoteBranchSnap[k], localBranchSnap[k], k, combinedDeleted); });
      // Onlayn-do'kon: buyurtma/sharhlar ID bo'yicha (yangirog'i ustun), sozlamalar — yangirog'i
      if (typeof fwShopMerge === 'function') mergedBranchSnap.shop = fwShopMerge(remoteBranchSnap.shop, localBranchSnap.shop);
      // Sonli hisoblagichlar — eng kattasi olinadi (masalan partiya raqami takrorlanmasligi uchun)
      mergedBranchSnap.batchCounter = Math.max(remoteBranchSnap.batchCounter||0, localBranchSnap.batchCounter||0);

      // ── #2: yugurib turuvchi raqamlar — DELTA orqali birlashtiramiz ──
      // (shu sessiyada MEN qancha o'zgartirdim) + (bulutdagi eng so'nggi qiymat) = to'g'ri jami
      const nowNums = _numericBaselineSnapshot();
      const base = S._syncBaseline || nowNums;
      // Agar shu filial uchun boshlang'ich nuqta hali yo'q bo'lsa (masalan endigina filial almashtirildi) —
      // xavfsiz tomondan xato qilamiz: farqni 0 deb hisoblaymiz (bulutdagi qiymatni ustidan yozib yubormaslik uchun)
      const baseBranch = base.branch[S.branch] || nowNums.branch[S.branch];
      const dCash  = _deltaMap(baseBranch?.cashboxes, nowNums.branch[S.branch]?.cashboxes);
      const dSold  = _deltaMap(baseBranch?.batches,   nowNums.branch[S.branch]?.batches);
      const dCust  = _deltaMap(baseBranch?.customers, nowNums.branch[S.branch]?.customers);
      const dSupp  = _deltaMap(baseBranch?.suppliers, nowNums.branch[S.branch]?.suppliers);
      const dDebt  = _deltaMap(base.branchDebt, nowNums.branchDebt);
      const dDealerDebt  = _deltaMap(base.dealers, nowNums.dealers);
      const dDealerStock = _deltaMap(base.dealerStock, nowNums.dealerStock);

      const remoteCashMap = Object.fromEntries((remoteBranchSnap.cashboxes||[]).map(b=>[b.id,b.bal||0]));
      const remoteSoldMap = Object.fromEntries((remoteBranchSnap.batches||[]).map(b=>[b.id,b.sold||0]));
      const remoteCustMap = Object.fromEntries((remoteBranchSnap.customers||[]).map(c=>[c.id,c.debt||0]));
      const remoteSuppMap = Object.fromEntries((remoteBranchSnap.suppliers||[]).map(s=>[s.id,s.debt||0]));
      const mergedCashMap = _applyDelta(remoteCashMap, dCash);
      const mergedSoldMap = _applyDelta(remoteSoldMap, dSold);
      const mergedCustMap = _applyDelta(remoteCustMap, dCust);
      const mergedSuppMap = _applyDelta(remoteSuppMap, dSupp);
      mergedBranchSnap.cashboxes = (mergedBranchSnap.cashboxes||[]).map(b=>({ ...b, bal: mergedCashMap[b.id]!==undefined?mergedCashMap[b.id]:(b.bal||0) }));
      mergedBranchSnap.batches   = (mergedBranchSnap.batches||[]).map(b=>{
        const sold = mergedSoldMap[b.id]!==undefined?mergedSoldMap[b.id]:(b.sold||0);
        return { ...b, sold, status: (b.qty-sold<=0) ? 'empty' : (b.status==='empty'?'active':b.status) };
      });
      mergedBranchSnap.customers = (mergedBranchSnap.customers||[]).map(c=>({ ...c, debt: mergedCustMap[c.id]!==undefined?mergedCustMap[c.id]:(c.debt||0) }));
      mergedBranchSnap.suppliers = (mergedBranchSnap.suppliers||[]).map(s=>({ ...s, debt: mergedSuppMap[s.id]!==undefined?mergedSuppMap[s.id]:(s.debt||0) }));

      const mergedBranchDebt = _applyDelta(remote.branchDebt, dDebt);
      const mergedDealers = mergeById(remote.dealers, payload.dealers).map(d=>{
        const remD = (remote.dealers||[]).find(x=>x.id===d.id);
        const baseDebt = remD ? (remD.debt||0) : 0;
        return dDealerDebt[d.id]!==undefined ? { ...d, debt: baseDebt + dDealerDebt[d.id] } : d;
      });
      const mergedDealerStock = mergeById(remote.dealerStock, payload.dealerStock).map(r=>{
        const remR = (remote.dealerStock||[]).find(x=>x.id===r.id);
        const baseQty = remR ? (remR.qty||0) : 0;
        return dDealerStock[r.id]!==undefined ? { ...r, qty: baseQty + dDealerStock[r.id] } : r;
      });

      // Hamkorlar: ism/%/ta'sischi belgisi — qaysi nusxa YANGIROQ tahrirlangan
      // bo'lsa (updatedAt) o'sha; hisob (invested) — bulutdagi qiymat + shu
      // qurilmadagi o'zgarish (delta), xuddi kassa balansi kabi.
      const dPartner = _deltaMap(base.partners, nowNums.partners);
      const mergedPartners = mergeByIdSafe(remote.partners, payload.partners, 'partners', combinedDeleted).map(p=>{
        const rem = (remote.partners||[]).find(x=>x.id===p.id);
        const loc = (payload.partners||[]).find(x=>x.id===p.id);
        if (!rem || !loc) return p;
        const newer = (loc.updatedAt===undefined && rem.updatedAt===undefined) || (loc.updatedAt||0) > (rem.updatedAt||0) ? loc : rem;
        return { ...newer, invested: (rem.invested||0) + (dPartner[p.id]||0) };
      });

      merged = {
        ...payload,
        products: mergeByIdSafe(remote.products, payload.products, 'products', combinedDeleted),
        auditLogs: mergeById(remote.auditLogs, payload.auditLogs).sort((a,b)=>new Date(b.ts)-new Date(a.ts)).slice(0,200),
        partners: mergedPartners,
        partnerPeriods: sortPartnerPeriods(mergeByIdSafe(remote.partnerPeriods, payload.partnerPeriods, 'partnerPeriods', combinedDeleted)),
        filialOrders: mergeById(remote.filialOrders, payload.filialOrders),
        dealerRevisions: mergeById(remote.dealerRevisions, payload.dealerRevisions),
        dealers: mergedDealers,
        dealerStock: mergedDealerStock,
        branchDebt: mergedBranchDebt,
        deletedIds: combinedDeleted,
        branchStore: { ...remoteStore, [S.branch]: mergedBranchSnap }
      };

      // Shu qurilmaning o'z holatini ham yangilangan (haqiqiy jami) qiymatlarga tenglashtiramiz —
      // aks holda ekranda eski (noto'g'ri) raqam ko'rinib qolishi mumkin
      S.cashboxes = mergedBranchSnap.cashboxes;
      S.batches = mergedBranchSnap.batches;
      S.customers = mergedBranchSnap.customers;
      S.suppliers = mergedBranchSnap.suppliers;
      S.branchDebt = mergedBranchDebt;
      if (remote.branchDebtUzs) S.branchDebtUzs = remote.branchDebtUzs;   // v25 (43): faqat server yozadi
      S.dealers = mergedDealers;
      S.dealerStock = mergedDealerStock;
      S.products = merged.products;
      S.partners = merged.partners;
      S.partnerPeriods = merged.partnerPeriods;
      S.deletedIds = combinedDeleted; // shu qurilma ham endi barcha (o'zi + boshqalar) tombstone'larni "biladi"
      S._store[S.branch] = _snapshotBranch();
      // Yangi boshlang'ich nuqta — endi bulut va bu qurilma bir xil holatda
      S._syncBaseline = _numericBaselineSnapshot();
    }
  } catch(e) {
    console.warn('Birlashtirib saqlashda ogohlantirish (oddiy saqlashga o\'tildi):', e);
  }
  await _cloudSave(merged);
}


async function _cloudLoad() {
  if (!_cloudEnabled || !_db) return null;
  // 1-USTUVORLIK / 1.2-QADAM: avval yangi, autentifikatsiya bilan himoyalangan
  // Function orqali o'qishga urinamiz. Muvaffaqiyatsiz bo'lsa (token yo'q, tarmoq
  // xatosi, Function javob bermasa) — ESKI, to'g'ridan-to'g'ri yo'lga qaytamiz.
  // Bu — orqaga moslik: hech qanday holatda ma'lumot yuklanmay qolmaydi.
  try {
    const res = await authFetch('/.netlify/functions/app-data-load', { method:'POST' });
    if (res.ok) {
      const result = await res.json();
      if (Number.isSafeInteger(result.version)) _fwVer = { main: result.version, branches: { ...(result.branchVersions || {}) } };
      _cashAuthority = !!result.cashAuthority;
      FWL.on = !!result.ledgerAuthority;   // v23.2 (F4b): qarz va ombor qoldig'i — server haqiqiy manba
      return result.data || null;
    }
    console.warn(`app-data-load Function xato qaytardi (${res.status}) — eski yo'lga o'tildi`);
  } catch(e) {
    console.warn('app-data-load Function chaqirishda xato — eski yo\'lga o\'tildi:', e);
  }
  // ESKI, to'g'ridan-to'g'ri yo'l (zaxira — hali olib tashlanmadi)
  try {
    const { data:row, error } = await _db.from('app_data').select('data').eq('id','main').maybeSingle();
    if (error) throw error;
    return row?.data || null;
  } catch(e) { console.warn('Cloud yuklash xatosi:', e); return null; }
}

// ── MAHSULOT RASMLARI — alohida saqlagichga (Supabase Storage) yuklanadi ──
// Bu bilan app_data jadvali yengil qoladi (rasmlar bazani og'irlashtirmaydi).
// Cloud yoqilmagan bo'lsa (oflayn/demo) — eski usulda (base64) davom etadi.
// Berilgan mahsulot (pid)ga tegishli BARCHA rasm fayllarini (eski "p123-vaqt.ext" va
// yangi "p123.ext" formatlarining ikkalasini ham) ANIQ, boshqa mahsulotga (masalan
// pid=1000ga pid=100 qidirilganda) aralashib ketmasdan topadi.
async function _findProductImageFiles(pid) {
  if (!_cloudEnabled || !_db) return [];
  try {
    const safePid = String(pid).replace(/[^0-9a-zA-Z]/g, ''); // ehtiyot uchun
    const { data } = await _db.storage.from('product-images').list('', { search: `p${safePid}` });
    // Supabase "search" qisman moslikni ham qaytarishi mumkin — shuning uchun bu yerda
    // ANIQ chegara bilan (pid'dan keyin darhol "-" yoki "." kelishi shart) qayta filtrlaymiz
    const re = new RegExp(`^p${safePid}[-.]`);
    return (data||[]).filter(f => re.test(f.name));
  } catch(e) { return []; }
}

// Rasmni tizimning standart formatiga moslashtiradi: juda katta bo'lsa
// (proporsiyani SAQLAB) kichraytiradi va siqadi; kichik/normal rasmga
// TEGILMAYDI (keraksiz xiralashtirmaslik uchun).
function resizeImageDataUrl(dataUrl, maxDim = 1000, quality = 0.85) {
  return new Promise((resolve) => {
    try {
      const img = new Image();
      img.onload = () => {
        const { width, height } = img;
        if (width <= maxDim && height <= maxDim) {
          resolve(dataUrl); // allaqachon mos hajmda — o'zgartirmasdan qaytaramiz
          return;
        }
        const scale = Math.min(maxDim / width, maxDim / height); // proporsiya SAQLANADI
        const newW = Math.max(1, Math.round(width * scale));
        const newH = Math.max(1, Math.round(height * scale));
        const canvas = document.createElement('canvas');
        canvas.width = newW; canvas.height = newH;
        const ctx = canvas.getContext('2d');
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        ctx.drawImage(img, 0, 0, newW, newH);
        const isPng = dataUrl.startsWith('data:image/png'); // shaffoflik kerak bo'lsa PNG saqlanadi
        resolve(canvas.toDataURL(isPng ? 'image/png' : 'image/jpeg', quality));
      };
      img.onerror = () => resolve(dataUrl); // o'qib bo'lmasa — asl holicha qaytaramiz (import to'xtamasin)
      img.src = dataUrl;
    } catch(e) { resolve(dataUrl); }
  });
}

async function uploadImageToStorage(dataUrl, pid) {
  if (!_cloudEnabled || !_db) return dataUrl; // oflayn — eski usul bilan davom etamiz
  try {
    dataUrl = await resizeImageDataUrl(dataUrl); // katta rasmlarni standart hajmga moslaymiz
    const m = /^data:image\/(png|jpe?g|gif|webp);base64,(.+)$/.exec(dataUrl);
    if (!m) return dataUrl;
    let ext = m[1]==='jpg' ? 'jpg' : m[1];
    const bin = atob(m[2]);
    const bytes = new Uint8Array(bin.length);
    for (let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
    const path = `p${pid}.${ext}`;
    // 1) AVVAL yangi rasmni yuklaymiz. Agar bir xil nom/kengaytmada eski bo'lsa,
    //    "upsert" uni ATOM tarzda (bo'sh oraliqsiz) ustidan yozadi.
    const { error } = await _db.storage.from('product-images').upload(path, bytes, { contentType:`image/${ext}`, upsert:true });
    if (error) {
      // Yangi yuklash MUVAFFAQIYATSIZ bo'ldi — eski rasmga TEGILMAYMIZ, u saqlanib qoladi
      console.warn('Rasm yuklashda xato — eski rasm saqlanib qoladi:', error);
      return null; // chaqiruvchi funksiya buni "yangilanmadi" deb tushunib, p.image'ni o'zgartirmasligi kerak
    }
    // 2) Yangi rasm MUVAFFAQIYATLI yuklangandan KEYINGINA — boshqa kengaytmadagi
    //    eski qoldiqni (masalan avval .png, endi .jpg bo'lsa) tozalaymiz
    try {
      const olderFiles = await _findProductImageFiles(pid);
      // Galereyadagi (2026-10-01) mahsulot ishlatayotgan boshqa rasmlarga TEGILMAYDI
      const prod = (S.products||[]).find(x => String(x.id) === String(pid));
      const keepNames = new Set(productImages(prod).map(storageNameOf).filter(Boolean));
      const toRemove = olderFiles.filter(f => f.name !== path && !keepNames.has(f.name)).map(f=>f.name);
      if (toRemove.length) await _db.storage.from('product-images').remove(toRemove);
    } catch(e) { /* tozalab bo'lmasa ham — yangi rasm allaqachon muvaffaqiyatli saqlangan */ }
    const { data:pub } = _db.storage.from('product-images').getPublicUrl(path);
    return pub?.publicUrl ? `${pub.publicUrl}?v=${Date.now()}` : null;
  } catch(e) { console.warn('Rasm yuklashda xato — eski rasm saqlanib qoladi:', e); return null; }
}

// ════════════════════════════════════════════
// 🖼️ MAHSULOT GALEREYASI (2026-10-01) — 4 tagacha rasm, qirqish, ~40 KB siqish.
// Ma'lumot: p.images = [url, ...] (≤4), p.image = p.images[0] — eski joylar (savdo,
// katalog, chek, eksport) avvalgidek p.image'dan foydalanadi, hech narsa buzilmaydi.
// Fayllar Storage'da "p<pid>-g<vaqt>.jpg" nomi bilan; app_data'ga faqat havola yoziladi.
// ════════════════════════════════════════════
const PG_MAX = 4;
function productImages(p) {
  if (!p) return [];
  const a = Array.isArray(p.images) ? p.images.filter(Boolean) : [];
  return (a.length ? a : (p.image ? [p.image] : [])).slice(0, PG_MAX);
}
function storageNameOf(url) { const m = /\/product-images\/([^?#]+)/.exec(String(url || '')); return m ? decodeURIComponent(m[1]) : null; }
// Rasmni ~targetKB gacha siqadi (JPEG): avval sifat, keyin o'lcham kamaytiriladi
function compressImageDataUrl(dataUrl, targetKB = 40, maxDim = 900) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      try {
        let dim = maxDim, out = dataUrl;
        for (let guard = 0; guard < 6; guard++) {
          const sc = Math.min(1, dim / Math.max(img.width, img.height));
          const w = Math.max(1, Math.round(img.width * sc)), h = Math.max(1, Math.round(img.height * sc));
          const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
          const cx = cv.getContext('2d'); cx.fillStyle = '#fff'; cx.fillRect(0, 0, w, h);
          cx.imageSmoothingEnabled = true; cx.imageSmoothingQuality = 'high'; cx.drawImage(img, 0, 0, w, h);
          for (const q of [0.82, 0.72, 0.62, 0.52, 0.45]) {
            out = cv.toDataURL('image/jpeg', q);
            if ((out.length - 23) * 0.75 <= targetKB * 1024) return resolve(out);
          }
          dim = Math.round(dim * 0.8);
          if (dim < 360) break;
        }
        resolve(out);
      } catch (e) { resolve(dataUrl); }
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
  });
}
async function uploadGalleryImage(dataUrl, pid) {
  if (!_cloudEnabled || !_db) return dataUrl; // oflayn — eski usul (keyin "Rasmlarni saqlagichga ko'chirish" bilan ko'chiriladi)
  try {
    const m = /^data:image\/(jpe?g|png|webp);base64,(.+)$/.exec(dataUrl);
    if (!m) return null;
    const bin = atob(m[2]); const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    const safePid = String(pid).replace(/[^0-9a-zA-Z]/g, '');
    const path = `p${safePid}-g${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}.jpg`;
    const { error } = await _db.storage.from('product-images').upload(path, bytes, { contentType:'image/jpeg', upsert:false });
    if (error) { console.warn('Galereya rasmi yuklanmadi:', error); return null; }
    const { data: pub } = _db.storage.from('product-images').getPublicUrl(path);
    return pub?.publicUrl || null;
  } catch (e) { console.warn('Galereya rasmi yuklanmadi:', e); return null; }
}
async function deleteStorageImageByUrl(url) {
  const name = storageNameOf(url);
  if (!name || !_cloudEnabled || !_db) return;
  try { await _db.storage.from('product-images').remove([name]); } catch (e) { console.warn("Rasmni o'chirib bo'lmadi:", e); }
}

// ── Formadagi galereya (saqlanmaguncha faqat xotirada; "Bekor" — hech narsa o'zgarmaydi) ──
let PG = null; // { items:[{src, isNew}], removed:[url] }
function pgInit(p) { PG = { items: productImages(p).map(src => ({ src, isNew:false })), removed: [] }; }
function pgSectionHtml() { return `<div class="pg-sec" id="pg-sec">${pgInner()}</div>`; }
function pgInner() {
  if (!PG) return '';
  const n = PG.items.length;
  return `<div class="pg-head"><b>📷 Mahsulot rasmi</b><span class="pg-count">${n} / ${PG_MAX}</span></div>
    <div class="pg-grid">
      ${PG.items.map((it, i) => `<div class="pg-th${i === 0 ? ' main' : ''}">
        <img src="${esc(fwImgSafe(it.src))}" alt="Rasm ${i + 1}" onclick="pgCrop(${i})" title="Qirqish uchun bosing">
        ${i === 0 ? '<span class="pg-badge">Asosiy</span>' : `<button type="button" class="pg-star" onclick="pgMain(${i})" title="Asosiy qilish" aria-label="Asosiy qilish">★</button>`}
        <button type="button" class="pg-del" onclick="pgRemove(${i})" aria-label="Rasmni o'chirish">×</button>
      </div>`).join('')}
      ${n < PG_MAX ? `<label class="pg-add"><span>+</span><b>Qo'shish</b><input type="file" accept="image/*" multiple hidden onchange="pgAddFiles(this)"></label>` : ''}
    </div>
    <div class="pg-note">4 tagacha rasm. Har bir rasm ~40 KB gacha siqiladi. Qirqish uchun rasm ustiga bosing. Birinchisi — asosiy rasm (savdo, katalog va chekda ko'rinadi).</div>`;
}
function pgRender() { const el = document.getElementById('pg-sec'); if (el) el.innerHTML = pgInner(); }
function _pgReadFile(f) { return new Promise(res => { const r = new FileReader(); r.onload = e => res(e.target.result); r.onerror = () => res(null); r.readAsDataURL(f); }); }
async function pgAddFiles(input) {
  if (!PG) return;
  const files = [...(input.files || [])].filter(f => /^image\//.test(f.type));
  const room = PG_MAX - PG.items.length;
  if (files.length > room) toast(`Faqat ${PG_MAX} tagacha rasm — ${files.length - room} tasi qo'shilmadi`, 'warning');
  for (const f of files.slice(0, room)) {
    if (f.size > 20 * 1024 * 1024) { toast(`"${f.name}" juda katta (20 MB dan ortiq)`, 'error'); continue; }
    const raw = await _pgReadFile(f); if (!raw) continue;
    const small = await compressImageDataUrl(raw);
    if (small) PG.items.push({ src: small, isNew: true }); else toast(`"${f.name}" rasmini o'qib bo'lmadi`, 'error');
    pgRender();
  }
  input.value = '';
}
function pgMain(i) { if (!PG) return; const [it] = PG.items.splice(i, 1); PG.items.unshift(it); pgRender(); }
function pgRemove(i) { if (!PG) return; const [it] = PG.items.splice(i, 1); if (it && !it.isNew) PG.removed.push(it.src); pgRender(); }
// Saqlashda: yangi rasmlar yuklanadi, olib tashlanganlar Storage'dan o'chiriladi. Qaytaradi: yuklanmagan rasmlar soni
async function pgCommit(p) {
  if (!PG) return 0;
  const urls = []; let failed = 0;
  for (const it of PG.items) {
    if (!it.isNew) { urls.push(it.src); continue; }
    const u = await uploadGalleryImage(it.src, p.id);
    if (u) urls.push(u); else failed++;
  }
  const removed = PG.removed.filter(u => !urls.includes(u));
  p.images = urls.slice(0, PG_MAX);
  p.image = p.images[0] || null;
  removed.forEach(u => deleteStorageImageByUrl(u)); // fire-and-forget
  PG = null;
  return failed;
}
// Qirqish: kvadrat ramka, surish va kattalashtirish
function pgCrop(i) {
  const it = PG && PG.items[i]; if (!it) return;
  const img = new Image(); img.crossOrigin = 'anonymous';
  img.onload = () => _pgOpenCropper(img, i);
  img.onerror = () => toast("Rasmni ochib bo'lmadi", 'error');
  img.src = it.src;
}
function _pgOpenCropper(img, i) {
  const ov = document.createElement('div'); ov.className = 'pg-crop-ov';
  ov.innerHTML = `<div class="pg-crop-box" role="dialog" aria-label="Rasmni qirqish"><b>Rasmni qirqish</b>
    <canvas width="320" height="320"></canvas>
    <label class="pg-zoom"><span>Kattalashtirish</span><input type="range" min="1" max="3" step="0.01" value="1"></label>
    <small>Rasmni barmoq yoki sichqoncha bilan suring — kvadrat ichidagi qism saqlanadi.</small>
    <div class="pg-crop-act"><button type="button" class="btn btn-ghost" data-a="cancel">Bekor</button><button type="button" class="btn btn-primary" data-a="ok">✂️ Qirqish</button></div></div>`;
  document.body.appendChild(ov);
  const cv = ov.querySelector('canvas'), ctx = cv.getContext('2d'), rng = ov.querySelector('input');
  const S0 = 320, base = Math.max(S0 / img.width, S0 / img.height);
  let z = 1, ox = (S0 - img.width * base) / 2, oy = (S0 - img.height * base) / 2, drag = null;
  const draw = () => { const sc = base * z, w = img.width * sc, h = img.height * sc;
    ox = Math.min(0, Math.max(S0 - w, ox)); oy = Math.min(0, Math.max(S0 - h, oy));
    ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, S0, S0); ctx.drawImage(img, ox, oy, w, h); };
  draw();
  cv.onpointerdown = e => { drag = { x:e.clientX, y:e.clientY, ox, oy }; cv.setPointerCapture(e.pointerId); };
  cv.onpointermove = e => { if (!drag) return; const k = S0 / cv.getBoundingClientRect().width; ox = drag.ox + (e.clientX - drag.x) * k; oy = drag.oy + (e.clientY - drag.y) * k; draw(); };
  cv.onpointerup = cv.onpointercancel = () => { drag = null; };
  rng.oninput = () => { const c = S0 / 2, old = base * z; z = +rng.value; const nw = base * z; ox = c - (c - ox) * nw / old; oy = c - (c - oy) * nw / old; draw(); };
  ov.onclick = async (e) => {
    const a = e.target.closest('[data-a]')?.dataset.a;
    if (e.target === ov || a === 'cancel') { ov.remove(); return; }
    if (a !== 'ok') return;
    try {
      const OUT = 900, out = document.createElement('canvas'); out.width = out.height = OUT;
      const o = out.getContext('2d'); o.fillStyle = '#fff'; o.fillRect(0, 0, OUT, OUT);
      const k = OUT / S0, sc = base * z * k; o.drawImage(img, ox * k, oy * k, img.width * sc, img.height * sc);
      const durl = await compressImageDataUrl(out.toDataURL('image/jpeg', 0.92));
      if (!durl) throw new Error('siqilmadi');
      const it = PG.items[i]; if (it && !it.isNew) PG.removed.push(it.src);
      PG.items[i] = { src: durl, isNew: true };
      ov.remove(); pgRender();
    } catch (err) { ov.remove(); toast("Saqlangan rasmni qirqib bo'lmadi — rasmni qayta yuklab qirqing", 'error'); }
  };
}

// Mahsulot BUTUNLAY o'chirilganda (Nofaol emas — faqat haqiqiy DELETE'da), Storage'dagi
// rasmini ham tozalaydi — aks holda hech kim ishlatmaydigan "etim" fayl abadiy qolib ketardi.
// Boshqa mahsulotlarning fayllariga ANIQ chegara (_findProductImageFiles) tufayli tegilmaydi.
async function deleteProductImage(pid) {
  if (!_cloudEnabled || !_db) return;
  try {
    const existing = await _findProductImageFiles(pid);
    if (existing.length) {
      await _db.storage.from('product-images').remove(existing.map(f=>f.name));
    }
  } catch(e) { console.warn('Rasmni Storage\'dan o\'chirishda xato:', e); }
}

// Eksport (Excel) uchun — rasm link bo'lsa yuklab olib base64ga aylantiradi, eski (base64) bo'lsa to'g'ridan-to'g'ri qaytaradi
async function imageToBase64Parts(img) {
  if (!img) return null;
  const mData = /^data:image\/(png|jpe?g|gif|webp);base64,(.+)$/.exec(img);
  if (mData) return { base64: mData[2], ext: mData[1]==='jpg'?'jpeg':mData[1] };
  try {
    const res = await fetch(img);
    if (!res.ok) return null;
    const blob = await res.blob();
    const ext = (blob.type.split('/')[1]||'png').replace('jpeg','jpeg');
    const buf = await blob.arrayBuffer();
    const base64 = u8ToBase64(new Uint8Array(buf));
    return { base64, ext: ext==='jpg'?'jpeg':ext };
  } catch(e) { return null; }
}

async function _syncToCloud() {
  S._store[S.branch] = _snapshotBranch();
  const payload = {
    products:S.products, partners:S.partners, partnerPeriods:S.partnerPeriods,
    settings:S.settings, auditLogs:S.auditLogs, activeBranch:S.branch, branchStore:S._store, branchDebt:S.branchDebt, filialOrders:S.filialOrders
  };
  // Eslatma: dealers/dealerStock/dealerTxns endi alohida Supabase jadvallarida
  // (RLS bilan himoyalangan) — shu blobga yozilmaydi.
  await _cloudSave(payload);
}

// ── DILLER/OMBORCHI — alohida jadvallar (RLS bilan himoyalangan) ────
// Bular S.dealers/S.dealerStock/S.dealerTxns bilan bir xil shaklda ishlaydi,
// shunda mavjud render funksiyalari o'zgarishsiz ishlayveradi.
const DEALER_EMAIL_DOMAIN = 'dillers.biznespro.local';

// ── DILLER AUDIT JURNALI — kim/qachon/qaysi filialdan/eski-yangi qiymat ──
// Odatda "fire-and-forget" (kutilmaydi) chaqiriladi, lekin promise qaytaradi —
// tartib muhim bo'lgan holatlarda (masalan o'chirishdan oldin) await qilish mumkin.
function dlAuditDealer(dealerId, action, oldValue, newValue) {
  if (!dealerId) return Promise.resolve();
  const actorKind = CURRENT_USER?.kind || 'owner';
  const actorName = CURRENT_USER?.name || (S.settings?.ownerName || 'Egasi');
  const actorStaffId = CURRENT_USER?.staffId || null;
  return authFetch('/.netlify/functions/dealer-audit-log-add', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ dealerId, action, actorKind, actorName, actorStaffId, filial: S.branch, oldValue: oldValue??null, newValue: newValue??null })
  }).catch(()=>{}); // audit yozuvi muvaffaqiyatsiz bo'lsa ham asosiy amal to'xtamaydi
}

async function dlLoadDealerData() {
  if (!_cloudEnabled) return;
  try {
    const res = await authFetch('/.netlify/functions/dealer-data-load', {
      method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ filial: S.branch })
    });
    const result = await res.json();
    if (!res.ok) throw new Error(result.error);
    const { dealers, stock, sales, payments: pays, moves } = result;
    if (dealers) {
      S.dealers = dealers.map(d=>({
        id:d.id, authUserId:d.auth_user_id, login:d.login, name:d.name, phone:d.phone, region:d.region,
        debt:d.debt_usd||0, totalShipped:d.total_shipped_usd||0, totalSold:d.total_sold_usd||0,
        totalPaid:d.total_paid_usd||0, color:d.color, av:d.av, commissionPct:d.commission_pct||0, telegramChatId:d.telegram_chat_id||'', points:d.points||0, filial:d.filial||'baza',
        creditLimitUsd:d.credit_limit_usd||0, paymentDueDays:d.payment_due_days||30
      }));
    }
    if (stock) {
      S.dealerStock = stock.map(r=>({
        id:r.id, dealerId:r.dealer_id, pid:r.pid, qty:r.qty||0, avgCostUsd:r.avg_cost_usd||0
      }));
    }
    // send/return/sale/payment — bittalashtirilgan tarix (printDealerStatement va h.k. shuni kutadi)
    const txns = [];
    (moves||[]).forEach(m=>txns.push({id:'m'+m.id, date:m.created_at?.slice(0,10), dealerId:m.dealer_id, type:m.type, items:[{pid:m.pid, qty:m.qty, priceUsd:m.cost_usd, condition:m.condition, reason:m.reason}], totalUsd:m.qty*(m.cost_usd||0)}));
    (sales||[]).forEach(s=>txns.push({id:'s'+s.id, date:s.sale_date, dealerId:s.dealer_id, type:'sale', items:[{pid:s.pid, qty:s.qty, priceUsd:s.sell_usd}], totalUsd:s.total_usd}));
    (pays||[]).forEach(p=>txns.push({id:'p'+p.id, date:p.created_at?.slice(0,10), dealerId:p.dealer_id, type:'payment', items:[], totalUsd:p.amount_usd}));
    txns.sort((a,b)=>(a.date<b.date?1:-1));
    S.dealerTxns = txns;
    S.dealerSalesRaw = sales||[]; // "bugungi nazorat" bo'limi uchun xom ma'lumot
  } catch(e) { console.warn('Diller ma\'lumotlari yuklanmadi:', e); }
}

