// ── KATALOG SINXRONIZATSIYASI — diller ko'radigan xavfsiz mahsulot ro'yxati.
//    1-USTUVORLIK / 1.4-QADAM: hisoblash endi CLIENT tomonda (S._store orqali)
//    EMAS, balki `catalog-full-sync.js` Function ichida, to'g'ridan-to'g'ri
//    bazadan amalga oshiriladi. Sabab: filial-cheklovi yoqilgach, admin bo'lmagan
//    xodimning brauzerida boshqa filiallar ma'lumoti endi mavjud emas — agar
//    hisoblash shu yerda (clientda) qolganida, boshqa filiallar uchun noto'g'ri
//    (bo'sh) qator yozilib qolardi. Endi BU FUNKSIYA shunchaki Function'ni
//    chaqiradi — u har doim TO'LIQ, TO'G'RI natija beradi, kim chaqirmasin.
// v24.5: server (catalog-full-sync) faqat admin yoki shu ruxsatlardan biri bo'lsa qayta hisoblaydi — ro'yxat serverdagi
// SYNC_PERMS bilan AYNAN bir xil. Ruxsatsiz xodimning har save()'i 403 olib, xavfsizlik jurnalini to'ldirmasin.
const FW_CATALOG_SYNC_PERMS = ['mahsulotlar.edit','mahsulotlar.create','mahsulotlar.delete','kirim.create',
  'savdo.create','savdo.edit','savdo.delete','qaytarish.create','dillerlar.manage'];
function fwCanSyncCatalog() { return FW_CATALOG_SYNC_PERMS.some(k => hasPerm(k)); }
async function dlSyncCatalog(manual) {
  if (!_cloudEnabled || !_db) {
    if (manual) toast('Bulut ulanmagan!','error');
    return false;
  }
  if (!fwCanSyncCatalog()) {
    if (manual) toast("Katalogni sinxronlash uchun ruxsatingiz yo'q", 'error');
    return false;
  }
  try {
    const res = await authFetch('/.netlify/functions/catalog-full-sync', { method:'POST' });
    const result = await res.json();
    if (!res.ok) { console.error('Katalog sinxronizatsiya xatosi (batafsil):', JSON.stringify(result)); throw new Error(result.error); }
    if (manual) toast(`✅ Katalog sinxronlandi (${result.count} ta yozuv, ${result.filiallar} filial)!`);
    return true;
  } catch(e) {
    console.warn('Katalog sinxronlanmadi:', e);
    if (manual) toast('⚠️ Katalog sinxronlanmadi: '+(e.message||e.hint||e.details||JSON.stringify(e)), 'error');
    return false;
  }
}

