// ── HELPERS ────────────────────────────────
// uid, td, parseAmt, liveFormatSpaces, deductFIFO, logCashTxn — endi js/shared.js'da (barcha ilovalarda umumiy)
function canEdit30(dateStr) {
  if (!dateStr) return false;
  const diff = (Date.now() - new Date(dateStr).getTime()) / 86400000;
  return diff <= 30;
}
const fmtD = d  => new Date(d).toLocaleDateString('uz-UZ');

function toast(msg, type='success') {
  const c = document.getElementById('toasts');
  if (!c) return;
  // v24.6: ilova ikonkalari (emoji emas); xabar boshidagi emoji olib tashlanadi (ikki marta belgi chiqmasin)
  const icons = {success:'check', error:'close', warning:'warning'};
  const el = document.createElement('div');
  el.className = `toast ${type}`;
  el.setAttribute('role', type==='error' ? 'alert' : 'status');
  // msg — textContent orqali (XSS: xabar ichida mijoz/mahsulot nomi bo'lishi mumkin)
  const ic = document.createElement('span'); ic.className = 'toast-ic'; ic.innerHTML = ICONF[icons[type]||'info'] || '';
  const tx = document.createElement('span'); tx.textContent = String(msg ?? '').replace(/^[\p{Extended_Pictographic}\uFE0F\u200D\s]+/u, '');
  el.append(ic, tx);
  c.appendChild(el);
  setTimeout(()=>el.remove(), 4000);
}

// ── SAQLASH HOLATI INDIKATORI ──
// save() bulutga saqlash muvaffaqiyatli yoki muvaffaqiyatsiz bo'lganini
// foydalanuvchiga aniq ko'rsatadi. type: 'success' | 'error'
let _saveIndicatorTimer = null;
function showSaveIndicator(type, message) {
  let el = document.getElementById('save-indicator');
  if (!el) {
    el = document.createElement('div');
    el.id = 'save-indicator';
    document.body.appendChild(el);
  }
  clearTimeout(_saveIndicatorTimer);
  el.textContent = message;
  el.className = `save-indicator ${type}`;
  el.style.display = 'flex';
  if (type === 'success') {
    // Muvaffaqiyatli bo'lsa — 2 soniyadan keyin o'zi yopiladi
    el.onclick = null;
    _saveIndicatorTimer = setTimeout(() => { el.style.display = 'none'; }, 2000);
  } else {
    // Xato bo'lsa — foydalanuvchi albatta ko'rishi kerak, faqat bosilganda yopiladi
    el.onclick = () => { el.style.display = 'none'; };
  }
}

function auditLog(action) {
  S.auditLogs.unshift({ id:uid(), action, ts:new Date().toISOString() });
  if (S.auditLogs.length > 200) S.auditLogs.pop();
}

function getStock(pid) {
  return S.batches.filter(b=>b.pid===pid && b.status!=='empty' && b.status!=='transit').reduce((s,b)=>s+(b.qty-b.sold),0);
}

function getTransitStock(pid) {
  return S.batches.filter(b=>b.pid===pid && b.status==='transit').reduce((s,b)=>s+(b.qty-b.sold),0);
}

function getCostFIFO(pid) {
  const b = S.batches.filter(x=>x.pid===pid && x.qty>x.sold && x.status!=='empty' && x.status!=='transit')
    .sort((a,b)=>new Date(a.date)-new Date(b.date))[0];
  return b ? (b.costUsd||0) : 0;
}

function sellPrice(p, cost) {
  const own = typeof fwBranchOwn === 'function' ? fwBranchOwn(S.branch) : null;   // v25: mustaqil filial — o'z ustamasi
  const pct = own && own.r != null ? own.r : (p && p.markupPct!=null) ? p.markupPct : 25;
  return cost * (1 + pct/100);
}

function optPrice(p, cost) {
  const own = typeof fwBranchOwn === 'function' ? fwBranchOwn(S.branch) : null;
  const pct = own && own.o != null ? own.o : (p && p.optMarkupPct!=null) ? p.optMarkupPct : 15;
  return cost * (1 + pct/100);
}

// v24.5: savdo rejimi (Chakana/Optom) va valyuta (UZS/USD) — js/pos.js (POS.mode, POS.cur)

function openArrivalCustoms(bno) {
  const batches = S.batches.filter(b=>b.bno===bno && b.status==='transit');
  if (!batches.length) { toast('Bu partiya allaqachon keldi yoki topilmadi!','warning'); return; }
  S.acDist = 'per_unit';
  S.acBno = bno;
  modal(`
    <div class="modal-header"><div class="modal-title">✅ #${esc(bno)} — Yetib keldi</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <p style="color:var(--text-secondary);font-size:12px;margin-bottom:12px">Endi O'zbekiston bojxonasi xarajatini kiriting — bu mahsulot tannarxiga qo'shiladi va ombor qoldig'iga chiqadi.</p>
      <div style="display:flex;gap:6px;margin-bottom:10px">
        <button class="btn btn-ghost btn-sm" id="ac-unit" onclick="acSetDist('per_unit')" style="border-color:var(--blue);color:var(--blue);background:rgba(59,130,246,0.1)">📦 Donaga</button>
        <button class="btn btn-ghost btn-sm" id="ac-val" onclick="acSetDist('by_value')">💰 Summaga</button>
      </div>
      <div class="form-group"><label class="form-label">Bojxona summasi ($)</label><input class="form-control" id="ac-customs" type="number" value="0" step="0.01" oninput="acUpdatePreview()"></div>
      <div style="font-size:11px;color:var(--text-muted);margin-bottom:10px">Bo'sh/0 qoldirsangiz — bojxonasiz, joriy tannarx bilan ombor qoldig'iga qo'shiladi.</div>
      <div id="ac-preview"></div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-success" onclick="confirmArrival('${escJsAttr(bno)}')">✅ Keldi — ombor qoldig'iga qo'shish</button>
    </div>`);
  acUpdatePreview();
}

// Jonli hisoblagich — bojxona summasini kiritganda, har bir mahsulotga
// qancha tushishi (yangi tannarx) darhol ko'rsatiladi (hali tasdiqlanmasdan)
function acUpdatePreview() {
  const el = document.getElementById('ac-preview');
  if (!el) return;
  const batches = S.batches.filter(b=>b.bno===S.acBno && b.status==='transit');
  const customsUsd = parseFloat(document.getElementById('ac-customs')?.value||0);
  const method = S.acDist || 'per_unit';
  let distributed = batches.map(()=>0);
  if (customsUsd>0) {
    const items = batches.map(b=>({qty:b.qty, unitUsd:b.costUsd}));
    distributed = CUR.distributeUsd(customsUsd, items, method);
  }
  el.innerHTML = `<div class="table-wrap"><table><thead><tr><th>Mahsulot</th><th>Dona</th><th>Eski tannarx</th><th>+Qo'shiladi</th><th>Yangi tannarx</th></tr></thead><tbody>
    ${batches.map((b,i)=>{
      const p = S.products.find(x=>x.id===b.pid);
      const addPerUnit = b.qty>0 ? (distributed[i]||0)/b.qty : 0;
      const newCost = b.costUsd + addPerUnit;
      return `<tr>
        <td>${esc(p?.sku||'')} ${esc(p?.name?.slice(0,16)||'')}</td>
        <td>${b.qty}</td>
        <td style="color:var(--text-muted)">${CUR.fmtUsd(b.costUsd)}</td>
        <td style="color:${addPerUnit>0?'var(--gold-dark)':'var(--text-muted)'}">${addPerUnit>0?'+':''}${CUR.fmtUsd(addPerUnit)}</td>
        <td style="font-weight:700;color:var(--emerald)">${CUR.fmtUsd(newCost)}</td>
      </tr>`;
    }).join('')}
  </tbody></table></div>`;
}

function acSetDist(m) {
  S.acDist = m;
  const u=document.getElementById('ac-unit'), v=document.getElementById('ac-val');
  if (m==='per_unit') { if(u){u.style.borderColor='var(--blue)';u.style.color='var(--blue)';u.style.background='rgba(59,130,246,0.1)';} if(v){v.style.borderColor='';v.style.color='';v.style.background='';} }
  else { if(v){v.style.borderColor='var(--blue)';v.style.color='var(--blue)';v.style.background='rgba(59,130,246,0.1)';} if(u){u.style.borderColor='';u.style.color='';u.style.background='';} }
  acUpdatePreview();
}

async function confirmArrival(bno) {
  const batches = S.batches.filter(b=>b.bno===bno && b.status==='transit');
  if (!batches.length) { closeModal(); return; }
  const customsUsd = parseFloat(document.getElementById('ac-customs')?.value||0);
  const method = S.acDist || 'per_unit';
  // v23.2 (F4b): "yo'lda" → omborga — holat va tannarx SERVERDA (bojxona ulushi: $/dona)
  if (fwLedgerRemote()) {
    const costAdds = {};
    if (customsUsd>0) {
      const distributed = CUR.distributeUsd(customsUsd, batches.map(b=>({qty:b.qty, unitUsd:b.costUsd})), method);
      batches.forEach((b,i)=>{ costAdds[String(b.id)] = b.qty>0 ? (distributed[i]||0)/b.qty : 0; });
    }
    try { await fwLedgerCall('stock-debt-ops', { kind:'batch_arrive', payload:{ localIds: batches.map(b=>String(b.id)), costAdds } }); }
    catch(e) { toast('⛔ ' + e.message, 'error'); return; }
    batches.forEach(b=>{ b.arrivedDate = td(); });
    auditLog(`Partiya keldi: #${bno}${customsUsd>0?' — bojxona +'+CUR.fmtUsd(customsUsd):''}`);
    save(); closeModal();
    if (S.page==='kirim') pgKirim(); else pgOmbor();
    toast(`✅ #${bno} — yetib keldi, ombor qoldig'iga qo'shildi!`);
    return;
  }
  if (customsUsd>0) {
    const items = batches.map(b=>({qty:b.qty, unitUsd:b.costUsd}));
    const distributed = CUR.distributeUsd(customsUsd, items, method);
    batches.forEach((b,i)=>{ b.costUsd += (distributed[i]||0)/b.qty; });
  }
  batches.forEach(b=>{ b.status='active'; b.arrivedDate = td(); });
  auditLog(`Partiya keldi: #${bno}${customsUsd>0?' — bojxona +'+CUR.fmtUsd(customsUsd):''}`);
  save(); closeModal();
  if (S.page==='kirim') pgKirim(); else pgOmbor();
  toast(`✅ #${bno} — yetib keldi, ombor qoldig'iga qo'shildi!`);
}

async function save() {
  // Joriy faol filialning ma'lumotlarini xotiradagi filial-omboriga olib qo'yamiz
  S._store[S.branch] = _snapshotBranch();
  const payload = {
    products:S.products, partners:S.partners, partnerPeriods:S.partnerPeriods,
    settings:S.settings, auditLogs:S.auditLogs,
    activeBranch:S.branch, branchStore:S._store, branchDebt:S.branchDebt, filialOrders:S.filialOrders,
    dealerRevisions:S.dealerRevisions, deletedIds:S.deletedIds,
    // dealers/staffList hozircha filial bo'yicha ajratilmagan (keyingi bosqich):
    dealers:S.dealers, dealerStock:S.dealerStock, dealerTxns:S.dealerTxns
  };
  // localStorage'ga DARHOL, sinxron tarzda yozamiz — bulutga ulanish sekin bo'lsa
  // yoki muvaffaqiyatsiz tugasa ham, shu qurilmadagi ma'lumot hech qachon yo'qolmaydi
  // Maxfiy tokenlar (Telegram) qurilma xotirasiga yozilmaydi — ular faqat serverda saqlanadi
  const _lsPayload = (payload.settings && (payload.settings.tgBotToken || payload.settings.shopBotToken))
    ? { ...payload, settings: (({ tgBotToken, shopBotToken, ...rest }) => rest)(payload.settings) } : payload;
  localStorage.setItem('bp_data', JSON.stringify(_lsPayload));
  // Bulutga dealers/dealerStock/dealerTxns yuborilmaydi — ular endi alohida,
  // RLS bilan himoyalangan jadvallarda (dlUpsertStock/dlInsertMove/... orqali yoziladi)
  const { dealers, dealerStock, dealerTxns, ...cloudPayload } = payload;
  // Bulutga saqlashni ENDI kutamiz (await) — sahifa yopilib/yangilanib qolsa ham
  // ma'lumot bulutga yetib bormay qolish xavfi kamayadi. Xato bo'lsa foydalanuvchi
  // buni DARHOL ko'radi — endi jimgina yo'qolib ketmaydi.
  let ok = true;
  try {
    await _safeCloudSave(cloudPayload); // ID bo'yicha birlashtirib saqlaydi
    if (_cloudEnabled) showSaveIndicator('success', '✓ Saqlandi');
  } catch (e) {
    ok = false;
    // v25: internet yo'q — ma'lumot qurilmada saqlandi, internet qaytganda bulutga yoziladi
    if (typeof fwIsNetErr === 'function' && fwIsNetErr(e)) { S._saveLater = true; showSaveIndicator('success', 'Oflayn — qurilmada saqlandi'); return true; }
    console.error('Saqlashda xatolik (save):', e && e.message);
    // v24: haqiqiy sabab ko'rsatiladi (sessiya, ruxsat, hajm, server) — jimgina yutilmaydi
    showSaveIndicator('error', `⚠ Saqlanmadi: ${(e && e.message) || "noma'lum xato"}. Qayta urinib ko'ring`);
  }
  dlSyncCatalog(); // async, kutilmaydi — dillerlar ko'radigan katalog yangilanadi
  return ok;
}

// v24: muvaffaqiyat xabari FAQAT bulutga haqiqatan yozilgandan keyin (yolg'on «Saqlandi» yo'q)
function fwSaveToast(msg, after) {
  return Promise.resolve(save()).then(ok => { if (ok !== false) { toast(msg); if (typeof after === 'function') after(); } return ok !== false; });
}

// ── Himoyalangan Netlify Function'larga so'rov yuborish uchun umumiy yordamchi ──
// Joriy Supabase Auth sessiyasining tokenini qo'shadi ("Authorization: Bearer ...")
// — server tomonda kim ekanligimiz va ruxsatlarimiz shu orqali tekshiriladi.
async function authHeaders() {
  try {
    const { data: { session } } = await _db.auth.getSession();
    if (session?.access_token) return { 'Authorization': 'Bearer ' + session.access_token };
  } catch(e) { /* sessiya yo'q — server 401 qaytaradi, bu kutilgan holat */ }
  return {};
}
async function authFetch(url, options = {}) {
  const hdrs = { 'Content-Type': 'application/json', ...(await authHeaders()), ...(options.headers||{}) };
  const res = await fetch(url, { ...options, headers: hdrs });
  if (res.status === 403 && typeof fwPwForceOn403 === 'function') fwPwForceOn403(res);   // v24.9: admin parolni tiklagan — yangi parol
  return res;
}

async function initData() {
  // 1. Avval cloud'dan yuklab ko'ramiz — app-data-load.js Function ichida
  //    app_data_branches ustunligi ALLAQACHON hisobga olingan (1.1-qadam),
  //    shuning uchun bu yerda alohida, to'g'ridan-to'g'ri so'rov shart emas.
  const cloudData = await _cloudLoad();
  const raw = cloudData ? JSON.stringify(cloudData) : localStorage.getItem('bp_data');

  let d0 = null;
  if (raw) { try { d0 = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (_) { console.warn("Mahalliy nusxa buzilgan — e'tiborsiz qoldirildi"); } } // v10 (J10)
  if (d0) {
    const d = d0;
    // Umumiy (filialga bog'liq bo'lmagan) maydonlar — to'g'ridan-to'g'ri ko'chiriladi
    ['products','partners','partnerPeriods','settings','dealers','dealerStock','dealerTxns','auditLogs','branchDebt','branchDebtUzs','filialOrders','dealerRevisions','deletedIds']
      .forEach(k => { if (d[k]!==undefined) S[k]=d[k]; });
    if (!S.deletedIds) S.deletedIds = {};
    // Bekor qilingan (tombstone) taqsimotlar qaytib chiqmasin; eng so'nggisi birinchi
    S.partnerPeriods = sortPartnerPeriods((S.partnerPeriods||[]).filter(per=>!isDeleted('partnerPeriods', per.id)));
    // O'tish davri: eski qarz maydoni (f729ToBaza) -> yangi umumiy filial-qarz xaritasiga ko'chiriladi
    if (!S.branchDebt) S.branchDebt = {};
    if (S.branchDebt.f729ToBaza !== undefined) {
      if (S.branchDebt.f729 === undefined) S.branchDebt.f729 = S.branchDebt.f729ToBaza;
      delete S.branchDebt.f729ToBaza;
    }

    if (d.branchStore) {
      // Har bir filial uchun: AVVAL yangi jadvaldagi ma'lumot (agar bor bo'lsa),
      // TOPILMASA — eski branchStore'dagi mos qism (orqaga moslik, hech narsa yo'qolmaydi)
      const pick = (key) => d.branchStore[key] || {};
      S._store = { baza: pick('baza'), f729: pick('f729'), ...Object.fromEntries(Object.entries(d.branchStore).filter(([k])=>k!=='baza'&&k!=='f729').map(([k])=>[k, pick(k)])) };
      // O'tish davri: salaryPeople avval umumiy (tashqarida) saqlanardi — endi Baza ichida bo'lishi kerak
      if (d.salaryPeople!==undefined && S._store.baza.salaryPeople===undefined) {
        S._store.baza.salaryPeople = d.salaryPeople;
      }
    } else {
      // ESKI FORMAT (filiallar hali yo'q edi) — mavjud BARCHA ma'lumot "Baza"ga tegishli deb saqlanadi
      S._store = { baza: {}, f729: {} };
      BRANCH_KEYS.forEach(k => { if (d[k]!==undefined) S._store.baza[k] = d[k]; });
    }

    // v10 (J2): qo'shilgan filiallar ro'yxatini (S.settings.extraBranches) filial
    // tanlanishidan OLDIN tiklaymiz — yangi qurilmada BRANCHES hali bo'sh bo'lgani uchun
    // filial xodimi xato ravishda bo'sh "Baza"ga tushib qolardi.
    syncExtraBranchesFromCloud();

    // Migratsiya (har ikki filial uchun): "Bank" kassasi olib tashlandi, "Diller kassasi" qo'shildi
    Object.keys(BRANCHES).forEach(brKey=>{
      const bs = S._store[brKey];
      // v10 (J1): admin bo'lmagan xodimga server faqat O'Z filialini yuboradi — boshqa
      // filial kalitlari S._store'da yo'q. Avval bu yerda TypeError chiqib, ilova ochilmasdi.
      if (!bs || !bs.cashboxes) return;
      const bankBox = bs.cashboxes.find(k=>k.type==='bank');
      // v11 (F4): qoldiq serverda bo'lsa, pulli "Bank" kassasini brauzer o'zi qo'shib/o'chira olmaydi
      // (server ruxsat bermaydi) — avval Kassalar → Ko'chirish orqali bo'shatiladi
      if (bankBox && !(_cashAuthority && (bankBox.bal||0) !== 0)) {
        const cashBox = bs.cashboxes.find(k=>k.type==='cash');
        if (cashBox && bankBox.bal) cashBox.bal += bankBox.bal;
        bs.cashboxes = bs.cashboxes.filter(k=>k.type!=='bank');
      }
      if (!bs.cashboxes.find(k=>k.type==='dealer')) {
        const maxId = bs.cashboxes.reduce((m,k)=>Math.max(m,k.id),0);
        bs.cashboxes.push({id:maxId+1, name:'Diller kassasi', icon:'🚚', cur:'USD', type:'dealer', bal:0});
      }
      if (!bs.cashboxes.find(k=>k.type==='qobiljon')) {
        const maxId2 = bs.cashboxes.reduce((m,k)=>Math.max(m,k.id),0);
        bs.cashboxes.push({id:maxId2+1, name:QOBILJON_BOX_NAME, icon:'🔒', cur:'USD', type:'qobiljon', bal:0});
      }
      // v23.6: yopiq (egasi) kassa — «Shaxsiy kassa» (brend nomi bilan atalmaydi: bosh kassa bilan adashmasin)
      const qBox = bs.cashboxes.find(k=>k.type==='qobiljon');
      if (qBox) qBox.name = QOBILJON_BOX_NAME;
    });

    // Faol filialni tanlaymiz: shu qurilmada saqlangani > bulutdagi > standart 'baza'
    const savedBranch = localStorage.getItem('bp_active_branch');
    S.branch = (savedBranch && BRANCHES[savedBranch]) ? savedBranch : ((d.activeBranch && BRANCHES[d.activeBranch]) ? d.activeBranch : 'baza');
    _applyBranchSnapshot(S._store[S.branch]);

    // Kurs — bulutdagi (S.settings) qiymat ustuvor, chunki boshqa qurilmada o'zgargan bo'lishi mumkin
    if (S.settings?.usdUzs) {
      CUR.usdUzs = S.settings.usdUzs;
      if (S.settings.usdCny) CUR.usdCny = S.settings.usdCny;
    } else if (cloudData) {
      // Bulutda hali kurs saqlanmagan — admin "Saqlash" bosmagan bo'lsa ham,
      // joriy (localdagi) kursni o'zi avtomatik bulutga yozib qo'yadi
      if (!S.settings) S.settings = {};
      S.settings.usdUzs = CUR.usdUzs;
      S.settings.usdCny = CUR.usdCny;
      save();
    }

    // Bank komissiyasi (CNY kirim uchun) — xuddi kurs kabi bulutdagi (S.settings) qiymat ustuvor
    if (S.settings?.bankFeePct != null) {
      CUR.BANK_FEE = S.settings.bankFeePct;
    } else if (cloudData) {
      if (!S.settings) S.settings = {};
      S.settings.bankFeePct = CUR.BANK_FEE;
      save();
    }

    // P1.2 — Yaxlitlash (rounding) qoidasi yoqilganmi. Standart: YOQILGAN
    // (AZIMSHER tasdiqlagan qoida) — Sozlamalar'dan istalgan payt o'chirish
    // mumkin (muammo chiqsa tezkor "feature flag" o'chirish yo'li sifatida).
    if (S.settings?.roundingEnabled == null) {
      if (!S.settings) S.settings = {};
      S.settings.roundingEnabled = true;
      if (cloudData) save();
    }
    if (fwApplyPendingBranchPins()) save();   // v24.8: kirish ekranida o'rnatilgan birinchi parol — bulutga
    syncAppPinFromCloud(); // boshqa qurilmada PIN o'zgargan bo'lsa — shu qurilmaga ham tortib olamiz
    syncBranchPinsFromCloud(); // xuddi shu — filial parollari uchun ham
    syncBranchNamesFromCloud(); // xuddi shu — filial nomlari uchun ham
    syncExtraBranchesFromCloud(); // xuddi shu — qo'shilgan yangi filiallar ro'yxati uchun ham
    // Cloud yuklangan bo'lsa localStorage'ni ham yangilaymiz (yangi filial-tuzilmasi bilan)
    if (cloudData) { S._store[S.branch] = _snapshotBranch(); localStorage.setItem('bp_data', JSON.stringify({...d, branchStore:S._store, activeBranch:S.branch})); }
    await dlLoadDealerData(); // dillerlar — endi alohida, RLS bilan himoyalangan jadvallardan
    await dlLoadOrders();
    await dlLoadStaff();
    if (typeof dpnStart === 'function') dpnStart();   // v23.8: diller yuborgan pul — bildirishnomalar
    if (typeof ntfStart === 'function') ntfStart();   // v24: 🔔 bildirishnomalar (31-migratsiya)
    S._syncBaseline = _numericBaselineSnapshot(); // xavfsiz saqlash uchun boshlang'ich nuqta
    return;
  }
  // Demo (boshlang'ich — sof boshlanish uchun minimal)
  S.products = [];
  S.branch = 'baza';
  S._store = { baza: _emptyBranchDefaults(), f729: _emptyBranchDefaults() };
  _applyBranchSnapshot(S._store.baza);
  S.partners = [
    {id:1, name:"Siz (Ta'sischi)", invested:0, keepPct:100, isFounder:true, color:'#B8700C', av:'ST'},
    {id:2, name:'Investor 1', invested:0, keepPct:50, isFounder:false, color:'#0ea876', av:'I1'},
    {id:3, name:'Investor 2', invested:0, keepPct:30, isFounder:false, color:'#7c3aed', av:'I2'},
  ];
  S.customers = [];
  S.suppliers = [];
  S.settings = { company:FW_BRAND_DEF.name, receipt:'Xaridingiz uchun rahmat!' };
  S.batchCounter = 0;
  S.partnerPeriods = [];
  S.dealers = [];
  S.dealerStock = [];
  S.dealerTxns = [];
  save();
  await dlLoadDealerData(); // birinchi marta ochilganda ham diller jadvallarini tekshiramiz
  S._syncBaseline = _numericBaselineSnapshot(); // xavfsiz saqlash uchun boshlang'ich nuqta
}

// ── MODAL ──────────────────────────────────
function modal(html) {
  const ov = document.getElementById('modal-ov');
  ov.innerHTML = `<div class="modal" role="dialog" aria-modal="true">${html}</div>`;
  fwModalDecorate(ov);
  ov.classList.add('open');
  fwBackPush('modal', () => _closeModalUi());   // v24: «Orqaga» — oyna yopiladi
}
function _closeModalUi() {
  const ov = document.getElementById('modal-ov'); ov.classList.remove('open');
}
function closeModal() { _closeModalUi(); fwBackDone('modal'); }

// ════════════════════════════════════════════
// FILIAL (Baza / 729) ALMASHTIRISH — parol bilan himoyalangan
// ════════════════════════════════════════════
function renderBranchBadge() {
  const b = BRANCHES[S.branch] || BRANCHES.baza;
  const el = document.getElementById('branch-btn');
  const isOwner = !CURRENT_USER || CURRENT_USER.kind === 'owner';
  if (el) {
    el.innerHTML = `${ICONF.building}<span class="branch-nm">${esc(branchName(S.branch))}</span>`;
    el.style.opacity = isOwner ? '1' : '0.6';
    el.title = isOwner ? 'Filial almashtirish' : `Doimiy filial: ${branchName(S.branch)} (faqat administrator almashtira oladi)`;
  }
  // v23: Hamkorlar (investor/ta'sischi) — HAR BIR filialning o'zi: filial o'z investorlari bilan
  // o'zi hisob-kitob qiladi (Baza bilan faqat tovar qarzi va pul qarzi orqali bog'langan).
  const hamkorNav = document.querySelector('[data-page="hamkorlar"]');
  if (hamkorNav) hamkorNav.style.display = '';
}

function openBranchSwitch() {
  // Filial almashtirish — faqat tizim egasi/administratori (role='admin') uchun.
  // Oddiy RBAC xodimi (menejer/kassir/sotuvchi) — bitta filialga doimiy bog'langan
  // (staff.filial), bu ularning ishlash tartibi va xavfsizlik chegarasi.
  if (CURRENT_USER && CURRENT_USER.kind !== 'owner') {
    toast(`⛔ Filial almashtirish faqat administrator uchun ruxsat etilgan. Sizning hisobingiz "${branchName(S.branch)}" filialiga doimiy bog'langan.`, 'error');
    return;
  }
  const activeBranches = Object.keys(BRANCHES).filter(k=>isBranchActive(k) || k===S.branch);
  const inactiveBranches = Object.keys(BRANCHES).filter(k=>!isBranchActive(k) && k!==S.branch);
  modal(`
    <div class="modal-header"><div class="modal-title">🏢 Filial tanlash</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div style="font-size:12px;color:var(--text-muted);margin-bottom:14px">Har bir filialning hisobi (ombor, savdo, kassa) alohida yuritiladi. Almashtirish uchun filial parolini kiriting.</div>
      ${activeBranches.filter(key => !(S.branch!=='baza' && key==='baza')).map(key=>{
        const b = BRANCHES[key];
        const active = S.branch===key;
        return `
        <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 14px;margin-bottom:10px;
          border:1px solid ${active?'var(--gold)':'var(--border)'};border-radius:var(--radius-sm);background:${active?'rgba(184,112,12,0.08)':'transparent'}">
          <div style="font-weight:700">${ICONF.building} ${esc(branchName(key))} ${active?'<span class="badge badge-success" style="margin-left:6px">Joriy</span>':''}</div>
          <div style="display:flex;gap:6px">
            <button class="btn btn-ghost btn-sm" onclick="promptRenameBranch('${key}')" title="Nomini oʻzgartirish">✏️</button>
            <button class="btn btn-ghost btn-sm" onclick="openChangeBranchPin('${key}')">🔑 Parol</button>
            ${!active && key!=='baza'?`<button class="btn btn-ghost btn-sm" onclick="confirmDeactivateBranch('${key}')" title="Nofaol qilish">⏸</button>`:''}
            ${!active?`<button class="btn btn-primary btn-sm" onclick="promptBranchSwitch('${key}')">Oʻtish</button>`:''}
          </div>
        </div>`;
      }).join('')}
      ${inactiveBranches.length ? `
        <div style="font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;margin:14px 0 6px">⏸ Nofaol filiallar</div>
        ${inactiveBranches.map(key=>{
          const b = BRANCHES[key];
          return `<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px;margin-bottom:8px;
            border:1px dashed var(--border);border-radius:var(--radius-sm);opacity:0.65">
            <div style="font-weight:700">${ICONF.building} ${esc(branchName(key))} <span class="badge" style="background:rgba(0,0,0,.08);color:var(--text-muted);margin-left:6px">Nofaol</span></div>
            <button class="btn btn-ghost btn-sm" onclick="reactivateBranch('${key}')">▶️ Faollashtirish</button>
          </div>`;
        }).join('')}` : ''}
      ${S.branch!=='baza'?`<div style="font-size:11px;color:var(--text-muted);margin-top:8px">Bazaga qaytish uchun chiqib, qayta Baza sifatida kiring.</div>`:''}
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Yopish</button>
      <button class="btn btn-danger btn-sm" onclick="appLogout()">🚪 Chiqish</button>
    </div>`);
}

function appLogout() {
  if (!confirm("Tizimdan chiqasizmi? Qayta kirish uchun login/parol (yoki PIN) kerak bo'ladi.")) return;
  if (typeof fwLogoutFlow === 'function') { fwLogoutFlow(_db, CURRENT_USER?.kind === 'staff' ? CURRENT_USER.name : (S.settings?.ownerName || '')); return; }
  try { localStorage.removeItem('fw_off_auth_v1'); localStorage.removeItem('fw_quick_v1'); } catch (_) {}
  sessionStorage.removeItem('bp_auth_ok');
  sessionStorage.removeItem('bp_pin_ok');
  sessionStorage.removeItem('bp_branch_ok');
  sessionStorage.removeItem('bp_staff_id');
  _db?.auth?.signOut?.().catch(()=>{});
  location.reload();
}

function promptBranchSwitch(key) {
  if (!isBranchActive(key)) { toast("Bu filial nofaol — avval uni faollashtiring.", 'error'); return; }
  if (!getBranchPin(key)) { openChangeBranchPin(key); return; }   // v24.8: parol o'rnatilmagan — avval yangi parol
  const b = BRANCHES[key];
  modal(`
    <div class="modal-header"><div class="modal-title">${esc(branchName(key))} — parol</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div class="form-group" style="margin-bottom:0">
        <label class="form-label">Parol</label>
        <input class="form-control" id="bs-pin" type="password" placeholder="Parol" autofocus
          onkeydown="if(event.key==='Enter')confirmBranchSwitch('${key}')">
      </div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="openBranchSwitch()">Orqaga</button>
      <button class="btn btn-primary" onclick="confirmBranchSwitch('${key}')">Oʻtish</button>
    </div>`);
  setTimeout(()=>document.getElementById('bs-pin')?.focus(), 50);
}

function promptRenameBranch(key) {
  const b = BRANCHES[key];
  modal(`
    <div class="modal-header"><div class="modal-title">Nomini oʻzgartirish</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div class="form-group" style="margin-bottom:0">
        <label class="form-label">Yangi nom</label>
        <input class="form-control" id="rn-name" value="${branchName(key)}" autofocus
          onkeydown="if(event.key==='Enter')renameBranch('${key}', document.getElementById('rn-name').value)">
      </div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="openBranchSwitch()">Orqaga</button>
      <button class="btn btn-primary" onclick="renameBranch('${key}', document.getElementById('rn-name').value)">💾 Saqlash</button>
    </div>`);
  setTimeout(()=>document.getElementById('rn-name')?.focus(), 50);
}

async function confirmBranchSwitch(key) {
  // Himoya — faqat UI trigger (openBranchSwitch)ga tayanmasdan, bu funksiyaning
  // o'zi ham rolni tekshiradi. Bu, konsoldan to'g'ridan-to'g'ri chaqirishga
  // (masalan `confirmBranchSwitch('f729')`) qarshi ikkinchi qatlam himoya —
  // real, server tomonidagi ma'lumot himoyasi esa Netlify Function'larda
  // (`requireStaffAuth`) alohida, bu yerdan mustaqil ta'minlangan.
  if (CURRENT_USER && CURRENT_USER.kind !== 'owner') {
    toast("⛔ Filial almashtirish faqat administrator uchun ruxsat etilgan.", 'error');
    closeModal();
    return;
  }
  const val = document.getElementById('bs-pin')?.value || '';
  if (!getBranchPin(key)) { openChangeBranchPin(key); return; }   // v24.8: standart parol yo'q — avval o'rnatiladi
  if (val !== getBranchPin(key)) { toast('❌ Parol notoʻgʻri!','error'); return; }
  if (key === S.branch) { closeModal(); return; }
  // Joriy filialning ma'lumotlarini xotiraga olib qo'yamiz, yangisini yuklaymiz
  S._store[S.branch] = _snapshotBranch();
  S.branch = key;
  if (!S._store[key]) S._store[key] = _emptyBranchDefaults();
  _applyBranchSnapshot(S._store[key]);
  S.cart = []; S.savdoCustId = null; S.savdoMixRows = []; // savat aralashmasin
  localStorage.setItem('bp_active_branch', key);
  sessionStorage.setItem('bp_branch_ok', key);
  S._syncBaseline = _numericBaselineSnapshot(); // yangi filial uchun toza boshlang'ich nuqta
  save();
  renderBranchBadge();
  closeModal();
  auditLog(`Filial almashtirildi: ${branchName(key)}`);
  // Tez javob: yangi filial DARHOL ko'rsatiladi; diller/buyurtma/xodim ro'yxatlari orqada PARALLEL yuklanadi
  // (avval ketma-ket kutilardi — o'tish bir necha soniya "qotib" turardi)
  go(S.page || 'dashboard');
  toast(`${branchName(key)} — faol filial`);
  if (typeof DPN !== 'undefined') { DPN.seen = null; DPN.list = []; dpnLoad(true); }   // yangi filialning diller to'lovlari
  // Buyurtmalar diller ro'yxatiga bog'liq (diller → buyurtma ketma-ket); xodimlar — parallel
  const _w = (p) => p.catch(e => console.warn('filial yuklash:', e));
  await Promise.all([_w(dlLoadDealerData().then(() => dlLoadOrders())), _w(dlLoadStaff())]);
  if (S.branch === key) go(S.page || 'dashboard');   // ro'yxatlar kelgach — sahifa yangilanadi (boshqa filialga o'tilmagan bo'lsa)
}

function openChangeBranchPin(key) {
  const b = BRANCHES[key];
  const isNew = !getBranchPin(key);   // v24.8: parol hali o'rnatilmagan — «joriy parol» so'ralmaydi
  modal(`
    <div class="modal-header"><div class="modal-title">${esc(b.name)} — ${isNew ? 'yangi parol oʻrnating' : 'parolni oʻzgartirish'}</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${isNew ? '<p class="me-hint" style="margin:0 0 10px">Bu filialga hali parol oʻrnatilmagan. Davom etish uchun yangi parol kiriting.</p>'
        : '<div class="form-group"><label class="form-label">Joriy parol</label><input class="form-control" id="bp-old" type="password" placeholder="Joriy parol"></div>'}
      <div class="form-group"><label class="form-label">Yangi parol (4-10 belgi)</label><input class="form-control" id="bp-new" type="password" placeholder="Yangi parol"></div>
      <div class="form-group" style="margin-bottom:0"><label class="form-label">Yangi parol (tasdiq)</label><input class="form-control" id="bp-new2" type="password" placeholder="Yangi parol — qayta"></div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="openBranchSwitch()">Orqaga</button>
      <button class="btn btn-primary" onclick="saveBranchPin('${key}')">💾 Saqlash</button>
    </div>`);
}

function saveBranchPin(key) {
  const oldPin = document.getElementById('bp-old')?.value||'';
  const newPin = document.getElementById('bp-new')?.value||'';
  const newPin2 = document.getElementById('bp-new2')?.value||'';
  const hadPin = !!getBranchPin(key);
  if (hadPin && oldPin !== getBranchPin(key)) { toast('❌ Joriy parol notoʻgʻri!','error'); return; }
  if (!fwPinValid(newPin)) { toast("Parol 4 dan 10 belgigacha boʻlishi kerak!",'error'); return; }
  if (newPin !== newPin2) { toast("Yangi parol ikkalasida ham bir xil boʻlishi kerak!",'error'); return; }
  if (!S.settings.branchPin) S.settings.branchPin = {};
  S.settings.branchPin[key] = newPin;
  localStorage.setItem('bp_branch_pin_'+key, newPin); // shu qurilmada darhol yangilanadi
  save();
  auditLog(`${branchName(key)} paroli ${hadPin ? 'oʻzgartirildi' : 'oʻrnatildi'}`);
  toast('✅ Parol yangilandi!');
  if (hadPin) openBranchSwitch(); else promptBranchSwitch(key);   // birinchi o'rnatishdan keyin — o'tish oynasi
}

