  dashboard:'Bosh sahifa', savdo:'Savdo', qaytarish:'Qaytarishlar', mahsulotlar:'Mahsulotlar',
  ombor:'Ombor (FIFO)', kirim:'Import / Kirim', mijozlar:'Mijozlar',
