function brandLoginLogo(){ return fwBrandLockup('lg on-light'); }

function injectIcons() {
  const g = document.querySelector('[data-glyph="logo"]'); if (g) g.innerHTML = LOGO_GLYPH;
  document.querySelectorAll('.nav-item').forEach(n=>{
    const p = n.getAttribute('data-page'); const s = n.querySelector('.nav-icon');
    if (s && ICONS[p]) s.innerHTML = ICONS[p];
  });
  document.querySelectorAll('[data-icf]').forEach(s=>{
    const k = s.getAttribute('data-icf'); if (ICONF[k]) s.innerHTML = ICONF[k];
  });
  document.querySelectorAll('.m-bn-ic[data-ic]').forEach(s=>{
    const k = s.getAttribute('data-ic'); if (ICONS[k]) s.innerHTML = ICONS[k];
  });
  document.querySelectorAll('[data-ic]:not(.m-bn-ic)').forEach(b=>{
    const k = b.getAttribute('data-ic'); if (ICONS[k]) b.innerHTML = ICONS[k];
  });
}

function toggleSidebar() {
  const sb = document.querySelector('.sidebar');
  if (!sb) return;
  sb.classList.toggle('collapsed');
  localStorage.setItem('bp_sidebar_collapsed', sb.classList.contains('collapsed') ? '1' : '0');
}

function initSidebarState() {
  const sb = document.querySelector('.sidebar');
  if (!sb) return;
  const saved = localStorage.getItem('bp_sidebar_collapsed');
  // Birinchi marta kirganda (saqlangan holat yo'q bo'lsa) — yig'ilgan holatda boshlanadi
  const shouldCollapse = saved===null ? true : saved==='1';
  if (shouldCollapse) sb.classList.add('collapsed');
}

let _hashLock = false;

function go(page) {
  const _perm = PAGE_VIEW_PERMISSION[page];
  if (_perm && !hasPerm(_perm)) {
    toast("Bu bo'limga ruxsatingiz yo'q", 'error');
    return;
  }
  S.page = page;
  document.querySelectorAll('.page-section').forEach(s=>s.classList.remove('active'));
  const el = document.getElementById('pg-'+page);
  if (el) el.classList.add('active');
  document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
  const nav = document.querySelector(`.nav-item[data-page="${page}"]`);
  if (nav) nav.classList.add('active');
  document.querySelectorAll('.m-bn-item').forEach(n=>n.classList.remove('active'));
  const bn = document.querySelector(`.m-bn-item[data-page="${page}"]`);
  if (bn) bn.classList.add('active');
  const nm = NAMES[page]||page;
  const tb = document.getElementById('topbar-title');
  if (tb) tb.innerHTML = ((page==='dashboard') ? `<span class="ox-brand">${fwBrandLockup()}</span>` : `${ICONS[page]||''}<span>${nm}</span>`) + `${S.branch!=='baza'?` <span class="badge badge-warning fw-br-badge" title="${esc(branchName(S.branch))} — alohida hisob" aria-label="${esc(branchName(S.branch))} — alohida hisob">${ICONF.building}</span>`:''}`;
  if (typeof fwFitBrandNames === 'function') requestAnimationFrame(fwFitBrandNames);   // v23.9: nom uzunligiga mos o'lcham
  if (typeof shellSync === 'function') shellSync(page);   // v24.2: telefonda bo'lim — to'liq ekran (✕ → bosh sahifa)
  auditLog(nm+' ochildi');
  renderPage(page);
  document.querySelector('.sidebar').classList.remove('open');
  // v24.5: manzil almashtiriladi, brauzer tarixiga yangi yozuv QO'SHILMAYDI («Orqaga» — shell.js: bitta qadam, kirilgan joyga)
  if (location.hash.slice(1) !== page) { try { history.replaceState(history.state, '', '#' + page); } catch (_) { _hashLock = true; location.hash = page; } }
  if (typeof shellAfterNav === 'function') shellAfterNav();
}

function renderPage(p) {
  const fns = {
    dashboard:pgDashboard, savdo:pgSavdo, qaytarish:pgQaytarish, mahsulotlar:pgMahsulotlar,
    ombor:pgOmbor, kirim:pgKirim, mijozlar:pgMijozlar,
    taminotchilar:pgTaminotchilar, hamkorlar:pgHamkorlar, dillerlar:pgDillerlar, filiallar:pgFiliallar, sotuvchilar:pgSotuvchilar,
    kassalar:pgKassalar, xarajatlar:pgXarajatlar,
    firmakassa: (typeof pgFirmaKassa === 'function' ? pgFirmaKassa : ()=>{}),
    dokon: (typeof pgDokon === 'function' ? pgDokon : ()=>{}),
    hisobot:pgHisobot, sozlamalar:pgSozlamalar, rollar:pgRollar,
    cheklar: (typeof pgCheklar === 'function' ? pgCheklar : ()=>{}), jurnal: (typeof pgJurnal === 'function' ? pgJurnal : ()=>{})
  };
  if (fns[p]) fns[p]();
}

// ════════════════════════════════════════════
// DASHBOARD
// ════════════════════════════════════════════
function calcOverallBalance() {
  const activeBatches = S.batches.filter(b=>b.status!=='empty' && b.status!=='transit');
  // Konsignatsiya tovar — hali bizniki emas (sotilmaguncha ta'minotchiga qarz yozilmaydi),
  // shuning uchun "bizniki" ombor qiymatiga qo'shilmaydi
  const omborQiymati = activeBatches.filter(b=>!b.consignment).reduce((s,b)=>s+(b.qty-b.sold)*(b.costUsd||0),0);
  const konsignatsiyaQiymati = activeBatches.filter(b=>b.consignment).reduce((s,b)=>s+(b.qty-b.sold)*(b.costUsd||0),0);
  const dillerOmborQiymati = S.dealerStock.reduce((s,r)=>s+(r.qty||0)*(r.avgCostUsd||0),0);
  const dillerKassaBox = S.cashboxes.find(k=>k.type==='dealer');
  const dillerQarzi = dillerKassaBox?.bal||0; // dillerlar bizga qarzdor (sotgan, hali topshirmagan pul)
  const liquidCash = S.cashboxes.filter(k=>k.type!=='dealer').reduce((s,k)=>s+(k.cur==='USD'?k.bal:CUR.toUsd(k.bal)),0);
  const mijozQarzi = S.customers.reduce((s,c)=>s+CUR.toUsd(c.debt||0),0);
  const taminotchiQarzi = S.suppliers.reduce((s,sp)=>s+(sp.debt||0),0);
  const hamkorlarPuli = brPartners().reduce((s,p)=>s+(p.invested||0),0);   // v23: shu filial hamkorlari
  const totalAssets = omborQiymati + dillerOmborQiymati + liquidCash + dillerQarzi + mijozQarzi - taminotchiQarzi;
  return { omborQiymati, konsignatsiyaQiymati, dillerOmborQiymati, dillerQarzi, liquidCash, mijozQarzi, taminotchiQarzi, hamkorlarPuli, totalAssets, diff: totalAssets - hamkorlarPuli };
}

// ════════════════════════════════════════════
// v23.7 — BIZNES HOLATI (foyda yoki ziyon): nima bor (aktiv) − kimga qarzmiz − kiritilgan kapital.
// Faqat hisob-kitob (ko'rsatish); pul va qarz qoidalari o'zgarmaydi. Har filial — o'z ko'rsatkichlari.
//  • Ombor — faqat haqiqatda bor va puli to'langan tovar (tannarx): konsignatsiya, yo'ldagi va «ta'minotchidan
//    sotiladi» (omborda yo'q) mahsulotlar bu qatorga kirmaydi; yo'ldagi tovar — alohida qatorda.
//  • Bosh kassa — faqat Bazada (firma darajasida).
// ════════════════════════════════════════════
function fwBizStatus() {
  const usdOf = (k) => k.cur === 'USD' ? (+k.bal || 0) : CUR.toUsd(+k.bal || 0);
  const live = (S.batches || []).filter(b => !b.deleted);
  const left = (b) => Math.max(0, (+b.qty || 0) - (+b.sold || 0));
  const ombor = live.filter(b => b.status !== 'transit' && b.status !== 'empty' && !b.consignment).reduce((s, b) => s + left(b) * (+b.costUsd || 0), 0);
  const yolda = live.filter(b => b.status === 'transit' && !b.consignment).reduce((s, b) => s + left(b) * (+b.costUsd || 0), 0);
  const konsig = live.filter(b => b.status !== 'transit' && b.status !== 'empty' && b.consignment).reduce((s, b) => s + left(b) * (+b.costUsd || 0), 0);
  // Dillerlar — faqat shu filialniki (filial o'z hisobini ko'radi)
  const myDealers = (S.dealers || []).filter(d => (d.filial || 'baza') === S.branch), myDids = new Set(myDealers.map(d => String(d.id)));
  const dillerTovar = (S.dealerStock || []).filter(r => myDids.has(String(r.dealerId))).reduce((s, r) => s + (+r.qty || 0) * (+r.avgCostUsd || 0), 0);
  const kassalar = (S.cashboxes || []).filter(k => k.type !== 'dealer').reduce((s, k) => s + usdOf(k), 0);
  const isBaza = S.branch === 'baza';
  const fk = DS.fk, boshKassa = isBaza && fk ? (+fk.USD || 0) + CUR.toUsd(+fk.UZS || 0) : 0;
  // Filial: kassa yopishda Bosh kassaga topshirgan puli — filialning ishlab topgani (Bosh kassada turibdi), ziyon emas
  const topshirgan = isBaza ? 0 : (S.dailyClosings || []).filter(c => c && c.toFirma).reduce((s, c) => s + (c.entries || [])
    .reduce((a, e) => a + (e.cur === 'USD' ? (+e.amount || 0) : CUR.toUsd(+e.amount || 0)), 0), 0);
  const mijozQarzi = (S.customers || []).reduce((s, c) => s + CUR.toUsd(+c.debt || 0), 0);
  const dillerQarzi = myDealers.reduce((s, d) => s + Math.max(0, +d.debt || 0), 0);
  const filialQarzi = isBaza ? [...new Set([...Object.keys(S.branchDebt || {}), ...Object.keys(S.branchDebtUzs || {})])].filter(k => k !== 'baza').reduce((s, k) => s + flDebtUsdEq(k), 0) : 0;
  const taminotchiQarzi = (S.suppliers || []).reduce((s, x) => s + Math.max(0, +x.debt || 0), 0);
  const bazagaQarz = isBaza ? 0 : flDebtUsdEq(S.branch);
  const ps = typeof brPartners === 'function' ? brPartners() : [];
  const investorlar = ps.filter(p => !p.isFounder).reduce((s, p) => s + (+p.invested || 0), 0);
  const tasischilar = ps.filter(p => p.isFounder).reduce((s, p) => s + (+p.invested || 0), 0);
  const aktiv = ombor + yolda + dillerTovar + kassalar + boshKassa + topshirgan + mijozQarzi + dillerQarzi + filialQarzi;
  const qarzim = taminotchiQarzi + bazagaQarz;
  const kapital = investorlar + tasischilar;
  const sof = aktiv - qarzim;            // biznesning sof qiymati
  const natija = sof - kapital;          // kiritilgan puldan ortiq (foyda) yoki kam (ziyon)
  // Shu oy: savdo foydasi − xarajatlar − hisobdan chiqarish zarari
  const m = td().slice(0, 7);
  const oySavdo = (S.sales || []).filter(x => String(x.date || '').startsWith(m));
  const oyFoyda = oySavdo.reduce((s, x) => s + (+x.profitUsd || 0), 0);
  const oyXarajat = (S.expenses || []).filter(e => String(e.date || '').startsWith(m) && !(e.turi === 'hamkor' && e.kind === 'kirim')).reduce((s, e) => s + (+e.amtUsd || 0), 0);
  const oyHc = typeof fwWriteoffLoss === 'function' ? fwWriteoffLoss(m + '-01', td()) : 0;
  return { ombor, yolda, konsig, dillerTovar, kassalar, boshKassa, topshirgan, boshKassaKnown: !isBaza || !!fk, isBaza, mijozQarzi, dillerQarzi, filialQarzi,
    taminotchiQarzi, bazagaQarz, investorlar, tasischilar, aktiv, qarzim, kapital, sof, natija, oyFoyda, oyXarajat, oyHc, oySof: oyFoyda - oyXarajat - oyHc };
}
function fwBizFkLoad(after) {
  if (S.branch !== 'baza' || DS.fk || DS.fkLoading || DS.fkErr || !_cloudEnabled || !(typeof hasPerm !== 'function' || hasPerm('firma_kassa.view'))) return;
  DS.fkLoading = true;
  fwFirmaCall({ action: 'state' }).then(d => { DS.fk = d.balances || {}; DS.fkErr = ''; }).catch(e => { DS.fkErr = e.message; })
    .finally(() => { DS.fkLoading = false; if (typeof after === 'function') after(); });
}
