function filialOrdersHtml() {
  const orders = S.filialOrders || [];
  if (S.branch === 'baza') {
    const pending = orders.filter(o=>o.toBranch==='baza' && o.status==='pending');
    if (!pending.length) return '';
    return `<div style="background:rgba(184,112,12,0.06);border:1px solid rgba(184,112,12,0.25);border-radius:var(--radius-sm);padding:12px;margin:12px 0">
      <div style="font-size:12px;font-weight:700;color:var(--gold);margin-bottom:8px">📨 Filiallardan buyurtmalar (${pending.length})</div>
      ${pending.map(o=>`<div style="background:var(--bg-card);border-radius:8px;padding:10px;margin-bottom:8px">
        <div style="font-size:11px;color:var(--text-muted);margin-bottom:6px">${ICONF.building} <b>${branchName(o.fromBranch)}</b> — ${fmtD(o.createdAt)} — ${o.items.length} xil mahsulot</div>
        <div style="font-size:12px;margin-bottom:8px">${o.items.map(i=>`<div><code style="color:var(--gold)">${esc(i.sku)}</code> ${esc(i.name)} — <strong>${i.qty}</strong> dona</div>`).join('')}</div>
        <div style="display:flex;gap:6px">
          <button class="btn btn-success btn-sm" onclick="approveFilialOrder('${o.id}')">✅ Berildi (jo'nat)</button>
          <button class="btn btn-danger btn-sm" onclick="rejectFilialOrder('${o.id}')">❌ Rad etish</button>
        </div>
      </div>`).join('')}
    </div>`;
  } else {
    const mine = orders.filter(o=>o.fromBranch===S.branch).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,10);
    if (!mine.length) return '';
    const stLabel = {pending:'⏳ Kutilmoqda', approved:'✅ Berildi', rejected:'❌ Rad etildi'};
    return `<div style="background:rgba(47,111,237,0.06);border:1px solid rgba(47,111,237,0.2);border-radius:var(--radius-sm);padding:12px;margin:12px 0">
      <div style="font-size:12px;font-weight:700;color:var(--blue);margin-bottom:8px">📨 Bazaga yuborilgan soʻrovlarim</div>
      ${mine.map(o=>`<div style="display:flex;justify-content:space-between;align-items:center;font-size:12px;padding:6px 0;border-bottom:1px solid var(--border-light)">
        <span>${fmtD(o.createdAt)} — ${o.items.length} xil mahsulot</span>
        <span class="badge badge-${o.status==='approved'?'success':o.status==='rejected'?'danger':'warning'}">${stLabel[o.status]}</span>
      </div>`).join('')}
    </div>`;
  }
}

function pgOmbor() {
  const el = document.getElementById('pg-ombor');
  const isBaza = S.branch==='baza';
  const filialKeys = Object.keys(BRANCHES).filter(k=>k!=='baza');
  const debtVal = isBaza
    ? filialKeys.reduce((s,k)=>s+flDebtUsdEq(k), 0)
    : flDebtUsdEq(S.branch);
  const debtLabel = isBaza
    ? `Filiallar qarzi (${branchName('baza')}ga)`
    : `${branchName('baza')}ga qarz`;
  const act = S.batches.filter(b=>b.status==='active'), tr = S.batches.filter(b=>b.status==='transit'), emp = S.batches.filter(b=>b.status==='empty');
  const value = S.batches.filter(b=>b.status!=='transit').reduce((s,b)=>s+(b.qty-b.sold)*(b.costUsd||0),0);
  const low = S.products.filter(p=>!p.archived && getStock(p.id)<=p.minStock).length;
  const f = S.omF || '';
  const chip = (k,l,c,n) => `<button class="pm-chip${f===k?' on':''}" style="--c:var(--${c})" onclick="S.omF='${k}';omRender()">${l}<em>${n}</em></button>`;
  el.innerHTML = `
    ${fwHero({ tone:'purple', label:'Ombor qiymati (tannarxda)', badge:'FIFO', big: fwMoneyUsd(value),
      cols:[[act.length,'Faol partiya','var(--emerald)',"S.omF='active';omRender()"],[tr.length,'Yoʻlda','var(--purple)',"S.omF='transit';omRender()"],[low,'Kam mahsulot','var(--red)',"S.pmSt='low';go('mahsulotlar')"]],
      foot: debtVal>0 ? `<div class="fw-hero-note static">${ICONF.building}<span>${esc(debtLabel)}: <b>${CUR.fmtUsd(debtVal)}</b></span></div>` : '' })}
    ${fwActs([
      ['swap','sky','Oʻtkazmalar','openTransfers()'],   // v24.6: so'rov / yuborish / yo'lda / sanab qabul (36 bo'lmasa — avvalgi oyna)
      ['truck','purple','Kirim',"go('kirim')"],
      ['ruler','amber','Revizya',"go('mahsulotlar');openRevision()"],
      ['inventory','emerald','Mahsulotlar',"go('mahsulotlar')"],
    ])}
    ${isBaza && filialKeys.length>1 ? `<section class="ox-card"><div class="ox-card-h"><b>Filiallar boʻyicha qarz</b><span>${CUR.fmtUsd(debtVal)}</span></div>
      ${filialKeys.map(k=>`<div class="dk-kv"><span>${ICONF.building} ${esc(branchName(k))}</span><b style="color:var(--gold)">${flDebtTxt(k)}</b></div>`).join('')}</section>` : ''}
    ${filialOrdersHtml()}
    ${fwSearch('om-q', 'Partiya №, mahsulot kodi yoki nomi', "S.omQ=this.value;omRender()", S.omQ||'')}
    <div class="pm-chips">${chip('','Hammasi','gold',S.batches.length)}${chip('active','Faol','emerald',act.length)}${chip('transit','Yoʻlda','purple',tr.length)}${chip('empty','Tugagan','red',emp.length)}</div>
    <div class="pm-head"><b>FIFO partiyalar</b><span>Eng eski partiyadan sotiladi</span></div>
    <div id="om-list"></div>`;
  omRender();
}
function omRender() {
  const box = document.getElementById('om-list'); if (!box) return;
  document.querySelectorAll('#pg-ombor .pm-chip').forEach(b=>b.classList.toggle('on', b.getAttribute('onclick')===`S.omF='${S.omF||''}';omRender()`));
  const q = String(S.omQ||'').trim().toLowerCase();
  const list = S.batches.slice().reverse().filter(b=>{
    if (S.omF && b.status!==S.omF) return false;
    if (!q) return true;
    const p = S.products.find(x=>x.id===b.pid);
    return [b.bno, p?.sku, p?.name, b.origin].some(v=>String(v||'').toLowerCase().includes(q));
  });
  if (!list.length) { box.innerHTML = fwEmpty('inventory', 'Partiya topilmadi', q ? 'Qidiruvni oʻzgartiring.' : 'Kirim qilinganda partiyalar shu yerda chiqadi.'); return; }
  box.innerHTML = `<div class="fw-list">${list.slice(0,300).map(b=>{
    const p=S.products.find(x=>x.id===b.pid);
    const rem=b.qty-b.sold, pct=b.qty>0?Math.max(0,Math.min(100,Math.round(rem/b.qty*100))):0;
    const isTransit=b.status==='transit', isEmpty=b.status==='empty';
    const c = isTransit?'purple':isEmpty?'red':rem<=3?'amber':'emerald';
    return `<article class="om-b" style="--c:var(--${c})">
      <div class="om-b-h"><code>${esc(b.bno)}</code><span class="dk-st">${isTransit?'Yoʻlda':isEmpty?'Tugagan':rem<=3?'Kam qoldi':'Omborda'}</span><time>${fmtD(b.date)}</time></div>
      <b class="om-b-n">${esc(p?.name||'—')}</b>
      <small class="om-b-s">${esc(p?.sku||'')}${b.origin?` · ${esc(b.origin)}`:''} · ${b.cur==='CNY'?'CNY':b.cur==='UZS'?'Soʻm':'USD'}${b.accCur==='UZS'?' → hisob soʻmda':''}</small>
      <div class="om-b-q"><span><b>${rem}</b> / ${b.qty} ${esc(p?.unit||'dona')}</span><i><em style="width:${pct}%"></em></i><b class="om-b-c">${b.accCur==='UZS'&&+b.costUzs>0?fwNum(b.costUzs)+' soʻm':CUR.fmtUsd(b.costUsd||0)}</b>
        <button class="dk-x" onclick="deleteBatch('${escJsAttr(String(b.id))}')" title="Partiyani oʻchirish" aria-label="Partiyani oʻchirish">${ICONF.trash}</button></div>
      ${isTransit?`<div class="fw-pc-a"><button class="fw-btn ok" onclick="openArrivalCustoms('${escJsAttr(b.bno)}')">${ICONF.check}<span>Keldi — omborga qabul qilish</span></button></div>`:''}
      </article>`; }).join('')}</div>`;
}

// ── Butun partiyani (bir xil #bno ga tegishli BARCHA mahsulot qatorlarini) o'chirish ──
async function deleteBatchGroup(bno) {
  const list = S.batches.filter(b=>b.bno===bno);
  if (!list.length) { toast('Partiya topilmadi', 'error'); return; }
  const totalSold = list.reduce((s,b)=>s+(b.sold||0), 0);
  const totalQty = list.reduce((s,b)=>s+b.qty, 0);
  if (totalSold > 0) {
    if (!confirm(`⚠️ DIQQAT: Partiya #${bno}dan jami ${totalSold} dona SOTILGAN. Butun partiyani o'chirsangiz, o'sha savdolarning tannarx hisob-kitobi buziladi. Baribir o'chirasizmi?`)) return;
  } else {
    if (!confirm(`Partiya #${bno} (${list.length} xil mahsulot, jami ${totalQty} dona) BUTUNLAY o'chirilsinmi?`)) return;
  }
  // v23.2 (F4b): o'chirish — SERVERDA (partiya FIFO'dan chiqadi, tarix saqlanadi); rad etilsa hech narsa o'zgarmaydi
  if (fwLedgerRemote()) {
    try { await fwLedgerCall('stock-debt-ops', { kind:'batch_delete', payload:{ localIds: list.map(b=>String(b.id)) } }); }
    catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  }
  S.batches = S.batches.filter(b=>b.bno!==bno);
  list.forEach(b=>markDeleted('batches', b.id));
  auditLog(`Butun partiya o'chirildi: #${bno} — ${list.length} xil mahsulot, ${totalQty} dona`);
  save();
  toast(`✅ Partiya #${bno} butunlay o'chirildi!`, 'warning');
  fwCleanupOrphans([...new Set(list.map(b => b.pid))], true);
  if (S.page==='kirim') pgKirim(); else pgOmbor();
}

// ── Alohida partiyani o'chirish (yo'lda yoki kelgan — ikkalasi ham) ──
async function deleteBatch(batchId) {
  const b = S.batches.find(x=>String(x.id)===String(batchId));
  if (!b) { toast('Partiya topilmadi', 'error'); return; }
  const p = S.products.find(x=>x.id===b.pid);
  if ((b.sold||0) > 0) {
    if (!confirm(`⚠️ DIQQAT: Bu partiyadan ${b.sold} dona SOTILGAN. O'chirsangiz, o'sha savdolarning tannarx hisob-kitobi buziladi. Baribir o'chirasizmi?`)) return;
  } else {
    if (!confirm(`Partiya #${b.bno} (${p?.name||''}, ${b.qty} dona) o'chirilsinmi?`)) return;
  }
  if (fwLedgerRemote()) {
    try { await fwLedgerCall('stock-debt-ops', { kind:'batch_delete', payload:{ localIds:[String(batchId)] } }); }
    catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  }
  S.batches = S.batches.filter(x=>x.id!==b.id);   // tugma ID'ni matn sifatida beradi — haqiqiy (raqamli) ID ishlatiladi
  markDeleted('batches', b.id);
  auditLog(`Partiya o'chirildi: #${b.bno} — ${p?.name||''} (${b.qty} dona)`);
  save();
  toast("✅ Partiya o'chirildi!", 'warning');
  fwCleanupOrphans([b.pid], true);
  if (S.page==='kirim') pgKirim(); else pgOmbor();
}

