function openSendTo729() {
  if (S.branch !== 'baza') { toast('Bu amal faqat Bazadan bajariladi!','error'); return; }
  const filialKeys = Object.keys(BRANCHES).filter(k=>k!=='baza');
  if (!filialKeys.length) { toast('Hali filial qoʻshilmagan!','error'); return; }
  if (filialKeys.length === 1) { S.branchTransferTarget = filialKeys[0]; openSendToBranchModal(); return; }
  // Bir nechta filial bo'lsa — avval qaysi biriga yuborishni so'raymiz
  modal(`
    <div class="modal-header"><div class="modal-title">🏪 Qaysi filialga yuborasiz?</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${filialKeys.map(k=>`<button class="btn btn-ghost" style="width:100%;justify-content:flex-start;margin-bottom:8px" onclick="S.branchTransferTarget='${k}';openSendToBranchModal()">${ICONF.building} ${esc(branchName(k))}</button>`).join('')}
    </div>`);
}

function openSendToBranchModal() {
  const target = S.branchTransferTarget;
  S.branchTransferCart = [];
  modal(`
    <div class="modal-header"><div class="modal-title">🏪 ${branchName(target)}ga tovar yuborish</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div style="font-size:11px;color:var(--text-muted);margin-bottom:12px">Tovar diller narxida yuboriladi. Baza ombiridan ayiriladi, ${branchName(target)}ning ombiriga kiradi. <b>Qarz hosil bo'lmaydi</b> — faqat filial sotganda avtomatik qarz yoziladi.</div>
      <div style="position:relative;margin-bottom:10px">
        <input type="text" class="form-control" id="st729-q" placeholder="Mahsulot qidirish..." oninput="st729Search(this.value)" autocomplete="off">
        <div id="st729-dd" style="display:none;position:absolute;top:100%;left:0;right:0;background:var(--bg-card);border:1px solid var(--border);border-top:none;border-radius:0 0 var(--radius-sm) var(--radius-sm);max-height:260px;overflow-y:auto;z-index:999"></div>
      </div>
      <div id="st729-rows"></div>
      <div id="st729-total" style="text-align:right;font-weight:700;margin-top:8px"></div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" onclick="confirmSendTo729()">🏪 Yuborish</button>
    </div>`);
}

function st729Search(q) {
  const dd = document.getElementById('st729-dd');
  if (!dd) return;
  if (!q || !q.length) { dd.style.display='none'; return; }
  const r = productSearchMatch(S.products, q).filter(p=>getStock(p.id)>0).slice(0,15);
  if (!r.length) { dd.innerHTML='<div style="padding:10px;color:var(--text-muted);font-size:12px">Topilmadi yoki qoldiq yo\'q</div>'; dd.style.display='block'; return; }
  dd.innerHTML = r.map(p=>{
    const st=getStock(p.id), cost=getCostFIFO(p.id), dp=optPrice(p,cost);
    return `<div onclick="st729Add(${p.id})" style="padding:9px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid var(--border-light)"
      onmouseover="this.style.background='var(--bg-hover)'" onmouseout="this.style.background=''">
      <code style="color:var(--gold)">${esc(p.sku)}</code> ${esc(p.name)} <span style="color:var(--text-muted)">(${st} dona, diller narx: ${CUR.fmtUsd(dp)})</span>
    </div>`;
  }).join('');
  dd.style.display='block';
}

function st729Add(pid) {
  const p = S.products.find(x=>x.id===pid); if (!p) return;
  const st = getStock(pid);
  const existing = S.branchTransferCart.find(r=>r.pid===pid);
  if (existing) { if (existing.qty<st) existing.qty++; }
  else S.branchTransferCart.push({pid, qty:1});
  const q=document.getElementById('st729-q'); if(q) q.value='';
  const dd=document.getElementById('st729-dd'); if(dd) dd.style.display='none';
  st729Render();
}

function st729SetQty(pid, val) {
  const r = S.branchTransferCart.find(x=>x.pid===pid); if (!r) return;
  const st = getStock(pid);
  let qty = parseInt(val)||1;
  if (qty>st) qty=st; if (qty<1) qty=1;
  r.qty = qty;
  st729Render();
}

function st729Remove(pid) {
  S.branchTransferCart = S.branchTransferCart.filter(r=>r.pid!==pid);
  st729Render();
}

function st729Render() {
  const rowsEl = document.getElementById('st729-rows');
  const totEl = document.getElementById('st729-total');
  if (!rowsEl) return;
  let total = 0;
  rowsEl.innerHTML = S.branchTransferCart.map(r=>{
    const p = S.products.find(x=>x.id===r.pid); if (!p) return '';
    const cost = getCostFIFO(p.id), dp = optPrice(p,cost);
    const line = dp*r.qty; total += line;
    return `<div style="display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid var(--border-light)">
      <div style="flex:1;font-size:12px"><code style="color:var(--gold)">${esc(p.sku)}</code> ${esc(p.name)}</div>
      <input type="number" class="form-control" style="width:64px;margin:0;padding:6px;font-size:12px;text-align:center" value="${r.qty}" min="1" max="${getStock(p.id)}" oninput="st729SetQty(${p.id},this.value)">
      <div style="width:90px;text-align:right;font-weight:700;color:var(--gold);font-size:12px">${CUR.fmtUsd(line)}</div>
      <button class="btn btn-danger btn-sm btn-icon" onclick="st729Remove(${p.id})">✕</button>
    </div>`;
  }).join('') || '<p style="color:var(--text-muted);font-size:12px;text-align:center;padding:10px">Mahsulot tanlanmagan</p>';
  if (totEl) totEl.textContent = S.branchTransferCart.length ? `Jami (diller narxida): ${CUR.fmtUsd(total)}` : '';
}

// Umumiy: Bazadan istalgan filialga tovar o'tkazish (items: [{pid, qty}]) — diller narxida, konsignatsiya.
// Qaytaradi: {cnt, totalVal} yoki xato bo'lsa null (toast ko'rsatadi)
async function transferItemsToBranch(items, targetKey) {
  if (S.branch !== 'baza') { toast('Bu amal faqat Bazadan bajariladi!','error'); return null; }
  if (!BRANCHES[targetKey] || targetKey==='baza') { toast('Filial topilmadi!','error'); return null; }
  for (const r of items) {
    if (r.qty > getStock(r.pid)) {
      const p = S.products.find(x=>x.id===r.pid);
      toast(`Qoldiq yetarli emas: ${p?.name||r.pid} (bor: ${getStock(r.pid)}, kerak: ${r.qty})`,'error');
      return null;
    }
  }
  if (!S._store[targetKey]) S._store[targetKey] = _emptyBranchDefaults();
  const fb = S._store[targetKey];
  if (fb.batchCounter===undefined) fb.batchCounter = 0;
  if (!fb.batches) fb.batches = [];

  // v23.2 (F4b): Baza omboridan chiqarish (FIFO), filial partiyalari va ichki "savdo" yozuvi — SERVERDA,
  // bitta tranzaksiyada. Tannarx (Bazadagi FIFO) server javobidan olinadi.
  if (fwLedgerRemote()) {
    const rowsP = items.map(r=>({ r, p:S.products.find(x=>x.id===r.pid) })).filter(x=>x.p);
    if (!rowsP.length) return null;
    const ids = fwStableIds('transfer:'+targetKey, [targetKey, rowsP.map(x=>[x.r.pid,x.r.qty])], rowsP.length + 1);
    const tb = [];
    const saleItems = rowsP.map((x,i)=>{
      const dealerPrice = Math.round(optPrice(x.p, getCostFIFO(x.p.id))*10000)/10000;
      tb.push({ pid:x.r.pid, localId:String(ids[i]), costUsd:dealerPrice, qty:x.r.qty, bno:'F' + String((fb.batchCounter||0)+1+i).padStart(2,'0'), date:td() });
      return { pid:x.r.pid, sku:x.p.sku, name:x.p.name, qty:x.r.qty, sellUsd:dealerPrice, lineUsd:dealerPrice*x.r.qty };
    });
    const inv = fwNextDocNo(targetKey.toUpperCase() + '-', S.sales);
    const custName = `${branchName(targetKey)} (ichki oʻtkazma)`;
    let res;
    try {
      res = await fwLedgerCall('stock-debt-ops', { kind:'stock_out', payload:{ reason:'transfer', target:targetKey,
        items: rowsP.map(x=>({ pid:x.r.pid, qty:x.r.qty })), targetBatches: tb,
        transferSale: { localId:String(ids[rowsP.length]), inv, custName, items: saleItems.map(i=>({ pid:i.pid, sku:i.sku, name:i.name, qty:i.qty, sellUsd:i.sellUsd })) } } });
    } catch(e) { toast('⛔ ' + e.message, 'error'); return null; }
    fwStableIdsDone('transfer:'+targetKey);
    const firstCost = new Map((res.items||[]).map(x=>[+x.pid, +x.firstCost]));
    tb.forEach(t => {
      fb.batchCounter = (fb.batchCounter||0) + 1;
      fb.batches.push({ id:+t.localId, pid:t.pid, bno:t.bno, origin:'Bazadan (filial)', cur:'USD', qty:t.qty, sold:0, costUsd:t.costUsd, bankFeeUsd:0, suppId:null,
        consignment:false, fromBranch:'baza', rates:{usdUzs:CUR.usdUzs, usdCny:CUR.usdCny}, date:td(), status:'active', items:[] });
    });
    if (res.authority) fwApplyLedger(res.authority);
    const totalVal = saleItems.reduce((s2,i)=>s2+i.lineUsd,0);
    const costTotal = saleItems.reduce((s2,i)=>s2+i.qty*(firstCost.get(+i.pid)||0),0);
    S.sales.push({ id:ids[rowsP.length], date:td(), inv, custId:null, custName,
      items: saleItems.map(i=>({ ...i, costUsd:firstCost.get(+i.pid)||0 })),
      subtotalUsd:totalVal, disc:0, discUsd:0, totalUsd:totalVal, paidUsd:0, debtUsd:totalVal,
      payType:'debt', boxId:null, mixedRows:null, profitUsd: totalVal-costTotal, status:'done', isFilialTransfer:true });
    return { cnt: saleItems.length, totalVal };
  }

  let totalVal = 0, cnt = 0;
  const saleItems = [];
  items.forEach(r => {
    const p = S.products.find(x=>x.id===r.pid); if (!p) return;
    const cost = getCostFIFO(p.id);
    const dealerPrice = Math.round(optPrice(p,cost)*10000)/10000;
    deductFIFO(r.pid, r.qty); // Baza ombiridan ayiriladi
    const bno = 'F' + String(++fb.batchCounter).padStart(4,'0');
    fb.batches.push({
      id:uid(), pid:r.pid, bno, origin:'Bazadan (filial)', cur:'USD',
      qty:r.qty, sold:0, costUsd:dealerPrice, bankFeeUsd:0, suppId:null,
      consignment:false, fromBranch:'baza',
      rates:{usdUzs:CUR.usdUzs, usdCny:CUR.usdCny}, date:td(), status:'active', items:[]
    });
    saleItems.push({pid:r.pid, sku:p.sku, name:p.name, qty:r.qty, costUsd:cost, sellUsd:dealerPrice, lineUsd:dealerPrice*r.qty});
    totalVal += dealerPrice*r.qty; cnt++;
  });

  // Bazaning o'z hisobotida foydasi darhol ko'rinishi uchun — "sotuv" sifatida yoziladi
  // (haqiqiy pul hali kelmagan — u faqat filial to'lov qilganda kassaga tushadi, shuning uchun "qarz" holatida)
  if (saleItems.length) {
    const costTotal = saleItems.reduce((s,i)=>s+i.qty*i.costUsd,0);
    const inv = fwNextDocNo(targetKey.toUpperCase() + '-', S.sales);
    S.sales.push({
      id:uid(), date:td(), inv,
      custId:null, custName:`${branchName(targetKey)} (ichki oʻtkazma)`,
      items:saleItems,
      subtotalUsd:totalVal, disc:0, discUsd:0, totalUsd:totalVal,
      paidUsd:0, debtUsd:totalVal,
      payType:'debt', boxId:null, mixedRows:null,
      profitUsd: totalVal-costTotal,
      status:'done', isFilialTransfer:true
    });
  }
  return { cnt, totalVal };
}

async function confirmSendTo729() {
  if (!S.branchTransferCart.length) { toast('Mahsulot tanlanmagan!','error'); return; }
  const target = S.branchTransferTarget;
  const res = await transferItemsToBranch(S.branchTransferCart, target);
  if (!res) return;
  auditLog(`🏪 ${branchName(target)}ga yuborildi: ${res.cnt} ta mahsulot, ${CUR.fmtUsd(res.totalVal)} (diller narxida)`);
  save(); closeModal(); pgOmbor();
  toast(`✅ ${res.cnt} ta mahsulot ${branchName(target)}ga yuborildi! Qarz faqat sotilganda yoziladi.`);
}

// ── FILIAL → BAZA: BUYURTMA (ZAKAZ) — diller kabi so'rov yuboradi, Baza "Berildi" bilan tasdiqlaydi ──
function openRequestFromBaza() {
  if (S.branch === 'baza') { toast('Bu amal faqat filialda bajariladi!','error'); return; }
  S.branchTransferCart = [];
  modal(`
    <div class="modal-header"><div class="modal-title">📦 Bazadan tovar soʻrash</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div style="font-size:11px;color:var(--text-muted);margin-bottom:12px">Kerakli mahsulot va miqdorni belgilang — Bazaga soʻrov (buyurtma) yuboriladi. Baza tasdiqlab "Berildi" desa, tovar avtomatik oʻtkaziladi.</div>
      <div style="position:relative;margin-bottom:10px">
        <input type="text" class="form-control" id="st729-q" placeholder="Mahsulot qidirish..." oninput="reqSearch(this.value)" autocomplete="off">
        <div id="st729-dd" style="display:none;position:absolute;top:100%;left:0;right:0;background:var(--bg-card);border:1px solid var(--border);border-top:none;border-radius:0 0 var(--radius-sm) var(--radius-sm);max-height:260px;overflow-y:auto;z-index:999"></div>
      </div>
      <div id="st729-rows"></div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" onclick="submitFilialOrder()">📨 Soʻrov yuborish</button>
    </div>`);
}

// Diqqat: filial o'z ombiridagi qoldiqni emas, Bazaning umumiy katalogini qidiradi (u yerda ombor yo'q,
// shuning uchun faqat mahsulot nomi/kod bo'yicha qidiramiz, qoldiq talab qilinmaydi)
function reqSearch(q) {
  const dd = document.getElementById('st729-dd');
  if (!dd) return;
  if (!q || !q.length) { dd.style.display='none'; return; }
  const r = productSearchMatch(S.products, q).slice(0,15);
  if (!r.length) { dd.innerHTML='<div style="padding:10px;color:var(--text-muted);font-size:12px">Topilmadi</div>'; dd.style.display='block'; return; }
  dd.innerHTML = r.map(p=>`<div onclick="st729Add(${p.id})" style="padding:9px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid var(--border-light)"
    onmouseover="this.style.background='var(--bg-hover)'" onmouseout="this.style.background=''">
    <code style="color:var(--gold)">${esc(p.sku)}</code> ${esc(p.name)}
  </div>`).join('');
  dd.style.display='block';
}

function submitFilialOrder() {
  if (S.branch === 'baza') { toast('Bu amal faqat filialda bajariladi!','error'); return; }
  if (!S.branchTransferCart.length) { toast('Mahsulot tanlanmagan!','error'); return; }
  if (!S.filialOrders) S.filialOrders = [];
  const items = S.branchTransferCart.map(r=>{
    const p = S.products.find(x=>x.id===r.pid);
    return { pid:r.pid, sku:p?.sku||'', name:p?.name||'', qty:r.qty };
  });
  S.filialOrders.push({
    id:uid(), fromBranch:S.branch, toBranch:'baza', items,
    status:'pending', createdAt:new Date().toISOString(), resolvedAt:null
  });
  auditLog(`📨 ${branchName(S.branch)} Bazadan tovar soʻradi: ${items.length} xil mahsulot`);
  save(); closeModal(); pgOmbor();
  toast('✅ Soʻrov Bazaga yuborildi! Tasdiqlanishini kuting.');
}

async function approveFilialOrder(orderId) {
  if (S.branch !== 'baza') { toast('Bu amal faqat Bazadan bajariladi!','error'); return; }
  const order = (S.filialOrders||[]).find(o=>o.id===orderId);
  if (!order || order.status!=='pending') return;
  const res = await transferItemsToBranch(order.items.map(i=>({pid:i.pid, qty:i.qty})), order.fromBranch);
  if (!res) return; // xato bo'lsa (qoldiq yetarli emas) — buyurtma "pending" holida qoladi
  order.status = 'approved';
  order.resolvedAt = new Date().toISOString();
  auditLog(`✅ ${branchName(order.fromBranch)} buyurtmasi berildi: ${res.cnt} ta mahsulot, ${CUR.fmtUsd(res.totalVal)}`);
  save(); pgOmbor();
  toast(`✅ Buyurtma berildi! ${res.cnt} ta mahsulot ${branchName(order.fromBranch)}ga oʻtkazildi.`);
}

function rejectFilialOrder(orderId) {
  if (S.branch !== 'baza') { toast('Bu amal faqat Bazadan bajariladi!','error'); return; }
  const order = (S.filialOrders||[]).find(o=>o.id===orderId);
  if (!order || order.status!=='pending') return;
  order.status = 'rejected';
  order.resolvedAt = new Date().toISOString();
  auditLog(`❌ ${branchName(order.fromBranch)} buyurtmasi rad etildi`);
  save(); pgOmbor();
  toast('Buyurtma rad etildi.');
}

// ════════════════════════════════════════════
// KIRIM — Ko'p mahsulot, CNY+USD
// ════════════════════════════════════════════
// ════════════════════════════════════════════
// KIRIM — yuqoridagi xulosa (yangi uslub). Pastdagi forma va
// «Kirim tarixi» o'zgarmagan — bu blok faqat ustiga qo'shiladi.
// ════════════════════════════════════════════
function kirimPeriodRange() {
  const per = S.kirimPeriod || 'today';
  const d0 = new Date(); const iso = d => d.toISOString().slice(0,10);
  if (per==='today') return [td(), td()];
  if (per==='yesterday') { const y=new Date(); y.setDate(y.getDate()-1); return [iso(y), iso(y)]; }
  if (per==='month') {   // tanlangan oy (standart — joriy oy); joriy oyda bugungacha
    const ym = S.kirimYm || td().slice(0,7);
    const [y,m] = ym.split('-').map(Number);
    const end = `${ym}-${String(new Date(y,m,0).getDate()).padStart(2,'0')}`;
    return [`${ym}-01`, ym===td().slice(0,7) ? td() : end];
  }
  if (per==='custom' && S.kirimDay) return [S.kirimDay, S.kirimDay];
  return [td(), td()];
}
// Kelgan sana: «Yetib keldi» bosilgan kun (arrivedDate); eski yozuvlarda — kirim sanasi. Yo'ldagida — yo'q.
function batchArrivalDate(b) { return b.status==='transit' ? null : (b.arrivedDate || b.date || null); }
function kirimPeriodBatches() {
  const [a,b] = kirimPeriodRange();
  return S.batches.filter(x => { const d = batchArrivalDate(x); return d && d>=a && d<=b && !(x.origin||'').startsWith('Qaytarish —'); });
}
function kirimSummaryHtml() {
  const list = kirimPeriodBatches();
  const sum = list.reduce((s,b)=>s+(b.qty||0)*(b.costUsd||0),0);
  const cnt = new Set(list.map(b=>b.bno)).size;
  const prods = new Set(list.map(b=>b.pid)).size;
  const units = list.reduce((s,b)=>s+(b.qty||0),0);
  const n = v => Math.round(+v||0).toLocaleString('en-US').replace(/,/g,' ');
  const usd = v => '$'+(Math.round((+v||0)*100)/100).toLocaleString('en-US',{maximumFractionDigits:2}).replace(/,/g,' ');
  const [a,b] = kirimPeriodRange(); const dmy = d => d.split('-').reverse().join('.');
  const per = S.kirimPeriod || 'today';
  const kTransitCnt = new Set(S.batches.filter(x=>x.status==='transit' && !(x.origin||'').startsWith('Qaytarish —')).map(x=>x.bno)).size;
  const tab = (k,l) => `<button class="kr-tab${per===k?' on':''}" onclick="kirimSetPeriod('${k}')">${l}</button>`;
  return `
  <section class="ox-hero kr-hero" aria-label="Kirim summasi">
    <div class="ox-hero-top"><span>Kirim summasi</span><span class="ox-date">${a===b?dmy(a):dmy(a)+' – '+dmy(b)}</span></div>
    <div class="ox-hero-big">${usd(sum)}</div>
    <div class="ox-hero-cols">
      <div><b>${n(cnt)}</b><span>Kirimlar</span></div>
      <div><b>${n(prods)}</b><span>Mahsulotlar</span></div>
      <div><b style="color:var(--sky)">${n(units)} dona</b><span>Birlik</span></div>
    </div>
  </section>
  <button class="kr-add" onclick="S.kirimFormOpen?kirimCloseForm():kirimScrollToForm()" aria-expanded="${!!S.kirimFormOpen}">
    <span class="kr-add-l">${ICONF.add}<span>Kirim qoʻshish</span></span><span class="kr-add-x" aria-label="Yopish">${ICONF.close}</span></button>
  <div class="kr-4">
    <button class="kr-q" style="--c:var(--sky)" onclick="openExcelImportModal()">${ICONF.upload}<span>Excelʼdan</span></button>
    <button class="kr-q${S.kirimStatusFilter==='transit'?' on':''}" style="--c:var(--purple)" onclick="kirimSetStatusFilter('transit')" aria-pressed="${S.kirimStatusFilter==='transit'}">${ICONF.truck}<span>Yoʻlda</span>${kTransitCnt?`<em>${kTransitCnt}</em>`:''}</button>
    <button class="kr-q${S.kirimStatusFilter==='active'?' on':''}" style="--c:var(--emerald)" onclick="kirimSetStatusFilter('active')" aria-pressed="${S.kirimStatusFilter==='active'}">${ICONF.check}<span>Keldi</span>${cnt?`<em>${cnt}</em>`:''}</button>
    <button class="kr-q" style="--c:#60a5fa" onclick="kirimStatsSheet()">${ICONF.chart}<span>Statistika</span></button>
  </div>
  <div class="kr-search">
    ${ICONF.search}
    <input type="search" id="kh-q" placeholder="Partiya, taʼminotchi yoki mahsulot kodi" autocomplete="off" spellcheck="false"
      value="${esc(S.kirimQ||'')}" oninput="kirimHistorySearch(this.value)">
    <button type="button" class="kr-search-x" onclick="kirimHistorySearch('');document.getElementById('kh-q').value='';document.getElementById('kh-q').focus()" aria-label="Tozalash" ${S.kirimQ?'':'hidden'}>${ICONF.close}</button>
  </div>
  <div class="kr-tabs" role="tablist">${tab('today','Bugun')}${tab('yesterday','Kecha')}
    <button class="kr-tab${per==='month'?' on':''}" onclick="kirimMonthPicker(${(S.kirimYm||td()).slice(0,4)})">${per==='month' ? `${UZ_MONTHS[+(S.kirimYm||td()).slice(5,7)-1]}${(S.kirimYm||td()).slice(0,4)!==td().slice(0,4)?' '+(S.kirimYm||td()).slice(2,4):''}` : 'Oy'}</button>
    <label class="kr-tab kr-cal${per==='custom'?' on has-d':''}" aria-label="Sana tanlash">${per==='custom'&&S.kirimDay ? `<span>${S.kirimDay.slice(8,10)}.${S.kirimDay.slice(5,7)}.${S.kirimDay.slice(2,4)}</span>` : ICONF.calendar}<input type="date" max="${td()}" value="${S.kirimDay||td()}" onchange="if(this.value){S.kirimDay=this.value;kirimSetPeriod('custom')}"></label>
  </div>`;
}
// «Oy» — qaysi oyni ko'rish: yil ‹ › va 12 oy (kelajakdagi oylar o'chiq)
function kirimMonthPicker(year) {
  const cy = +td().slice(0,4), cm = +td().slice(5,7);
  const sel = S.kirimPeriod==='month' ? (S.kirimYm||td().slice(0,7)) : '';
  const html = `<div class="kst-pk">
    <div class="kst-yr"><button class="kst-nav" onclick="kirimMonthPicker(${year-1})" aria-label="Oldingi yil">‹</button><b>${year}</b>
      <button class="kst-nav" onclick="kirimMonthPicker(${year+1})" ${year>=cy?'disabled':''} aria-label="Keyingi yil">›</button></div>
    <div class="kst-mg">${UZ_MONTHS.map((m,i)=>{ const ym=`${year}-${String(i+1).padStart(2,'0')}`; const fut = year>cy || (year===cy && i+1>cm);
      return `<button class="kst-m${ym===sel?' on':''}" ${fut?'disabled':''} onclick="S.kirimYm='${ym}';closeSheet();kirimSetPeriod('month')">${m}</button>`; }).join('')}</div>
  </div>`;
  const box = document.querySelector('#bs-ov .bs-body');
  if (box && box.querySelector('.kst-pk') && !box.querySelector('#kst')) { box.innerHTML = html; return; }
  openSheet({ic:'calendar', c:'sky', title:'Oyni tanlang', sub:'Shu oyda kelgan kirimlar ko\u02bbrsatiladi', body: html});
}
function kirimSetPeriod(p) {
  S.kirimPeriod = p;
  const el = document.getElementById('pg-kirim'); if (!el) return;
  // Faqat xulosa qismini yangilaymiz — forma va tarixdagi yozilgan qiymatlar joyida qoladi
  const tmp = document.createElement('div'); tmp.innerHTML = kirimSummaryHtml();
  el.querySelectorAll(':scope > .kr-hero, :scope > .kr-add, :scope > .kr-4, :scope > .kr-search, :scope > .kr-tabs').forEach(n=>n.remove());
  const kurs = document.getElementById('k-kurs');
  if (kurs) kurs.after(...tmp.children); else el.prepend(...tmp.children);
  const hl = document.getElementById('kh-list'); if (hl) hl.innerHTML = kirimHistoryHtml();
}
// «Kirim qo'shish» — alohida oyna: faqat shu tugma (sarlavha sifatida) va forma ko'rinadi
document.addEventListener('pointerdown', e=>{
  if (e.target.closest('.kf-search')) return;
  document.querySelectorAll('.kf-dd').forEach(d=>{ d.hidden = true; });
});
// Yo'lda / Keldi — tarixni holat bo'yicha ko'rsatish (qayta bosilsa — hammasi)
function kirimSetStatusFilter(st) {
  S.kirimStatusFilter = (S.kirimStatusFilter===st) ? '' : st;
  kirimSetPeriod(S.kirimPeriod || 'today');
  document.getElementById('k-hist-card')?.scrollIntoView({behavior:'smooth', block:'start'});
}
// v24.5 (egasi talabi): ikki qavat X yo'q — telefonda forma yuqoridagi yagona ✕ (va «Orqaga») bilan yopiladi;
// forma ochilishi — bitta qadam (✕ avval formani yopadi, keyingi ✕ — bo'limdan chiqadi)
function kirimScrollToForm() {
  S.kirimFormOpen = true;
  const pgEl = document.getElementById('pg-kirim'); pgEl?.classList.add('k-mode-form');
  const f = document.getElementById('k-form-card'); if (f) f.hidden = false;
  const b = pgEl?.querySelector('.kr-add'); if (b) b.setAttribute('aria-expanded','true');
  if (typeof fwBackPush === 'function') fwBackPush('kirimform', _kirimCloseFormUi);
  window.scrollTo({top:0, behavior:'smooth'});
}
function _kirimCloseFormUi() {
  S.kirimFormOpen = false;
  const pgEl = document.getElementById('pg-kirim'); pgEl?.classList.remove('k-mode-form');
  const f = document.getElementById('k-form-card'); if (f) f.hidden = true;
  const b = pgEl?.querySelector('.kr-add'); if (b) b.setAttribute('aria-expanded','false');
  window.scrollTo({top:0, behavior:'smooth'});
}
function kirimCloseForm() { _kirimCloseFormUi(); if (typeof fwBackDone === 'function') fwBackDone('kirimform'); }
// ════════════════════════════════════════════
// KIRIM STATISTIKASI — Hafta / Oy / Butun vaqt / tanlangan oy
// Sana: kirim (ortilgan) sanasi; yo'ldagilar ham hisobga kiradi.
// ════════════════════════════════════════════
const UZ_MONTHS = ['Yanvar','Fevral','Mart','Aprel','May','Iyun','Iyul','Avgust','Sentyabr','Oktyabr','Noyabr','Dekabr'];
function _kstRange(st) {
  const iso = d => d.toISOString().slice(0,10);
  if (st.mode==='week') { const a=new Date(); a.setDate(a.getDate()-6); return [iso(a), td()]; }
  if (st.mode==='all') return ['0000-00-00','9999-12-31'];
  const ym = st.mode==='pick' ? st.ym : td().slice(0,7);
  const [y,m] = ym.split('-').map(Number);
  return [`${ym}-01`, `${ym}-${String(new Date(y,m,0).getDate()).padStart(2,'0')}`];
}
function kirimStatsSheet() {
  if (!S.kst) S.kst = { mode:'month', ym: td().slice(0,7) };
  openSheet({ic:'chart', c:'blue', title:'Kirimlar statistikasi', body:'<div id="kst"></div>'});
  kstRender();
}
function kstSet(mode) { S.kst.mode = mode; if (mode!=='pick') S.kst.ym = td().slice(0,7); kstRender(); }
function kstRender() {
  const box = document.getElementById('kst'); if (!box) return;
  const st = S.kst, [a,b] = _kstRange(st);
  const usd = v => '$'+(Math.round((+v||0)*100)/100).toLocaleString('en-US',{maximumFractionDigits:2}).replace(/,/g,' ');
  const n = v => Math.round(+v||0).toLocaleString('en-US').replace(/,/g,' ');
  const list = S.batches.filter(x => x.date && x.date.slice(0,10)>=a && x.date.slice(0,10)<=b && !(x.origin||'').startsWith('Qaytarish —'));
  const val = x => (x.qty||0)*(x.costUsd||0);
  const sum = list.reduce((s,x)=>s+val(x),0);
  const pickLbl = st.mode==='pick' ? `${UZ_MONTHS[+st.ym.slice(5,7)-1]} ${st.ym.slice(0,4)}` : 'Oyni tanlash';
  const tab = (k,l) => `<button class="kr-tab${st.mode===k?' on':''}" onclick="kstSet('${k}')">${l}</button>`;
  let html = `<div class="kr-tabs kst-tabs">${tab('week','Hafta')}${tab('month','Oy')}${tab('all','Butun vaqt')}
    <button class="kr-tab kst-pick${st.mode==='pick'?' on':''}" onclick="kstPicker(${(st.ym||td()).slice(0,4)})">${ICONF.calendar}<span>${pickLbl}</span></button></div>`;
  if (!list.length) {
    box.innerHTML = html + `<div class="bs-card kst-empty">${ICONF.inventory}<b>Bu davrda kirim boʻlmagan</b><span>Boshqa davrni tanlang.</span></div>`;
    return;
  }
  const bnos = new Set(list.map(x=>x.bno));
  const transit = list.filter(x=>x.status==='transit'), arrived = list.filter(x=>x.status!=='transit');
  // Diagramma: kunlar (hafta/oy) yoki oylar (butun vaqt)
  let buckets = [];
  if (st.mode==='all') {
    const by = {}; list.forEach(x=>{ const k=x.date.slice(0,7); by[k]=(by[k]||0)+val(x); });
    buckets = Object.keys(by).sort().slice(-12).map(k=>({k, l: UZ_MONTHS[+k.slice(5,7)-1].slice(0,3), v: by[k]}));
  } else {
    const by = {}; list.forEach(x=>{ const k=x.date.slice(0,10); by[k]=(by[k]||0)+val(x); });
    for (let d=new Date(a+'T00:00:00'); d<=new Date(b+'T00:00:00'); d.setDate(d.getDate()+1)) {
      const k = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
      buckets.push({k, l: String(d.getDate()), v: by[k]||0});
    }
  }
  const max = Math.max(1, ...buckets.map(x=>x.v));
  const many = buckets.length > 12;
  const supp = {}; list.forEach(x=>{ const nm = x.suppId ? (S.suppliers.find(s=>s.id===x.suppId)?.name||'—') : 'Belgilanmagan'; supp[nm]=(supp[nm]||0)+val(x); });
  const suppL = Object.entries(supp).sort((p,q)=>q[1]-p[1]).slice(0,6);
  const prod = {}; list.forEach(x=>{ const p=S.products.find(y=>y.id===x.pid); const k=x.pid; if(!prod[k]) prod[k]={sku:p?.sku||'', name:p?.name||'—', q:0, v:0}; prod[k].q+=x.qty||0; prod[k].v+=val(x); });
  const prodL = Object.values(prod).sort((p,q)=>q.v-p.v).slice(0,8);
  const tv = transit.reduce((s,x)=>s+val(x),0), av = arrived.reduce((s,x)=>s+val(x),0);
  html += `
  <section class="ox-hero kr-hero kst-hero">
    <div class="ox-hero-top"><span>Kirim summasi</span><span class="ox-date">${st.mode==='all'?'Butun vaqt':a.split('-').reverse().join('.')+' – '+b.split('-').reverse().join('.')}</span></div>
    <div class="ox-hero-big">${usd(sum)}</div>
    <div class="ox-hero-cols">
      <div><b>${n(bnos.size)}</b><span>Kirimlar</span></div>
      <div><b>${n(new Set(list.map(x=>x.pid)).size)}</b><span>Mahsulotlar</span></div>
      <div><b style="color:var(--sky)">${n(list.reduce((s,x)=>s+(x.qty||0),0))} dona</b><span>Birlik</span></div>
    </div>
  </section>
  <div class="kst-split">
    <div class="kst-s" style="--c:var(--emerald)">${ICONF.check}<span>Keldi</span><b>${usd(av)}</b><small>${new Set(arrived.map(x=>x.bno)).size} ta partiya</small></div>
    <div class="kst-s" style="--c:var(--purple)">${ICONF.truck}<span>Yoʻlda</span><b>${usd(tv)}</b><small>${new Set(transit.map(x=>x.bno)).size} ta partiya</small></div>
  </div>
  <div class="bs-card"><div class="kst-h"><b class="bs-t">${st.mode==='all'?'Oylar boʻyicha':'Kunlar boʻyicha'}</b><span>eng koʻp: ${usd(max)}</span></div>
    <div class="kst-chart${many?' many':''}">${buckets.map((x,i)=>`<div class="kst-col" title="${x.k}: ${usd(x.v)}"><div class="kst-bar${x.v?'':' zero'}" style="height:${x.v?Math.max(4,Math.round(x.v/max*100)):0}%"></div><span>${!many||i%5===0||i===buckets.length-1?x.l:''}</span></div>`).join('')}</div>
  </div>
  <div class="bs-card"><b class="bs-t">Taʼminotchilar</b>
    ${suppL.map(([k,v])=>`<div class="kr-st"><div class="kr-st-t"><span>${esc(k)}</span><b>${usd(v)} <em class="kst-pct">${Math.round(v/sum*100)}%</em></b></div><div class="kr-st-bar"><i style="width:${Math.max(3,Math.round(v/sum*100))}%"></i></div></div>`).join('')}</div>
  <div class="bs-card"><b class="bs-t">Eng koʻp kelgan mahsulotlar</b>
    ${prodL.map((x,i)=>`<div class="kst-p"><span class="kst-i">${i+1}</span><div class="kst-pn"><b>${esc(x.name)}</b><small>${esc(x.sku)} · ${n(x.q)} dona</small></div><b class="kst-pv">${usd(x.v)}</b></div>`).join('')}</div>`;
  box.innerHTML = html;
}
// Oyni tanlash — yil ‹ › va 12 oy
function kstPicker(year) {
  const box = document.getElementById('kst'); if (!box) return;
  const now = td(), cy = +now.slice(0,4), cm = +now.slice(5,7);
  const sel = S.kst.mode==='pick' ? S.kst.ym : '';
  box.innerHTML = `<div class="kst-pk">
    <div class="kst-pk-h"><button class="kst-nav" onclick="kstRender()" aria-label="Orqaga">‹</button><b>Oyni tanlang</b><span></span></div>
    <div class="kst-yr"><button class="kst-nav" onclick="kstPicker(${year-1})" aria-label="Oldingi yil">‹</button><b>${year}</b>
      <button class="kst-nav" onclick="kstPicker(${year+1})" ${year>=cy?'disabled':''} aria-label="Keyingi yil">›</button></div>
    <div class="kst-mg">${UZ_MONTHS.map((m,i)=>{ const ym=`${year}-${String(i+1).padStart(2,'0')}`; const fut = year>cy || (year===cy && i+1>cm);
      return `<button class="kst-m${ym===sel?' on':''}" ${fut?'disabled':''} onclick="S.kst.mode='pick';S.kst.ym='${ym}';kstRender()">${m}</button>`; }).join('')}</div>
  </div>`;
}

function kirimHistorySearch(v) {
  S.kirimQ = v || '';
  const x = document.querySelector('#pg-kirim .kr-search-x'); if (x) x.hidden = !S.kirimQ;
  const hl = document.getElementById('kh-list'); if (hl) hl.innerHTML = kirimHistoryHtml();
}
function kirimHistoryHtml(q, statusFilter, sort) {
  q = (q ?? S.kirimQ ?? '').toString().trim().toLowerCase();
  const groups = {};
  S.batches.forEach(b=>{ const k = (b.bno != null && b.bno !== '') ? String(b.bno) : '—'; (groups[k] = groups[k]||[]).push(b); });   // v24.6: raqamsiz partiya — «#undefined» emas
  let bnos = Object.keys(groups);

  // Qidiruv: partiya raqami, ta'minotchi nomi yoki mahsulot nomi/kodi bo'yicha
  if (q) {
    bnos = bnos.filter(bno=>{
      const list = groups[bno];
      const first = list[0];
      const supp = first.suppId ? S.suppliers.find(s=>s.id===first.suppId) : null;
      const haystack = [bno, supp?.name||'', ...list.map(b=>{
        const p = S.products.find(x=>x.id===b.pid);
        return (p?.sku||'')+' '+(p?.name||'');
      })].join(' ').toLowerCase();
      return haystack.includes(q);
    });
  }

  // Holat bo'yicha filtr
  if (statusFilter) {
    bnos = bnos.filter(bno=>{
      const list = groups[bno];
      const first = list[0];
      const allEmpty = list.every(b=>b.status==='empty');
      const st = first.status==='transit' ? 'transit' : (allEmpty ? 'empty' : 'active');
      return st === statusFilter;
    });
  }

  // Davr bo'yicha (Bugun / Kecha / Oy / kalendar): kelgan sanasi shu davrga tushgan partiyalar.
  // Yo'ldagi partiyalar davrdan qat'i nazar doim yuqorida turadi — ular hali kelmagan.
  const [pa, pb] = kirimPeriodRange();
  bnos = bnos.filter(bno => {
    const list = groups[bno];
    if (list.some(x=>(x.origin||'').startsWith('Qaytarish —'))) return false;
    if (list[0].status==='transit' || q) return true;          // qidiruvda — barcha davrlar
    const d = batchArrivalDate(list[0]); return d && d>=pa && d<=pb;
  });
  if (S.kirimStatusFilter==='transit') bnos = bnos.filter(bno => groups[bno][0].status==='transit');
  if (S.kirimStatusFilter==='active')  bnos = bnos.filter(bno => groups[bno][0].status!=='transit');

  // Saralash
  const sortKey = sort || 'date-desc';
  bnos.sort((a,b)=>{
    const la=groups[a], lb=groups[b];
    if (sortKey==='date-asc') return new Date(la[0].date)-new Date(lb[0].date);
    if (sortKey==='val-desc') return lb.reduce((s,x)=>s+x.qty*(x.costUsd||0),0) - la.reduce((s,x)=>s+x.qty*(x.costUsd||0),0);
    if (sortKey==='val-asc')  return la.reduce((s,x)=>s+x.qty*(x.costUsd||0),0) - lb.reduce((s,x)=>s+x.qty*(x.costUsd||0),0);
    const ta = la[0].status==='transit', tb = lb[0].status==='transit';
    if (ta !== tb) return ta ? -1 : 1;                                    // yo'ldagilar yuqorida
    return new Date(batchArrivalDate(lb[0])||lb[0].date) - new Date(batchArrivalDate(la[0])||la[0].date); // yangi → eski
  });
  setTimeout(()=>{ const c=document.getElementById('kh-count'); if(c) c.textContent = bnos.length; }, 0);

  if (!bnos.length && q) return `<div class="kr-empty">${ICONF.search}<b>«${esc(q)}» topilmadi</b><span>Partiya raqami, taʼminotchi nomi yoki mahsulot kodini tekshiring.</span></div>`;
  if (!bnos.length) return `<div class="kr-empty">${ICONF.inbox}<b>Bu davrda kirim bo\u02bblmagan</b><span>Mahsulotlarni to\u02bbldirish uchun \u00abKirim qo\u02bbshish\u00bbni bosing.</span></div>`;
  const dmy = d => String(d||'').slice(0,10).split('-').reverse().join('/');
  const days = (a,b) => Math.max(0, Math.round((new Date(b) - new Date(a)) / 86400000));
  const money = v => '$'+(Math.round((+v||0)*100)/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).replace(/,/g,' ');
  const num = v => Math.round(+v||0).toLocaleString('en-US').replace(/,/g,' ');
  return bnos.map(bno=>{
    const list = groups[bno];
    const first = list[0];
    const isTransit = first.status==='transit';
    const allEmpty = list.every(b=>b.status==='empty');
    const st = isTransit ? 'transit' : allEmpty ? 'empty' : 'active';
    const totalQty = list.reduce((s,b)=>s+b.qty,0);
    const totalRem = list.reduce((s,b)=>s+(b.qty-b.sold),0);
    const totalVal = list.reduce((s,b)=>s+b.qty*(b.costUsd||0),0);
    const soldPct = totalQty ? Math.round((totalQty-totalRem)/totalQty*100) : 0;
    const supp = first.suppId ? S.suppliers.find(s=>s.id===first.suppId) : null;
    const shortNo = bno === '—' ? '#—' : '#' + String(String(bno).split('-').pop()).padStart(2,'0');
    const curName = first.cur==='CNY' ? 'Yuan' : first.cur==='UZS' ? 'Soʻm' : 'Dollar';
    const arr = batchArrivalDate(first);
    const onRoad = isTransit ? days(first.date, td()) : days(first.date, arr);
    const pill = st==='transit' ? `${ICONF.truck}Yoʻlda` : st==='empty' ? `${ICONF.inventory}Tugagan` : `${ICONF.check}Keldi`;
    const bnoJs = escJsAttr(bno);
    return `<article class="kh-card kh-${st}">
      <header class="kh-head">
        <span class="kh-no">${esc(shortNo)}</span>
        <div class="kh-who"><b>${supp ? esc(supp.name) : '<span class="kh-muted">Taʼminotchi belgilanmagan</span>'}</b>
          <small>${bno === '—' ? 'Raqamsiz partiya' : esc(bno)} · ${curName}${first.consignment?' · Konsignatsiya':''}</small></div>
        <span class="kh-pill">${pill}</span>
      </header>

      <div class="kh-route">
        <div class="kh-pt"><i></i><small>Ortilgan</small><b>${dmy(first.date)}</b></div>
        <div class="kh-line"><span>${isTransit ? `${onRoad} kundan beri yoʻlda` : onRoad ? `${onRoad} kunda keldi` : 'shu kuni keldi'}</span></div>
        <div class="kh-pt kh-pt-end"><i></i><small>Kelgan</small><b>${isTransit ? '—' : dmy(arr)}</b></div>
      </div>

      <div class="kh-figs">
        <div><b>${money(totalVal)}</b><span>Summa</span></div>
        <div><b>${num(totalQty)}</b><span>dona · ${list.length} xil</span></div>
        <div><b>${num(totalRem)}</b><span>qoldi</span></div>
      </div>
      ${isTransit ? '' : `<div class="kh-sold"><div class="kh-bar"><i style="width:${soldPct}%"></i></div><span>${soldPct}% sotildi</span></div>`}

      <footer class="kh-acts">
        <button class="kh-more" onclick="kirimToggleDetail('${bnoJs}')" aria-expanded="false" aria-controls="kirim-detail-${esc(bno)}"><span>Mahsulotlar</span>${ICONF.chevron}</button>
        ${canEdit30(first.date) ? `<button class="kh-ib" onclick="openBatchGroupEdit('${bnoJs}')" title="Tahrirlash" aria-label="Tahrirlash">${ICONF.edit}</button>` : ''}
        <button class="kh-ib" onclick="printImport('${bnoJs}')" title="Chop etish" aria-label="Chop etish">${ICONF.print}</button>
        <button class="kh-ib kh-del" onclick="deleteBatchGroup('${bnoJs}')" title="Butun partiyani oʻchirish" aria-label="Oʻchirish">${ICONF.trash}</button>
      </footer>
      ${isTransit ? `<button class="kh-arrive" onclick="openArrivalCustoms('${bnoJs}')">${ICONF.check}<span>Yetib keldi — omborga qoʻshish</span></button>` : ''}

      <div class="kh-detail" id="kirim-detail-${esc(bno)}" hidden>
        ${list.map(b=>{ const p=S.products.find(x=>x.id===b.pid); return `<div class="kh-row">
          <div class="kh-row-t"><code>${esc(p?.sku||'')}</code><span>${esc(p?.name||'—')}</span>${b.edited?'<em>tahrirlangan</em>':''}</div>
          <div class="kh-row-r"><span>${num(b.qty)} × ${money(b.costUsd||0)}</span>
            ${canEdit30(b.date) ? `<button class="kh-ib sm" onclick="openBatchEdit(${b.id})" aria-label="Tahrirlash">${ICONF.edit}</button>` : ''}
            <button class="kh-ib sm kh-del" onclick="deleteBatch('${b.id}')" aria-label="Oʻchirish">${ICONF.trash}</button></div>
        </div>`; }).join('')}
      </div>
    </article>`;
  }).join('');
}

function kirimToggleDetail(bno) {
  const el = document.getElementById(`kirim-detail-${bno}`);
  if (!el) return;
  el.hidden = !el.hidden;
  const btn = el.closest('.kh-card')?.querySelector('.kh-more');
  if (btn) { btn.setAttribute('aria-expanded', String(!el.hidden)); btn.classList.toggle('open', !el.hidden); }
}

// ── PARTIYA QATORINI TAHRIRLASH — 30 kun ichida ──
// ── BUTUN PARTIYANI BIRDANIGA TAHRIRLASH — formula ishlatmasdan, to'g'ridan-to'g'ri saqlanadi ──
function openBatchGroupEdit(bno) {
  const list = S.batches.filter(b=>b.bno===bno);
  if (!list.length) return;
  const first = list[0];
  modal(`
    <div class="modal-header"><div class="modal-title">✏️ Partiya #${esc(bno)} — hammasini tahrirlash (${list.length} xil)</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body" style="max-height:65vh;overflow-y:auto">
      <div style="background:rgba(47,111,237,.06);border:1px solid rgba(47,111,237,.25);border-radius:10px;padding:12px;margin-bottom:12px">
        <div style="font-size:12px;font-weight:700;margin-bottom:8px">🏭 Butun partiya uchun ta'minotchi/konsignatsiya</div>
        <select class="form-control" id="bg-supp" style="margin-bottom:8px">
          <option value="">— ta'minotchi yo'q —</option>
          ${S.suppliers.map(s=>`<option value="${s.id}" ${first.suppId===s.id?'selected':''}>${esc(s.name)}${s.isConsignment?' (📋 konsignatsiya)':''}</option>`).join('')}
        </select>
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:12.5px">
          <input type="checkbox" id="bg-consign" ${first.consignment?'checked':''} style="width:16px;height:16px">
          Bu partiya konsignatsiya hisoblansin (qarz yozilmasin, faqat sotilganda)
        </label>
        <button class="btn btn-primary btn-sm" style="margin-top:8px" onclick="applyBatchGroupSupplier('${escJsAttr(bno)}')">Ta'minotchi/holatni butun partiyaga qo'llash</button>
      </div>
      <div style="font-size:11px;color:var(--gold-dark);background:rgba(184,112,12,.08);border:1px solid rgba(184,112,12,.3);border-radius:8px;padding:8px 10px;margin-bottom:10px">
        ⚠️ Miqdor/Tannarx qatorlari — formula qayta hisoblanmasdan, to'g'ridan-to'g'ri saqlanadi.
      </div>
      <table style="width:100%;font-size:12px">
        <thead><tr style="text-align:left;color:var(--text-muted)">
          <th style="padding:4px">SKU</th><th style="padding:4px">Nomi</th><th style="padding:4px;width:80px">Miqdor</th><th style="padding:4px;width:90px">Tannarx ($)</th>
        </tr></thead>
        <tbody>
          ${list.map(b=>{
            const p = S.products.find(x=>x.id===b.pid);
            return `<tr data-bgid="${b.id}">
              <td style="padding:4px"><code style="color:var(--gold)">${esc(p?.sku||'')}</code></td>
              <td style="padding:4px">${esc(p?.name||'')}</td>
              <td style="padding:4px"><input type="number" class="form-control bg-qty" data-bid="${b.id}" data-min="${b.sold}" value="${b.qty}" min="${b.sold}" style="padding:5px;font-size:12px"></td>
              <td style="padding:4px"><input type="number" class="form-control bg-cost" data-bid="${b.id}" value="${b.costUsd}" step="0.0001" min="0" style="padding:5px;font-size:12px"></td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" id="bg-save-btn" onclick="saveBatchGroupEdit('${escJsAttr(bno)}')">💾 Hammasini saqlash</button>
    </div>`);
}

function applyBatchGroupSupplier(bno) {
  const list = S.batches.filter(b=>b.bno===bno);
  const suppIdRaw = document.getElementById('bg-supp')?.value;
  const suppId = suppIdRaw ? parseInt(suppIdRaw) : null;
  const isConsign = !!document.getElementById('bg-consign')?.checked;
  if (!confirm(`Butun partiya #${bno} (${list.length} xil mahsulot) uchun ta'minotchi/holat o'zgartiriladi. Davom etasizmi?`)) return;
  list.forEach(b=>{ b.suppId = suppId; b.consignment = isConsign; b.edited = true; b.editedAt = new Date().toISOString(); });
  auditLog(`Partiya #${bno} — ta'minotchi/konsignatsiya holati butunlay o'zgartirildi`);
  save();
  toast('✅ Butun partiya uchun ta\'minotchi/holat yangilandi!');
  closeModal();
  openBatchGroupEdit(bno);
}

async function saveBatchGroupEdit(bno) {
  const btn = document.getElementById('bg-save-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Saqlanmoqda...'; }

  const qtyInputs = document.querySelectorAll('.bg-qty');
  const costInputs = document.querySelectorAll('.bg-cost');
  const costMap = {};
  costInputs.forEach(inp => { costMap[inp.dataset.bid] = parseFloat(inp.value||0); });

  // Avval tekshiramiz — hech qaysi miqdor sotilgandan kam bo'lmasin
  for (const inp of qtyInputs) {
    const newQty = parseInt(inp.value||0);
    const minQty = parseInt(inp.dataset.min||0);
    if (newQty < minQty) {
      const b = S.batches.find(x=>x.id===parseInt(inp.dataset.bid));
      const p = b ? S.products.find(x=>x.id===b.pid) : null;
      toast(`${p?.sku||'Mahsulot'}: miqdor sotilgandan (${minQty}) kam bo'la olmaydi!`, 'error');
      if (btn) { btn.disabled=false; btn.textContent='💾 Hammasini saqlash'; }
      return;
    }
  }

  // v23.2 (F4b): miqdor/tannarx va ta'minotchi qarzi farqi — SERVERDA (bazadagi qiymatdan)
  if (fwLedgerRemote()) {
    const edits = [];
    qtyInputs.forEach(inp => {
      const bid = parseInt(inp.dataset.bid);
      const b = S.batches.find(x=>x.id===bid); if (!b) return;
      const newQty = parseInt(inp.value||0);
      const newCost = costMap[bid] !== undefined ? costMap[bid] : b.costUsd;
      if (newQty === b.qty && newCost === b.costUsd) return;
      edits.push({ localId:String(bid), qty:newQty, costUsd:newCost });
    });
    if (edits.length) {
      try { await fwLedgerCall('stock-debt-ops', { kind:'batch_edit', payload:{ edits } }); }
      catch(e) { toast('⛔ ' + e.message, 'error'); if (btn) { btn.disabled=false; btn.textContent='💾 Hammasini saqlash'; } return; }
      edits.forEach(e => { const b = S.batches.find(x=>String(x.id)===e.localId); if (b) { b.edited = true; b.editedAt = new Date().toISOString(); } });
    }
    auditLog(`Partiya #${bno} — ${edits.length} ta mahsulot birdaniga tahrirlandi`);
    save(); closeModal(); pgKirim();
    toast(`✅ ${edits.length} ta mahsulot yangilandi!`);
    return;
  }

  let changedCnt = 0;
  const suppDebtDelta = {};
  qtyInputs.forEach(inp => {
    const bid = parseInt(inp.dataset.bid);
    const b = S.batches.find(x=>x.id===bid); if (!b) return;
    const newQty = parseInt(inp.value||0);
    const newCost = costMap[bid] !== undefined ? costMap[bid] : b.costUsd;
    if (newQty === b.qty && newCost === b.costUsd) return;

    const oldTotal = b.qty*b.costUsd;
    const newTotal = newQty*newCost;
    if (b.suppId) suppDebtDelta[b.suppId] = (suppDebtDelta[b.suppId]||0) + (newTotal-oldTotal);

    b.qty = newQty; b.costUsd = newCost;
    b.edited = true; b.editedAt = new Date().toISOString();
    if (b.qty===b.sold) b.status='empty'; else if (b.status==='empty') b.status='active';
    changedCnt++;
  });

  Object.keys(suppDebtDelta).forEach(sid=>{
    const supp = S.suppliers.find(x=>x.id===parseInt(sid));
    if (supp) supp.debt = Math.max(0, (supp.debt||0) + suppDebtDelta[sid]);
  });

  auditLog(`Partiya #${bno} — ${changedCnt} ta mahsulot birdaniga tahrirlandi`);
  save(); closeModal(); pgKirim();
  toast(`✅ ${changedCnt} ta mahsulot yangilandi!`);
}

function openBatchEdit(bid) {
  const b = S.batches.find(x=>x.id===bid); if (!b) return;
  if (!canEdit30(b.date)) { toast('⛔ 30 kundan o\'tgan kirimlarni tahrirlab bo\'lmaydi!','error'); return; }
  const p = S.products.find(x=>x.id===b.pid);
  modal(`
    <div class="modal-header"><div class="modal-title">✏️ Kirimni tahrirlash — ${esc(p?.sku||'')}</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div style="font-size:11px;color:var(--gold-dark);background:rgba(184,112,12,.08);border:1px solid rgba(184,112,12,.3);border-radius:8px;padding:8px 10px;margin-bottom:12px">
        ⚠️ Miqdorni sotilgandan (${b.sold} dona) kamroq qila olmaysiz. Ta'minotchi qarzi avtomatik tuzatiladi.
      </div>
      <div class="form-group"><label class="form-label">Miqdor (jami, ${b.sold} dona allaqachon sotilgan)</label>
        <input class="form-control" id="be-qty" type="number" min="${b.sold}" value="${b.qty}"></div>
      <div class="form-group" style="margin-bottom:0"><label class="form-label">Tannarx ($/dona)</label>
        <input class="form-control" id="be-cost" type="number" step="0.0001" value="${b.costUsd}"></div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" onclick="saveBatchEdit(${bid})">💾 Saqlash</button>
    </div>`);
}

async function saveBatchEdit(bid) {
  const b = S.batches.find(x=>x.id===bid); if (!b) return;
  const newQty = parseInt(document.getElementById('be-qty')?.value||0);
  const newCost = parseFloat(document.getElementById('be-cost')?.value||0);
  if (newQty < b.sold) { toast(`Miqdor sotilgandan (${b.sold}) kam bo'la olmaydi!`,'error'); return; }
  if (newCost < 0) { toast('Tannarx noto\'g\'ri!','error'); return; }
  // v23.2 (F4b): SERVERDA (sotilgan miqdor va ta'minotchi qarzi bazadagi qiymatdan tekshiriladi)
  if (fwLedgerRemote()) {
    try { await fwLedgerCall('stock-debt-ops', { kind:'batch_edit', payload:{ edits:[{ localId:String(bid), qty:newQty, costUsd:newCost }] } }); }
    catch(e) { toast('⛔ ' + e.message, 'error'); return; }
    b.edited = true; b.editedAt = new Date().toISOString();
    auditLog(`Kirim tahrirlandi: #${b.bno} — yangi miqdor ${newQty}, tannarx ${CUR.fmtUsd(newCost)}`);
    save(); closeModal(); pgKirim();
    toast('✅ Tahrirlandi!');
    return;
  }

  const oldGoodsTotal = b.qty*b.costUsd;
  const newGoodsTotal = newQty*newCost;
  if (b.suppId) {
    const supp = S.suppliers.find(x=>x.id===b.suppId);
    if (supp) supp.debt = Math.max(0, (supp.debt||0) + (newGoodsTotal-oldGoodsTotal));
  }

  b.qty = newQty; b.costUsd = newCost;
  b.edited = true; b.editedAt = new Date().toISOString();
  if (b.qty===b.sold) b.status='empty'; else if (b.status==='empty') b.status='active';

  auditLog(`Kirim tahrirlandi: #${b.bno} — yangi miqdor ${newQty}, tannarx ${CUR.fmtUsd(newCost)}`);
  save(); closeModal(); pgKirim();
  toast('✅ Tahrirlandi!');
}

