async function saveSupp() {
  const name=document.getElementById('ns-n')?.value?.trim();
  if(!name){toast('Nomi kiriting!','error');return;}
  const openingDebt = parseFloat(document.getElementById('ns-debt')?.value||0) || 0;
  if (openingDebt < 0) { toast("Qarz manfiy bo'lmasligi kerak",'error'); return; }
  const sp = {id:uid(),name,country:document.getElementById('ns-c')?.value||'',contact:document.getElementById('ns-p')?.value||'',debt:openingDebt,paid:0,isConsignment:!!document.getElementById('ns-consign')?.checked,allowDirectSale:!!document.getElementById('ns-direct')?.checked, ...suppReadContacts('ns')};
  // v23.2 (F4b): boshlang'ich qarz — SERVERDA (qarz jurnali); rad etilsa ta'minotchi qo'shilmaydi
  if (fwLedgerRemote() && openingDebt > 0) {
    let r;
    try { r = await fwLedgerCall('stock-debt-ops', { kind:'supp_set', payload:{ supplierId:sp.id, debt:openingDebt, reason:'opening', name } }); }
    catch(e) { toast('⛔ ' + e.message, 'error'); return; }
    sp.debt = +r.debt || 0;
  }
  S.suppliers.push(sp);
  save();closeModal();
  if (!fwAfterAdd('supp', sp.id)) pgTaminotchilar();
  toast('✅ Ta\'minotchi qo\'shildi!');
}

