function esCurUnit() {
  const u = document.getElementById('es-debt-u'); if (u) u.textContent = document.getElementById('es-cur')?.dataset.v === 'UZS' ? "so'm" : '$';
}
async function saveEditSupplier(sid) {
  const s=S.suppliers.find(x=>x.id===sid); if(!s) return;
  const name=document.getElementById('es-n')?.value?.trim();
  if(!name){toast('Nomi kiriting!','error');return;}
  // v25 (44): qarz valyutasi — avval (faqat qarz 0 bo'lganda; serverda tekshiriladi)
  const curWant = document.getElementById('es-cur')?.dataset.v === 'UZS' ? 'UZS' : 'USD', curNow = suppIsUzs(s) ? 'UZS' : 'USD';
  if (curWant !== curNow) {
    if (fwLedgerRemote()) {
      let rc;
      try { rc = await fwLedgerCall('stock-debt-ops', { kind:'supp_cur', payload:{ supplierId:s.id, currency:curWant } }); }
      catch(e) { toast('⛔ ' + e.message, 'error'); return; }
      s.debtCur = rc.currency === 'UZS' ? 'UZS' : 'USD'; s.debtUzs = +rc.debtUzs || 0; s.debt = +rc.debt || 0;
    } else { s.debtCur = curWant; s.debtUzs = 0; }
    auditLog(`Ta'minotchi qarz valyutasi: ${s.name} — ${curNow} → ${curWant}`);
  }
  const rawDebt = parseFloat(document.getElementById('es-debt')?.value||0) || 0;
  const uzsMode = suppIsUzs(s) && curWant === curNow;
  const newDebt = uzsMode ? rawDebt / (CUR.usdUzs || 1) : (curWant !== curNow ? (s.debt||0) : rawDebt);
  const changed = uzsMode ? Math.abs(rawDebt - (+s.debtUzs||0)) >= 1 : Math.abs(newDebt - (s.debt||0)) > 0.00005;
  // v23.2 (F4b): qarzni qo'lda o'zgartirish — SERVERDA (ruxsat: taminotchilar.edit; qarz jurnaliga yoziladi)
  if (fwLedgerRemote() && changed) {
    if (newDebt < 0) { toast("Qarz manfiy bo'lmasligi kerak",'error'); return; }
    let r;
    try { r = await fwLedgerCall('stock-debt-ops', { kind:'supp_set', payload:{ supplierId:s.id, debt:Math.round(newDebt*1e6)/1e6, reason:'adjust', name } }); }
    catch(e) { toast('⛔ ' + e.message, 'error'); return; }
    s.debt = +r.debt || 0;
  } else if (!fwLedgerRemote()) {
    s.debt = newDebt; if (uzsMode) s.debtUzs = Math.round(rawDebt);
  }
  s.name = name;
  s.country = document.getElementById('es-c')?.value||'';
  s.contact = document.getElementById('es-p')?.value||'';
  Object.assign(s, suppReadContacts('es'));
  s.isConsignment = !!document.getElementById('es-consign')?.checked;
  s.allowDirectSale = !!document.getElementById('es-direct')?.checked;
  closeModal();pgTaminotchilar();fwSaveToast('✅ Saqlandi!');
}

function deleteSupplier(sid) {
  if(!confirm("Ta'minotchini o'chirasizmi?")) return;
  S.suppliers = S.suppliers.filter(s=>s.id!==sid);
  markDeleted('suppliers', sid);
  save();closeModal();pgTaminotchilar();toast("✅ O'chirildi!",'warning');
}

function openPaySupplierDebt(sid) {
  const s=S.suppliers.find(x=>x.id===sid); if(!s) return;
  const boxes = S.cashboxes.filter(k=>k.type!=='dealer');
  const uz = suppIsUzs(s), debtUzs = uz ? (+s.debtUzs||0) : CUR.toUzs(+s.debt||0), debtUsd = uz ? CUR.toUsd(debtUzs) : (+s.debt||0);
  const box0 = (uz && boxes.find(k=>k.cur==='UZS')) || boxes[0];
  const opts = meBoxOpts(boxes, box0?.id);
  if (fwFirmaAvailable()) opts.push({v:'firma-USD', cur:'USD', ic:'🏛', name:'Bosh kassa ($)', sub:'Asosiy kassa'}, {v:'firma-UZS', cur:'UZS', ic:'🏛', name:'Bosh kassa (soʻm)', sub:'Asosiy kassa'});
  modal(`
    <div class="modal-header"><div class="modal-title">💰 Ta'minotchiga to'lov</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${meCard({ name:s.name, sub:esc(s.country||'') + (uz?' · qarz soʻmda':''), kpi:uz?CUR.fmtUzs(debtUzs):CUR.fmtUsd(debtUsd), kpiLabel:'bizning qarz', tone:'neg' })}
      ${meSec('Qaysi kassadan')}
      ${meBoxPick('psd-b', opts, "meCurSwap('psd-a','psd-b','psd-u')")}
      ${meSec('Summa')}
      ${meAmt('psd-a', box0?.cur==='USD'?debtUsd.toFixed(2):Math.round(debtUzs), box0?.cur==='USD'?'$':"so'm", 'psd-u', `oninput="meRemain('psd-a','psd-b','psd-r',${uz?debtUzs:debtUsd},'${uz?'UZS':'USD'}')"`)}
      ${meFillChips('psd-a','psd-b',debtUsd,debtUzs)}
      <div class="me-res" id="psd-r"></div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-success" onclick="paySupplierDebt(${sid})">✅ To'lash</button>
    </div>`);
  meRemain('psd-a','psd-b','psd-r',uz?debtUzs:debtUsd,uz?'UZS':'USD');
}

function psdBoxChange() {
  const v = document.getElementById('psd-b')?.value || '';
  const cur = v.startsWith('firma-') ? v.slice(6) : (S.cashboxes.find(k=>k.id===parseInt(v))?.cur);
  const lbl = document.getElementById('psd-label');
  if (lbl) lbl.textContent = `Summa (${cur==='USD'?'$':"so'm"})`;
}

async function paySupplierDebt(sid) {
  const s=S.suppliers.find(x=>x.id===sid); if(!s) return;
  const raw=parseFloat(document.getElementById('psd-a')?.value||0);
  const srcV = document.getElementById('psd-b')?.value || '1';
  if(!(raw>0)||!isFinite(raw)){toast('Summa kiriting!','error');return;}
  if (srcV.startsWith('firma-')) return paySupplierDebtFirma(sid, srcV.slice(6), Math.round(raw*100)/100);
  const bid=parseInt(srcV);
  const box=S.cashboxes.find(k=>k.id===bid);
  if(!box){toast('⛔ Kassa tanlang','error');return;}
  const usd = box.cur==='USD' ? raw : CUR.toUsd(raw);
  if (raw > (box.bal||0) + 0.005) { toast(`⛔ "${box.name}"da mablag' yetarli emas`, 'error'); return; }
  if (suppOverpay(s, box.cur, raw)) return;

  // v23 fail-close: kassa chiqimi + to'lov yozuvi serverda BITTA tranzaksiyada; server qarzni
  // o'zidagi ma'lumotdan tekshiradi. Rad etilsa yoki javob bo'lmasa — hech narsa o'zgarmaydi.
  let pr;
  try {
    pr = await fwCashOps('supp_pay', [{boxId:box.id, dir:'out', amount:raw, desc:`Ta'minotchiga to'lov — ${s.name}`, suppId:sid}], {
      remote:_cloudEnabled, refType:'supplier', refId:sid, record:{ supplierId:sid },
      legacy: () => fwLegacyPost('supplier-payment-add', { supplierLocalId:sid, supplierName:s.name, amountUsd:usd, boxId:bid, debtBeforePayment:s.debt||0, idemKey:uid(), filial:S.branch }),
    });
  } catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  // v23.2 (F4b): qarz — bazadagi haqiqiy qiymat (server qulflab kamaytirdi)
  if (pr && pr.supplierDebt != null) fwApplyLedger({ filial:S.branch, suppliers:{ [sid]: { debt:pr.supplierDebt, paid:pr.supplierPaid, debtCur:pr.supplierDebtCur, debtUzs:pr.supplierDebtUzs } } });
  else { s.debt = Math.max(0, (s.debt||0)-usd); s.paid = (s.paid||0)+usd; }
  auditLog(`Ta'minotchiga to'landi: ${s.name} — ${CUR.fmtUsd(usd)}`);
  save();closeModal();pgTaminotchilar();toast(`✅ ${CUR.fmtUsd(usd)} to'landi!`);
}

// To'lov qarzdan oshmasin: so'mdagi ta'minotchi — so'mda, aks holda $ da
function suppOverpay(s, cur, amount) {
  if (suppIsUzs(s)) {
    const uzs = cur === 'UZS' ? amount : CUR.toUzs(amount), d = +s.debtUzs || 0;
    if (uzs > d + 1) { toast(`⛔ To'lov ta'minotchi qarzidan (${CUR.fmtUzs(d)}) oshib ketdi`, 'error'); return true; }
    return false;
  }
  const usd = cur === 'USD' ? amount : CUR.toUsd(amount);
  if (usd > (s.debt||0) + 0.01) { toast(`⛔ To'lov ta'minotchi qarzidan (${CUR.fmtUsd(s.debt||0)}) oshib ketdi`, 'error'); return true; }
  return false;
}
// v23.4: ta'minotchi qarzini Bosh kassadan to'lash — kassa va qarz serverda BITTA tranzaksiyada
// (28-migratsiya: firma_supplier_pay). Qarzdan ortiq yoki kassada yetmasa — rad, hech narsa o'zgarmaydi.
let _psdFk = null;
async function paySupplierDebtFirma(sid, cur, amount) {
  const s = S.suppliers.find(x=>x.id===sid); if (!s) return;
  if (!fwFirmaAvailable()) { toast("⛔ Bosh kassa bilan ishlash huquqingiz yo'q", 'error'); return; }
  const usd = cur==='USD' ? amount : CUR.toUsd(amount);
  if (suppOverpay(s, cur, amount)) return;
  const sig = JSON.stringify([S.branch, sid, cur, amount]);
  if (!_psdFk || _psdFk.sig !== sig) _psdFk = { sig, key: 'fsp' + uid() };
  let d;
  try { d = await fwFirmaCall({ action:'supplier_pay', suppId: sid, currency: cur, amount, idemKey: _psdFk.key, cpName: s.name, filial: S.branch, note: `Ta'minotchiga to'lov — ${s.name}` }); }
  catch (e) { if (!e.retry) _psdFk = null; toast('⛔ ' + e.message, 'error'); return; }
  _psdFk = null;
  const p = d.payment || {};
  if (p.supplierDebt != null) fwApplyLedger({ filial:S.branch, suppliers:{ [sid]: { debt:+p.supplierDebt, paid:+p.supplierPaid, debtCur:p.supplierDebtCur, debtUzs:p.supplierDebtUzs } } });
  const s2 = S.suppliers.find(x=>x.id===sid) || s;   // fwApplyLedger obyektni almashtirishi mumkin
  s2.fkPays = (s2.fkPays || []).concat([{ date: td(), cur, amount, usd: +p.amountUsd || usd, fkEntryId: p.fkEntryId || null }]).slice(-200);
  if (typeof FK !== 'undefined') FK.loaded = false;
  auditLog(`Ta'minotchiga to'landi (Bosh kassa): ${s.name} — ${cur==='USD'?CUR.fmtUsd(amount):CUR.fmtUzs(amount)}`);
  save(); closeModal(); pgTaminotchilar();
  toast(p.replay ? "✅ Bu to'lov avval bajarilgan edi (takror yozilmadi)" : `✅ Bosh kassadan to'landi! Qolgan qarz: ${suppDebtTxt(S.suppliers.find(x=>x.id===sid) || s)}`);
}

// ── TA'MINOTCHI TARIXI — kirimlar (qarz+) va to'lovlar (qarz-), xronologik, balans bilan ──
function taminotchiLedger(sid) {
  const s = S.suppliers.find(x=>x.id===sid);
  const events = [];
  const bnos = {};
  S.batches.filter(b=>b.suppId===sid).forEach(b=>{ (bnos[b.bno] = bnos[b.bno]||[]).push(b); });
  Object.keys(bnos).forEach(bno=>{
    const list = bnos[bno];
    const total = list.reduce((s2,b)=>s2+b.qty*(b.costUsd||0),0);
    events.push({ date:list[0].date, desc: /^B2B/.test(bno) ? `🔗 B2B qabul — ${bno}` : `📦 Kirim — Partiya #${bno}`, delta: list[0].consignment ? 0 : total });
  });
  // Omborsiz, to'g'ridan sotilgan itemlar (🚚 qoldiqsiz sotuv)
  S.sales.forEach(sale=>{
    (sale.items||[]).filter(i=>i.directSupply && i.suppId===sid).forEach(i=>{
      events.push({ date:sale.date, desc:`🚚 Toʻgʻridan sotildi — ${esc(sale.inv)} (${i.name} × ${i.qty})`, delta: i.qty*(i.costUsd||0) });
    });
  });
  (S.cashTxns||[]).filter(t=>t.suppId===sid && t.type==='out').forEach(t=>{
    const usdAmt = t.cur==='USD' ? t.amount : CUR.toUsd(t.amount);
    events.push({ date:t.date, desc:`💰 To'lov (${t.boxName})`, delta:-usdAmt });
  });
  (s?.fkPays||[]).forEach(f=>{ events.push({ date:f.date, desc:`🏛 To'lov (Bosh kassa)`, delta:-(+f.usd||0) }); });
  (s?.discounts||[]).forEach(d=>{ events.push({ date:d.date, desc:`Chegirma (taʼminotchidan)${d.note?' — '+d.note:''}`, delta:-(+d.amt||0) }); });
  events.sort((a,b)=> a.date<b.date?-1:a.date>b.date?1:0);
  const totalDelta = events.reduce((s2,e)=>s2+e.delta,0);
  let bal = (s?.debt||0) - totalDelta;
  events.forEach(e=>{ bal += e.delta; e.balance = bal; });
  return events;
}

function openTaminotchiTarixi(sid) {
  const s = S.suppliers.find(x=>x.id===sid); if (!s) return;
  const events = taminotchiLedger(sid);
  modal(`
    <div class="modal-header"><div class="modal-title">🕒 ${esc(s.name)} — tarix</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <span style="font-size:12px;color:var(--text-muted)">Joriy qarzi: <strong style="color:${(s.debt||0)>0?'var(--red)':'var(--emerald)'}">${CUR.fmtUsd(s.debt||0)}</strong></span>
        <button class="btn btn-ghost btn-sm" onclick="printTaminotchiTarixi(${sid})">🖨️ Chop etish</button>
      </div>
      <div class="table-wrap" style="max-height:420px;overflow-y:auto">
        <table>
          <thead><tr><th>Sana</th><th>Izoh</th><th>Miqdor</th><th>Balans (qarz)</th></tr></thead>
          <tbody>
            ${events.length ? events.map(e=>`<tr>
              <td>${fmtD(e.date)}</td>
              <td style="color:var(--text-secondary)">${esc(e.desc)}</td>
              <td style="font-weight:700;color:${e.delta>=0?'var(--red)':'var(--emerald)'}">${e.delta>=0?'+':''}${CUR.fmtUsd(e.delta)}</td>
              <td style="font-weight:700;color:var(--gold)">${CUR.fmtUsd(e.balance)}</td>
            </tr>`).join('') : '<tr><td colspan="4" style="text-align:center;color:var(--text-muted)">Hali tarix yo\'q</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>
    <div class="modal-footer"><button class="btn btn-ghost" onclick="closeModal()">Yopish</button></div>`);
}

function printTaminotchiTarixi(sid) {
  const s = S.suppliers.find(x=>x.id===sid); if (!s) return;
  const events = taminotchiLedger(sid);
  const w = fwDocWin();
  w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Ta'minotchi tarixi — ${esc(s.name)}</title>
  <style>body{font-family:Arial,sans-serif;font-size:12px;margin:24px}table{width:100%;border-collapse:collapse}
  th{background:#1a2236;color:#f5a623;padding:7px;text-align:left}td{padding:6px 7px;border-bottom:1px solid #eee}
  .plus{color:#e23d3d;font-weight:bold}.minus{color:#0ea876;font-weight:bold}</style></head><body>
  <h2>🕒 Ta'minotchi tarixi — ${esc(s.name)}</h2>
  <p>${new Date().toLocaleString('uz-UZ')} | ${esc(fwBrand().name)} | Joriy qarzi: <strong>${CUR.fmtUsd(s.debt||0)}</strong></p>
  <table><thead><tr><th>Sana</th><th>Izoh</th><th>Miqdor</th><th>Balans</th></tr></thead><tbody>
  ${events.length ? events.map(e=>`<tr><td>${fmtD(e.date)}</td><td>${esc(e.desc)}</td><td class="${e.delta>=0?'plus':'minus'}">${e.delta>=0?'+':''}${CUR.fmtUsd(e.delta)}</td><td>${CUR.fmtUsd(e.balance)}</td></tr>`).join('') : '<tr><td colspan="4" style="text-align:center">Hali tarix yo\'q</td></tr>'}
  </tbody></table></body></html>`);
  w.document.close(); w.print();
}

// ════════════════════════════════════════════
// HAMKORLAR
// ════════════════════════════════════════════
const PARTNER_COLORS = ['#B8700C','#0ea876','#7c3aed','#2f6fed','#e23d3d','#0ea5e9'];

// ── v23: HAMKORLAR — HAR BIR FILIALNING O'Z INVESTORLARI ──────────────
// Filial o'z balansini, hisob-kitobini, investorlari va mijozlarini o'zi yuritadi (egasining
// qarori). Eski yozuvlarda "filial" maydoni yo'q → ular Bazaniki ('baza') hisoblanadi, shuning
// uchun mavjud ma'lumot va qoidalar o'zgarmaydi. Server ham (appDataGuard) admin bo'lmagan
// xodimga faqat O'Z filiali hamkorlarini o'zgartirishga ruxsat beradi.
function partnerFilial(x) { return (x && x.filial) || 'baza'; }
function brPartners() { return (S.partners||[]).filter(p => partnerFilial(p) === S.branch); }
function brPartner(pid) { return brPartners().find(x => x.id === pid); }
function brPeriods() { return sortPartnerPeriods((S.partnerPeriods||[]).filter(per => partnerFilial(per) === S.branch)); }

function pgHamkorlar() {
  const el=document.getElementById('pg-hamkorlar');
  const partners = brPartners();
  const totalInvested = partners.reduce((s,p)=>s+(p.invested||0),0);
  S.partnerPeriods = sortPartnerPeriods(S.partnerPeriods);
  const founderCount = partners.filter(p=>p.isFounder).length;
  const founderPctSet = partners.some(p=>p.isFounder && p.founderPct!==undefined && p.founderPct!==null && p.founderPct!=='');
  const lastPer = (S.partnerPeriods||[]).find(x=>!x.filial || x.filial===S.branch);
  el.innerHTML=`
    ${fwHero({ tone:'gold', label:'Hamkorlar investitsiyasi', badge: esc(branchName(S.branch)), big: fwMoneyUsd(totalInvested),
      cols:[[partners.length,'Hamkor'],[founderCount,'Taʼsischi','var(--amber)'],[lastPer?esc(monthLabel(lastPer.ym||lastPer.month||'')):'—','Oxirgi taqsimot','var(--emerald)']] })}
    ${(() => { const dr = fwPeriodDrift(); return dr ? `<button class="fw-drift" onclick="fwPeriodDriftFix()">${ICONF.warning}<span><b>${esc(monthLabel(periodMonth(dr.period)))} yopilgandan keyin oʻzgardi</b><small>Oy foydasi ${dr.delta >= 0 ? '+' : '−'}${CUR.fmtUsd(Math.abs(dr.delta))} — taqsimotni qayta hisoblash</small></span>${ICONF.chevron}</button>` : ''; })()}
    ${fwCta('Oyni hisoblash (foyda taqsimoti)', 'openMonthlyCalc()', 'calc')}
    ${fwActs([
      ['add','sky','Hamkor','openAddPartner()'],
      ['wallet','pink','Hamkor xarajati',"S.xarajatTab='hamkor';go('xarajatlar')"],
      ['building','purple','Bosh kassa',"go('firmakassa')"],
      ['chart','emerald','Statistika',"go('hisobot')"],
    ])}
    ${partners.length ? `<div class="hm-share">${partners.map(p=>`<i style="width:${totalInvested>0?((p.invested||0)/totalInvested*100):0}%;background:${esc(p.color||'var(--gold)')}" title="${esc(p.name)}"></i>`).join('')}</div>` : ''}
    <div class="fw-list" style="margin-bottom:14px">
      ${partners.map(p=>{
        const pct = totalInvested>0 ? (p.invested||0)/totalInvested*100 : 0;
        const todayYm = td().slice(0,7);
        const pendingDep = partnerPendingDeposits(p.id, td(), todayYm);
        const nextElig = pendingDep>0 ? partnerNextEligibleMonth(p.id, td(), todayYm) : null;
        return `<article class="fw-pc hm-pc">
          <span class="fw-av" style="--c:${esc(p.color||'var(--gold)')}">${p.isFounder?ICONF.star:fwInitials(p.name)}</span>
          <div class="fw-pc-m"><b>${esc(p.name)}</b><small>${p.isFounder?'Taʼsischi':'Hamkor'} · ulush <b style="color:${esc(p.color||'var(--gold)')}">${pct.toFixed(1)}%</b></small>
            <small>${p.isFounder
              ? `Taʼsischilar ulushi: ${founderPctSet?(+Number(p.founderPct||0).toFixed(2))+'%':'teng ('+(100/Math.max(1,founderCount)).toFixed(0)+'%)'}`
              : `Foydadan oladi ${100-(p.keepPct||0)}% · taʼsischilarga ${p.keepPct||0}%`}</small></div>
          <div class="fw-pc-v"><b style="color:var(--gold)">${CUR.fmtUsd(p.invested||0)}</b><small>hisobi</small></div>
          ${pendingDep>0?`<p class="hm-pend">${ICONF.hourglass}<span>${CUR.fmtUsd(pendingDep)} kirim hali band${nextElig?` — ${monthLabel(nextElig)}dan foyda taqsimotiga qoʻshiladi`:''}</span></p>`:''}
          <div class="fw-pc-a">
            <button class="fw-btn" onclick="openHamkorTarixi(${p.id})">${ICONF.history}<span>Tarix</span></button>
            <button class="fw-btn" onclick="openPartnerReport(${p.id})">${ICONF.receipt}<span>Hisobot</span></button>
            <button class="fw-btn${p.tgChat?' ok':''}" onclick="openPartnerTg(${p.id})" title="${p.tgChat?'Telegram ulangan':'Telegramga ulash'}">${ICONF.send}<span>${p.tgChat?'Ulangan':'Telegram'}</span></button>
            <button class="fw-btn" onclick="editPartner(${p.id})">${ICONF.edit}<span>Tahrir</span></button>
          </div>
        </article>`;
      }).join('') || fwEmpty('people','Hamkor yoʻq','«Hamkor» tugmasi bilan qoʻshing.')}
    </div>

    ${partnerMonthsHtml()}`;
}

// Hamkor % maydonlari: oddiy hamkor — "ta'sischilarga qoladigan qism (%)",
// ta'sischi — "ta'sischilar o'rtasidagi ulush (%)". Ikkalasi ham jonli izoh bilan.
function partnerPctFieldsHtml(pre, p) {
  const keep = p.isFounder ? 0 : (p.keepPct||0);
  const fp = (p.founderPct===undefined||p.founderPct===null) ? '' : p.founderPct;
  return `<div id="${pre}-keep-wrap" class="form-group" style="${p.isFounder?'display:none':''}">
      <label class="form-label">Ta'sischilarga qoladigan qism (%) — hamkor foydasidan</label>
      <input class="form-control" id="${pre}-keep" type="number" value="${keep}" min="0" max="100" oninput="partnerKeepHint('${pre}')">
      <div id="${pre}-keep-hint" style="font-size:11px;color:var(--text-muted);margin-top:4px">Hamkor o'z foyda ulushining <b>${100-keep}%</b>ini oladi, <b>${keep}%</b>i ta'sischilarga qoladi.</div>
    </div>
    <div id="${pre}-fp-wrap" class="form-group" style="${p.isFounder?'':'display:none'}">
      <label class="form-label">Ta'sischilar o'rtasidagi ulushi (%)</label>
      <input class="form-control" id="${pre}-fp" type="number" value="${fp}" min="0" max="100" step="0.01" placeholder="bo'sh — ta'sischilar teng bo'ladi">
      <div style="font-size:11px;color:var(--text-muted);margin-top:4px">Barcha ta'sischilar ulushi yig'indisi 100% bo'lishi kerak (masalan 60 va 40). Hech biriga kiritilmasa — teng bo'linadi. Ta'sischi xarajatlari ham shu ulushda ayiriladi.</div>
    </div>`;
}
function partnerKeepHint(pre) {
  const v = Math.min(100, Math.max(0, parseFloat(document.getElementById(pre+'-keep')?.value||0)||0));
  const h = document.getElementById(pre+'-keep-hint');
  if (h) h.innerHTML = `Hamkor o'z foyda ulushining <b>${100-v}%</b>ini oladi, <b>${v}%</b>i ta'sischilarga qoladi.`;
}
function partnerFounderToggle(pre) {
  const on = document.getElementById(pre+'-founder')?.checked;
  const kw = document.getElementById(pre+'-keep-wrap'), fw = document.getElementById(pre+'-fp-wrap');
  if (kw) kw.style.display = on ? 'none' : '';
  if (fw) fw.style.display = on ? '' : 'none';
  if (!on) { const k = document.getElementById(pre+'-keep'); if (k && k.value==='100') { k.value = 0; partnerKeepHint(pre); } }
}
function readPartnerPctFields(pre, isFounder) {
  if (isFounder) {
    const raw = document.getElementById(pre+'-fp')?.value;
    if (raw===undefined || raw==='') return { keepPct:0, founderPct:null };
    const fp = parseFloat(raw);
    if (!(fp>=0 && fp<=100)) { toast("Ta'sischi ulushi 0–100% oralig'ida bo'lishi kerak!",'error'); return null; }
    return { keepPct:0, founderPct:fp };
  }
  const k = parseFloat(document.getElementById(pre+'-keep')?.value||0);
  if (!(k>=0 && k<=100)) { toast("Foiz 0–100 oralig'ida bo'lishi kerak!",'error'); return null; }
  return { keepPct:k, founderPct:null };
}

function openAddPartner() {
  modal(`
    <div class="modal-header"><div class="modal-title">👥 Yangi hamkor</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${meField('Ism *', `<input class="form-control" id="np-n" placeholder="Hamkor ismi yoki 'Siz (Ta'sischi)'" autocomplete="off">`)}
      ${meField('Hozirgi hisobi / investitsiya', meAmt('np-inv', 0, '$'))}
      ${meSec('Foyda taqsimoti')}
      ${meSw('np-founder', "👑 Bu — ta'sischi", "Hamkorlardan ushlab qolingan foyda ta'sischilarga bo'linadi.", false, `onchange="partnerFounderToggle('np')"`)}
      ${partnerPctFieldsHtml('np', {isFounder:false, keepPct:0})}
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" onclick="savePartner()">💾 Saqlash</button>
    </div>`);
}

function savePartner() {
  const name=document.getElementById('np-n')?.value?.trim();
  if(!name){toast('Ism kiriting!','error');return;}
  const inv=parseFloat(document.getElementById('np-inv')?.value||0);
  const isFounder=document.getElementById('np-founder')?.checked||false;
  const pc = readPartnerPctFields('np', isFounder); if (!pc) return;
  const av = name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase()||'H';
  const color = PARTNER_COLORS[brPartners().length % PARTNER_COLORS.length];
  // v23: hamkor shu filialga tegishli (filial o'z investorlari bilan o'zi hisob-kitob qiladi)
  S.partners.push({id:uid(),name,invested:inv,keepPct:pc.keepPct,founderPct:pc.founderPct,isFounder,color,av,filial:S.branch,updatedAt:Date.now()});
  save();closeModal();pgHamkorlar();toast("✅ Hamkor qo'shildi!");
}

function editPartner(pid) {
  const p=brPartner(pid); if(!p) return;
  modal(`
    <div class="modal-header"><div class="modal-title">✏️ Hamkorni tahrirlash</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${meCard({ name:p.name, sub:p.isFounder?"👑 Ta'sischi":'Hamkor', kpi:CUR.fmtUsd(p.invested||0), kpiLabel:'hisobi',
        acts: meActs([ ['history','Tarix',`closeModal();openHamkorTarixi(${pid})`] ]) })}
      ${meSec('Asosiy')}
      ${meField('Ism *', `<input class="form-control" id="ep-n" value="${esc(p.name)}">`)}
      ${meField('Hozirgi hisobi', meAmt('ep-inv', (p.invested||0).toFixed(2), '$'))}
      ${meSec('Foyda taqsimoti')}
      ${meSw('ep-founder', "👑 Bu — ta'sischi", '', !!p.isFounder, `onchange="partnerFounderToggle('ep')"`)}
      ${partnerPctFieldsHtml('ep', p)}
    </div>
    <div class="modal-footer">
      <button class="btn btn-danger btn-sm" onclick="deletePartner(${pid})">🗑 O'chirish</button>
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" onclick="saveEditPartner(${pid})">💾 Saqlash</button>
    </div>`);
}

function saveEditPartner(pid) {
  const p=brPartner(pid); if(!p) return;
  const name=document.getElementById('ep-n')?.value?.trim();
  if(!name){toast('Ism kiriting!','error');return;}
  p.name=name;
  p.invested=parseFloat(document.getElementById('ep-inv')?.value||0);
  const isFounder=document.getElementById('ep-founder')?.checked||false;
  const pc = readPartnerPctFields('ep', isFounder); if (!pc) return;
  p.isFounder=isFounder;
  p.keepPct=pc.keepPct;
  p.founderPct=pc.founderPct;
  p.updatedAt=Date.now();
  p.av = name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase()||'H';
  closeModal();pgHamkorlar();fwSaveToast('✅ Saqlandi!');
}

function deletePartner(pid) {
  if(!confirm("Hamkorni o'chirasizmi?")) return;
  if (!brPartner(pid)) return;
  S.partners = S.partners.filter(p=>p.id!==pid);
  markDeleted('partners', pid);
  save();closeModal();pgHamkorlar();toast("✅ O'chirildi!",'warning');
}

// ── HAMKOR TARIXI — oylik taqsimotlar + shu hamkorga yozilgan xarajatlar, xronologik ──
function partnerLedger(pid) {
  const p = brPartner(pid);
  const events = [];
  S.expenses.filter(e=>e.turi==='hamkor' && e.partnerId===pid).forEach(e=>{
    const isKirim = e.kind==='kirim';
    events.push({ date:e.date, desc:isKirim?`💰 Kirim: ${fwExpCatLabel(e)}${e.desc?' — '+e.desc:''}`:`💸 Xarajat: ${fwExpCatLabel(e)}${e.desc?' — '+e.desc:''}`, delta: isKirim?(e.amtUsd||0):-(e.amtUsd||0) });
  });
  brPeriods().forEach(per=>{
    const row = per.rows.find(r=>r.pid===pid);
    if (row) events.push({ date:per.end, desc:`📊 Oylik taqsimot (${fmtD(per.start)}–${fmtD(per.end)})`, delta:row.foydaPlus });
  });
  events.sort((a,b)=> a.date<b.date?-1:a.date>b.date?1:0);
  const totalDelta = events.reduce((s,e)=>s+e.delta,0);
  let bal = (p?.invested||0) - totalDelta;
  events.forEach(e=>{ bal += e.delta; e.balance = bal; });
  return events;
}

function openHamkorTarixi(pid) {
  const p = brPartner(pid); if (!p) return;
  const events = partnerLedger(pid);
  modal(`
    <div class="modal-header"><div class="modal-title">🕒 ${esc(p.name)} — hamkor tarixi</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <span style="font-size:12px;color:var(--text-muted)">Joriy hisobi: <strong style="color:var(--gold)">${CUR.fmtUsd(p.invested||0)}</strong></span>
        <button class="btn btn-ghost btn-sm" onclick="printHamkorTarixi(${pid})">🖨️ Chop etish</button>
      </div>
      <div class="table-wrap" style="max-height:420px;overflow-y:auto">
        <table>
          <thead><tr><th>Sana</th><th>Izoh</th><th>Miqdor</th><th>Balans</th></tr></thead>
          <tbody>
            ${events.length ? events.map(e=>`<tr>
              <td>${fmtD(e.date)}</td>
              <td style="color:var(--text-secondary)">${esc(e.desc)}</td>
              <td style="font-weight:700;color:${e.delta>=0?'var(--emerald)':'var(--red)'}">${e.delta>=0?'+':''}${CUR.fmtUsd(e.delta)}</td>
              <td style="font-weight:700;color:var(--gold)">${CUR.fmtUsd(e.balance)}</td>
            </tr>`).join('') : '<tr><td colspan="4" style="text-align:center;color:var(--text-muted)">Hali tarix yo\'q</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>
    <div class="modal-footer"><button class="btn btn-ghost" onclick="closeModal()">Yopish</button></div>`);
}

function printHamkorTarixi(pid) {
  const p = brPartner(pid); if (!p) return;
  const events = partnerLedger(pid);
  const w = fwDocWin();
  w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Hamkor tarixi — ${esc(p.name)}</title>
  <style>body{font-family:Arial,sans-serif;font-size:12px;margin:24px}table{width:100%;border-collapse:collapse}
  th{background:#1a2236;color:#f5a623;padding:7px;text-align:left}td{padding:6px 7px;border-bottom:1px solid #eee}
  .plus{color:#0ea876;font-weight:bold}.minus{color:#e23d3d;font-weight:bold}</style></head><body>
  <h2>🕒 Hamkor tarixi — ${esc(p.name)}</h2>
  <p>${new Date().toLocaleString('uz-UZ')} | ${esc(fwBrand().name)} | Joriy hisobi: <strong>${CUR.fmtUsd(p.invested||0)}</strong></p>
  <table><thead><tr><th>Sana</th><th>Izoh</th><th>Miqdor</th><th>Balans</th></tr></thead><tbody>
  ${events.length ? events.map(e=>`<tr><td>${fmtD(e.date)}</td><td>${esc(e.desc)}</td><td class="${e.delta>=0?'plus':'minus'}">${e.delta>=0?'+':''}${CUR.fmtUsd(e.delta)}</td><td>${CUR.fmtUsd(e.balance)}</td></tr>`).join('') : '<tr><td colspan="4" style="text-align:center">Hali tarix yo\'q</td></tr>'}
  </tbody></table></body></html>`);
  w.document.close(); w.print();
}

// Taqsimotlar — eng so'nggisi (eng katta id — uid() vaqtga bog'liq) birinchi
function sortPartnerPeriods(list) {
  return (Array.isArray(list)?list:[]).slice().sort((a,b)=>(Number(b.id)||0)-(Number(a.id)||0));
}

function calcProfitForRange(start, end) {
  const inRange = (d) => { const x = String(d||'').slice(0,10); return x>=start && x<=end; };
  const salesProfit = S.sales.filter(s=>inRange(s.date)).reduce((s,x)=>s+(x.profitUsd||0),0);
  // Faqat DO'KON xarajatlari korxona foydasidan ayriladi — ta'sischi xarajatlari bu yerga kirmaydi
  const exp = S.expenses.filter(e=>inRange(e.date) && (e.turi||'dokon')==='dokon').reduce((s,e)=>s+(e.amtUsd||CUR.toUsd(e.amount||0)),0);
  const wo = typeof fwWriteoffLoss==='function' ? fwWriteoffLoss(start, end) : 0;   // v23.6: hisobdan chiqarish zarari ham ayriladi
  return salesProfit - exp - wo;
}

function tasischiExpensesForRange(start, end) {
  const inRange = (d) => { const x = String(d||'').slice(0,10); return x>=start && x<=end; };
  return S.expenses.filter(e=>inRange(e.date) && e.turi==='tasischi').reduce((s,e)=>s+(e.amtUsd||CUR.toUsd(e.amount||0)),0);
}

// ════════════════════════════════════════════════════════════
// HAMKORLAR FOYDA TAQSIMOTI — YAGONA FORMULA (2026-09-28)
// Sof funksiya: S'ni o'zgartirmaydi — oldindan ko'rish (preview) ham,
// haqiqiy hisoblash ham AYNAN shu natijadan foydalanadi.
//
//  1) Har bir hamkorning ulushi (pct) = uning "foyda uchun hisobi" (shareBase) /
//     jami. shareBase = oy boshidagi hisob − shu oyda olgan summasining YARMI
//     (AZIMSHER qoidasi, 2026-09-28). shareBase berilmasa — joriy hisob (invested).
//  2) foydaSumma = jami foyda × pct
//  3) Oddiy hamkor: keepPct — ta'sischilarga qoladigan qism;
//       hamkor oladi = foydaSumma × (100 − keepPct)%
//     Ta'sischi: o'z ulushining 100%ini oladi
//  4) Oddiy hamkorlardan ushlab qolingan jami summa ta'sischilar o'rtasida
//     ularning founderPct ulushiga ko'ra bo'linadi (hech biriga belgilanmagan
//     bo'lsa — teng). Ta'sischi xarajatlari ham xuddi shu ulushda ayiriladi.
//  5) jamiSumma = invested + foydaPlus (keyingi davr uchun yangi hisob)
// Natija: { ok, error?, rows, totalInvested, keptTotal, tasExp }
// ════════════════════════════════════════════════════════════
function computePartnerDistribution(partners, totalProfit, tasExp) {
  const list = (partners||[]).filter(Boolean);
  if (!list.length) return { ok:false, error:"Avval hamkor qo'shing!" };
  const baseOf = (p) => (p.shareBase!==undefined && p.shareBase!==null) ? Number(p.shareBase)||0 : Number(p.invested)||0;
  const totalInvested = list.reduce((s,p)=>s+(Number(p.invested)||0),0);
  const totalBase = list.reduce((s,p)=>s+baseOf(p),0);
  if (!(totalBase>0)) return { ok:false, error:"Hamkorlar hisobi 0 — % hisoblab bo'lmaydi!" };
  const founders = list.filter(p=>p.isFounder);
  const withPct = founders.filter(p=>p.founderPct!==undefined && p.founderPct!==null && p.founderPct!=='');
  if (withPct.length) {
    if (withPct.length !== founders.length) return { ok:false, error:"Ta'sischilar ulushi (%) hamma ta'sischiga kiritilishi kerak (yoki hech biriga)." };
    const sum = founders.reduce((s,p)=>s+(Number(p.founderPct)||0),0);
    if (Math.abs(sum-100) > 0.01) return { ok:false, error:`Ta'sischilar ulushi yig'indisi 100% bo'lishi kerak (hozir ${+sum.toFixed(2)}%).` };
  }
  const founderShare = (p) => withPct.length ? (Number(p.founderPct)||0)/100 : 1/founders.length;

  const profit = Number(totalProfit)||0;
  const rows = list.map(p=>{
    const invested = Number(p.invested)||0;
    const base = baseOf(p);
    const pct = base/totalBase*100;
    const foydaSumma = profit*pct/100;
    const isFounder = !!p.isFounder;
    const keepPct = isFounder ? 0 : Math.min(100, Math.max(0, Number(p.keepPct)||0));
    const foydaPlus = isFounder ? foydaSumma : foydaSumma*(100-keepPct)/100;
    return { pid:p.id, name:p.name, invested, base, monthStart: p.monthStart ?? null, withdrawn: p.withdrawn ?? 0, pendingDeposits: p.pendingDeposits ?? 0, pct, foydaSumma, foydaPlus, isFounder, keepPct,
             founderPct: isFounder ? +(founderShare(p)*100).toFixed(4) : null, keptFromOthers:0, tasExpShare:0 };
  });
  const keptTotal = rows.filter(r=>!r.isFounder).reduce((s,r)=>s+(r.foydaSumma-r.foydaPlus),0);
  const exp = Number(tasExp)||0;
  const founderRows = rows.filter(r=>r.isFounder);
  if (founderRows.length) {
    founderRows.forEach(r=>{
      const sh = r.founderPct/100;
      r.keptFromOthers = keptTotal*sh;
      r.tasExpShare = exp*sh;
      r.foydaPlus += r.keptFromOthers - r.tasExpShare;
    });
  } else if (rows.length) {
    rows[0].foydaPlus += keptTotal; // ta'sischi belgilanmagan bo'lsa — birinchisiga (eski xulq)
    rows[0].keptFromOthers = keptTotal;
  }
  rows.forEach(r=>{ r.jamiSumma = r.invested + r.foydaPlus; });
  return { ok:true, rows, totalInvested, totalBase, keptTotal, tasExp: founderRows.length ? exp : 0 };
}

function partnerDistributionTableHtml(res) {
  if (!res.ok) return `<div style="color:var(--red);font-weight:600;font-size:13px">⚠️ ${esc(res.error)}</div>`;
  return `<div class="table-wrap mc-compact"><table>
    <thead><tr><th>Hamkor</th><th>Oy boshida</th><th>Oyda oldi</th><th title="Oy boshidagi hisob − oyda olganining yarmi">Foyda uchun hisob</th><th>Ulush</th><th>Foyda ulushi</th><th>Ta'sischiga qoladi</th><th>Oladi</th><th>Yangi hisob</th></tr></thead>
    <tbody>${res.rows.map(r=>`<tr>
      <td style="font-weight:600">${r.isFounder?'👑 ':''}${esc(r.name)}${r.isFounder?`<div style="font-size:10px;color:var(--text-muted)">ta'sischilar ulushi: ${(+r.founderPct.toFixed(2))}%</div>`:''}</td>
      <td>${CUR.fmtUsd(r.monthStart ?? r.invested)}${r.pendingDeposits>0?`<div style="font-size:10px;color:var(--purple)" title="Oldingi oy(lar)da qo'shilgan, hali foyda taqsimotiga qo'shilmagan kirim">⏳ band: ${CUR.fmtUsd(r.pendingDeposits)}</div>`:''}</td>
      <td style="color:${r.withdrawn>0?'var(--red)':'var(--text-muted)'}">${r.withdrawn>0?'−'+CUR.fmtUsd(r.withdrawn):'—'}</td>
      <td style="font-weight:700">${CUR.fmtUsd(r.base ?? r.invested)}</td>
      <td>${r.pct.toFixed(1)}%</td>
      <td>${CUR.fmtUsd(r.foydaSumma)}</td>
      <td>${r.isFounder ? (r.keptFromOthers? '+'+CUR.fmtUsd(r.keptFromOthers):'—') + (r.tasExpShare?`<div style="font-size:10px;color:var(--red)">xarajat −${CUR.fmtUsd(r.tasExpShare)}</div>`:'') : `${r.keepPct}% · ${CUR.fmtUsd(r.foydaSumma-r.foydaPlus)}`}</td>
      <td style="font-weight:700;color:var(--emerald)">${CUR.fmtUsd(r.foydaPlus)}</td>
      <td style="font-weight:700;color:var(--gold)">${CUR.fmtUsd(r.jamiSumma)}</td>
    </tr>`).join('')}</tbody></table></div>`;
}

// ── OYLIK TAQSIMOT: har bir oy bitta taqsimot, hisoblangan oy YOPILADI ──
// (2026-09-28, AZIMSHER talabi). Davr = oyning 1-kunidan oxirgi kunigacha.
function fmtDMY(s) { if(!s) return ''; const [y,m,d]=String(s).slice(0,10).split('-'); return `${d}.${m}.${y}`; }
function periodMonth(per) { return per.month || String(per.start||'').slice(0,7); }
function monthRange(ym) {
  const [y, m] = ym.split('-').map(Number);
  const last = new Date(y, m, 0).getDate();
  return { start: `${ym}-01`, end: `${ym}-${String(last).padStart(2,'0')}` };
}
function monthLabel(ym) {
  const names = ['Yanvar','Fevral','Mart','Aprel','May','Iyun','Iyul','Avgust','Sentabr','Oktabr','Noyabr','Dekabr'];
  const [y, m] = ym.split('-').map(Number);
  return `${names[m-1]||ym} ${y}`;
}
function isMonthClosed(ym, exceptId) {
  return brPeriods().some(per => periodMonth(per)===ym && per.id!==exceptId);
}

// ════════════════════════════════════════════════════════════
// v24.4 — YOPIQ OY QOIDASI (egasi qarori 2026-10-14):
// foydasi hamkorlarga taqsimlangan oyga sana bilan savdo, qaytarish, xarajat yoki hisobdan chiqarish kiritilsa —
//   • OXIRGI yopiq oy: ogohlantirish → tasdiqlansa yozuv kiritiladi va shu oy taqsimoti avtomatik qayta hisoblanib
//     yopiladi (hamkor hisoblariga faqat FARQ yoziladi; qo'lda kiritilgan foyda tuzatishi saqlanadi — oy foydasi
//     yozuv keltirgan farq qadar o'zgaradi);
//   • undan ESKI yopiq oy — taqiq (avval keyingi oylar taqsimotini bekor qilish kerak).
// Kirimning o'zi oy foydasiga ta'sir qilmaydi (faqat sotilganda).
// ════════════════════════════════════════════════════════════
async function fwClosedMonthCheck(dates, what) {
  const per = brPeriods(); if (!per.length) return { ok: true, period: null };
  const months = [...new Set((dates || []).filter(Boolean).map(d => String(d).slice(0, 7)))];
  const closed = months.filter(ym => per.some(p => periodMonth(p) === ym));
  if (!closed.length) return { ok: true, period: null };
  const latest = per[0], lym = periodMonth(latest);
  const older = closed.find(ym => ym !== lym);
  if (older) {
    toast(`⛔ ${monthLabel(older)} foydasi hamkorlarga taqsimlangan va undan keyingi oy ham yopilgan — ${what} mumkin emas. Avval keyingi oylar taqsimotini bekor qiling (Hamkorlar).`, 'error');
    return { ok: false };
  }
  // v24.5: yopiq oyni o'zgartirish — xavfli amal: Egasining paroli bilan tasdiqlanadi (bulutsiz — oddiy tasdiq)
  if (!(await fwOwnerConfirm(`⚠️ ${monthLabel(lym)} foydasi hamkorlarga taqsimlangan (oy yopilgan).\n\nDavom etsangiz: shu oy taqsimoti bekor qilinadi, ${what} yoziladi va ${monthLabel(lym)} foydasi qayta hisoblanib, taqsimot qayta yopiladi.`, { title: 'Yopiq oy', okText: 'Davom etish' }))) return { ok: false };
  const { start, end } = monthRange(lym);
  return { ok: true, period: latest, before: calcProfitForRange(start, end), tasBefore: tasischiExpensesForRange(start, end), what };
}
// Yozuv muvaffaqiyatli bo'lgach chaqiriladi: oy foydasi farq qadar o'zgaradi, taqsimot qayta yopiladi
function fwReclosePeriod(g, reason) {
  if (!g || !g.period) return;
  const period = brPeriods().find(p => p.id === g.period.id); if (!period) return;
  const ym = periodMonth(period), { start, end } = monthRange(ym);
  const after = calcProfitForRange(start, end);
  const delta = Math.round((after - (g.before != null ? g.before : after)) * 100) / 100;
  const tasExp = tasischiExpensesForRange(start, end);
  // amal bekor qilingan yoki oy foydasiga ta'sir qilmagan bo'lsa — taqsimot o'zgarmaydi
  if (Math.abs(delta) < 0.005 && g.tasBefore != null && Math.abs(tasExp - g.tasBefore) < 0.005) return;
  const totalProfit = Math.round(((+period.totalProfit || 0) + delta) * 100) / 100;
  const res = computePartnerDistribution(_partnersForPeriod(period, ym), totalProfit, tasExp);
  if (!res.ok) { toast(`⚠️ ${monthLabel(ym)} taqsimotini qayta hisoblab boʻlmadi: ${res.error}. Hamkorlar boʻlimida qoʻlda yoping.`, 'warning'); return; }
  const oldMap = Object.fromEntries((period.rows || []).map(r => [r.pid, r.foydaPlus || 0])), now = Date.now();
  res.rows.forEach(r => { const p = brPartner(r.pid); if (p) { p.invested = (p.invested || 0) + (r.foydaPlus - (oldMap[r.pid] || 0)); p.updatedAt = now; } });
  const hist = (period.recalcs || []).concat([{ at: new Date().toISOString(), reason: String(reason || g.what || '').slice(0, 200), delta, from: +period.totalProfit || 0, to: totalProfit }]).slice(-30);
  Object.assign(period, { totalProfit, totalInvested: res.totalInvested, rows: res.rows, tasischiExpense: res.tasExp, keptTotal: res.keptTotal, calcBase: after, recalcs: hist, editedAt: new Date().toISOString() });
  auditLog(`Hamkorlar taqsimoti qayta yopildi: ${monthLabel(ym)} — ${reason || g.what || ''} (foyda ${delta >= 0 ? '+' : '−'}${CUR.fmtUsd(Math.abs(delta))} → ${CUR.fmtUsd(totalProfit)})`);
  save();
  toast(`🔁 ${monthLabel(ym)} taqsimoti qayta hisoblandi va yopildi (foyda ${delta >= 0 ? '+' : '−'}${CUR.fmtUsd(Math.abs(delta))})`, 'success');
}
// Oxirgi yopiq oyda yopilgandan keyin (masalan, sotuvchi portalidan) o'zgarish bo'lganmi — Hamkorlar bo'limida eslatma
function fwPeriodDrift() {
  const per = brPeriods()[0]; if (!per || per.calcBase == null) return null;
  const { start, end } = monthRange(periodMonth(per));
  const d = Math.round((calcProfitForRange(start, end) - per.calcBase) * 100) / 100;
  return Math.abs(d) > 0.009 ? { period: per, delta: d } : null;
}
function fwPeriodDriftFix() {
  const dr = fwPeriodDrift(); if (!dr) return;
  if (!confirm(`${monthLabel(periodMonth(dr.period))} yopilgandan keyin oy foydasi ${dr.delta >= 0 ? '+' : '−'}${CUR.fmtUsd(Math.abs(dr.delta))} oʻzgargan. Taqsimot qayta hisoblanib yopilsinmi?`)) return;
  fwReclosePeriod({ period: dr.period, before: dr.period.calcBase }, 'Yopilgandan keyingi oʻzgarishlar');
  pgHamkorlar();
}
// Standart tanlov: o'tgan oy yopilmagan bo'lsa — o'tgan oy, aks holda joriy oy
function defaultCalcMonth() {
  const now = new Date();
  const prev = new Date(now.getFullYear(), now.getMonth()-1, 1);
  const ym = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
  return (!isMonthClosed(ym(prev)) && !monthOrderError(ym(prev))) ? ym(prev) : ym(now);
}

function partnerMonthsHtml() {
  const list = brPeriods();
  if (!list.length) return `<div class="card" style="margin-bottom:16px;text-align:center;color:var(--text-muted);padding:22px">
      📅 Hali birorta oy taqsimlanmagan — "📊 Oyni hisoblash" tugmasi bilan boshlang.</div>`;
  const latestId = list[0].id;
  return `<div class="card" style="margin-bottom:16px">
    <div class="card-header"><div class="card-title">📅 Oylik taqsimotlar</div>
      <span style="font-size:11px;color:var(--text-muted)">Hisoblangan oy yopiladi · tahrir/o'chirish faqat oxirgi oyda</span></div>
    ${list.map(per=>{
      const ym = periodMonth(per);
      const isLast = per.id===latestId;
      return `<div style="border-top:1px solid var(--border-light);padding:12px 16px">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap">
          <div style="display:flex;align-items:baseline;gap:12px;flex-wrap:wrap">
            <span style="font-weight:800;font-size:15px">${fmtDMY(per.start)}</span>
            <span style="font-size:12px;color:var(--text-muted)">${monthLabel(ym)}</span>
            <span style="font-weight:800;color:var(--gold);font-size:15px">${CUR.fmtUsd(per.totalProfit||0)}</span>
            ${isLast?'':'<span class="badge" style="background:rgba(0,0,0,.06);color:var(--text-muted)">🔒 yopilgan</span>'}
          </div>
          <div style="display:flex;gap:6px">
            ${isLast?`<button class="btn btn-ghost btn-sm btn-icon" title="Tahrirlash" onclick="openMonthlyCalc('${per.id}')">🖊</button>
            <button class="btn btn-ghost btn-sm btn-icon" title="O'chirish (bekor qilish)" onclick="undoLastPeriod()">🗑</button>`:''}
            <button class="btn btn-ghost btn-sm btn-icon" title="Chop etish" onclick="printPartnerPeriod('${per.id}')">🖨</button>
          </div>
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:4px 16px;margin-top:8px;font-size:13px">
          ${(per.rows||[]).map(r=>`<div style="display:flex;justify-content:space-between;gap:8px;padding:3px 0">
            <span>${r.isFounder?'👑 ':''}${esc(r.name)}</span>
            <strong style="color:${(r.foydaPlus||0)<0?'var(--red)':'var(--emerald)'}">${CUR.fmtUsd(r.foydaPlus||0)}</strong>
          </div>`).join('')}
        </div>
        ${per.tasischiExpense>0?`<div style="font-size:11px;color:var(--red);margin-top:4px">👑 Ta'sischi xarajatlari ayirildi: −${CUR.fmtUsd(per.tasischiExpense)}</div>`:''}
      </div>`;
    }).join('')}
  </div>`;
}

// Hamkorning oy davomidagi chiqimlari (Xarajatlar → Hamkorlar xarajatlari, "chiqim")
function partnerWithdrawals(pid, start, end) {
  return S.expenses.filter(e=>e.turi==='hamkor' && (!e.kind||e.kind==='chiqim') && e.partnerId===pid && String(e.date||'').slice(0,10)>=start && String(e.date||'').slice(0,10)<=end)
    .reduce((s,e)=>s+(e.amtUsd||0),0);
}
// Hamkorning oy davomida QO'SHGAN puli ("kirim" turidagi hamkor xarajati yozuvi)
function partnerDeposits(pid, start, end) {
  return S.expenses.filter(e=>e.turi==='hamkor' && e.kind==='kirim' && e.partnerId===pid && String(e.date||'').slice(0,10)>=start && String(e.date||'').slice(0,10)<=end)
    .reduce((s,e)=>s+(e.amtUsd||0),0);
}
// Kirim qo'shilgan sanaga qarab, u FOYDA TAQSIMOTIGA qaysi oydan boshlab qo'shiladi
// (AZIMSHER qoidasi, 2026-09-28): oyning 1–5-sanasida qo'shilsa — KEYINGI oydan;
// 6-sanadan boshlab qo'shilsa — undan KEYINGI oydan (bir oy o'tkazib) hisoblanadi.
function depositEffectiveMonth(dateStr) {
  const s = String(dateStr||'').slice(0,10);
  const parts = s.split('-').map(Number);
  const y = parts[0], mo = parts[1], da = parts[2] || 1;
  if (!y || !mo) return '9999-12';
  const addMonths = da <= 5 ? 1 : 2;
  let ny = y, nmo = mo + addMonths;
  while (nmo > 12) { nmo -= 12; ny++; }
  return `${ny}-${String(nmo).padStart(2,'0')}`;
}
// asOfDate sanagacha (shu sana ham) qo'shilgan kirimlar orasida, "ym" oyi uchun
// HALI band bo'lganlari (effektiv oyi ym'dan keyin bo'lganlari) yig'indisi.
function partnerPendingDeposits(pid, asOfDate, ym) {
  return S.expenses.filter(e=>e.turi==='hamkor' && e.kind==='kirim' && e.partnerId===pid
      && String(e.date||'').slice(0,10) <= asOfDate
      && depositEffectiveMonth(e.date) > ym)
    .reduce((s,e)=>s+(e.amtUsd||0),0);
}
// Band turgan kirimlar orasida ENG YAQIN ochiladigan oy (UI'da ko'rsatish uchun)
function partnerNextEligibleMonth(pid, asOfDate, ym) {
  const months = S.expenses.filter(e=>e.turi==='hamkor' && e.kind==='kirim' && e.partnerId===pid
      && String(e.date||'').slice(0,10) <= asOfDate
      && depositEffectiveMonth(e.date) > ym)
    .map(e=>depositEffectiveMonth(e.date));
  return months.length ? months.sort()[0] : null;
}
// Oy uchun "foyda uchun hisob": oy boshidagi (band bo'lmagan) hisob − oyda olganining yarmi.
// Oy boshidagi hisob = joriy hisob + shu oyda va undan KEYIN olingan chiqimlar
// (ular joriy hisobdan allaqachon ayirilgan) − shu oyda va undan KEYIN qo'shilgan
// kirimlar (ular joriy hisobga allaqachon qo'shilgan, lekin oy boshida yo'q edi).
// Bundan tashqari, OLDINGI oylarda qo'shilgan, lekin hali eligibility oyi
// kelmagan ("band") kirimlar ham shareBase'dan chiqarib tashlanadi — ular
// oy boshidagi hisobning bir qismi bo'lsa-da, hali foyda olmaydi.
// Qo'lda kiritilgan hisob o'zgarishlarining sanasi yo'q — ular joriy
// hisobning bir qismi deb olinadi.
function partnersForMonth(ym) {
  const { start, end } = monthRange(ym);
  const far = '9999-12-31';
  const nextDay = (d) => { const x = new Date(d+'T00:00:00Z'); x.setUTCDate(x.getUTCDate()+1); return x.toISOString().slice(0,10); };
  const prevDay = (d) => { const x = new Date(d+'T00:00:00Z'); x.setUTCDate(x.getUTCDate()-1); return x.toISOString().slice(0,10); };
  return brPartners().map(p=>{
    const withdrawn = partnerWithdrawals(p.id, start, end);
    const afterW = partnerWithdrawals(p.id, nextDay(end), far);
    const depositedFromStart = partnerDeposits(p.id, start, far); // shu oy + keyingi oylarda qo'shilgan kirimlar
    const monthStart = (p.invested||0) + withdrawn + afterW - depositedFromStart;
    const pendingDeposits = partnerPendingDeposits(p.id, prevDay(start), ym); // oldingi oylarda qo'shilgan, hali band kirimlar
    const shareBase = monthStart - pendingDeposits - withdrawn/2;
    return { ...p, monthStart, withdrawn, pendingDeposits, shareBase };
  });
}
// Oylar ketma-ket yopiladi: oxirgi yopilgan oydan OLDINGI oyni hisoblab bo'lmaydi
function monthOrderError(ym, exceptId) {
  const closed = brPeriods().filter(x=>x.id!==exceptId).map(periodMonth).sort();
  const last = closed[closed.length-1];
  return (last && ym < last) ? `${monthLabel(ym)} — ${monthLabel(last)} allaqachon yopilgan, undan oldingi oyni hisoblab bo'lmaydi.` : '';
}

// editId berilsa — o'sha (oxirgi) oyni tahrirlash rejimi
function openMonthlyCalc(editId) {
  const editing = editId ? brPeriods().find(x=>String(x.id)===String(editId)) : null;
  const ym = editing ? periodMonth(editing) : defaultCalcMonth();
  const { start, end } = monthRange(ym);
  const profit = editing ? (editing.totalProfit||0) : calcProfitForRange(start, end);
  modal(`
    <div class="modal-header"><div class="modal-title">${editing?'🖊 Taqsimotni tahrirlash':'📊 Oylik foyda taqsimlash'}</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <input type="hidden" id="mc-edit" value="${editing?editing.id:''}">
      <div class="grid-2">
        <div class="form-group"><label class="form-label">Oy</label><input class="form-control" id="mc-month" type="month" value="${ym}" ${editing?'disabled':''} onchange="mcRecalc(true)"></div>
        <div class="form-group"><label class="form-label">Davr</label><div id="mc-range" style="padding:10px 0;font-weight:600">${fmtDMY(start)} – ${fmtDMY(end)}</div></div>
      </div>
      <div id="mc-closed" style="display:none;color:var(--red);font-weight:600;font-size:13px;margin-bottom:10px"></div>
      <div class="form-group"><label class="form-label">Jami foyda ($) — ${esc(branchName(S.branch))} savdolari foydasi − do'kon xarajatlari (kerak bo'lsa o'zgartiring)</label>
        <input class="form-control" id="mc-profit" type="number" step="0.01" value="${Number(profit).toFixed(2)}" oninput="mcRecalc(false)"></div>
      ${editing?`<div style="font-size:11px;color:var(--text-muted);margin:-6px 0 10px">Avtomatik hisob bo'yicha: ${CUR.fmtUsd(calcProfitForRange(start,end))}</div>`:''}
      <div id="mc-tas-info" style="font-size:12px;color:var(--purple);background:rgba(124,58,237,0.06);border:1px solid rgba(124,58,237,0.2);border-radius:var(--radius-sm);padding:10px 12px;margin-bottom:12px"></div>
      <div style="font-size:11px;color:var(--text-muted);margin-bottom:8px">Ulush "Foyda uchun hisob" bo'yicha: oy boshidagi hisob − shu oyda olgan summaning yarmi (masalan 2 000$ − (200$+300$)/2 = 1 750$). Yangi qo'shilgan kirim (⏳ band) — 1–5-sanada qo'shilsa keyingi oydan, 6-sanadan keyin qo'shilsa undan keyingi oydan foyda taqsimotiga qo'shiladi.</div>
      <div style="font-size:12px;font-weight:700;margin-bottom:6px">Kim qancha oladi (saqlashdan oldin tekshiring):</div>
      <div id="mc-preview"></div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" id="mc-save" onclick="doMonthlyCalc()">${editing?'💾 Saqlash':'✅ Hisoblash va oyni yopish'}</button>
    </div>`);
  const md = document.querySelector('#modal-ov .modal'); if (md) { md.style.width = '1100px'; md.style.maxWidth = '96vw'; }
  mcRecalc(false);
}

// Tahrirda: foizlar taqsimot paytidagi hisoblar (snapshot) asosida qayta hisoblanadi
function _partnersForPeriod(editing, ym) {
  if (!editing) return ym ? partnersForMonth(ym) : brPartners();
  return (editing.rows||[]).map(r=>{
    const p = brPartner(r.pid) || {};
    return { ...p, id:r.pid, name:p.name||r.name, invested:r.invested, shareBase: r.base ?? r.invested, monthStart: r.monthStart ?? null, withdrawn: r.withdrawn||0, pendingDeposits: r.pendingDeposits||0, isFounder: p.id!==undefined ? p.isFounder : r.isFounder };
  });
}

function mcRecalc(fromMonth) {
  const editId = document.getElementById('mc-edit')?.value || '';
  const editing = editId ? brPeriods().find(x=>String(x.id)===editId) : null;
  const ym = document.getElementById('mc-month')?.value;
  if (!ym) return;
  const { start, end } = monthRange(ym);
  const rg = document.getElementById('mc-range'); if (rg) rg.textContent = `${fmtDMY(start)} – ${fmtDMY(end)}`;
  const el=document.getElementById('mc-profit');
  if (fromMonth && el) el.value = calcProfitForRange(start,end).toFixed(2);
  const orderErr = editing ? '' : monthOrderError(ym);
  const closed = isMonthClosed(ym, editing?.id) || !!orderErr;
  const cl = document.getElementById('mc-closed');
  if (cl) { cl.style.display = closed?'':'none'; cl.textContent = !closed ? '' : (orderErr ? '🔒 '+orderErr : `🔒 ${monthLabel(ym)} allaqachon taqsimlangan (yopilgan). Boshqa oyni tanlang yoki ro'yxatdan tahrirlang.`); }
  const tasExp = tasischiExpensesForRange(start, end);
  const tasEl = document.getElementById('mc-tas-info');
  if (tasEl) tasEl.innerHTML = `👑 Shu oydagi ta'sischilar xarajatlari: <strong>${CUR.fmtUsd(tasExp)}</strong> — ta'sischilar o'rtasida ularning ulushiga ko'ra ayiriladi (korxona foydasiga ta'sir qilmaydi).`;
  const res = computePartnerDistribution(_partnersForPeriod(editing, ym), parseFloat(el?.value||0), tasExp);
  const pv = document.getElementById('mc-preview'); if (pv) pv.innerHTML = partnerDistributionTableHtml(res);
  const btn = document.getElementById('mc-save'); if (btn) btn.disabled = !res.ok || closed;
}

function doMonthlyCalc() {
  const editId = document.getElementById('mc-edit')?.value || '';
  const editing = editId ? brPeriods().find(x=>String(x.id)===editId) : null;
  const ym = editing ? periodMonth(editing) : document.getElementById('mc-month')?.value;
  if (!ym) { toast('Oyni tanlang!','error'); return; }
  if (isMonthClosed(ym, editing?.id)) { toast(`${monthLabel(ym)} allaqachon taqsimlangan (yopilgan)!`,'error'); return; }
  if (!editing) { const oe = monthOrderError(ym); if (oe) { toast(oe,'error'); return; } }
  if (editing && brPeriods()[0]?.id !== editing.id) { toast("Faqat oxirgi oyni tahrirlash mumkin!",'error'); return; }
  const { start, end } = monthRange(ym);
  const totalProfit=parseFloat(document.getElementById('mc-profit')?.value||0);
  if (!isFinite(totalProfit)) { toast('Jami foydani kiriting!','error'); return; }

  const tasExp = tasischiExpensesForRange(start, end);
  const res = computePartnerDistribution(_partnersForPeriod(editing, ym), totalProfit, tasExp);
  if (!res.ok) { toast(res.error,'error'); return; }

  const now = Date.now();
  if (editing) {
    // Tahrir: har bir hamkor hisobiga faqat FARQ (yangi − eski) qo'shiladi
    const oldMap = Object.fromEntries((editing.rows||[]).map(r=>[r.pid, r.foydaPlus||0]));
    res.rows.forEach(r=>{
      const p = brPartner(r.pid);
      if (p) { p.invested = (p.invested||0) + (r.foydaPlus - (oldMap[r.pid]||0)); p.updatedAt = now; }
    });
    Object.assign(editing, { totalProfit, totalInvested:res.totalInvested, rows:res.rows, tasischiExpense:res.tasExp, keptTotal:res.keptTotal, month:ym, start, end, calcBase: calcProfitForRange(start, end), editedAt:new Date().toISOString() });
    auditLog(`Hamkorlar taqsimoti tahrirlandi: ${monthLabel(ym)} — ${CUR.fmtUsd(totalProfit)}`);
    save(); closeModal(); pgHamkorlar();
    toast('✅ Taqsimot yangilandi!');
    return;
  }

  res.rows.forEach(r=>{
    const p=brPartner(r.pid);
    if(p) { p.invested = r.jamiSumma; p.updatedAt = now; }
  });
  const period = {id:uid(), filial:S.branch, month:ym, start, end, totalProfit, totalInvested:res.totalInvested, rows:res.rows, tasischiExpense: res.tasExp, keptTotal:res.keptTotal, calcBase: calcProfitForRange(start, end), createdAt:new Date().toISOString()};
  S.partnerPeriods = sortPartnerPeriods([period, ...S.partnerPeriods]);
  auditLog(`Hamkorlar foyda taqsimoti (${branchName(S.branch)}): ${monthLabel(ym)} (${start}–${end}) — ${CUR.fmtUsd(totalProfit)}${res.tasExp>0?` (ta'sischi xarajati: ${CUR.fmtUsd(res.tasExp)})`:''}`);
  save(); closeModal(); pgHamkorlar();
  toast(`✅ ${monthLabel(ym)} taqsimlandi va yopildi!`);
}

function undoLastPeriod() {
  S.partnerPeriods = sortPartnerPeriods(S.partnerPeriods);
  const period = brPeriods()[0]; if (!period) return;   // v23: faqat SHU filialning oxirgi oyi
  if (!confirm(`${monthLabel(periodMonth(period))} taqsimotini o'chirasizmi? Har bir hamkor hisobidan shu oyda qo'shilgan summa ayiriladi va oy qayta ochiladi.`)) return;
  const now = Date.now();
  period.rows.forEach(r=>{
    const p = brPartner(r.pid);
    // Faqat SHU taqsimot qo'shgan summani qaytaramiz (keyingi hamkor xarajatlari saqlanib qoladi)
    if (p) { p.invested = (p.invested||0) - (r.foydaPlus||0); p.updatedAt = now; }
  });
  S.partnerPeriods = S.partnerPeriods.filter(x=>x.id!==period.id);
  // Tombstone — boshqa qurilma/bulut nusxasidan qaytib "tirilmasligi" uchun
  markDeleted('partnerPeriods', period.id);
  auditLog(`Hamkorlar taqsimoti bekor qilindi: ${period.start}–${period.end}`);
  save(); pgHamkorlar();
  toast(`✅ ${monthLabel(periodMonth(period))} o'chirildi — oy qayta ochildi.`);
}

function printPartnerPeriod(periodId) {
  const period = brPeriods().find(x=>x.id==periodId); if(!period) return;
  const w=fwDocWin();
  w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Hamkorlar</title>
  <style>body{font-family:Arial,sans-serif;font-size:12px;margin:20px}table{width:100%;border-collapse:collapse}
  th{background:#1a2236;color:#f5a623;padding:7px;text-align:left}td{padding:6px 7px;border-bottom:1px solid #eee}
  .tot{font-weight:bold;background:#f6f6f6}</style></head><body>
  <h2>👥 Hamkorlar — Foyda taqsimoti: ${monthLabel(periodMonth(period))} · ${esc(branchName(partnerFilial(period)))}</h2><p>Davr: ${fmtD(period.start)} – ${fmtD(period.end)} | Jami foyda: ${CUR.fmtUsd(period.totalProfit)}${period.tasischiExpense>0?` | 👑 Ta'sischi xarajatlari: ${CUR.fmtUsd(period.tasischiExpense)}`:''}</p>
  <table><thead><tr><th>№</th><th>Hamkor</th><th>SUMMA</th><th>Oyda oldi</th><th>Foyda uchun hisob</th><th>Foyda+</th><th>Foyda summa</th><th>%</th><th>Jami summa</th></tr></thead><tbody>
  ${period.rows.map((r,i)=>`<tr><td>${i+1}</td><td>${r.isFounder?'👑 ':''}${esc(r.name)}</td><td>${CUR.fmtUsd(r.invested)}</td><td>${r.withdrawn?'−'+CUR.fmtUsd(r.withdrawn):'—'}</td><td>${CUR.fmtUsd(r.base ?? r.invested)}</td><td>${CUR.fmtUsd(r.foydaPlus)}</td><td>${CUR.fmtUsd(r.foydaSumma)}</td><td>${r.pct.toFixed(0)}%</td><td>${CUR.fmtUsd(r.jamiSumma)}</td></tr>`).join('')}
  <tr class="tot"><td colspan="2">JAMI</td><td>${CUR.fmtUsd(period.totalInvested)}</td><td></td><td>${CUR.fmtUsd(period.rows.reduce((s,r)=>s+(r.base ?? r.invested),0))}</td><td>${CUR.fmtUsd(period.rows.reduce((s,r)=>s+r.foydaPlus,0))}</td><td>${CUR.fmtUsd(period.totalProfit)}</td><td>100%</td><td>${CUR.fmtUsd(period.rows.reduce((s,r)=>s+r.jamiSumma,0))}</td></tr>
  </tbody></table>
  <p style="margin-top:20px;font-size:11px;color:#999">Chop etildi: ${new Date().toLocaleString('uz-UZ')}</p>
  </body></html>`);
  w.document.close();w.print();
}

