function calcDealerPoints(lineTotalUsd, pointPct) {
  const usdVal = (S.settings && S.settings.pointUsdValue!=null) ? S.settings.pointUsdValue : 2;
  const step = (S.settings && S.settings.pointRoundStep!=null) ? S.settings.pointRoundStep : 1;
  if (!pointPct || usdVal<=0) return 0;
  const raw = (lineTotalUsd * pointPct / 100) / usdVal;
  return Math.round(raw/step)*step;
}

