async function approveDealerOrder(orderId) {
  const order = (S.dealerOrders||[]).find(o=>o.id===orderId);
  if (!order) return;
  const d = S.dealers.find(x=>x.id===order.dealer_id);
  if (!d) { toast('Diller topilmadi!','error'); return; }

  // Admin tahrirlagan miqdorlarni inputlardan o'qiymiz (0 bo'lsa — chiqarib tashlanadi)
  const original = order.items||[];
  const items = [];
  original.forEach((orig, idx) => {
    const input = document.querySelector(`input[data-order-item="${orderId}:${idx}"]`);
    const qty = input ? parseFloat(input.value||0) : orig.qty;
    if (qty > 0) items.push({ pid:orig.pid, sku:orig.sku, name:orig.name, qty });
  });
  if (!items.length) { toast('Kamida bitta mahsulot miqdori 0 dan katta bo\'lishi kerak!','error'); return; }

  // Asosiy ombordagi qoldiqni tekshiramiz
  for (const i of items) {
    const st = getStock(i.pid);
    if (i.qty > st) { toast(`${i.name}: omborda ${st} dona bor, ${i.qty} dona yetkazib bo'lmaydi!`,'error'); return; }
  }

  if (!confirm(`${d.name} uchun buyurtmani tasdiqlaysizmi? Tovar uning omboriga o'tkaziladi.`)) return;

  // v24.5 (35-migratsiya): firma ombori (FIFO) + diller ombori + buyurtma tasdig'i — serverda BITTA tranzaksiyada;
  // rad etilsa hech narsa o'zgarmaydi, buyurtmani ikki marta tasdiqlab bo'lmaydi
  let dres;
  try { dres = await fwDealerCall({ kind:'ship', dealerId:d.id, orderId, items: items.map(i=>({ pid:i.pid, qty:i.qty, sku:i.sku, name:i.name })) }); }
  catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  if (dres) {
    fwApplyDealerResult(d, dres);
    S.dealerTxns.unshift({id:uid(), date:td(), dealerId:d.id, type:'send', items:items.map(i=>({pid:i.pid,qty:i.qty})), totalUsd:+dres.totalCostUsd||0});
    auditLog(`Buyurtma tasdiqlandi: ${d.name} — ${items.reduce((s,i)=>s+i.qty,0)} dona`);
    order.status='approved';
    save(); dillerRenderTab(); toast(`✅ Tasdiqlandi — ${d.name}ning omboriga o'tkazildi!`);
    dlAuditDealer(d.id, 'order_approve', null, { orderId, items, totalCost: +dres.totalCostUsd||0 });
    return;
  }
  // 35-migratsiyagacha (eski yo'l) — v23.2 (F4b): asosiy ombordan chiqarish (FIFO) — SERVERDA; tannarx server javobidan
  let srvCost = null;
  if (fwLedgerRemote()) {
    try {
      const r = await fwLedgerCall('stock-debt-ops', { kind:'stock_out', payload:{ reason:'dealer', dealerId:String(d.id), items: items.map(i=>({ pid:i.pid, qty:i.qty })) } });
      srvCost = new Map((r.items||[]).map(x=>[+x.pid, +x.firstCost]));
    } catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  }
  let totalCost = 0;
  const cloudOps = [];
  items.forEach(i=>{
    const costNow = srvCost ? (srvCost.get(+i.pid)||0) : getCostFIFO(i.pid);
    if (!srvCost) deductFIFO(i.pid, i.qty);
    let rec = S.dealerStock.find(r=>r.dealerId===d.id&&r.pid===i.pid);
    if (!rec) { rec={id:uid(),dealerId:d.id,pid:i.pid,qty:0,avgCostUsd:0}; S.dealerStock.push(rec); }
    const newQty = rec.qty + i.qty;
    rec.avgCostUsd = newQty>0 ? ((rec.qty*rec.avgCostUsd)+(i.qty*costNow))/newQty : costNow;
    rec.qty = newQty;
    totalCost += i.qty*costNow;
    cloudOps.push(dlUpsertStock(d.id, i.pid, i.sku, i.name, rec.qty, rec.avgCostUsd));
    cloudOps.push(dlInsertMove(d.id, 'send', i.pid, i.sku, i.name, i.qty, costNow));
  });
  d.totalShipped = (d.totalShipped||0) + totalCost;
  S.dealerTxns.unshift({id:uid(), date:td(), dealerId:d.id, type:'send', items:items.map(i=>({pid:i.pid,qty:i.qty})), totalUsd:totalCost});
  auditLog(`Buyurtma tasdiqlandi: ${d.name} — ${items.reduce((s,i)=>s+i.qty,0)} dona`);
  order.status='approved'; // darhol UI'da ko'rinishi uchun
  save(); dillerRenderTab(); toast(`✅ Tasdiqlandi — ${d.name}ning omboriga o'tkazildi!`);

  try {
    await Promise.all(cloudOps);
    await dlUpdateDealerRow(d.id, {totalShipped:d.totalShipped});
    const res = await authFetch('/.netlify/functions/dealer-order-status', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ orderId, status:'approved', items })
    });
    const result = await res.json();
    if (!res.ok) throw new Error(result.error);
  } catch(e) { toast('⚠️ Bulutga yozishda xatolik: '+e.message, 'error'); }
  dlAuditDealer(d.id, 'order_approve', null, { orderId, items, totalCost });
}

async function rejectDealerOrder(orderId) {
  if (!confirm("Bu buyurtmani rad etasizmi?")) return;
  const order = (S.dealerOrders||[]).find(o=>o.id===orderId);
  if (order) order.status='rejected';
  dillerRenderTab();
  try {
    const res = await authFetch('/.netlify/functions/dealer-order-status', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ orderId, status:'rejected' })
    });
    const result = await res.json();
    if (!res.ok) throw new Error(result.error);
    toast('❌ Buyurtma rad etildi');
  } catch(e) { toast('⚠️ Bulutga yozishda xatolik: '+e.message, 'error'); }
  if (order) dlAuditDealer(order.dealer_id, 'order_reject', null, { orderId });
}

function dillerStockValueTotal() {
  return S.dealerStock.reduce((s,r)=>s+(r.qty*(r.avgCostUsd||0)),0);
}

// ── RO'YXAT ──
// Diller kartasi uchun qo'shimcha ko'rsatkichlar: oxirgi savdo/to'lov/qaytarish sanasi,
// umumiy foyda, to'lov intizomi
function dealerCardExtra(d) {
  const txns = S.dealerTxns.filter(t=>t.dealerId===d.id);
  const lastSale = txns.filter(t=>t.type==='sale').sort((a,b)=>(a.date<b.date?1:-1))[0];
  const lastPayment = txns.filter(t=>t.type==='payment').sort((a,b)=>(a.date<b.date?1:-1))[0];
  const lastReturn = txns.filter(t=>t.type==='return').sort((a,b)=>(a.date<b.date?1:-1))[0];
  const totalProfit = txns.filter(t=>t.type==='sale').reduce((s,t)=>s+(t.profitUsd||0),0);
  const risk = dealerCreditRisk().find(r=>r.dealer.id===d.id);
  let discipline = 'A\'lo', disciplineColor = 'var(--emerald)';
  if (risk?.overdue) { discipline = `Yomon (${risk.overdueDays} kun kechikdi)`; disciplineColor = 'var(--red)'; }
  else if ((d.debt||0)>0) { discipline = 'Yaxshi (qarzi bor, muddatida)'; disciplineColor = 'var(--gold-dark)'; }
  return {
    lastSaleDate: lastSale?.date, lastPaymentDate: lastPayment?.date, lastReturnDate: lastReturn?.date,
    totalProfit, discipline, disciplineColor
  };
}

