function dlRows(list) {
  if (!list.length) return fwEmpty('people', 'Diller yoʻq', '«Diller qoʻshish» tugmasi bilan qoʻshing.');
  return `<div class="fw-list">${list.map(d=>{
    const stockVal = S.dealerStock.filter(r=>r.dealerId===d.id).reduce((s,r)=>s+(r.qty*(r.avgCostUsd||0)),0);
    const debt = (d.debt||0)>0, lim = +d.creditLimitUsd||0, over = lim>0 && (d.debt||0)>lim;
    return `<article class="fw-pc">
      <span class="fw-av" style="--c:var(--${fwToneOf(d.id)})">${fwInitials(d.name)}</span>
      <div class="fw-pc-m"><b>${esc(d.name)}</b><small>${esc(d.region||'—')}${d.phone?` · ${esc(d.phone)}`:''}${d.login?` · <code>${esc(d.login)}</code>`:''}</small>
        <small>Omborida: ${CUR.fmtUsd(stockVal)} · <em class="fw-tag" style="--c:var(--gold)">★ ${d.points||0}</em>${(d.commissionPct||0)>0?` · xizmat ${d.commissionPct}%`:''}</small></div>
      <div class="fw-pc-v ${debt?(over?'bad':'warn'):'ok'}"><b>${debt?CUR.fmtUsd(d.debt):'Qarz yoʻq'}</b>${lim>0?`<small>limit ${CUR.fmtUsd(lim)}</small>`:''}</div>
      <div class="fw-pc-a">
        <button class="fw-btn" onclick="dlToggleDetail(${d.id})"><span id="dl-toggle-${d.id}">▾</span><span>Batafsil</span></button>
        <button class="fw-btn" onclick="editDealer(${d.id})">${ICONF.edit}<span>Tahrir</span></button>
        <button class="fw-btn icon" onclick="printDealerStatement(${d.id})" title="Hisob-varaqni chop etish" aria-label="Chop etish">${ICONF.print}</button>
      </div>
      <div id="dl-detail-${d.id}" class="dl-detail" style="display:none">${dlDetailPanel(d)}</div>
    </article>`;}).join('')}</div>`;
}

function dlDetailPanel(d) {
  const x = dealerCardExtra(d);
  const row = (label, val) => `<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:12.5px;border-bottom:1px solid var(--border-light)"><span style="color:var(--text-muted)">${label}</span><strong>${val}</strong></div>`;
  return `<div class="grid-2" style="gap:20px">
    <div>
      ${row('Oxirgi savdo sanasi', x.lastSaleDate ? fmtD(x.lastSaleDate) : '—')}
      ${row('Oxirgi to\'lov sanasi', x.lastPaymentDate ? fmtD(x.lastPaymentDate) : '—')}
      ${row('Oxirgi qaytarish sanasi', x.lastReturnDate ? fmtD(x.lastReturnDate) : '—')}
    </div>
    <div>
      ${row('Umumiy foyda', `<span style="color:var(--emerald)">${CUR.fmtUsd(x.totalProfit)}</span>`)}
      ${row('Umumiy qarzdorlik', `<span style="color:${(d.debt||0)>0?'var(--red)':'var(--emerald)'}">${CUR.fmtUsd(d.debt||0)}</span>`)}
      ${row('Kredit limiti', (d.creditLimitUsd||0)>0 ? CUR.fmtUsd(d.creditLimitUsd) : "Belgilanmagan")}
      ${row("To'lov intizomi", `<span style="color:${x.disciplineColor}">${x.discipline}</span>`)}
    </div>
  </div>
  <button class="btn btn-ghost btn-sm" style="margin-top:8px" onclick="openDealerAuditLog(${d.id})">📜 To'liq audit tarixini ko'rish</button>`;
}

function dlToggleDetail(did) {
  const row = document.getElementById('dl-detail-'+did);
  const btn = document.getElementById('dl-toggle-'+did);
  if (!row) return;
  const showing = row.style.display!=='none';
  row.style.display = showing ? 'none' : '';
  if (btn) btn.textContent = showing ? '▾' : '▴';
}

async function openDealerAuditLog(did) {
  const d = S.dealers.find(x=>x.id===did); if (!d) return;
  modal(`
    <div class="modal-header"><div class="modal-title">📜 ${esc(d.name)} — audit tarixi</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body" id="dl-audit-body"><div style="text-align:center;padding:20px;color:var(--text-muted)">⏳ Yuklanmoqda...</div></div>
    <div class="modal-footer"><button class="btn btn-ghost" onclick="closeModal()">Yopish</button></div>`);
  try {
    const res = await authFetch('/.netlify/functions/dealer-audit-log-list', {
      method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ dealerId: did, limit: 100 })
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error);
    const ACTION_LABELS = { create:"➕ Yaratildi", update:"✏️ Tahrirlandi", delete:"🗑 O'chirildi", stock_send:"🚚 Yuborildi", stock_return:"↩️ Qaytarildi", payment:"💰 To'lov", sale:"🧾 Sotdi", order_approve:"✅ Buyurtma tasdiqlandi", order_reject:"❌ Buyurtma rad etildi" };
    const body = document.getElementById('dl-audit-body');
    if (body) body.innerHTML = data.logs.length ? `<div class="table-wrap"><table><thead><tr><th>Sana</th><th>Amal</th><th>Kim</th><th>Filial</th></tr></thead><tbody>
      ${data.logs.map(l=>`<tr>
        <td style="font-size:11px">${new Date(l.created_at).toLocaleString('uz-UZ')}</td>
        <td>${esc(ACTION_LABELS[l.action]||l.action)}</td>
        <td>${esc(l.actor_name||'—')} ${l.actor_kind==='owner'?'(Egasi)':''}</td>
        <td>${esc(l.filial)}</td>
      </tr>`).join('')}
      </tbody></table></div>` : `<div style="text-align:center;padding:20px;color:var(--text-muted)">Audit yozuvi yo'q</div>`;
  } catch(e) {
    const body = document.getElementById('dl-audit-body');
    if (body) body.innerHTML = `<div style="color:var(--red);padding:12px">⚠️ Yuklanmadi: ${esc(e && e.message)}</div>`;
  }
}

