async function saveDealer() {
  const name=document.getElementById('nd-n')?.value?.trim();
  const login=document.getElementById('nd-login')?.value?.trim();
  const pass=document.getElementById('nd-pass')?.value||'';
  if(!name){toast('Ism kiriting!','error');return;}
  if(!login){toast('Login kiriting!','error');return;}
  if(pass.length<6){toast('Parol kamida 6 belgi bo\'lishi kerak!','error');return;}
  if(S.dealers.find(d=>(d.login||'').toLowerCase()===login.toLowerCase())){toast('Bu login band!','error');return;}

  const btn=document.getElementById('nd-save-btn');
  if(btn){btn.disabled=true;btn.textContent='Yaratilmoqda...';}
  try {
    const res = await authFetch('/.netlify/functions/create-dealer', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({
        login, password:pass, name,
        phone:document.getElementById('nd-p')?.value||'', region:document.getElementById('nd-r')?.value||'',
        commissionPct: parseFloat(document.getElementById('nd-pct')?.value||0),
        filial: S.branch
      })
    });
    const result = await res.json();
    if (!res.ok) throw new Error(result.error || 'Diller yaratilmadi');

    const row = result.dealer;
    S.dealers.push({id:row.id, authUserId:row.auth_user_id, login:row.login, name:row.name, phone:row.phone, region:row.region, debt:0, totalShipped:0, totalSold:0, totalPaid:0, av:row.av, color:DEALER_COLORS[S.dealers.length%DEALER_COLORS.length], commissionPct:row.commission_pct||0});
    auditLog(`Yangi diller: ${name}`);
    save();
    closeModal();pgDillerlar();toast("✅ Diller qo'shildi — login/parolni o'ziga bering!");
    dlAuditDealer(row.id, 'create', null, { name, login, phone: document.getElementById('nd-p')?.value||'', region: document.getElementById('nd-r')?.value||'', commissionPct: row.commission_pct||0 });
  } catch(e) {
    toast('Xatolik: '+(e.message||"diller yaratilmadi"), 'error');
    if(btn){btn.disabled=false;btn.textContent='💾 Saqlash';}
  }
}

function editDealer(did) {
  const d=S.dealers.find(x=>x.id===did);if(!d)return;
  modal(`
    <div class="modal-header"><div class="modal-title">✏️ Dillerni tahrirlash</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${meCard({ name:d.name, sub:[esc(d.region||''), esc(d.phone||''), 'login: '+esc(d.login||'—')].filter(Boolean).join(' · '),
        kpi:(d.debt||0)>0?CUR.fmtUsd(d.debt):'Qarzsiz', kpiLabel:(d.debt||0)>0?'qarz':'', tone:(d.debt||0)>0?'neg':'pos',
        acts: meActs([ (d.debt||0)>0 && ['payments',"To'lov olish",`closeModal();openDealerPay(${did})`] ]) })}
      ${meSec('Asosiy')}
      ${meField('Ism *', `<input class="form-control" id="ed-n" value="${esc(d.name)}">`)}
      <div class="me-2">
        ${meField('Telefon', `<input class="form-control" id="ed-p" type="tel" inputmode="tel" value="${esc(d.phone||'')}">`)}
        ${meField('Hudud', `<input class="form-control" id="ed-r" value="${esc(d.region||'')}">`)}
      </div>
      ${meField('Xizmat foizi', `<div class="me-amt"><input class="form-control" id="ed-pct" type="number" step="0.5" min="0" max="100" value="${+d.commissionPct||0}" inputmode="decimal"><i>%</i></div>`, 'Diller savdosidan tutib qolinadigan ulush.')}
      ${meSec('Kredit nazorati')}
      <div class="me-2">
        ${meField('Kredit limiti', meAmt('ed-climit', +d.creditLimitUsd||0, '$'))}
        ${meField("To'lov muddati", `<div class="me-amt"><input class="form-control" id="ed-duedays" type="number" step="1" min="1" value="${+d.paymentDueDays||30}" inputmode="numeric"><i>kun</i></div>`)}
      </div>
      <div class="me-hint">🔐 Parolni tiklash — tizim administratori orqali (Supabase → Authentication → Users).</div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-danger btn-sm" onclick="deleteDealer(${did})">🗑 O'chirish</button>
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" onclick="saveEditDealer(${did})">💾 Saqlash</button>
    </div>`);
}

async function saveEditDealer(did) {
  const d=S.dealers.find(x=>x.id===did);if(!d)return;
  const oldSnapshot = { name:d.name, phone:d.phone, region:d.region, commissionPct:d.commissionPct, creditLimitUsd:d.creditLimitUsd, paymentDueDays:d.paymentDueDays };
  const name=document.getElementById('ed-n')?.value?.trim();
  if(!name){toast('Ism kiriting!','error');return;}
  const phone=document.getElementById('ed-p')?.value||'';
  const region=document.getElementById('ed-r')?.value||'';
  const commissionPct=parseFloat(document.getElementById('ed-pct')?.value||0);
  const creditLimitUsd=parseFloat(document.getElementById('ed-climit')?.value||0);
  const paymentDueDays=parseInt(document.getElementById('ed-duedays')?.value||30);
  const av=name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase()||'D';
  d.name=name; d.phone=phone; d.region=region; d.av=av; d.commissionPct=commissionPct;
  d.creditLimitUsd=creditLimitUsd; d.paymentDueDays=paymentDueDays;
  try { await dlUpdateDealerRow(did, {name, phone, region, av, commissionPct, creditLimitUsd, paymentDueDays}); } catch(e) { toast('Bulutga yozilmadi: '+e.message,'error'); }
  save();
  closeModal();pgDillerlar();toast('✅ Saqlandi!');
  dlAuditDealer(did, 'update', oldSnapshot, { name, phone, region, commissionPct, creditLimitUsd, paymentDueDays });
}

async function deleteDealer(did) {
  if(!confirm("Dillerni o'chirasizmi? Uning ombordagi mahsulotlari va tarixi ham o'chadi.")) return;
  const d = S.dealers.find(x=>x.id===did);
  // Audit yozuvi o'chirishdan OLDIN va KUTIB yoziladi — aks holda FK cascade
  // audit yozuvini ulgurmasdan yo'qotib yuborishi mumkin edi.
  await dlAuditDealer(did, 'delete', d ? { name:d.name, debt:d.debt, totalSold:d.totalSold } : null, null);
  try { await dlDeleteDealerRow(did); } catch(e) { toast('Bulutdan o\'chmadi: '+e.message,'error'); return; }
  S.dealers = S.dealers.filter(d=>d.id!==did);
  S.dealerStock = S.dealerStock.filter(r=>r.dealerId!==did);
  S.dealerTxns = S.dealerTxns.filter(t=>t.dealerId!==did);
  auditLog(`Diller o'chirildi: #${did}`);
  save();
  closeModal();pgDillerlar();toast("✅ O'chirildi!",'warning');
}

// ── OMBOR ──
function dillerOmborHtml() {
  const d = S.dillerOmborId ? S.dealers.find(x=>x.id===S.dillerOmborId) : null;
  const allStock = d ? S.dealerStock.filter(r=>r.dealerId===d.id&&r.qty>0) : [];
  const totalVal = allStock.reduce((s,r)=>s+r.qty*(r.avgCostUsd||0),0);
  return `
    <div class="card" style="margin-bottom:16px">
      <div class="card-title" style="margin-bottom:12px">📦 Diller omborini ko'rish</div>
      <div style="position:relative;max-width:340px">
        <input type="text" class="form-control" id="do-q" placeholder="Diller ismini qidiring..."
          value="${esc(d?d.name:'')}" oninput="doSearch(this.value)" autocomplete="off">
        <div id="do-dd" style="display:none;position:absolute;top:100%;left:0;right:0;
          background:var(--bg-card);border:1px solid var(--border);border-top:none;
          border-radius:0 0 var(--radius-sm) var(--radius-sm);max-height:220px;overflow-y:auto;z-index:999"></div>
      </div>
    </div>
    ${d ? `
    <div class="card">
      <div class="card-header">
        <div class="card-title">📦 ${esc(d.name)} — ombor</div>
        <div style="display:flex;gap:6px">
          <button class="btn btn-ghost btn-sm" onclick="exportDealerStockXls(${d.id})">📊 Excel</button>
          <button class="btn btn-ghost btn-sm" onclick="openDealerReturn(${d.id})">↩️ Qaytarish</button>
        </div>
      </div>
      ${allStock.length ? `<div style="font-size:12px;color:var(--gold);font-weight:700;padding:6px 16px">Jami qiymat: ${CUR.fmtUsd(totalVal)}</div>` : ''}
      <div class="table-wrap">
        <table>
          <thead><tr><th>Mahsulot</th><th>Qoldiq</th><th>Opt narx ($)</th><th>Tannarx ($)</th><th>Qiymati ($)</th></tr></thead>
          <tbody>
            ${allStock.map(r=>{
              const p=S.products.find(x=>x.id===r.pid);
              const oPrice=optPrice(p, r.avgCostUsd||0);
              return `<tr>
                <td><code style="color:var(--gold)">${esc(p?.sku||'')}</code> ${esc(p?.name?.slice(0,22)||'')}</td>
                <td style="font-weight:700">${r.qty}</td>
                <td style="color:var(--blue)">${CUR.fmtUsd(oPrice)}</td>
                <td style="color:var(--text-muted)">${CUR.fmtUsd(r.avgCostUsd||0)}</td>
                <td style="color:var(--gold);font-weight:700">${CUR.fmtUsd(r.qty*(r.avgCostUsd||0))}</td>
              </tr>`;
            }).join('') || '<tr><td colspan="5" style="text-align:center;color:var(--text-muted)">Omborida hech narsa yo\'q</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>` : '<p style="color:var(--text-muted)">Dillerni qidirib tanlang...</p>'}`;
}

async function exportDealerStockXls(did) {
  const d = S.dealers.find(x=>x.id===did); if(!d) return;
  const rows = S.dealerStock.filter(r=>r.dealerId===did&&r.qty>0).map(r=>{
    const p=S.products.find(x=>x.id===r.pid);
    return [p?.sku||'', p?.name||'', r.qty, Number((r.avgCostUsd||0).toFixed(2)), Number(optPrice(p,r.avgCostUsd||0).toFixed(2)), Number((r.qty*(r.avgCostUsd||0)).toFixed(2))];
  });
  await xlsxDownload(`${d.name}_ombor_${td()}.xlsx`, d.name,
    ['Kod','Mahsulot','Qoldiq','Tannarx ($)','Opt narx ($)','Jami ($)'], rows);
  toast(`✅ ${d.name} ombor Excel tayyor!`);
}

function doSearch(q) {
  const dd=document.getElementById('do-dd'); if(!dd) return;
  if(!q||!q.length){dd.style.display='none';return;}
  const r=multiFieldSearch(S.dealers, q, d=>[d.name, d.phone, d.region]).slice(0,12);
  if(!r.length){dd.innerHTML='<div style="padding:10px;color:var(--text-muted);font-size:12px">Topilmadi</div>';dd.style.display='block';return;}
  dd.innerHTML=r.map(d=>`<div onclick="doSelect(${d.id})" style="padding:9px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid var(--border-light);color:var(--text-primary)"
    onmouseover="this.style.background='var(--bg-hover)'" onmouseout="this.style.background=''">${esc(d.name)} <span style="color:var(--text-muted)">— ${esc(d.region||'')}</span></div>`).join('');
  dd.style.display='block';
}

function doSelect(did) {
  S.dillerOmborId = did;
  const dd=document.getElementById('do-dd'); if(dd) dd.style.display='none';
  dillerRenderTab();
}

// ── DILLER REVIZИYASI — dillerdagi haqiqiy (fakt) qoldiqni tizimdagi bilan solishtirish ──
function drSearch(q) {
  const dd=document.getElementById('dr-dd'); if(!dd) return;
  if(!q||!q.length){dd.style.display='none';return;}
  const r=multiFieldSearch(S.dealers, q, d=>[d.name, d.phone, d.region]).slice(0,12);
  if(!r.length){dd.innerHTML='<div style="padding:10px;color:var(--text-muted);font-size:12px">Topilmadi</div>';dd.style.display='block';return;}
  dd.innerHTML=r.map(d=>`<div onclick="drSelect(${d.id})" style="padding:9px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid var(--border-light);color:var(--text-primary)"
    onmouseover="this.style.background='var(--bg-hover)'" onmouseout="this.style.background=''">${esc(d.name)} <span style="color:var(--text-muted)">— ${esc(d.region||'')}</span></div>`).join('');
  dd.style.display='block';
}
function drSelect(did) {
  S.dillerRevDealerId = did;
  S.dillerRevDate = td();
  S.dillerRevFacts = {};
  const dd=document.getElementById('dr-dd'); if(dd) dd.style.display='none';
  dillerRenderTab();
}
function drSetDate(v) { S.dillerRevDate = v; }

// Bitta dillerning SAQLANGAN revizya tarixi — boshqa dillerning ma'lumotiga hech
// qanday aloqasi yo'q (dealerId bo'yicha qat'iy filtrlangan)
function openDealerRevisionHistory(dealerId) {
  const d = S.dealers.find(x=>x.id===dealerId);
  const hist = S.dealerRevisions.filter(r=>r.dealerId===dealerId);
  modal(`
    <div class="modal-header"><div class="modal-title">💾 ${esc(d?.name||'')} — revizya tarixi</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body" style="max-height:70vh;overflow-y:auto">
      ${hist.length ? hist.map(r=>`
        <div class="card" style="margin-bottom:10px;padding:12px">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
            <div><strong>${fmtD(r.date)}</strong> <span style="color:var(--text-muted);font-size:11px">— ${esc(r.performedBy||'Noma\'lum')}</span></div>
            <div style="display:flex;gap:8px;align-items:center">
              <span class="badge ${r.applied?'badge-success':'badge-warning'}">${r.applied?"✅ Tasdiqlangan":'📋 Faqat qayd etilgan'}</span>
              <strong style="color:${r.totalDiffUsd>=0?'var(--emerald)':'var(--red)'}">${r.totalDiffUsd>=0?'+':''}${CUR.fmtUsd(r.totalDiffUsd)}</strong>
            </div>
          </div>
          <div class="table-wrap"><table style="font-size:11px">
            <thead><tr><th>Mahsulot</th><th>Tizimda</th><th>Fakt</th><th>Farq</th><th>Qiymat</th></tr></thead>
            <tbody>${r.rows.map(x=>{const p=S.products.find(pp=>pp.id===x.pid);return `<tr>
              <td><code style="color:var(--gold)">${esc(p?.sku||'')}</code> ${esc(p?.name?.slice(0,24)||'')}</td>
              <td>${x.sysQty}</td><td>${x.factQty}</td>
              <td style="color:${x.diff>0?'var(--emerald)':x.diff<0?'var(--red)':'var(--text-muted)'}">${x.diff>0?'+':''}${x.diff}</td>
              <td style="color:${x.diffUsd>=0?'var(--emerald)':'var(--red)'}">${x.diffUsd>=0?'+':''}${CUR.fmtUsd(x.diffUsd)}</td>
            </tr>`;}).join('')}</tbody>
          </table></div>
        </div>`).join('') : '<p style="color:var(--text-muted);text-align:center">Hali revizya qilinmagan</p>'}
    </div>
    <div class="modal-footer"><button class="btn btn-ghost" onclick="closeModal()">Yopish</button></div>`);
}

function dillerRevizyaHtml() {
  const d = S.dillerRevDealerId ? S.dealers.find(x=>x.id===S.dillerRevDealerId) : null;
  const dealerHist = S.dealerRevisions.filter(r=>r.dealerId===S.dillerRevDealerId).length;
  const searchBox = `
    <div class="card" style="margin-bottom:16px">
      <div class="card-title" style="margin-bottom:12px">📐 Diller revizияsi — dillerni tanlang</div>
      <div style="position:relative;max-width:340px">
        <input type="text" class="form-control" id="dr-q" placeholder="Diller ismini qidiring..."
          value="${esc(d?d.name:'')}" oninput="drSearch(this.value)" autocomplete="off">
        <div id="dr-dd" style="display:none;position:absolute;top:100%;left:0;right:0;
          background:var(--bg-card);border:1px solid var(--border);border-top:none;
          border-radius:0 0 var(--radius-sm) var(--radius-sm);max-height:220px;overflow-y:auto;z-index:999"></div>
      </div>
    </div>`;
  if (!d) return searchBox + '<p style="color:var(--text-muted)">Dillerni qidirib tanlang, keyin uning qo\'lidagi FAKT qoldiqni kiritib, tizim bilan solishtirasiz.</p>';

  const rows = S.dealerStock.filter(r=>r.dealerId===d.id && r.qty>0).map(r=>{
    const p = S.products.find(x=>x.id===r.pid);
    const sysQty = r.qty;
    const fact = S.dillerRevFacts[r.pid];
    const factQty = (fact===undefined||fact===null||fact==='') ? null : parseInt(fact);
    const diff = factQty===null ? null : factQty-sysQty;
    const cost = r.avgCostUsd||0;
    const diffUsd = diff===null ? null : diff*cost;
    return { p, r, sysQty, factQty, diff, diffUsd, cost };
  });
  const totalDiffUsd = rows.reduce((s,x)=>s+(x.diffUsd||0),0);
  const countedCnt = rows.filter(x=>x.factQty!==null).length;

  return searchBox + `
    <div class="card-header" style="margin-bottom:14px;flex-wrap:wrap;gap:10px">
      <div class="card-title" style="margin:0">📐 ${esc(d.name)} — revizия (aksiverka)</div>
      <div style="display:flex;align-items:center;gap:8px">
        <label class="form-label" style="margin:0">Sana:</label>
        <input type="date" class="form-control" id="dr-date" value="${S.dillerRevDate}" onchange="drSetDate(this.value)" style="margin:0;width:150px">
      </div>
    </div>
    <div class="stats-grid" style="grid-template-columns:repeat(3,1fr);margin-bottom:14px">
      <div class="stat-card blue"><div class="stat-value" id="dr-counted">${countedCnt}/${rows.length}</div><div class="stat-label">Sanaldi</div></div>
      <div class="stat-card ${totalDiffUsd>=0?'emerald':'red'}" id="dr-totaldiff-card"><div class="stat-value" id="dr-totaldiff">${totalDiffUsd>=0?'+':''}${CUR.fmtUsd(totalDiffUsd)}</div><div class="stat-label">Jami farq</div></div>
      <div class="stat-card gold" style="cursor:pointer" onclick="openDealerRevisionHistory(${d.id})"><div class="stat-value">${dealerHist}</div><div class="stat-label">Avvalgi revizialar (bosing)</div></div>
    </div>
    <div class="card">
      <div class="table-wrap">
        <table>
          <thead><tr><th>Mahsulot</th><th>Tizimda</th><th>Fakt (sanab kiriting)</th><th>Farq (dona)</th><th>Farq ($)</th></tr></thead>
          <tbody>
            ${rows.map(x=>`<tr id="dr-row-${x.p.id}">
              <td><code style="color:var(--gold)">${esc(x.p?.sku||'')}</code> ${esc(x.p?.name?.slice(0,28)||'')}</td>
              <td>${x.sysQty}</td>
              <td><input type="number" class="form-control" style="margin:0;width:80px;padding:6px 8px" placeholder="—"
                value="${x.factQty===null?'':x.factQty}" oninput="drSetFact(${x.p.id},this.value)"></td>
              <td id="dr-diff-${x.p.id}" style="font-weight:700;color:${x.diff===null?'var(--text-muted)':x.diff===0?'var(--text-secondary)':x.diff>0?'var(--emerald)':'var(--red)'}">${x.diff===null?'—':(x.diff>0?'+':'')+x.diff}</td>
              <td id="dr-diffusd-${x.p.id}" style="font-weight:700;color:${x.diffUsd===null?'var(--text-muted)':x.diffUsd>=0?'var(--emerald)':'var(--red)'}">${x.diffUsd===null?'—':(x.diffUsd>=0?'+':'')+CUR.fmtUsd(x.diffUsd)}</td>
            </tr>`).join('') || '<tr><td colspan="5" style="text-align:center;color:var(--text-muted)">Bu dillerda hozircha mahsulot yo\'q</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>
    ${rows.length ? `<div style="margin-top:14px;display:flex;gap:10px;align-items:center;flex-wrap:wrap">
      <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text-secondary)">
        <input type="checkbox" id="dr-apply" style="width:auto;margin:0"> Qoldiqni FAKT bo'yicha to'g'irlash (kamomadni dillerga qarz qilib yozish)
      </label>
      <button class="btn btn-primary btn-lg" onclick="saveDealerRevision()" style="margin-left:auto">💾 Revizyani saqlash</button>
    </div>` : ''}`;
}

function drSetFact(pid, val) {
  S.dillerRevFacts[pid] = (val===''||val===null) ? null : val;
  const rec = S.dealerStock.find(r=>r.dealerId===S.dillerRevDealerId && r.pid===pid);
  const sysQty = rec ? rec.qty : 0;
  const cost = rec ? (rec.avgCostUsd||0) : 0;
  const factQty = (S.dillerRevFacts[pid]===null||S.dillerRevFacts[pid]===undefined) ? null : parseInt(S.dillerRevFacts[pid]);
  const diff = factQty===null ? null : factQty-sysQty;
  const diffUsd = diff===null ? null : diff*cost;

  const diffEl = document.getElementById('dr-diff-'+pid);
  if (diffEl) { diffEl.textContent = diff===null?'—':(diff>0?'+':'')+diff; diffEl.style.color = diff===null?'var(--text-muted)':diff===0?'var(--text-secondary)':diff>0?'var(--emerald)':'var(--red)'; }
  const diffUsdEl = document.getElementById('dr-diffusd-'+pid);
  if (diffUsdEl) { diffUsdEl.textContent = diffUsd===null?'—':(diffUsd>=0?'+':'')+CUR.fmtUsd(diffUsd); diffUsdEl.style.color = diffUsd===null?'var(--text-muted)':diffUsd>=0?'var(--emerald)':'var(--red)'; }

  let totalDiffUsd=0, countedCnt=0;
  S.dealerStock.filter(r=>r.dealerId===S.dillerRevDealerId && r.qty>0).forEach(rr=>{
    const f = S.dillerRevFacts[rr.pid];
    if (f!==undefined && f!==null && f!=='') {
      countedCnt++;
      const fq=parseInt(f);
      totalDiffUsd += (fq-rr.qty)*(rr.avgCostUsd||0);
    }
  });
  const totalRows = S.dealerStock.filter(r=>r.dealerId===S.dillerRevDealerId && r.qty>0).length;
  const ce = document.getElementById('dr-counted'); if (ce) ce.textContent = `${countedCnt}/${totalRows}`;
  const te = document.getElementById('dr-totaldiff');
  if (te) te.textContent = (totalDiffUsd>=0?'+':'')+CUR.fmtUsd(totalDiffUsd);
  const tc = document.getElementById('dr-totaldiff-card');
  if (tc) tc.className = `stat-card ${totalDiffUsd>=0?'emerald':'red'}`;
}

function saveDealerRevision() {
  const d = S.dealers.find(x=>x.id===S.dillerRevDealerId); if (!d) return;
  const apply = document.getElementById('dr-apply')?.checked;
  const rows = [];
  S.dealerStock.filter(r=>r.dealerId===d.id && r.qty>0).forEach(r=>{
    const f = S.dillerRevFacts[r.pid];
    if (f===undefined||f===null||f==='') return;
    const p = S.products.find(x=>x.id===r.pid);
    const sysQty=r.qty, factQty=parseInt(f), cost=r.avgCostUsd||0;
    const diff=factQty-sysQty, diffUsd=diff*cost;
    rows.push({pid:r.pid, sku:p?.sku||'', name:p?.name||'', sysQty, factQty, diff, diffUsd});
  });
  if (!rows.length) { toast("Kamida 1 mahsulot uchun fakt kiriting!",'error'); return; }
  const totalDiffUsd = rows.reduce((s,r)=>s+r.diffUsd,0);

  if (apply) {
    rows.forEach(r=>{
      if (r.diff===0) return;
      const rec = S.dealerStock.find(x=>x.dealerId===d.id && x.pid===r.pid);
      if (rec) rec.qty = Math.max(0, r.factQty);
      // Kamomad (fakt < tizim) — dillerga tannarx bo'yicha qarz qilib yoziladi (kamomad uning javobgarligi)
      if (r.diff<0) { d.debt = (d.debt||0) + Math.abs(r.diffUsd); }
    });
  }

  if (!S.dealerRevisions) S.dealerRevisions = [];
  S.dealerRevisions.unshift({id:uid(), dealerId:d.id, dealerName:d.name, date:S.dillerRevDate, rows, totalDiffUsd, applied:!!apply, performedBy: (CURRENT_USER?.name || 'Admin')});
  auditLog(`Diller revizияsi: ${d.name} — ${S.dillerRevDate} — farq ${CUR.fmtUsd(totalDiffUsd)}${apply?" (qoldiq to'g'irlandi)":''}`);
  S.dillerRevFacts = {};
  save(); dillerRenderTab();
  toast(`✅ Revizya saqlandi! Jami farq: ${totalDiffUsd>=0?'+':''}${CUR.fmtUsd(totalDiffUsd)}${apply?" (qoldiq va qarz to'g'irlandi)":''}`);
}

// ── DILLER SOTUVI (komissiya asosida — debt va foyda shu yerda hisoblanadi) ──
// ── DILLER SAVDOSI (komissiya asosida — bir nechta mahsulot birdan) ──
function dillerSaleHtml() {
  const d = S.dillerSaleId ? S.dealers.find(x=>x.id===S.dillerSaleId) : null;
  if (!S.dillerSaleCart) S.dillerSaleCart = [];
  if (d && S.dillerSaleCart.length===0) S.dillerSaleCart.push({id:uid(), pid:null, qty:1, price:0});
  if (S.dillerSalePct===undefined||S.dillerSalePct===null) S.dillerSalePct = 5;
  const stock = d ? S.dealerStock.filter(r=>r.dealerId===d.id&&r.qty>0) : [];

  return `
    <div class="grid-2">
      <div class="card">
        <div class="card-title" style="margin-bottom:6px">🧾 Diller sotuvini belgilash</div>
        <div style="font-size:11px;color:var(--text-muted);margin-bottom:14px">Diller o'z mijozlariga sotgan tovarni shu yerda belgilang — bir nechta mahsulotni birdan kiritishingiz mumkin. Shundan keyin qarz va foyda hisoblanadi.</div>
        <div class="form-group">
          <label class="form-label">Diller (ism bo'yicha qidiring)</label>
          <div style="position:relative">
            <input type="text" class="form-control" id="dls-q" placeholder="Diller ismi..." value="${esc(d?d.name:'')}"
              oninput="dlsDealerSearch(this.value)" autocomplete="off">
            <div id="dls-dd" style="display:none;position:absolute;top:100%;left:0;right:0;
              background:var(--bg-card);border:1px solid var(--border);border-top:none;
              border-radius:0 0 var(--radius-sm) var(--radius-sm);max-height:220px;overflow-y:auto;z-index:999"></div>
          </div>
        </div>
        ${!d ? '<p style="color:var(--text-muted);font-size:12px">Avval dillerni tanlang...</p>' : !stock.length ? `<p style="color:var(--text-muted);font-size:12px">${esc(d.name)} omborida tovar yo'q.</p>` : `
        <div style="background:rgba(226,61,61,0.04);border:1px solid rgba(226,61,61,0.15);border-radius:var(--radius-sm);padding:12px;margin-bottom:12px">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
            <span style="font-size:12px;font-weight:700;color:var(--red)">📦 Sotilgan mahsulotlar</span>
            <button class="btn btn-primary btn-sm" onclick="addDlsRow()">+ Qo'shish</button>
          </div>
          <div style="display:grid;grid-template-columns:1.6fr 55px 75px 32px;gap:6px;margin-bottom:6px">
            <span style="font-size:10px;color:var(--text-muted);text-transform:uppercase">Mahsulot</span>
            <span style="font-size:10px;color:var(--text-muted);text-transform:uppercase">Dona</span>
            <span style="font-size:10px;color:var(--text-muted);text-transform:uppercase">Narx/dona</span>
            <span></span>
          </div>
          <div id="dls-items">${renderDlsRows()}</div>
        </div>
        <div class="form-group">
          <label class="form-label">Diller xizmat haqi (%) — barcha qatorlarga qo'llanadi</label>
          <div style="display:flex;gap:6px;margin-bottom:8px">
            <button class="btn btn-ghost btn-sm" onclick="dlsSetPct(3)">3%</button>
            <button class="btn btn-ghost btn-sm" onclick="dlsSetPct(5)">5%</button>
            <button class="btn btn-ghost btn-sm" onclick="dlsSetPct(8)">8%</button>
          </div>
          <input class="form-control" id="dls-pct" type="number" step="0.5" value="${S.dillerSalePct}" oninput="dlsPctInput(this.value)">
        </div>
        <div id="dls-result" class="formula-result" style="margin-bottom:12px"></div>
        <button class="btn btn-primary btn-lg" onclick="dlsSubmit()" style="width:100%;justify-content:center">✅ BELGILASH</button>
        `}
      </div>
      <div class="card">
        <div class="card-title" style="margin-bottom:12px">📋 Dillerlar tarixi</div>
        <div style="max-height:560px;overflow-y:auto">
          ${S.dealerTxns.slice(0,40).map(t=>{
            const dl=S.dealers.find(x=>x.id===t.dealerId);
            const icon=t.type==='send'?'🚚':t.type==='return'?'↩️':t.type==='sale'?'🧾':'💰';
            const color=t.type==='sale'?'var(--red)':t.type==='payment'?'var(--emerald)':'var(--text-muted)';
            const lbl=t.type==='send'?(t.mode==='debt'?`Qarzga yuborildi → qarz +${CUR.fmtUsd(t.debtUsd||0)}`:'Yuborildi (ombor)'):t.type==='return'?'Qaytarildi':t.type==='sale'?'Diller sotdi → qarz':"To'lov qabul qilindi";
            const sign=t.type==='sale'?'+':t.type==='payment'?'−':'';
            return `<div style="display:flex;justify-content:space-between;align-items:center;padding:9px 0;border-bottom:1px solid var(--border-light)">
              <div><div style="font-size:12px;font-weight:600">${icon} ${esc(dl?.name||'—')}</div><div style="font-size:11px;color:var(--text-muted)">${fmtD(t.date)} · ${lbl}</div></div>
              <span style="font-weight:700;color:${color}">${sign}${CUR.fmtUsd(t.totalUsd)}${t.profitUsd!=null?` <span style="font-size:10px;color:var(--emerald)">(foyda +${CUR.fmtUsd(t.profitUsd)})</span>`:''}</span>
            </div>`;
          }).join('')||'<p style="color:var(--text-muted);font-size:13px">Tarix yo\'q</p>'}
        </div>
      </div>
    </div>`;
}

function dlsDealerSearch(q) {
  const dd = document.getElementById('dls-dd'); if (!dd) return;
  S.dillerSaleId = null;
  if (!q || !q.length) { dd.style.display='none'; return; }
  const r = multiFieldSearch(S.dealers, q, d=>[d.name, d.phone, d.region]).slice(0,12);
  if (!r.length) { dd.innerHTML='<div style="padding:10px;color:var(--text-muted);font-size:12px">Topilmadi</div>'; dd.style.display='block'; return; }
  dd.innerHTML = r.map(x=>`<div onclick="dlsDealerSelect(${x.id})" style="padding:9px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid var(--border-light);color:var(--text-primary)"
    onmouseover="this.style.background='var(--bg-hover)'" onmouseout="this.style.background=''">${esc(x.name)} <span style="color:var(--text-muted)">— ${esc(x.region||'')}</span></div>`).join('');
  dd.style.display = 'block';
}

function dlsDealerSelect(did) {
  S.dillerSaleId = did;
  S.dillerSaleCart = [];
  const d = S.dealers.find(x=>x.id===did);
  S.dillerSalePct = d?.commissionPct ?? 0;
  const dd = document.getElementById('dls-dd'); if (dd) dd.style.display='none';
  dillerRenderTab();
}

function renderDlsRows() {
  if (!S.dillerSaleCart) S.dillerSaleCart = [];
  const d = S.dealers.find(x=>x.id===S.dillerSaleId);
  const stock = d ? S.dealerStock.filter(r=>r.dealerId===d.id&&r.qty>0) : [];
  return S.dillerSaleCart.map(it=>{
    const p = it.pid ? S.products.find(x=>x.id===it.pid) : null;
    return `<div style="display:grid;grid-template-columns:1.6fr 55px 75px 32px;gap:6px;margin-bottom:6px" id="dlsrow-${it.id}">
      <div style="position:relative">
        <input type="text" class="form-control" id="dlsrow-q-${it.id}" style="margin:0;font-size:12px;padding:7px 10px"
          placeholder="Kod yoki nom..." autocomplete="off" value="${p?`${p.sku} — ${p.name}`.replace(/"/g,'&quot;'):''}"
          oninput="dlsRowSearch(${it.id},this.value)">
        <div id="dlsrow-dd-${it.id}" style="display:none;position:absolute;top:100%;left:0;right:0;
          background:var(--bg-card);border:1px solid var(--border);border-top:none;
          border-radius:0 0 var(--radius-sm) var(--radius-sm);max-height:180px;overflow-y:auto;z-index:999"></div>
      </div>
      <input type="number" class="form-control" style="margin:0;font-size:12px;padding:7px 8px" placeholder="Dona"
        value="${it.qty||''}" min="1" oninput="dlsRowSet(${it.id},'qty',parseInt(this.value)||1)">
      <input type="number" class="form-control" id="dlsrow-price-${it.id}" style="margin:0;font-size:12px;padding:7px 8px" placeholder="$" step="0.01"
        value="${it.price||''}" oninput="dlsRowSet(${it.id},'price',parseFloat(this.value)||0)">
      <button class="btn btn-danger btn-sm btn-icon" onclick="removeDlsRow(${it.id})" style="padding:7px">✕</button>
    </div>`;
  }).join('');
}

function addDlsRow() {
  if (!S.dillerSaleCart) S.dillerSaleCart = [];
  S.dillerSaleCart.push({id:uid(), pid:null, qty:1, price:0});
  const el = document.getElementById('dls-items'); if (el) el.innerHTML = renderDlsRows();
}

function removeDlsRow(id) {
  S.dillerSaleCart = S.dillerSaleCart.filter(x=>x.id!==id);
  const el = document.getElementById('dls-items'); if (el) el.innerHTML = renderDlsRows();
  dlsCalc();
}

function dlsRowSearch(rowId, q) {
  const dd = document.getElementById('dlsrow-dd-'+rowId); if (!dd) return;
  const d = S.dealers.find(x=>x.id===S.dillerSaleId);
  const stock = d ? S.dealerStock.filter(r=>r.dealerId===d.id&&r.qty>0) : [];
  if (!q || !q.length) { dd.style.display='none'; dlsRowSet(rowId,'pid',null); return; }
  const r = stock.filter(rec=>{
    const p=S.products.find(x=>x.id===rec.pid);
    return p && productSearchMatch([p], q).length>0;
  }).slice(0,15);
  if (!r.length) { dd.innerHTML='<div style="padding:10px 12px;color:var(--text-muted);font-size:12px">Diller omborida topilmadi</div>'; dd.style.display='block'; return; }
  dd.innerHTML = r.map(rec=>{
    const p=S.products.find(x=>x.id===rec.pid);
    return `<div onclick="dlsRowSelect(${rowId},${rec.pid})" style="padding:8px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid var(--border-light);color:var(--text-primary)"
    onmouseover="this.style.background='var(--bg-hover)'" onmouseout="this.style.background=''">
    <code style="color:var(--gold);margin-right:6px">${esc(p.sku)}</code>${esc(p.name)} <span style="color:var(--text-muted)">(bor: ${rec.qty})</span></div>`;
  }).join('');
  dd.style.display = 'block';
}

function dlsRowSelect(rowId, pid) {
  const it = S.dillerSaleCart.find(x=>x.id===rowId); if (!it) return;
  it.pid = pid;
  const p = S.products.find(x=>x.id===pid);
  const q = document.getElementById('dlsrow-q-'+rowId); if (q) q.value = p?`${p.sku} — ${p.name}`:'';
  if (p && !it.price) {
    const rec = S.dealerStock.find(r=>r.dealerId===S.dillerSaleId&&r.pid===pid);
    it.price = +optPrice(p, rec?.avgCostUsd||getCostFIFO(pid)).toFixed(2);
    const priceEl = document.getElementById('dlsrow-price-'+rowId); if (priceEl) priceEl.value = it.price;
  }
  const dd = document.getElementById('dlsrow-dd-'+rowId); if (dd) dd.style.display='none';
  dlsCalc();
}

function dlsRowSet(id, field, val) {
  const it = S.dillerSaleCart.find(x=>x.id===id);
  if (it) { it[field]=val; dlsCalc(); }
}

function dlsSetPct(pct) {
  S.dillerSalePct = pct;
  const el = document.getElementById('dls-pct'); if (el) el.value = pct;
  dlsCalc();
}

function dlsPctInput(v) {
  S.dillerSalePct = parseFloat(v)||0;
  dlsCalc();
}

function dlsCalc() {
  const d = S.dealers.find(x=>x.id===S.dillerSaleId);
  const el = document.getElementById('dls-result'); if (!el) return;
  if (!d) { el.innerHTML=''; return; }
  const pct = S.dillerSalePct||0;
  const rows = (S.dillerSaleCart||[]).filter(i=>i.pid&&i.qty>0&&i.price>0).map(i=>{
    const rec = S.dealerStock.find(r=>r.dealerId===d.id&&r.pid===i.pid);
    const cost = rec?.avgCostUsd||0;
    const lineTotal = i.qty*i.price;
    return { ...i, cost, lineTotal, lineProfit:(i.price-cost)*i.qty };
  });
  if (!rows.length) { el.innerHTML='<div class="formula-result-title">📐 Jami</div><div style="color:var(--text-muted);font-size:13px">Mahsulot, miqdor va narx kiriting...</div>'; return; }
  const saleTotal = rows.reduce((s,r)=>s+r.lineTotal,0);
  const commission = saleTotal*pct/100;
  const owed = saleTotal-commission;
  const profit = rows.reduce((s,r)=>s+r.lineProfit,0);
  const lossRows = rows.filter(r=>r.price<r.cost);
  el.innerHTML = `
    <div class="formula-result-title">📐 Jami</div>
    <div style="display:flex;flex-direction:column;gap:5px;font-size:13px">
      <div style="display:flex;justify-content:space-between"><span style="color:var(--text-muted)">Sotilgan summa</span><span style="font-weight:700">${CUR.fmtUsd(saleTotal)}</span></div>
      <div style="display:flex;justify-content:space-between"><span style="color:var(--text-muted)">Diller xizmat haqi (${pct}%)</span><span style="color:var(--blue)">−${CUR.fmtUsd(commission)}</span></div>
      <div style="display:flex;justify-content:space-between;font-weight:700;border-top:1px solid var(--border);padding-top:5px"><span>Diller topshiradigan (qarzga)</span><span style="color:var(--red)">${CUR.fmtUsd(owed)}</span></div>
      <div style="display:flex;justify-content:space-between;font-weight:700"><span>Sizning foyda (opt−tannarx)</span><span style="color:${profit<0?'var(--red)':'var(--emerald)'}">${profit<0?'':'+'}${CUR.fmtUsd(profit)}</span></div>
      ${lossRows.length?`<div style="font-size:11px;color:var(--red);margin-top:4px">⚠️ Tannarxdan past: ${esc(lossRows.map(r=>{const p=S.products.find(x=>x.id===r.pid);return p?.sku;}).join(', '))} — zararga sotilmoqda</div>`:''}
    </div>`;
}

async function dlsSubmit() {
  const d = S.dealers.find(x=>x.id===S.dillerSaleId);
  if (!d) { toast('Dillerni tanlang!','error'); return; }
  const pct = S.dillerSalePct||0;
  const rows = (S.dillerSaleCart||[]).filter(i=>i.pid&&i.qty>0&&i.price>0);
  if (!rows.length) { toast('Mahsulot, miqdor va narx kiriting!','error'); return; }

  const items = [];
  for (const r of rows) {
    const rec = S.dealerStock.find(x=>x.dealerId===d.id&&x.pid===r.pid);
    if (!rec || r.qty>rec.qty) { const p=S.products.find(x=>x.id===r.pid); toast(`${p?.name||''}: dillerda yetarli qoldiq yo'q!`,'error'); return; }
    items.push({pid:r.pid, qty:r.qty, price:r.price, cost:rec.avgCostUsd||0});
  }

  // v24.5 (35-migratsiya): diller qoldig'i, qarzi, total_sold va ballar — serverda BITTA tranzaksiyada (qoldiqdan oshsa — rad)
  let dres;
  try { dres = await fwDealerCall({ kind:'sale', dealerId:d.id, pct, items: items.map(i=>{ const p=S.products.find(x=>x.id===i.pid); return { pid:i.pid, qty:i.qty, priceUsd:i.price, sku:p?.sku, name:p?.name }; }) }); }
  catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  if (dres) {
    fwApplyDealerResult(d, dres);
    const owedS = +dres.owedUsd||0, profitS = +dres.profitUsd||0, ptsS = +dres.points||0;
    const costOf = new Map((dres.items||[]).map(x=>[+x.pid, +x.costUsd||0]));
    const inv = fwNextDocNo('DLR-', S.sales);
    S.sales.push({
      id:uid(), date:td(), inv, custId:null, custName:`${d.name} (diller)`,
      items: items.map(i=>{ const p=S.products.find(x=>x.id===i.pid); const c=costOf.has(+i.pid)?costOf.get(+i.pid):i.cost; return {pid:i.pid, sku:p?.sku||'', name:p?.name||'', qty:i.qty, costUsd:c, sellUsd:i.price, lineUsd:i.qty*i.price}; }),
      subtotalUsd:+dres.saleTotalUsd||0, disc:pct, discUsd:(+dres.saleTotalUsd||0)-owedS, totalUsd:owedS,
      paidUsd:0, debtUsd:owedS, payType:'dealer', boxId:null, profitUsd:profitS, status:'done', dealerId:d.id, dealerCommissionPct:pct
    });
    S.dealerTxns.unshift({id:uid(),date:td(),dealerId:d.id,type:'sale',items:items.map(i=>({pid:i.pid,qty:i.qty,priceUsd:i.price})),totalUsd:owedS,profitUsd:profitS,commissionPct:pct});
    auditLog(`Diller sotdi: ${d.name} — ${items.length} xil mahsulot — qarz +${CUR.fmtUsd(owedS)}, foyda +${CUR.fmtUsd(profitS)}, ball +${ptsS}`);
    S.dillerSaleCart = []; S.dillerSaleId = null;
    save(); pgDillerlar();
    toast(`✅ Belgilandi! Qarz: +${CUR.fmtUsd(owedS)}, Foyda: +${CUR.fmtUsd(profitS)}, Ball: +${ptsS}`);
    dlAuditDealer(d.id, 'sale', null, { items: items.map(i=>({pid:i.pid,qty:i.qty,priceUsd:i.price})), owed: owedS, profit: profitS, pointsEarned: ptsS });
    return;
  }
  // 35-migratsiyagacha (eski yo'l): mahalliy hisob + alohida bulut yozuvlari
  const saleTotal = items.reduce((s,i)=>s+i.qty*i.price,0);
  const commission = saleTotal*pct/100;
  const owed = saleTotal-commission;
  const profit = items.reduce((s,i)=>s+(i.price-i.cost)*i.qty,0);
  const pointsEarned = items.reduce((s,i)=>{
    const p = S.products.find(x=>x.id===i.pid);
    return s + calcDealerPoints(i.qty*i.price, p?.pointPct||0);
  }, 0);

  items.forEach(i=>{
    const rec = S.dealerStock.find(x=>x.dealerId===d.id&&x.pid===i.pid);
    rec.qty -= i.qty;
  });
  d.debt = (d.debt||0)+owed;
  d.totalSold = (d.totalSold||0)+owed;
  d.points = (d.points||0)+pointsEarned;

  const inv = fwNextDocNo('DLR-', S.sales);
  S.sales.push({
    id:uid(), date:td(), inv,
    custId:null, custName:`${d.name} (diller)`,
    items: items.map(i=>{ const p=S.products.find(x=>x.id===i.pid); return {pid:i.pid, sku:p?.sku||'', name:p?.name||'', qty:i.qty, costUsd:i.cost, sellUsd:i.price, lineUsd:i.qty*i.price}; }),
    subtotalUsd:saleTotal, disc:pct, discUsd:commission, totalUsd:owed,
    paidUsd:0, debtUsd:owed,
    payType:'dealer', boxId:null,
    profitUsd:profit, status:'done',
    dealerId:d.id, dealerCommissionPct:pct
  });

  S.dealerTxns.unshift({id:uid(),date:td(),dealerId:d.id,type:'sale',items:items.map(i=>({pid:i.pid,qty:i.qty,priceUsd:i.price})),totalUsd:owed,profitUsd:profit,commissionPct:pct});
  auditLog(`Diller sotdi: ${d.name} — ${items.length} xil mahsulot — qarz +${CUR.fmtUsd(owed)}, foyda +${CUR.fmtUsd(profit)}, ball +${pointsEarned}`);
  S.dillerSaleCart = []; S.dillerSaleId = null;
  save(); pgDillerlar();
  toast(`✅ Belgilandi! Qarz: +${CUR.fmtUsd(owed)}, Foyda: +${CUR.fmtUsd(profit)}, Ball: +${pointsEarned}`);

  try {
    const cloudOps = items.map(i=>{
      const rec = S.dealerStock.find(x=>x.dealerId===d.id&&x.pid===i.pid);
      const p = S.products.find(x=>x.id===i.pid);
      return dlUpsertStock(d.id, i.pid, p?.sku, p?.name, rec.qty, rec.avgCostUsd||0);
    });
    cloudOps.push(authFetch('/.netlify/functions/dealer-sale-add', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({
        dealerId: d.id, saleDate: td(),
        items: items.map(i=>{
          const p = S.products.find(x=>x.id===i.pid);
          return { pid:i.pid, sku:p?.sku, name:p?.name, qty:i.qty, sellUsd:i.price, totalUsd:i.qty*i.price };
        })
      })
    }).then(async r=>{ const d2=await r.json(); if(!r.ok) throw new Error(d2.error); }));
    cloudOps.push(dlUpdateDealerRow(d.id, {debt:d.debt, totalSold:d.totalSold, points:d.points}));
    await Promise.all(cloudOps);
    dlAuditDealer(d.id, 'sale', null, { items: items.map(i=>({pid:i.pid,qty:i.qty,priceUsd:i.price})), owed, profit, pointsEarned });
  } catch(e) { toast('⚠️ Bulutga yozishda xatolik: '+e.message, 'error'); }
}

function openDealerReturn(did) {
  const d=S.dealers.find(x=>x.id===did);if(!d)return;
  const stock=S.dealerStock.filter(r=>r.dealerId===did&&r.qty>0);
  if(!stock.length){toast("Diller omborida tovar yo'q!",'warning');return;}
  S.dillerReturnDid = did;
  S.dillerReturnCart = [{id:uid(), pid:null, qty:1}];
  modal(`
    <div class="modal-header"><div class="modal-title">↩️ ${esc(d.name)} — tovar qaytarish</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <p style="color:var(--text-secondary);font-size:12px;margin-bottom:12px">Sotilmagan tovarni asosiy omborga qaytarish — qarzga ta'sir qilmaydi (chunki hali sotilmagan). Bir nechta mahsulotni, turli miqdorda (masalan 3, 5, 100 dona) birdan qaytarishingiz mumkin.</p>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
        <span style="font-size:11px;color:var(--text-muted);text-transform:uppercase">Mahsulotlar</span>
        <button class="btn btn-primary btn-sm" onclick="addDillerReturnRow()">+ Qo'shish</button>
      </div>
      <div id="dr-items">${renderDillerReturnRows()}</div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" onclick="doDealerReturn(${did})">✅ Qaytarish</button>
    </div>`);
}

function renderDillerReturnRows() {
  if (!S.dillerReturnCart) S.dillerReturnCart = [];
  const did = S.dillerReturnDid;
  const stockList = S.dealerStock.filter(r=>r.dealerId===did&&r.qty>0);
  const CONDITIONS = ['Yangi','Yaxshi',"Ta'mirtalab",'Yaroqsiz'];
  return S.dillerReturnCart.map(it=>{
    const rec = it.pid ? stockList.find(r=>r.pid===it.pid) : null;
    const p = rec ? S.products.find(x=>x.id===rec.pid) : null;
    return `<div style="margin-bottom:10px;padding-bottom:10px;border-bottom:1px dashed var(--border-light)" id="drrow-${it.id}">
      <div style="display:grid;grid-template-columns:2fr 70px 32px;gap:6px">
        <div style="position:relative">
          <input type="text" class="form-control" id="drrow-q-${it.id}" style="margin:0;font-size:12px;padding:7px 10px"
            placeholder="Kod yoki nom..." autocomplete="off" value="${p?`${p.sku} — ${p.name}`.replace(/"/g,'&quot;'):''}"
            oninput="drrowSearch(${it.id},this.value)">
          <div id="drrow-dd-${it.id}" style="display:none;position:absolute;top:100%;left:0;right:0;
            background:var(--bg-card);border:1px solid var(--border);border-top:none;
            border-radius:0 0 var(--radius-sm) var(--radius-sm);max-height:200px;overflow-y:auto;z-index:999"></div>
        </div>
        <input type="number" class="form-control" id="drrow-qty-${it.id}" style="margin:0;font-size:12px;padding:7px 8px" placeholder="Dona"
          value="${it.qty||''}" min="1" max="${rec?.qty??''}" oninput="drRowSet(${it.id},'qty',parseInt(this.value)||1)">
        <button class="btn btn-danger btn-sm btn-icon" onclick="removeDillerReturnRow(${it.id})" style="padding:7px">✕</button>
      </div>
      ${rec ? `<div style="font-size:10.5px;color:var(--text-muted);margin:3px 0 6px 2px">📦 Dillerda bor: <strong>${rec.qty}</strong> dona</div>` : ''}
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:4px">
        <select class="form-control" style="margin:0;font-size:12px;padding:7px 8px" onchange="drRowSet(${it.id},'condition',this.value)">
          <option value="">Holati...</option>
          ${CONDITIONS.map(c=>`<option value="${c}" ${it.condition===c?'selected':''}>${c}</option>`).join('')}
        </select>
        <input type="text" class="form-control" style="margin:0;font-size:12px;padding:7px 8px" placeholder="Sababi (ixtiyoriy)"
          value="${esc(it.reason||'')}" oninput="drRowSet(${it.id},'reason',this.value)">
      </div>
      ${(it.condition==="Ta'mirtalab"||it.condition==='Yaroqsiz') ? `<div style="font-size:10.5px;color:var(--red);margin-top:4px">⚠️ Bu holat sotiladigan omborga avtomatik QO'SHILMAYDI — faqat dillerdan ayiriladi, alohida qayd etiladi.</div>` : ''}
    </div>`;
  }).join('');
}

function addDillerReturnRow() {
  if (!S.dillerReturnCart) S.dillerReturnCart = [];
  S.dillerReturnCart.push({id:uid(), pid:null, qty:1});
  const el = document.getElementById('dr-items');
  if (el) el.innerHTML = renderDillerReturnRows();
}

function drrowSearch(rowId, q) {
  const dd = document.getElementById('drrow-dd-'+rowId); if (!dd) return;
  if (!q || !q.length) { dd.style.display='none'; drRowSet(rowId,'pid',null); return; }
  const did = S.dillerReturnDid;
  const stockList = S.dealerStock.filter(r=>r.dealerId===did&&r.qty>0);
  const r = stockList.filter(rec=>{
    const p = S.products.find(x=>x.id===rec.pid);
    return p && productSearchMatch([p], q).length>0;
  }).slice(0,15);
  if (!r.length) { dd.innerHTML='<div style="padding:10px 12px;color:var(--text-muted);font-size:12px">Topilmadi</div>'; dd.style.display='block'; return; }
  dd.innerHTML = r.map(rec=>{
    const p=S.products.find(x=>x.id===rec.pid);
    return `<div onclick="drrowSelect(${rowId},${p.id})" style="padding:8px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid var(--border-light);color:var(--text-primary)"
    onmouseover="this.style.background='var(--bg-hover)'" onmouseout="this.style.background=''">
    <code style="color:var(--gold);margin-right:6px">${esc(p.sku)}</code>${esc(p.name)} <span style="color:var(--text-muted)">(bor: ${rec.qty})</span></div>`;
  }).join('');
  dd.style.display = 'block';
}

function drrowSelect(rowId, pid) {
  const it = S.dillerReturnCart.find(x=>x.id===rowId); if (!it) return;
  it.pid = pid;
  const dd = document.getElementById('drrow-dd-'+rowId); if (dd) dd.style.display='none';
  const el = document.getElementById('dr-items');
  if (el) el.innerHTML = renderDillerReturnRows();
}

function drRowSet(id, field, val) {
  const it = S.dillerReturnCart.find(x=>x.id===id);
  if (it) { it[field]=val; }
}

function removeDillerReturnRow(id) {
  S.dillerReturnCart = S.dillerReturnCart.filter(x=>x.id!==id);
  const el = document.getElementById('dr-items'); if (el) el.innerHTML = renderDillerReturnRows();
}

async function doDealerReturn(did) {
  const d=S.dealers.find(x=>x.id===did);if(!d)return;
  const rows = (S.dillerReturnCart||[]).filter(r=>r.pid && r.qty>0);
  if (!rows.length) { toast('Kamida bitta mahsulot va miqdor tanlang!','error'); return; }
  if (rows.some(r=>!r.condition)) { toast("Har bir mahsulot uchun holatini tanlang!",'error'); return; }

  for (const row of rows) {
    const rec = S.dealerStock.find(r=>r.dealerId===did&&r.pid===row.pid);
    if (!rec || row.qty>rec.qty) {
      const p = S.products.find(x=>x.id===row.pid);
      toast(`"${p?.name||''}" uchun miqdor noto'g'ri (dillerda yetarli emas)!`,'error');
      return;
    }
  }

  let totalQty = 0, restockedQty = 0;
  const cloudUpdates = [];
  // v23.2 (F4b): sotiladigan holatdagi tovar asosiy omborga — SERVERDA (ombor jurnali)
  const sellRows = rows.filter(row=>row.condition==='Yangi' || row.condition==='Yaxshi');
  const retIds = fwStableIds('dealer_return:'+did, sellRows.map(r=>[r.pid,r.qty,r.condition]), sellRows.length);
  const retBatches = sellRows.map((row,i)=>{
    const rec = S.dealerStock.find(r=>r.dealerId===did&&r.pid===row.pid);
    return {id:retIds[i],pid:row.pid,bno:String((S.batchCounter||0)+1+i).padStart(2,'0'),origin:`Dillerdan qaytdi (${row.condition})`,cur:'USD',qty:row.qty,sold:0,costUsd:rec.avgCostUsd||0,bankFeeUsd:0,suppId:null,rates:{usdUzs:CUR.usdUzs,usdCny:CUR.usdCny},date:td(),status:'active',items:[{pid:row.pid,qty:row.qty}]};
  });
  // v24.5 (35-migratsiya): diller omboridan ayirish + harakat + (sotiladigan holat) firma omboriga partiya — serverda BITTA tranzaksiyada
  let dres;
  try {
    let _k = 0;
    dres = await fwDealerCall({ kind:'return', dealerId:did, items: rows.map(row=>{
      const sell = (row.condition==='Yangi' || row.condition==='Yaxshi'); const rb = sell ? retBatches[_k++] : null;
      const p = S.products.find(x=>x.id===row.pid);
      return { pid:row.pid, qty:row.qty, condition:row.condition, reason:row.reason||'', localId: rb ? String(rb.id) : undefined, bno: rb ? rb.bno : undefined, sku:p?.sku, name:p?.name };
    }) });
  } catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  if (dres) {
    fwStableIdsDone('dealer_return:'+did);
    const byPid = new Map((dres.items||[]).map(x=>[+x.pid, x]));
    const before = new Map(rows.map(r=>{ const rec=S.dealerStock.find(x=>x.dealerId===did&&x.pid===r.pid); return [r.pid, rec ? rec.qty : 0]; }));
    fwApplyDealerResult(d, dres);
    let restocked = 0, total = 0;
    rows.forEach(row=>{ total += row.qty; if (row.condition==='Yangi' || row.condition==='Yaxshi') restocked += row.qty; });
    retBatches.forEach(b=>{ S.batchCounter = (S.batchCounter||0) + 1; S.batches.push(b); });
    if (dres.authority) fwApplyLedger(dres.authority);   // yangi partiyalar — bazadagi qiymat
    S.dealerTxns.unshift({id:uid(),date:td(),dealerId:did,type:'return',
      items: rows.map(r=>({pid:r.pid, qty:r.qty, priceUsd:+(byPid.get(+r.pid)?.costUsd)||0, condition:r.condition, reason:r.reason||''})),
      totalUsd: +dres.totalCostUsd||0});
    auditLog(`Diller qaytarish: ${d.name} — ${rows.length} xil mahsulot, jami ${total} dona (omborga qaytdi: ${restocked}, nosozlik/yaroqsiz: ${total-restocked})`);
    save();closeModal();pgDillerlar();
    toast(restocked<total
      ? `✅ ${total} dona qaytdi — ${restocked} dona sotiladigan omborga, ${total-restocked} dona nosoz sifatida qayd etildi`
      : `✅ Jami ${total} dona (${rows.length} xil mahsulot) asosiy omborga qaytdi!`);
    rows.forEach(row=>{
      const rec = S.dealerStock.find(r=>r.dealerId===did&&r.pid===row.pid);
      dlAuditDealer(did, 'stock_return', { pid:row.pid, qty:before.get(row.pid) }, { pid:row.pid, qty:rec ? rec.qty : null, returnedQty:row.qty, condition:row.condition, reason:row.reason||'', restocked:(row.condition==='Yangi' || row.condition==='Yaxshi') });
    });
    return;
  }
  // 35-migratsiyagacha (eski yo'l)
  if (fwLedgerRemote() && retBatches.length) {
    try { await fwLedgerCall('stock-debt-ops', { kind:'batches_create', payload:{ reason:'dealer_return',
      batches: retBatches.map(o=>({ localId:String(o.id), pid:o.pid, qty:o.qty, costUsd:o.costUsd, meta:{ bno:o.bno, origin:o.origin, date:o.date } })) } }); }
    catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  }
  fwStableIdsDone('dealer_return:'+did);
  let _ri = 0;
  rows.forEach(row=>{
    const rec = S.dealerStock.find(r=>r.dealerId===did&&r.pid===row.pid);
    const costBasis = rec.avgCostUsd||0;
    const sellable = (row.condition==='Yangi' || row.condition==='Yaxshi');
    rec.qty -= row.qty;
    if (sellable) {
      S.batchCounter = (S.batchCounter||0) + 1;
      S.batches.push(retBatches[_ri++]);
      restockedQty += row.qty;
    }
    totalQty += row.qty;
    cloudUpdates.push({pid:row.pid, qty:rec.qty, avgCostUsd:rec.avgCostUsd, retQty:row.qty, costBasis, reason:row.reason||'', condition:row.condition, sellable});
  });
  S.dealerTxns.unshift({id:uid(),date:td(),dealerId:did,type:'return',
    items: cloudUpdates.map(u=>({pid:u.pid, qty:u.retQty, priceUsd:u.costBasis, condition:u.condition, reason:u.reason})),
    totalUsd: cloudUpdates.reduce((s,u)=>s+u.retQty*u.costBasis,0)});
  auditLog(`Diller qaytarish: ${d.name} — ${rows.length} xil mahsulot, jami ${totalQty} dona (omborga qaytdi: ${restockedQty}, nosozlik/yaroqsiz: ${totalQty-restockedQty})`);
  save();closeModal();pgDillerlar();
  toast(restockedQty<totalQty
    ? `✅ ${totalQty} dona qaytdi — ${restockedQty} dona sotiladigan omborga, ${totalQty-restockedQty} dona nosoz sifatida qayd etildi`
    : `✅ Jami ${totalQty} dona (${rows.length} xil mahsulot) asosiy omborga qaytdi!`);
  try {
    for (const u of cloudUpdates) {
      const p = S.products.find(x=>x.id===u.pid);
      await dlUpsertStock(did, u.pid, p?.sku, p?.name, u.qty, u.avgCostUsd);
      await dlInsertMove(did, 'return', u.pid, p?.sku, p?.name, u.retQty, u.costBasis, u.reason, u.condition);
      dlAuditDealer(did, 'stock_return', { pid:u.pid, qty:u.qty+u.retQty }, { pid:u.pid, qty:u.qty, returnedQty:u.retQty, condition:u.condition, reason:u.reason, restocked:u.sellable });
    }
  } catch(e) { toast('⚠️ Bulutga yozishda xatolik: '+e.message, 'error'); }
}

// ── YUBORISH (faqat ko'chirish — qarz yo'q, sotuvgacha) ──
