function renderDillerRows() {
  if (!S.dillerCart) S.dillerCart = [];
  return S.dillerCart.map(it=>{
    const p = it.pid ? S.products.find(x=>x.id===it.pid) : null;
    const stock = p ? getStock(p.id) : null;
    return `<div style="margin-bottom:6px" id="dsrow-${it.id}">
      <div style="display:grid;grid-template-columns:2fr 70px 32px;gap:6px">
        <div style="position:relative">
          <input type="text" class="form-control" id="dsrow-q-${it.id}" style="margin:0;font-size:12px;padding:7px 10px"
            placeholder="Kod yoki nom..." autocomplete="off" value="${p?`${p.sku} — ${p.name}`.replace(/"/g,'&quot;'):''}"
            oninput="dsrowSearch(${it.id},this.value)">
          <div id="dsrow-dd-${it.id}" style="display:none;position:absolute;top:100%;left:0;right:0;
            background:var(--bg-card);border:1px solid var(--border);border-top:none;
            border-radius:0 0 var(--radius-sm) var(--radius-sm);max-height:200px;overflow-y:auto;z-index:999"></div>
        </div>
        <input type="number" class="form-control" id="dsrow-qty-${it.id}" style="margin:0;font-size:12px;padding:7px 8px" placeholder="Dona"
          value="${it.qty||''}" min="1" max="${stock??''}" oninput="dsRowSet(${it.id},'qty',parseInt(this.value)||1)">
        <button class="btn btn-danger btn-sm btn-icon" onclick="removeDillerRow(${it.id})" style="padding:7px">✕</button>
      </div>
      ${p ? `<div style="font-size:10.5px;color:${stock<=0?'var(--red)':'var(--text-muted)'};margin:3px 0 0 2px">📦 Asosiy omborda qoldi: <strong>${stock}</strong> dona${S.dillerSendMode === 'debt' ? ` · qarzga narx (optom): <strong>${CUR.fmtUsd(dsDebtPrice(p.id))}</strong>` : ''}</div>` : ''}
    </div>`;
  }).join('');
}

function addDillerRow() {
  if (!S.dillerCart) S.dillerCart = [];
  S.dillerCart.push({id:uid(), pid:null, qty:1});
  const el = document.getElementById('ds-items');
  if (el) el.innerHTML = renderDillerRows();
}

function dsrowSearch(rowId, q) {
  const dd = document.getElementById('dsrow-dd-'+rowId); if (!dd) return;
  if (!q || !q.length) { dd.style.display='none'; dsRowSet(rowId,'pid',null); return; }
  const r = productSearchMatch(S.products, q).slice(0,15);
  if (!r.length) { dd.innerHTML='<div style="padding:10px 12px;color:var(--text-muted);font-size:12px">Topilmadi</div>'; dd.style.display='block'; return; }
  dd.innerHTML = r.map(p=>{
    const st=getStock(p.id);
    return `<div onclick="dsrowSelect(${rowId},${p.id})" style="padding:8px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid var(--border-light);color:var(--text-primary)"
    onmouseover="this.style.background='var(--bg-hover)'" onmouseout="this.style.background=''">
    <code style="color:var(--gold);margin-right:6px">${esc(p.sku)}</code>${esc(p.name)} <span style="color:var(--text-muted)">(bor: ${st})</span></div>`;
  }).join('');
  dd.style.display = 'block';
}

function dsrowSelect(rowId, pid) {
  const it = S.dillerCart.find(x=>x.id===rowId); if (!it) return;
  it.pid = pid;
  const el = document.getElementById('ds-items');
  if (el) el.innerHTML = renderDillerRows();
}

function dsRowSet(id, field, val) {
  const it = S.dillerCart.find(x=>x.id===id);
  if (it) { it[field]=val; }
}

function removeDillerRow(id) {
  S.dillerCart = S.dillerCart.filter(x=>x.id!==id);
  const el = document.getElementById('ds-items'); if (el) el.innerHTML = renderDillerRows();
}

// v25 (42): dillerga jo'natma turi — «sotish uchun» (qarz sotilganda) yoki «qarzga» (qarz hozir, optom narxda)
function dsMode(m) {
  S.dillerSendMode = m === 'debt' ? 'debt' : 'consign';
  pgDillerlar();
}
function dsDebtPrice(pid) {
  const p = S.products.find(x => x.id === pid) || {};
  return Math.round(optPrice(p, getCostFIFO(pid)) * 10000) / 10000;
}

function dsSearch(q) {
  const dd = document.getElementById('ds-dd'); if (!dd) return;
  S.dillerSendId = null;
  if (!q || !q.length) { dd.style.display='none'; return; }
  const r = S.dealers.filter(d=>d.name.toLowerCase().includes(q.toLowerCase())).slice(0,12);
  if (!r.length) { dd.innerHTML='<div style="padding:10px;color:var(--text-muted);font-size:12px">Topilmadi</div>'; dd.style.display='block'; return; }
  dd.innerHTML = r.map(d=>`<div onclick="dsSelect(${d.id})" style="padding:9px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid var(--border-light);color:var(--text-primary)"
    onmouseover="this.style.background='var(--bg-hover)'" onmouseout="this.style.background=''">${esc(d.name)} <span style="color:var(--text-muted)">— ${esc(d.region||'')}</span></div>`).join('');
  dd.style.display = 'block';
}

function dsSelect(did) {
  S.dillerSendId = did;
  const d = S.dealers.find(x=>x.id===did);
  const q = document.getElementById('ds-q'); if (q) q.value = d?.name||'';
  const dd = document.getElementById('ds-dd'); if (dd) dd.style.display='none';
}

async function sendToDealer() {
  if (!S.dillerSendId) { toast('Dillerni tanlang!','error'); return; }
  const items = (S.dillerCart||[]).filter(i=>i.pid&&i.qty>0);
  if (!items.length) { toast('Mahsulot va miqdor kiriting!','error'); return; }
  for (const i of items) {
    const st = getStock(i.pid);
    if (i.qty > st) { const p=S.products.find(x=>x.id===i.pid); toast(`${p?.name||''} omborida ${st} dona bor, ${i.qty} dona yuborib bo'lmaydi!`,'error'); return; }
  }
  const d = S.dealers.find(x=>x.id===S.dillerSendId); if (!d) return;
  // v24.5 (35-migratsiya): firma ombori (FIFO) + diller ombori + total_shipped — serverda BITTA tranzaksiyada
  let dres;
  const shipItems = [];   // bir mahsulot savatda ikki qatorda bo'lsa — bitta qatorga (server takrorni rad etadi)
  items.forEach(i=>{ const ex = shipItems.find(x=>x.pid===i.pid); if (ex) ex.qty += i.qty; else { const p=S.products.find(x=>x.id===i.pid); shipItems.push({ pid:i.pid, qty:i.qty, sku:p?.sku, name:p?.name }); } });
  const debtMode = S.dillerSendMode === 'debt';
  if (debtMode) {
    for (const i of shipItems) { i.priceUsd = dsDebtPrice(i.pid); if (!(i.priceUsd > 0)) { toast(`${i.name || ''}: optom narx yoʻq — «Qarzga» joʻnatib boʻlmaydi`, 'error'); return; } }
    const sum = shipItems.reduce((s, i) => s + i.qty * i.priceUsd, 0);
    if (!confirm(`«Qarzga» joʻnatma: ${d.name} qarziga hozir ${CUR.fmtUsd(sum)} yoziladi. Davom etilsinmi?`)) return;
  }
  try { dres = await fwDealerCall({ kind:'ship', dealerId:d.id, items: shipItems, ...(debtMode ? { mode:'debt' } : {}) }); }
  catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  if (!dres && debtMode) { toast("⛔ «Qarzga» joʻnatma faqat internet va serverdagi yangi hisob (42-migratsiya) bilan ishlaydi", 'error'); return; }
  if (dres) {
    fwApplyDealerResult(d, dres);
    S.dealerTxns.unshift({id:uid(), date:td(), dealerId:d.id, type:'send', items:items.map(i=>({pid:i.pid,qty:i.qty})), totalUsd:+dres.totalCostUsd||0, ...(debtMode ? { mode:'debt', debtUsd:+dres.debtUsd||0 } : {})});
    auditLog(`Dillerga yuborildi${debtMode ? ' (qarzga)' : ''}: ${d.name} — ${items.reduce((s,i)=>s+i.qty,0)} dona`);
    S.dillerCart = []; S.dillerSendId = null;
    save(); pgDillerlar(); toast(debtMode ? `✅ ${d.name}ga joʻnatildi — qarziga ${CUR.fmtUsd(+dres.debtUsd||0)} yozildi` : `✅ ${d.name}ning omboriga jo'natildi (hali qarz emas)`);
    return;
  }
  // 35-migratsiyagacha (eski yo'l) — v23.2 (F4b): asosiy ombordan chiqarish (FIFO) — SERVERDA; rad etilsa hech narsa o'zgarmaydi
  let srvCost = null;
  if (fwLedgerRemote()) {
    try {
      const r = await fwLedgerCall('stock-debt-ops', { kind:'stock_out', payload:{ reason:'dealer', dealerId:String(d.id), items: items.map(i=>({ pid:i.pid, qty:i.qty })) } });
      srvCost = new Map((r.items||[]).map(x=>[+x.pid, +x.firstCost]));
    } catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  }
  let totalCost = 0;
  const cloudOps = [];
  items.forEach(i=>{
    const costNow = srvCost ? (srvCost.get(+i.pid)||0) : getCostFIFO(i.pid);
    if (!srvCost) deductFIFO(i.pid, i.qty);
    let rec = S.dealerStock.find(r=>r.dealerId===d.id&&r.pid===i.pid);
    if (!rec) { rec={id:uid(),dealerId:d.id,pid:i.pid,qty:0,avgCostUsd:0}; S.dealerStock.push(rec); }
    const newQty = rec.qty + i.qty;
    rec.avgCostUsd = newQty>0 ? ((rec.qty*rec.avgCostUsd)+(i.qty*costNow))/newQty : costNow;
    rec.qty = newQty;
    totalCost += i.qty*costNow;
    const p = S.products.find(x=>x.id===i.pid);
    cloudOps.push(dlUpsertStock(d.id, i.pid, p?.sku, p?.name, rec.qty, rec.avgCostUsd));
    cloudOps.push(dlInsertMove(d.id, 'send', i.pid, p?.sku, p?.name, i.qty, costNow));
  });
  d.totalShipped = (d.totalShipped||0) + totalCost;
  S.dealerTxns.unshift({id:uid(), date:td(), dealerId:d.id, type:'send', items:items.map(i=>({pid:i.pid,qty:i.qty})), totalUsd:totalCost});
  auditLog(`Dillerga yuborildi: ${d.name} — ${items.reduce((s,i)=>s+i.qty,0)} dona`);
  S.dillerCart = []; S.dillerSendId = null;
  save(); pgDillerlar(); toast(`✅ ${d.name}ning omboriga jo'natildi (hali qarz emas)`);
  try { await Promise.all(cloudOps); await dlUpdateDealerRow(d.id, {totalShipped:d.totalShipped}); }
  catch(e) { toast('⚠️ Bulutga yozishda xatolik: '+e.message, 'error'); }
}

// ── QARZLAR ──
function dillerDebtHtml() {
  return `
    <div class="card">
      <div class="card-title" style="margin-bottom:12px">💰 Dillerlar qarzlari</div>
      <div class="table-wrap">
        <table>
          <thead><tr><th>Diller</th><th>Sotilgan ($)</th><th>To'langan ($)</th><th>Qarz ($)</th><th></th></tr></thead>
          <tbody>
            ${S.dealers.map(d=>`<tr>
              <td style="font-weight:600">${esc(d.name)}</td>
              <td>${CUR.fmtUsd(d.totalSold||0)}</td>
              <td style="color:var(--emerald)">${CUR.fmtUsd(d.totalPaid||0)}</td>
              <td style="color:${(d.debt||0)>0?'var(--red)':'var(--emerald)'};font-weight:700">${(d.debt||0)>0?CUR.fmtUsd(d.debt):'✅'}</td>
              <td>${(d.debt||0)>0?`<button class="btn btn-success btn-sm" onclick="openDealerPay(${d.id})">💰 To'lov</button>`:''}</td>
            </tr>`).join('')||`<tr><td colspan="5" style="text-align:center;color:var(--text-muted)">Diller yo'q</td></tr>`}
          </tbody>
        </table>
      </div>
    </div>`;
}

function openDealerPay(did) {
  const d=S.dealers.find(x=>x.id===did);if(!d)return;
  const dealerBox = S.cashboxes.find(k=>k.type==='dealer');
  const debtUsd = +d.debt||0, debtUzs = CUR.toUzs(debtUsd);
  modal(`
    <div class="modal-header"><div class="modal-title">💰 Dillerdan to'lov</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${meCard({ name:d.name, sub:esc(d.region||''), kpi:CUR.fmtUsd(debtUsd), kpiLabel:'qarz', tone:'neg' })}
      ${meSec('Qaysi kassaga')}
      ${meBoxPick('dp-b', meBoxOpts(S.cashboxes, dealerBox?.id ?? S.cashboxes[0]?.id), "meCurSwap('dp-a','dp-b','dp-u')")}
      ${meSec('Summa')}
      ${meAmt('dp-a', dealerBox?.cur==='USD'?debtUsd.toFixed(2):Math.round(debtUzs), dealerBox?.cur==='USD'?'$':"so'm", 'dp-u', `oninput="meRemain('dp-a','dp-b','dp-r',${debtUsd},'USD')"`)}
      ${meFillChips('dp-a','dp-b',debtUsd,debtUzs)}
      <div class="me-res" id="dp-r"></div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-success" onclick="doDealerPay(${did})">✅ Qabul qilish</button>
    </div>`);
  meRemain('dp-a','dp-b','dp-r',debtUsd,'USD');
}

function dpBoxChange() {
  const bid = parseInt(document.getElementById('dp-b')?.value||0);
  const box = S.cashboxes.find(k=>k.id===bid);
  const lbl = document.getElementById('dp-label');
  if (lbl) lbl.textContent = `Summa (${box?.cur==='USD'?'$':"so'm"})`;
}

async function doDealerPay(did) {
  const d=S.dealers.find(x=>x.id===did);if(!d)return;
  const raw=parseFloat(document.getElementById('dp-a')?.value||0);
  const bid=parseInt(document.getElementById('dp-b')?.value||1);
  if(!(raw>0)||!isFinite(raw)){toast('Summa kiriting!','error');return;}
  const box=S.cashboxes.find(k=>k.id===bid);
  if(!box){toast('⛔ Kassa tanlang','error');return;}
  const usd = box.cur==='USD' ? raw : CUR.toUsd(raw);
  if (usd > (d.debt||0) + 0.01) { toast(`⛔ To'lov diller qarzidan (${CUR.fmtUsd(d.debt||0)}) oshib ketdi`,'error'); return; }
  const before = { debt: d.debt||0, totalPaid: d.totalPaid||0 };
  // v23 fail-close: kassa kirimi + dealer_payments yozuvi + dealers.debt_usd — serverda BITTA
  // tranzaksiyada (cash_payment_atomic). Avval kassa yozilib, bulutga yozish xatosi faqat
  // "⚠️" bilan o'tib ketardi (qarz bulutda o'zgarmay qolardi).
  let r;
  try {
    r = await fwCashOps('dealer_pay', [{boxId:box.id, dir:'in', amount:raw, desc:`Diller to'lovi — ${d.name}`}], {
      remote:_cloudEnabled, refType:'dealer', refId:did, record:{ dealerId:did },
      legacy: () => dlInsertPayment(did, usd, box.name||'', 'dp-' + uid()),
    });
  } catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  if (r.authority && r.dealerDebtUsd != null) {
    d.debt = r.dealerDebtUsd; d.totalPaid = r.dealerTotalPaidUsd;   // server — haqiqiy manba
  } else {
    d.debt = Math.max(0,(d.debt||0)-usd);
    d.totalPaid = (d.totalPaid||0)+usd;
  }
  S.dealerTxns.unshift({id:uid(),date:td(),dealerId:did,type:'payment',items:[],totalUsd:usd});
  auditLog(`Diller to'lovi: ${d.name} — ${CUR.fmtUsd(usd)}`);
  save();closeModal();pgDillerlar();toast(`✅ ${CUR.fmtUsd(usd)} qabul qilindi!`);
  if (_cloudEnabled && !r.authority) {
    // 24-migratsiyagacha (eski yo'l): to'lov yozuvi yuqorida (fail-close) yozildi; qarz qatori —
    // avvalgidek alohida. Xato bo'lsa ochiq ko'rsatiladi.
    try { await dlUpdateDealerRow(did, {debt:d.debt, totalPaid:d.totalPaid}); }
    catch(e) { toast('⚠️ Diller qarzi bulutda yangilanmadi: '+e.message, 'error'); }
  }
  dlAuditDealer(did, 'payment', before, { debt: d.debt, totalPaid: d.totalPaid, amountUsd: usd });
}

