// KASSALAR
// ════════════════════════════════════════════
const KS_TONE = { cash:['payments','emerald'], card:['card','sky'], usd:['money','gold'], dealer:['truck','purple'], qobiljon:['wallet','amber'] };
function pgKassalar() {
  const el=document.getElementById('pg-kassalar');
  const debt = flDebtUsdEq(S.branch);
  // "Qobiljon kassasi" — faqat Admin (owner) va Kirim huquqiga ega xodimga ko'rinadi
  const canSeeQobiljon = !CURRENT_USER || CURRENT_USER.kind==='owner' || hasPerm('kirim.view');
  const visibleBoxes = S.cashboxes.filter(k => k.type!=='qobiljon' || canSeeQobiljon);
  const uzs = visibleBoxes.filter(k=>k.cur!=='USD').reduce((s,k)=>s+(+k.bal||0),0);
  const usd = visibleBoxes.filter(k=>k.cur==='USD').reduce((s,k)=>s+(+k.bal||0),0);
  const today = td();
  const tIn = (S.cashTxns||[]).filter(t=>t.date===today && t.type==='in').reduce((s,t)=>s+(t.cur==='USD'?(+t.amount||0):CUR.toUsd(+t.amount||0)),0);
  const tOut = (S.cashTxns||[]).filter(t=>t.date===today && t.type==='out').reduce((s,t)=>s+(t.cur==='USD'?(+t.amount||0):CUR.toUsd(+t.amount||0)),0);
  el.innerHTML=`
    ${fwHero({ tone:'emerald', label:'Kassalardagi jami pul', badge:`${visibleBoxes.length} ta kassa`, big: fwMoneyUsd(usd + CUR.toUsd(uzs)),
      cols:[[fwShortUzs(uzs),'Soʻm kassalar'],[fwMoneyUsd(usd),'Dollar kassalar','var(--gold)'],[`${tIn>=tOut?'+':'−'}${fwMoneyUsd(Math.abs(tIn-tOut)).replace('−','')}`,'Bugun (sof)', tIn>=tOut?'var(--emerald)':'var(--red)']],
      foot: S.branch!=='baza' && debt>0 ? `<button class="fw-hero-note" onclick="openPay729Baza()">${ICONF.warning}<span>Bazaga qarz: <b>${flDebtTxt(S.branch)}</b> — toʻlash</span>${ICONF.chevron}</button>` : '' })}
    ${typeof dpnBannerHtml === 'function' ? dpnBannerHtml() : ''}
    ${fwActs([
      ['swap','sky','Ayirboshlash','openExchange()'],
      ['kassaClose','emerald','Kassa yopish','openKunlikHisob()'],
      S.branch!=='baza' ? ['send','red','Bazaga toʻlov','openPay729Baza()'] : ['building','purple','Bosh kassa',"go('firmakassa')"],
      ['wallet','amber','Jami pul',"dashSheet('cash')"],
    ])}
    ${typeof fkBranchCardHtml === 'function' ? fkBranchCardHtml() : ''}
    <div class="ks-grid">
      ${visibleBoxes.map(k=>{ const [ic,c]=KS_TONE[k.type]||['wallet','sky']; return `
        <div class="ks-card" style="--c:var(--${c})">
          <div class="ks-card-h"><span class="ks-ic">${ICONF[ic]}</span><b>${esc(k.name)}</b><em>${esc(k.cur)}</em></div>
          <div class="ks-bal">${k.cur==='USD'?CUR.fmtUsd(k.bal):CUR.fmtUzs(k.bal)}</div>
          <div class="ks-acts">
            <button onclick="kassaOp(${k.id},'in')" class="in">${ICONF.download}<span>Kirim</span></button>
            <button onclick="kassaOp(${k.id},'out')" class="out">${ICONF.upload}<span>Chiqim</span></button>
            <button onclick="kassaOp(${k.id},'move')" title="Boshqa kassaga koʻchirish">${ICONF.swap}<span>Oʻtkaz</span></button>
          </div>
        </div>`; }).join('')}
    </div>
    <section class="ox-card" id="ks-moves">
      <div class="ox-card-h"><b>Pullar harakati</b><span class="ks-tabs">${['','in','out'].map(k=>`<button class="${(S.ksF||'')===k?'on':''}" onclick="S.ksF='${k}';ksMovesRender()">${{'':'Hammasi',in:'Kirim',out:'Chiqim'}[k]}</button>`).join('')}</span></div>
      <div id="ks-mv"></div>
    </section>`;
  ksMovesRender();
  if (typeof fkLoadBranchCard === 'function') fkLoadBranchCard();
}
function ksMovesRender() {
  const box = document.getElementById('ks-mv'); if (!box) return;
  document.querySelectorAll('.ks-tabs button').forEach((b,i)=>b.classList.toggle('on', ['','in','out'][i]===(S.ksF||'')));
  const list = (S.cashTxns||[]).filter(t=>!S.ksF || t.type===S.ksF).slice(0,80);
  let last = '';
  box.innerHTML = list.map(t=>{ const head = t.date!==last ? `<div class="ks-day">${t.date===td()?'Bugun':fmtD(t.date)}</div>` : ''; last = t.date;
    return `${head}<div class="ks-mv ${t.type==='in'?'in':'out'}"><span class="ks-mv-ic">${t.type==='in'?ICONF.download:ICONF.upload}</span>
      <span class="ks-mv-t"><b>${esc(t.desc||'—')}</b><small>${esc(t.boxName || (S.cashboxes.find(k=>k.id===t.boxId)||{}).name || '')}${t.ts?' · '+esc(new Date(t.ts).toLocaleTimeString('uz-UZ',{hour:'2-digit',minute:'2-digit'})):''}</small></span>
      <b class="ks-mv-v">${t.type==='in'?'+':'−'}${t.cur==='USD'?CUR.fmtUsd(t.amount):CUR.fmtUzs(t.amount)}</b></div>`; }).join('')
    || '<p class="bs-note">Hali harakat yoʻq — har savdo, kirim, xarajat va toʻlov shu yerda koʻrinadi.</p>';
}

// ════════════════════════════════════════════
// 729-FILIAL → BAZA: QARZ TO'LOVI
// ════════════════════════════════════════════
// v25 (43): qarz $ da va/yoki so'mda bo'lishi mumkin — qaysi qarz to'lanayotgani tanlanadi (_p729Cur)
let _p729Cur = 'USD';
function p729Debt() { const d = flDebt(S.branch); return _p729Cur === 'UZS' ? d.uzs : d.usd; }
function p729Fmt(v) { return _p729Cur === 'UZS' ? CUR.fmtUzs(v) : CUR.fmtUsd(v); }
// Kassa valyutasida taklif qilinadigan summa (qarz to'liq yopiladi)
function p729Suggest(box) {
  const d = p729Debt();
  if (_p729Cur === 'UZS') return box.cur === 'UZS' ? Math.round(d) : (Math.floor(CUR.toUsd(d) * 100) / 100).toFixed(2);
  return box.cur === 'USD' ? d.toFixed(2) : Math.round(CUR.toUzs(d));
}
function openPay729Baza(cur) {
  if (S.branch === 'baza') { toast('Bu amal faqat filialdan bajariladi!','error'); return; }
  const d = flDebt(S.branch);
  _p729Cur = cur === 'UZS' || cur === 'USD' ? cur : (d.uzs > 0 && (d.usd <= 0.004 || flDebtCur(S.branch) === 'UZS') ? 'UZS' : 'USD');
  const debt = p729Debt();
  if (debt<=0) { toast("Qarz yo'q!",'warning'); return; }
  // v11 (B7): dollar VA so'm kassalaridan to'lash mumkin (boshqa valyuta — serverdagi kurs bo'yicha qarzdan ayiriladi)
  const boxes = S.cashboxes.filter(k=>(k.cur==='USD' || k.cur==='UZS') && k.type!=='dealer');
  if (!boxes.length) { toast("Kassa topilmadi!",'error'); return; }
  const b0 = boxes.find(k=>k.cur===_p729Cur) || boxes[0];
  const both = d.usd > 0.004 && d.uzs > 0;
  modal(`
    <div class="modal-header"><div class="modal-title">💰 Bazaga to'lov</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${both ? `<div class="bs-seg" style="margin-bottom:10px"><button class="${_p729Cur === 'USD' ? 'on' : ''}" onclick="openPay729Baza('USD')">$ dagi qarz</button><button class="${_p729Cur === 'UZS' ? 'on' : ''}" onclick="openPay729Baza('UZS')">Soʻmdagi qarz</button></div>` : ''}
      <div style="font-size:12px;color:var(--text-muted);margin-bottom:12px">Joriy qarz: <b style="color:var(--red)">${p729Fmt(debt)}</b> · pul <b>Bosh kassaga</b> tushadi</div>
      <div class="form-group"><label class="form-label">Qaysi kassadan</label>
        <select class="form-control" id="p729-box" onchange="p729BoxChange()">${boxes.map(k=>`<option value="${k.id}" ${k.id===b0.id?'selected':''}>${k.icon} ${esc(k.name)} (${k.cur==='USD'?CUR.fmtUsd(k.bal):CUR.fmtUzs(k.bal)})</option>`).join('')}</select>
      </div>
      <div class="form-group" style="margin-bottom:0"><label class="form-label" id="p729-lbl">Summa (${b0.cur==='USD'?'$':"so'm"})</label><input class="form-control" id="p729-amt" type="number" step="0.01" value="${p729Suggest(b0)}"></div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" id="p729-btn" onclick="confirmPay729Baza()">💰 To'lash</button>
    </div>`);
}
function p729BoxChange() {
  const box = S.cashboxes.find(k=>k.id===parseInt(document.getElementById('p729-box')?.value));
  if (!box) return;
  const lbl = document.getElementById('p729-lbl'); if (lbl) lbl.textContent = `Summa (${box.cur==='USD'?'$':"so'm"})`;
  const inp = document.getElementById('p729-amt'); if (inp) inp.value = p729Suggest(box);
}

// v11 (B7): FILIAL KASSA → FIRMA KASSA (+ filial qarzi kamayadi) — BITTA server tranzaksiyasida.
// Avval: filial kassasidan ayirish, qarzni kamaytirish va Baza kassasiga qo'shish brauzerda
// bajarilardi; Baza kassasiga qo'shilgan pul HECH QACHON saqlanmasdi (faqat joriy filial
// saqlanadi) — pul "yo'qolardi"; tarmoq uzilsa yarim holat qolardi.
let _p729Idem = null, _p729Busy = false;
async function confirmPay729Baza() {
  if (S.branch === 'baza') { toast('Bu amal faqat filialdan bajariladi!','error'); return; }
  if (_p729Busy) return;
  const boxId = parseInt(document.getElementById('p729-box')?.value);
  const amt = Math.round(parseFloat(document.getElementById('p729-amt')?.value||0) * 100) / 100;
  if (!boxId || !(amt>0) || !isFinite(amt)) { toast("Ma'lumot to'liq emas!",'error'); return; }
  const box = S.cashboxes.find(k=>k.id===boxId);
  if (!box) { toast('Kassa topilmadi!','error'); return; }
  if (amt > (box.bal||0) + 0.005) { toast("Kassada yetarli mablag' yo'q!",'error'); return; }
  const debt = p729Debt(), uzsDebt = _p729Cur === 'UZS';
  const amtUsd = box.cur==='USD' ? amt : CUR.toUsd(amt);
  const amtIn = uzsDebt ? (box.cur === 'UZS' ? amt : Math.round(CUR.toUzs(amt) * 100) / 100) : amtUsd;   // qarz valyutasida
  if (amtIn > debt + (uzsDebt ? 1 : 0.01)) { toast(`⛔ To'lov (${p729Fmt(amtIn)}) qarzdan (${p729Fmt(debt)}) oshib ketdi`,'error'); return; }

  if (!_cloudEnabled) {
    // Oflayn/demo rejim (server yo'q): avvalgi mahalliy hisob
    try { await fwCashOps('branch_to_firma', [{boxId, dir:'out', amount:amt, desc:"Bazaga to'lov (filial qarzi)"}], { remote:false }); }
    catch(e) { toast('⛔ ' + e.message, 'error'); return; }
    const map = uzsDebt ? (S.branchDebtUzs = S.branchDebtUzs || {}) : (S.branchDebt = S.branchDebt || {});
    map[S.branch] = Math.max(0, Math.round(((map[S.branch]||0) - amtIn) * 100) / 100);
    auditLog(`💰 Bazaga to'lov: ${box.cur==='USD'?CUR.fmtUsd(amt):CUR.fmtUzs(amt)} (${branchName(S.branch)})`);
    save(); closeModal(); pgKassalar();
    toast(`✅ To'landi! Qolgan qarz: ${p729Fmt(map[S.branch])}`);
    return;
  }

  const payload = { action:'branch_pay', currency: box.cur, amount: amt, boxId, filial: S.branch, note: `${branchName(S.branch)} → Bazaga to'lov (filial qarzi${uzsDebt ? ', soʻmda' : ''})`, ...(uzsDebt ? { debtCur:'UZS' } : {}) };
  const sig = JSON.stringify(payload);
  if (!_p729Idem || _p729Idem.sig !== sig) _p729Idem = { sig, key: 'p729-' + uid() };
  payload.idemKey = _p729Idem.key;
  _p729Busy = true;
  const btn = document.getElementById('p729-btn'); if (btn) btn.disabled = true;
  try {
    let res, data;
    try {
      res = await authFetch('/.netlify/functions/firma-kassa', { method:'POST', body: JSON.stringify(payload) });
      data = await res.json().catch(()=>({}));
    } catch(e) { toast("⛔ Server bilan aloqa yo'q — qayta urinib ko'ring (to'lov ikki marta yozilmaydi)", 'error'); return; }
    if (!res.ok || !data.transfer) {
      if (res.status < 500 && res.status !== 409) _p729Idem = null;
      toast('⛔ ' + fwCashErr(data.error || "To'lov amalga oshmadi"), 'error'); return;
    }
    _p729Idem = null;
    const t = data.transfer;
    // Server natijasi — haqiqiy manba: filial kassasi qoldig'i va qolgan qarz
    fwApplyCashBalances({ [boxId]: +t.branchBalance });
    fwCashSeq++;
    if (!data.duplicate) logCashTxn({boxId, type:'out', amount:amt, desc:`Bazaga to'lov (filial qarzi) → Bosh kassa`});
    if (t.debtUzsAfter != null) { if (!S.branchDebtUzs) S.branchDebtUzs = {}; S.branchDebtUzs[S.branch] = +t.debtUzsAfter; }
    if (t.debtAfter != null && !uzsDebt) {
      if (!S.branchDebt) S.branchDebt = {};
      S.branchDebt[S.branch] = +t.debtAfter;
      if (S._syncBaseline && S._syncBaseline.branchDebt) S._syncBaseline.branchDebt[S.branch] = +t.debtAfter; // delta ikki marta qo'llanmasin
    }
    auditLog(`💰 Bazaga to'lov: ${box.cur==='USD'?CUR.fmtUsd(amt):CUR.fmtUzs(amt)} (${branchName(S.branch)}) → Bosh kassa`);
    save(); closeModal(); pgKassalar();
    toast(data.duplicate ? "✅ Bu to'lov avval bajarilgan edi (takror yozilmadi)" : `✅ To'landi! Qolgan qarz: ${p729Fmt(p729Debt())}`);
  } finally {
    _p729Busy = false;
    const b2 = document.getElementById('p729-btn'); if (b2) b2.disabled = false;
  }
}

function kassaOp(kid, type) {
  const k=S.cashboxes.find(x=>x.id===kid);if(!k)return;
  const lbl={in:'📥 Kirim',out:'📤 Chiqim',move:"🔄 Ko'chirish"}[type];
  const unit = k.cur==='USD'?'$':"so'm", bal = k.cur==='USD'?CUR.fmtUsd(k.bal||0):CUR.fmtUzs(k.bal||0);
  const tone = {in:'pos', out:'neg', move:''}[type];
  modal(`
    <div class="modal-header"><div class="modal-title">${lbl}</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${meCard({ name:k.name, sub:(k.cur==='USD'?'Dollar kassa':"So'm kassa"), kpi:bal, kpiLabel:'hozirgi qoldiq', tone })}
      ${meField('Summa', meAmt('ko-a', '', unit, '', 'placeholder="0" autofocus'), type!=='in'?`Kassada: ${bal}`:'')}
      ${type==='move'?meField('Qaysi kassaga', `<select class="form-control" id="ko-t">${S.cashboxes.filter(x=>x.id!==kid).map(x=>`<option value="${x.id}">${esc(x.icon||'')} ${esc(x.name)}</option>`).join('')}</select>`, 'Boshqa valyutadagi kassaga — joriy kurs bo\'yicha.'):''}
      ${meField('Izoh', `<input class="form-control" id="ko-d" placeholder="Sabab...">`)}
      ${meField('Kim bilan (ixtiyoriy)', `<select class="form-control" id="ko-who">
          <option value="">— Tanlash —</option>
          <optgroup label="Mijozlar">${S.customers.map(c=>`<option value="cust:${c.id}">🤝 ${esc(c.name)}</option>`).join('')}</optgroup>
          <optgroup label="Ta'minotchilar">${S.suppliers.map(s=>`<option value="supp:${s.id}">🏭 ${esc(s.name)}</option>`).join('')}</optgroup>
          <optgroup label="Dillerlar">${S.dealers.map(d=>`<option value="deal:${d.id}">🚚 ${esc(d.name)}</option>`).join('')}</optgroup>
        </select>`, '', ' style="margin-bottom:0"')}
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" onclick="doKassaOp(${kid},'${type}')">✅ Tasdiqlash</button>
    </div>`);
}

async function doKassaOp(kid, type) {
  const amt=parseFloat(document.getElementById('ko-a')?.value||0);
  const desc=document.getElementById('ko-d')?.value||'';
  const who=document.getElementById('ko-who')?.value||'';
  if(!(amt>0) || !isFinite(amt)){toast('Summa kiriting!','error');return;}
  const k=S.cashboxes.find(x=>x.id===kid);
  if(!k){toast('Kassa topilmadi!','error');return;}
  // v10 (B11/B6): chiqim/ko'chirish — kassa qoldig'idan oshmasin (avval server ishlamasa
  // ham amal bajarilib, qoldiq jimgina 0 ga "kesilardi", jurnalda esa to'liq summa qolardi)
  if ((type==='out' || type==='move') && amt > (k.bal||0) + 0.005) {
    toast(`⛔ "${k.name}"da yetarli mablag' yo'q: ${k.cur==='USD'?CUR.fmtUsd(k.bal||0):CUR.fmtUzs(k.bal||0)}`,'error'); return;
  }
  let moveTarget = null;
  if (type==='move') {
    const tid0=parseInt(document.getElementById('ko-t')?.value);
    moveTarget=S.cashboxes.find(x=>x.id===tid0);
    if(!moveTarget || moveTarget.id===k.id){toast('Qabul qiluvchi kassani tanlang!','error');return;}
  }

  // v23 fail-close: eski cashbox-transact yozuvi (faqat 24-migratsiyagacha) endi kassa
  // amalidan OLDIN, fwCashOps ichida chaqiriladi — server rad etsa yoki javob bermasa kassa
  // o'zgarmaydi (avval tarmoq xatosi "fail-open" bilan yutilardi). 24-migratsiyadan keyin
  // bu endpoint 410 (eskirgan) — amal faqat cashbox-ops orqali.
  const legacyOut = (_cloudEnabled && (type==='out' || type==='move'))
    ? () => fwLegacyPost('cashbox-transact', { boxId:kid, boxName:k.name, type:'out', amount:amt, desc, currentBal:k.bal||0, idemKey:uid(), filial:S.branch })
    : undefined;

  let whoName='';
  if(who){
    const [wt,wid]=who.split(':');
    if(wt==='cust') whoName=S.customers.find(x=>x.id==wid)?.name||'';
    else if(wt==='supp') whoName=S.suppliers.find(x=>x.id==wid)?.name||'';
    else if(wt==='deal') whoName=S.dealers.find(x=>x.id==wid)?.name||'';
  }
  const fullDesc = [desc, whoName].filter(Boolean).join(' — ') || (type==='in'?"Qo'lda kirim":"Qo'lda chiqim");
  // v11 (F4): qoldiq brauzerda hisoblanmaydi — amal serverda (kassa jurnali) bajariladi
  try {
    if (type==='in') await fwCashOps('manual_in', [{boxId:kid, dir:'in', amount:amt, desc:fullDesc}], { remote:_cloudEnabled });
    else if (type==='out') await fwCashOps('manual_out', [{boxId:kid, dir:'out', amount:amt, desc:fullDesc}], { remote:_cloudEnabled, legacy:legacyOut });
    else {
      const t=moveTarget;
      // v10 (B6): turli valyutadagi kassalar orasida ko'chirishda joriy kurs bo'yicha
      // konvertatsiya (avval so'm summasi dollar kassaga O'ZGARISHSIZ qo'shilardi)
      const tAmt = (k.cur===t.cur) ? amt : (k.cur==='USD' ? CUR.toUzs(amt) : CUR.toUsd(amt));
      const rateNote = (k.cur===t.cur) ? '' : ` (kurs ${CUR.usdUzs})`;
      await fwCashOps('move', [
        {boxId:kid, dir:'out', amount:amt, desc:`${fullDesc} → ${t.name}${rateNote}`},
        {boxId:t.id, dir:'in', amount:tAmt, desc:`${fullDesc} ← ${k.name}${rateNote}`},
      ], { remote:_cloudEnabled, rate: (k.cur===t.cur) ? undefined : CUR.usdUzs, legacy:legacyOut });
    }
  } catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  auditLog(`Kassa ${type}: ${k.name} — ${amt} — ${fullDesc}`);
  save();closeModal();pgKassalar();toast('✅ Amalga oshirildi!');
}

// ════════════════════════════════════════════
// FIRMA KASSASI — ASOSIY KASSA (v23.4): kunlik yopish, xarajat va ta'minotchi to'lovi shu kassa orqali
// ════════════════════════════════════════════
function fwFirmaAvailable() { return !!_cloudEnabled && hasPerm('firma_kassa.transact'); }
async function fwFirmaCall(payload) {
  let res, d;
  try { res = await authFetch('/.netlify/functions/firma-kassa', { method:'POST', body: JSON.stringify(payload) }); d = await res.json().catch(()=>({})); }
  catch (e) { const err = new Error("Server bilan aloqa yo'q — qayta urinib ko'ring (takror yozilmaydi)"); err.retry = true; throw err; }
  if (!res.ok || d.ok === false) { const err = new Error(fwCashErr(String(d.error || 'Bosh kassa amali bajarilmadi').replace(/^FIRMA_KASSA:\s*/, ''))); err.status = res.status; err.retry = res.status >= 500; throw err; }
  return d;
}
const FW_FIRMA_OPT = `<option value="firma">🏛 Bosh kassa (asosiy kassa)</option>`;

// ── KASSA YOPISH (kun yakuni) — v23.7 ──
// Filial savdo kassalaridagi pul ASOSIY kassaga — Bosh kassaga topshiriladi (pul tizimda qoladi, Bosh kassada ko'rinadi).
// • Shaxsiy kassa (type='qobiljon') bu ro'yxatda YO'Q; diller kassasi — faqat kassa huquqi bor xodimga (v23.8).
// • Sotuvchi ham yopa oladi (savdo.create) — faqat o'z filiali (server: firma-kassa daily_close).
// • Foyda/sof natija faqat egasi yoki hisobot huquqi bor xodimga ko'rinadi; boshqalarga — pul harakati.
function khCanClose() { return hasPerm('kassalar.transact') || hasPerm('savdo.create'); }
function khCanSeeProfit() { return !CURRENT_USER || CURRENT_USER.kind==='owner' || hasPerm('hisobot.view'); }
// v23.8: Diller kassasi (dillerlar yuborgan pul) — kun yakunida boshqa kassalar bilan Bosh kassaga; sotuvchiga emas (server ham rad etadi)
function khBoxes() { const kas = hasPerm('kassalar.transact'); return (S.cashboxes||[]).filter(k => k.type!=='qobiljon' && (k.type!=='dealer' || kas)); }
function khFmt(cur, n) { return cur==='USD' ? CUR.fmtUsd(n) : CUR.fmtUzs(n); }
function todaySummary() {
  const today = td();
  const sales = S.sales.filter(s=>s.date===today && s.status!=='cancelled');
  const sumF = (a, f) => a.reduce((t, x) => t + (+x[f] || 0), 0);
  const totalRevenue = sumF(sales, 'totalUsd');
  const totalProfit = sumF(sales, 'profitUsd');
  const totalDebt = sumF(sales, 'debtUsd');
  const pay = { cash:0, card:0, usd:0, mixed:0 };
  sales.forEach(x => { const k = x.payType==='cash_uzs' ? 'cash' : x.payType; if (k in pay) pay[k] += (+x.paidUsd || 0); });
  const expenses = S.expenses.filter(e=>e.date===today && (e.turi||'dokon')==='dokon');
  const totalExpense = sumF(expenses, 'amtUsd');
  // Bugun undirilgan mijoz qarzi — kassaga mijoz nomidan tushgan pul (savdo tushumidan tashqari)
  const debtIn = (S.cashTxns||[]).filter(t => t.date===today && t.type==='in' && t.custId != null && !/^Savdo /.test(t.desc||''))
    .reduce((t, x) => t + (x.cur==='USD' ? (+x.amount||0) : CUR.toUsd(+x.amount||0)), 0);
  const writeoff = typeof fwWriteoffLoss==='function' ? fwWriteoffLoss(today, today) : 0;
  return { today, salesCount: sales.length, totalRevenue, totalProfit, totalDebt, totalExpense, writeoff, pay, debtIn,
    expenseCount: expenses.length, netUsd: totalProfit-totalExpense-writeoff };
}
function khBoxToday(k, today) {
  const t = (S.cashTxns||[]).filter(x => x.date===today && String(x.boxId)===String(k.id));
  return { inn: t.filter(x=>x.type==='in').reduce((a,x)=>a+(+x.amount||0),0), out: t.filter(x=>x.type==='out').reduce((a,x)=>a+(+x.amount||0),0) };
}
function khLeft(id) {
  const k = khBoxes().find(b => String(b.id)===String(id)); const el = document.getElementById('kh-left-'+id); if (!k || !el) return;
  const v = parseFloat(document.getElementById('kh-amt-'+id)?.value) || 0;
  el.textContent = v > 0 ? `Kassada qoladi: ${khFmt(k.cur, Math.max(0, (k.bal||0) - v))}` : '';
  el.classList.toggle('bad', v > (k.bal||0) + 0.005);
}
function khAll(id) {
  const k = khBoxes().find(b => String(b.id)===String(id)); const el = document.getElementById('kh-amt-'+id); if (!k || !el) return;
  el.value = k.cur==='USD' ? Math.round((k.bal||0)*100)/100 : Math.round(k.bal||0); el.dispatchEvent(new Event('input')); khLeft(id);
}

function openKunlikHisob() {
  // RBAC: kassa xodimi (kassalar.transact) yoki sotuvchi (savdo.create). Server ham shuni tekshiradi.
  if (!khCanClose()) { toast("⛔ Bu amal uchun ruxsatingiz yo'q — kassa yoki savdo huquqi kerak", 'error'); return; }
  const sum = todaySummary(), today = sum.today, boxes = khBoxes(), seeProfit = khCanSeeProfit();
  const closedToday = fwClosingsSorted(S.dailyClosings).filter(c => c.date===today);
  const brName = branchName(S.branch);
  const kpi = (l, v, tone='', sub='') => `<div class="kh-k ${tone}"><small>${l}</small><b>${v}</b>${sub?`<i>${sub}</i>`:''}</div>`;
  const paySub = [sum.pay.cash>0?`naqd ${CUR.fmtUsd(sum.pay.cash)}`:'', sum.pay.card>0?`karta ${CUR.fmtUsd(sum.pay.card)}`:'', sum.pay.usd>0?`$ ${CUR.fmtUsd(sum.pay.usd)}`:'', sum.pay.mixed>0?`aralash ${CUR.fmtUsd(sum.pay.mixed)}`:''].filter(Boolean).join(' · ');
  modal(`
    <div class="modal-header"><div class="modal-title"><span class="kh-ti">${ICONF.kassaClose}</span>Kassa yopish — ${fmtD(today)}</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div class="kh-to">${ICONF.building}<div><b>Pul asosiy kassaga — Bosh kassaga topshiriladi</b><small>${esc(brName)} savdo kassalaridan · pul tizimda qoladi va Bosh kassada koʻrinadi</small></div></div>
      ${closedToday.length ? `<div class="kh-note-ok">Bugun ${closedToday.length} marta yopilgan — oxirgisi: ${esc(closedToday[0].performedBy||'—')}</div>` : ''}
      ${meSec('Bugungi kun')}
      <div class="kh-kpis">
        ${kpi('Savdolar', sum.salesCount, 'sky', 'ta chek')}
        ${kpi('Tushum', CUR.fmtUsd(sum.totalRevenue), 'gold', paySub)}
        ${kpi('Qarzga sotildi', CUR.fmtUsd(sum.totalDebt), sum.totalDebt>0?'red':'')}
        ${kpi('Qarz undirildi', CUR.fmtUsd(sum.debtIn), sum.debtIn>0?'emerald':'')}
        ${kpi('Xarajat', '−'+CUR.fmtUsd(sum.totalExpense), sum.totalExpense>0?'red':'', sum.expenseCount?`${sum.expenseCount} ta`:'')}
        ${seeProfit ? kpi('Sof natija', (sum.netUsd>=0?'+':'')+CUR.fmtUsd(sum.netUsd), sum.netUsd>=0?'emerald':'red', `foyda ${CUR.fmtUsd(sum.totalProfit)}${sum.writeoff>0?` · hisobdan chiqarish −${CUR.fmtUsd(sum.writeoff)}`:''}`) : ''}
      </div>
      ${meSec('Kassalar — qancha topshiriladi')}
      ${boxes.length ? boxes.map(k => { const t = khBoxToday(k, today); return `
        <div class="kh-box">
          <div class="kh-box-h"><b>${esc(k.icon||'')} ${esc(k.name)}</b><span>${khFmt(k.cur, k.bal||0)}</span></div>
          <div class="kh-box-m"><span class="in">+${khFmt(k.cur, t.inn)}</span><span class="out">−${khFmt(k.cur, t.out)}</span><span>bugun</span></div>
          <div class="kh-box-r">${meAmt('kh-amt-'+k.id, '', k.cur==='USD'?'$':"so'm", '', `placeholder="0" oninput="khLeft('${k.id}')"`)}
            <button type="button" class="btn btn-ghost btn-sm" onclick="khAll('${k.id}')" ${(k.bal||0)>0?'':'disabled'}>Hammasi</button></div>
          <div class="kh-left" id="kh-left-${k.id}"></div>
        </div>`; }).join('') : `<div class="kh-empty">Bu filialda savdo kassasi yoʻq</div>`}
      <div class="me-hint">Boʻsh qoldirilgan kassadan pul olinmaydi — kassada qolib, ertaga savdo davom etadi.${_cloudEnabled?'':'<br>⚠️ Oflayn rejim: Bosh kassa serverda — internet boʻlganda bajaring.'}</div>
      ${meField('Izoh (ixtiyoriy)', `<input class="form-control" id="kh-note" maxlength="300" placeholder="Masalan: kun yakuni, smena topshirildi">`)}
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost btn-sm" onclick="openKunlikHisobTarixi()">Tarix</button>
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-primary" id="kh-btn" onclick="doKunlikHisob()" ${boxes.length?'':'disabled'}>Bosh kassaga topshirish</button>
    </div>`);
}

async function doKunlikHisob() {
  // RBAC — ikkinchi qatlam (konsoldan to'g'ridan-to'g'ri chaqirishga qarshi); asosiy tekshiruv — serverda
  if (!khCanClose()) { toast("⛔ Bu amal uchun ruxsatingiz yo'q", 'error'); return; }
  const boxes = khBoxes();
  const entries = [];
  const noteRaw = (document.getElementById('kh-note')?.value||'').trim().slice(0, 300);
  let over = null;
  boxes.forEach(k=>{
    const amt = parseFloat(document.getElementById(`kh-amt-${k.id}`)?.value||0);
    if (!(amt>0) || !isFinite(amt)) return;
    // v23: qoldiqdan ortiq summa jimgina qisqartirilmaydi — aniq rad etiladi
    if (amt > (k.bal||0) + 0.005) over = over || k;
    entries.push({ boxId:k.id, boxName:k.name, boxIcon:k.icon, cur:k.cur, amount:Math.round(amt*100)/100, currentBal:k.bal });
  });
  if (over) { toast(`⛔ "${over.name}"da yetarli mablag' yo'q`,'error'); return; }
  if (!entries.length) { toast("Kamida bitta kassadan summa kiriting!",'error'); return; }

  const desc = noteRaw ? `🏛 Kassa yopish → Bosh kassa — ${noteRaw}` : '🏛 Kassa yopish → Bosh kassa';
  if (!_cloudEnabled) { toast("⛔ Bosh kassa serverda — internetga ulaning va qayta urinib ko'ring", 'error'); return; }

  // v23.4: har bir kassa → Bosh kassa (filial kassasi va Bosh kassa BITTA server tranzaksiyasida).
  // Kalitlar barqaror: tarmoq uzilsa, qayta bosish allaqachon o'tgan kassalarni takror yozmaydi.
  const sig = JSON.stringify([S.branch, entries.map(e=>[e.boxId, e.amount])]);
  if (!S._khPend || S._khPend.sig !== sig) S._khPend = { sig, id: 'dc' + uid(), done: {} };
  const pend = S._khPend;
  const btn = document.getElementById('kh-btn'); if (btn) btn.disabled = true;
  try {
    for (const e of entries) {
      if (pend.done[e.boxId]) continue;
      let d;
      try { d = await fwFirmaCall({ action:'daily_close', currency:e.cur, amount:e.amount, boxId:e.boxId, filial:S.branch, note: noteRaw || null, idemKey:`${pend.id}-${e.boxId}` }); }
      catch (err) {
        const n = Object.keys(pend.done).length;
        toast(`⛔ ${e.boxName}: ${err.message}${n ? ` (${n} ta kassa allaqachon topshirildi — qayta bosing, takror yozilmaydi)` : ''}`, 'error');
        if (!err.retry && !n) S._khPend = null;
        if (n) { save(); pgKassalar(); }
        return;
      }
      pend.done[e.boxId] = true;
      if (d.transfer && d.transfer.branchBalance != null) { fwApplyCashBalances({ [e.boxId]: +d.transfer.branchBalance }); fwCashSeq++; }
      if (!d.duplicate) logCashTxn({ boxId:e.boxId, type:'out', amount:e.amount, desc });
    }
  } finally { const b2 = document.getElementById('kh-btn'); if (b2) b2.disabled = false; }
  S._khPend = null;

  const sum = todaySummary();
  S.dailyClosings = S.dailyClosings || [];
  // "Kim bajargani" — staffId (xodim) yoki "owner"; ism — o'qish uchun
  S.dailyClosings.unshift({
    id:uid(), date:sum.today, ts:new Date().toISOString(), entries, salesCount:sum.salesCount, totalRevenue:sum.totalRevenue,
    totalProfit:sum.totalProfit, totalExpense:sum.totalExpense, totalDebt:sum.totalDebt, debtIn:sum.debtIn,
    note: noteRaw || null, toFirma: true,
    performedBy: CURRENT_USER?.name || 'Admin',
    performedByStaffId: (CURRENT_USER?.kind==='staff' ? CURRENT_USER.staffId : null),
    performedByKind: CURRENT_USER?.kind || 'owner'
  });

  auditLog(`Kassa yopildi (${fmtD(sum.today)}) — Bosh kassaga: ${entries.map(e=>khFmt(e.cur, e.amount)).join(', ')}${noteRaw?` — izoh: ${noteRaw}`:''}`);
  save(); closeModal(); pgKassalar();
  if (typeof FK !== 'undefined') FK.loaded = false;   // Bosh kassa sahifasi keyingi ochilishda yangilanadi
  if (typeof DS !== 'undefined' && DS) DS.fk = null;  // bosh sahifadagi «Biznes holati» Bosh kassani qayta oladi
  toast('✅ Kassa yopildi — pul Bosh kassaga topshirildi');
}

function openKunlikHisobTarixi() {
  const list = fwClosingsSorted(S.dailyClosings), seeProfit = khCanSeeProfit();
  modal(`
    <div class="modal-header"><div class="modal-title"><span class="kh-ti">${ICONF.kassaClose}</span>Kassa yopish tarixi</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      ${list.length ? list.slice(0, 60).map(c=>`<div class="kh-h">
        <div class="kh-h-t"><b>${fmtD(c.date)}${c.ts?` · ${esc(new Date(c.ts).toTimeString().slice(0,5))}`:''}</b><span>${c.entries.map(e=>khFmt(e.cur, e.amount)).join(' + ')}</span></div>
        <div class="kh-h-s">${esc(c.performedBy||'—')} · ${c.salesCount||0} ta savdo · tushum ${CUR.fmtUsd(c.totalRevenue||0)}${seeProfit && c.totalProfit!=null?` · foyda ${CUR.fmtUsd(c.totalProfit)}`:''} · ${c.toFirma?'→ Bosh kassa':'→ tizimdan chiqarilgan (eski tartib)'}</div>
        ${c.note?`<div class="kh-h-s">Izoh: ${esc(c.note)}</div>`:''}
      </div>`).join('') : '<div class="kh-empty">Hali kassa yopilmagan</div>'}
    </div>
    <div class="modal-footer"><button class="btn btn-ghost" onclick="openKunlikHisob()">Orqaga</button><button class="btn btn-ghost" onclick="closeModal()">Yopish</button></div>`);
}

function openExchange() {
  if (!hasPerm('kassalar.transact')) { toast("Ayirboshlash uchun kassa huquqi kerak", 'error'); return; }
  const usdBox=S.cashboxes.find(k=>k.cur==='USD');
  modal(`
    <div class="modal-header"><div class="modal-title">💱 Kun yakunida ayirboshlash</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div style="background:linear-gradient(135deg,rgba(245,166,35,0.1),rgba(59,130,246,0.05));
        border:1px solid rgba(245,166,35,0.2);border-radius:var(--radius-sm);padding:12px;margin-bottom:14px">
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <span style="font-size:12px;color:var(--text-muted)">1$ =</span>
          <input type="number" id="ex-rate" value="${CUR.usdUzs}" class="form-control"
            style="width:100px;margin:0;padding:7px 10px;font-weight:700" oninput="exCalc()">
          <span style="font-size:12px;color:var(--text-muted)">UZS</span>
        </div>
      </div>
      ${S.cashboxes.filter(k=>k.cur==='UZS').map(k=>`
        <div style="background:var(--bg-secondary);border:1px solid var(--border);border-radius:var(--radius-sm);padding:12px;margin-bottom:10px">
          <div style="display:flex;justify-content:space-between;margin-bottom:8px">
            <span style="font-weight:600">${k.icon} ${esc(k.name)}</span>
            <span style="color:var(--gold);font-weight:700">${CUR.fmtUzs(k.bal)}</span>
          </div>
          <div style="display:flex;gap:8px;align-items:center">
            <input type="number" id="ex-uzs-${k.id}" placeholder="UZS summa"
              class="form-control" style="margin:0;flex:1" oninput="exCalcFor(${k.id})">
            <span style="color:var(--text-muted)">→</span>
            <div class="form-control" id="ex-usd-${k.id}" style="background:var(--bg-card);width:110px;color:var(--emerald);font-weight:700;cursor:default">$0.00</div>
          </div>
        </div>`).join('')}
      <div style="background:rgba(16,185,129,0.08);border:1px solid rgba(16,185,129,0.25);border-radius:var(--radius-sm);padding:12px;margin-top:10px">
        <div style="font-size:11px;color:var(--text-muted)">Dollar kassa joriy holati</div>
        <div style="font-size:20px;font-weight:800;color:var(--emerald)">${CUR.fmtUsd(usdBox?.bal||0)}</div>
      </div>
    </div>
    <div class="modal-footer">
      <button class="btn btn-ghost" onclick="closeModal()">Bekor</button>
      <button class="btn btn-success" onclick="doExchange()">✅ Ayirboshlash</button>
    </div>`);
}

function exCalcFor(kid) {
  const rate=parseFloat(document.getElementById('ex-rate')?.value||CUR.usdUzs);
  const uzs=parseFloat(document.getElementById(`ex-uzs-${kid}`)?.value||0);
  const el=document.getElementById(`ex-usd-${kid}`);
  if(el) el.textContent=CUR.fmtUsd(uzs/rate);
}

function exCalc() {
  S.cashboxes.filter(k=>k.cur==='UZS').forEach(k=>exCalcFor(k.id));
}

async function doExchange() {
  const rate=parseFloat(document.getElementById('ex-rate')?.value||CUR.usdUzs);
  // v10 (B15): kurs tekshiriladi (0/manfiy kurs cheksiz dollar yaratardi)
  if(!(rate>0) || !isFinite(rate)){toast("Kurs noto'g'ri!",'error');return;}
  const usdBox=S.cashboxes.find(k=>k.cur==='USD' && k.type==='usd') || S.cashboxes.find(k=>k.cur==='USD');
  if(!usdBox){toast('Dollar kassa topilmadi!','error');return;}
  // v10 (B15): AVVAL hamma qatorlar tekshiriladi, keyin bajariladi — avval bitta kassada
  // mablag' yetmasa ham boshqalari yechilib, amal yarim bajarilib qolardi
  const plan=[];
  for (const k of S.cashboxes.filter(k=>k.cur==='UZS')) {
    const uzs=parseFloat(document.getElementById(`ex-uzs-${k.id}`)?.value||0);
    if(!(uzs>0)) continue;
    if(!isFinite(uzs) || uzs>(k.bal||0)+0.5){toast(`${k.name}da yetarli mablag' yo'q!`,'error');return;}
    plan.push({k,uzs});
  }
  if(!plan.length){toast('Summa kiriting!','error');return;}
  const totalUsd = Math.round(plan.reduce((t,{uzs})=>t+uzs/rate,0) * 100) / 100;
  // v11 (F4): so'm kassalaridan chiqim + dollar kassaga kirim — serverda BITTA amal
  // (server kursni o'z kursidan ±25% chegarasida tekshiradi, qiymat yaratilmaydi)
  try {
    await fwCashOps('exchange', [
      ...plan.map(({k,uzs})=>({boxId:k.id, dir:'out', amount:uzs, desc:`Ayirboshlash → $`})),
      {boxId:usdBox.id, dir:'in', amount:totalUsd, desc:`Ayirboshlash natijasi`},
    ], { remote:_cloudEnabled, rate });
  } catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  CUR.usdUzs=rate; CUR.save();
  syncRateToSettings();
  auditLog(`Ayirboshlash: +${CUR.fmtUsd(totalUsd)} | kurs: ${rate.toLocaleString('en-US').replace(/,/g,' ')}`);
  save();closeModal();pgKassalar();
  toast(`✅ +${CUR.fmtUsd(totalUsd)} dollar kassaga qo'shildi!`);
}

