  const meta = XAR_TAB_META[tab];
  const listAll = S.expenses.filter(e=>(e.turi||'dokon')===tab);
  const total = listAll.reduce((s,e)=>s+(e.amtUsd||CUR.toUsd(e.amount||0)),0);
  const totalOut = tab==='hamkor' ? listAll.filter(e=>e.kind!=='kirim').reduce((s,e)=>s+(e.amtUsd||CUR.toUsd(e.amount||0)),0) : total;
  const totalIn = tab==='hamkor' ? listAll.filter(e=>e.kind==='kirim').reduce((s,e)=>s+(e.amtUsd||CUR.toUsd(e.amount||0)),0) : 0;
