  const catTop = {}; listAll.filter(e=>String(e.date||'').slice(0,7)===month && e.kind!=='kirim').forEach(e=>{ const k=fwExpCatLabel(e)||'—'; catTop[k]=(catTop[k]||0)+(e.amtUsd||CUR.toUsd(e.amount||0)); });
