// ── XARAJATNI O'CHIRISH/TAHRIRLASH — faqat admin panelida mavjud (sotuvchi/diller portalida yo'q) ──
// v11 (F4): kassa qismi alohida — avval SERVERDA bajariladi (fwCashOps), keyin qolgan ta'sir
function _reverseExpenseCashOp(e) {
  // "Kirim" (hamkor puli qo'shish) — teskari ta'sir; boshqa barchasi (chiqim) — asl xulq
  const isKirim = e.turi==='hamkor' && e.kind==='kirim';
  const box = S.cashboxes.find(k=>k.id===e.boxId);
  if (!box || !((e.amtUsd||0) > 0)) return null;
  const amt = box.cur==='USD' ? (e.amtUsd||0) : CUR.toUzs(e.amtUsd||0);
  return isKirim ? {boxId:box.id, dir:'out', amount:amt, desc:`↩️ Hamkor kirimi bekor qilindi: ${e.person||''}`}
                 : {boxId:box.id, dir:'in', amount:amt, desc:`↩️ Xarajat bekor qilindi: ${e.cat}`};
}
function _reverseExpenseEffect(e) {
  const isKirim = e.turi==='hamkor' && e.kind==='kirim';
  // Hamkor yozuvi bo'lsa — uning hisobiga (invested) teskari ta'sir
  if (e.turi==='hamkor' && e.partnerId) {
    const partner = brPartner(e.partnerId);
    if (partner) { partner.invested = (partner.invested||0) + (isKirim ? -(e.amtUsd||0) : (e.amtUsd||0)); partner.updatedAt = Date.now(); }
  }
}

async function deleteExpenseRow(id) {
  const e = S.expenses.find(x=>x.id===id); if (!e) return;
  // v24.4: zaklad xizmati — kassa zaklad bilan birga serverda o'zgargan; alohida o'chirilmaydi
  if (e.locked || e.sysType === 'transfer_fee') { toast("⛔ Bu xarajat taʼminotchi zakladi bilan bogʻliq — alohida oʻchirilmaydi", 'error'); return; }
  let warn = '';
  if (e.turi==='tasischi' && e.salaryPersonId) warn = "\n\n⚠️ Bu — oylik to'lovi yozuvi edi. O'chirilgach, xodimning qarz summasini qo'lda tekshirib qo'ying.";
  if (e.turi==='hamkor' && e.kind==='kirim') warn = "\n\n⚠️ Bu — hamkor kirimi (pul qo'shish) yozuvi edi. O'chirilgach, hamkor hisobidan va kassadan shu summa ayiriladi.";
  if (!confirm(`Ushbu ${e.turi==='hamkor'&&e.kind==='kirim'?'kirimni':'xarajatni'} o'chirasizmi?\n${e.cat} — ${CUR.fmtUsd(e.amtUsd||0)}${warn}`)) return;
  if (e.source === 'firma_kassa' && e.fkEntryId) {
    // v23.4: Bosh kassadan to'langan xarajat — Bosh kassada teskari yozuv (serverda); rad etilsa o'chirilmaydi
    try { await fwFirmaCall({ action:'expense_reverse', entryId:+e.fkEntryId, idemKey:'exr' + e.id, note:`Xarajat o'chirildi: ${e.cat}` }); }
    catch(err) { toast('⛔ ' + err.message, 'error'); return; }
  } else {
    const revOp = _reverseExpenseCashOp(e);
    if (revOp) {
      try { await fwCashOps('expense_fix', [revOp], { remote:_cloudEnabled, refType:'expense', refId:e.id }); }
      catch(err) { toast('⛔ ' + err.message, 'error'); return; }
    }
  }
  _reverseExpenseEffect(e);
  S.expenses = S.expenses.filter(x=>x.id!==id);
  markDeleted('expenses', id);
  auditLog(`Xarajat o'chirildi: ${e.cat} — ${CUR.fmtUsd(e.amtUsd||0)}`);
  save(); pgXarajatlar();
  toast("✅ Xarajat o'chirildi, kassa summasi qaytarildi!");
}

