function openGiveSalary(id) {
  const p = (S.salaryPeople||[]).find(x=>x.id===id); if (!p) return;
  const debtNative = p.cur==='USD' ? (p.debtUsd||0) : CUR.toUzs(p.debtUsd||0);
  const fmt = p.cur==='USD' ? CUR.fmtUsd : CUR.fmtUzs;
  modal(`
    <div class="modal-header"><div class="modal-title">💰 ${esc(p.name)} — to'lov berish</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div style="font-size:12px;color:var(--text-muted);margin-bottom:10px">Belgilangan: <strong>${fmt(p.amount)}</strong>${(p.debtUsd||0)>0.01?` · Joriy qarzi: <strong style="color:var(--red)">${fmt(debtNative)}</strong>`:''}</div>
      <div class="form-group"><label class="form-label">Berilayotgan summa (${p.cur==='USD'?'$':"so'm"})</label><input class="form-control" id="gs-amt" type="text" inputmode="decimal" value="${p.amount}" oninput="liveFormatSpaces(this)"></div>
      <div class="form-group"><label class="form-label">Kassa</label><select class="form-control" id="gs-box">${S.cashboxes.map(k=>`<option value="${k.id}">${k.icon} ${esc(k.name)}</option>`).join('')}</select></div>
      <div style="font-size:11px;color:var(--text-muted)">Agar belgilangandan ko'p bersangiz — ortiqcha qism avtomatik qarzga yoziladi. Kam bersangiz — qarzi shuncha kamayadi.</div>
    </div>
    <div class="modal-footer"><button class="btn btn-ghost" onclick="closeModal()">Bekor</button><button class="btn btn-primary" onclick="giveSalary(${id})">✅ Berish</button></div>`);
}
async function giveSalary(id) {
  const p = (S.salaryPeople||[]).find(x=>x.id===id); if (!p) return;
  const given = parseAmt(document.getElementById('gs-amt')?.value);
  const bid = parseInt(document.getElementById('gs-box')?.value||1);
  if (given<=0) { toast('Summa kiriting!','error'); return; }

  const givenUsd = p.cur==='USD' ? given : CUR.toUsd(given);
  const baseUsd = p.cur==='USD' ? p.amount : CUR.toUsd(p.amount);
  const diffUsd = givenUsd - baseUsd;
  const sysType = fwSalarySysType(p.name), cat = FW_SYS_EXPENSE[sysType];   // tizim yozuvi (tanlanadigan kategoriya emas)

  // v11 (F4): kassadan chiqim — avval serverda (rad etilsa oylik yozilmaydi)
  const box=S.cashboxes.find(k=>k.id===bid);
  if (!box) { toast('⛔ Kassa tanlang','error'); return; }   // kassasiz pul yozuvi bo'lmaydi
  {
    const amt = box.cur==='USD'?givenUsd:CUR.toUzs(givenUsd);
    try { await fwCashOps('salary', [{boxId:box.id, dir:'out', amount:amt, desc:`${cat}: ${p.name}`}], { remote:_cloudEnabled, refType:'salary', refId:p.id }); }
    catch(e) { toast('⛔ ' + e.message, 'error'); return; }
  }
  p.debtUsd = (p.debtUsd||0) + diffUsd;

  S.expenses.push({ id:uid(), date:td(), cat, sysType, amtUsd:givenUsd, amount:given, cur:p.cur, desc:`${cat}: ${p.name}`, person:p.name, boxId:bid, turi:'tasischi', salaryPersonId:p.id, rate: p.cur==='UZS' ? CUR.usdUzs : null });

  auditLog(`${cat} berildi: ${p.name} — ${CUR.fmtUsd(givenUsd)}${diffUsd>0.01?` (ortiqcha ${CUR.fmtUsd(diffUsd)} qarzga yozildi)`:''}`);

  closeModal(); save(); pgXarajatlar();
  toast(diffUsd>0.01 ? `✅ Berildi! ${CUR.fmtUsd(diffUsd)} qarzga yozildi.` : '✅ To\'lov berildi!');
}

