// Mahsulotlar — rasm bilan Excel (chop etish o'rniga)
async function exportProductsWithImages() {
  toast('⏳ Excel (rasm+QR bilan) tayyorlanmoqda...','warning');
  // QR kodi yo'q mahsulotlarga avval yaratib qo'yamiz
  const missingQr = S.products.filter(p=>!p.qrCode && p.sku);
  if (missingQr.length) { for (const p of missingQr) { await genProductQR(p.id); } save(); }

  const wb = new ExcelJS.Workbook();
  const ws = wb.addWorksheet('Mahsulotlar');
  ws.columns = [
    {header:'Rasm', key:'img', width:13},
    {header:'QR kod', key:'qr', width:13},
    {header:'Kod', key:'sku', width:14},
    {header:'Nomi', key:'name', width:36},
    {header:'Kategoriya', key:'cat', width:16},
    {header:'Qoldiq', key:'stock', width:9},
    {header:"Tannarx ($)", key:'cost', width:12},
    {header:"Sotish ($)", key:'sell', width:12},
    {header:'Holat', key:'status', width:10},
  ];
  const head = ws.getRow(1);
  head.font = { bold:true, color:{argb:'FF1C2433'} };
  head.height = 22;
  head.eachCell(c=>{ c.fill = {type:'pattern',pattern:'solid',fgColor:{argb:'FFEFF1F5'}}; });

  for (let i=0;i<S.products.length;i++) {
    const p = S.products[i];
    const st = getStock(p.id), cost = getCostFIFO(p.id), sell = sellPrice(p, cost);
    const rowIdx = i+2;
    ws.addRow({
      sku:p.sku, name:p.name, cat:p.cat, stock:st,
      cost:Number(cost.toFixed(2)), sell:Number(sell.toFixed(2)),
      status: st===0?'Tugagan':st<=p.minStock?'Kam':'OK'
    });
    ws.getRow(rowIdx).height = 58;
    if (p.image) {
      try {
        const parts = await imageToBase64Parts(p.image);
        if (parts) {
          const imgId = wb.addImage({ base64:parts.base64, extension:parts.ext });
          ws.addImage(imgId, { tl:{col:0.12, row:rowIdx-1+0.08}, ext:{width:58,height:54} });
        }
      } catch(e) { /* rasm xato bo'lsa o'tkazib yuboramiz */ }
    }
    if (p.qrCode) {
      try {
        const base64 = p.qrCode.split(',')[1];
        const imgId = wb.addImage({ base64, extension:'png' });
        ws.addImage(imgId, { tl:{col:1.12, row:rowIdx-1+0.08}, ext:{width:54,height:54} });
      } catch(e) { /* QR xato bo'lsa o'tkazib yuboramiz */ }
    }
  }

  await fwXlSave(wb, `mahsulotlar_rasm_${td()}.xlsx`);
  toast('✅ Excel (rasm bilan) tayyor!');
}

// ════════════════════════════════════════════
// YAGONA SHABLON — mahsulot ham, kirim ham shu bitta fayl orqali
// ════════════════════════════════════════════
// v24.5 (v23.10.2 dan): shablon bitta — Kirim «Shablon» tugmasi va «Excel orqali bosh qoldiq» oynasidagi
// «Shablonni yuklab olish» — ikkalasi shu faylni beradi (avval ikki xil fayl edi: «Shablon» va «Mahsulotlar»).
// Namuna qatori SKU «NAMUNA-…» bilan belgilangan va import qilinmaydi (avval «115 / 70 dona / 15.10»
// haqiqiy qatordek yozilgan edi — o'chirilmasa omborga 70 dona tushardi).
// v24.5: Excel katagi — ExcelJS formula / rich text / havola obyektlarini oddiy qiymatga
// (avval String(obj) → «[object Object]», parseInt(formula) → 0 bo'lib, kirim jimgina tushib qolardi)
function xlVal(v) {
  if (v == null) return '';
  if (v instanceof Date) return v;
  if (typeof v === 'object') {
    if ('result' in v) return xlVal(v.result);                                   // formula
    if (Array.isArray(v.richText)) return v.richText.map(t => (t && t.text) || '').join('');
    if ('text' in v) return xlVal(v.text);                                       // havola
    return '';                                                                   // xato (#N/A va h.k.)
  }
  return v;
}
function xlText(v) { const x = xlVal(v); return x instanceof Date ? x.toISOString().slice(0,10) : String(x).trim(); }
// Son: 15.10 · 15,10 · 1 000 · 1 000,5 · 1,000.50 · $15. Bo'sh — 0, son emas — NaN (jimgina 0 EMAS — qator xatosi).
function xlNum(v) {
  const x = xlVal(v);
  if (typeof x === 'number') return Number.isFinite(x) ? x : NaN;
  if (x instanceof Date) return NaN;
  let t = String(x).replace(/[\s  '’$¥]/g, '');
  if (!t) return 0;
  if (t.includes(',') && t.includes('.')) t = t.replace(/,/g, '');
  else if (/^-?\d{1,3}(,\d{3}){2,}$/.test(t)) t = t.replace(/,/g, '');
  else t = t.replace(',', '.');
  return /^-?\d+(\.\d+)?$/.test(t) ? Number(t) : NaN;
}
function xlShowErrors(errs) {
  modal(`<div class="modal-header"><div class="modal-title">⚠️ Import qilinmadi — faylda ${errs.length} ta xato</div><button class="modal-close" onclick="closeModal()">×</button></div>
    <div class="modal-body"><div style="font-size:13px;margin-bottom:8px">Hech narsa yozilmadi (ombor va mahsulotlar o'zgarmadi). Xatolarni tuzatib, faylni qayta yuklang:</div>
    <div style="max-height:320px;overflow:auto;font-size:12.5px;line-height:1.6;background:var(--bg-secondary);border-radius:10px;padding:10px 12px">${errs.slice(0,100).map(e=>`• ${esc(e)}`).join('<br>')}${errs.length>100?`<br>… va yana ${errs.length-100} ta`:''}</div></div>
    <div class="modal-footer"><button class="btn btn-primary" onclick="closeModal()">Tushunarli</button></div>`);
}
const XL_HEADERS = ['Rasm','SKU (Kod)','Nomi','Kategoriya','Brend','Miqdor','Tannarx ($, 1 dona)','Chakana narxi ($)','Optom narxi ($)'];
const XL_SAMPLE_RE = /^namuna\b/i;
// v24.5: chegaralar — juda katta fayl brauzerni osib qo'ymasin, xato aniq ko'rsatilsin
const XL_MAX_ROWS = 20000;
const XL_MAX_BYTES = 50 * 1024 * 1024;
function xlFileGuard(f) {
  if (f && f.size > XL_MAX_BYTES) return `Fayl juda katta (${Math.round(f.size/1024/1024)} MB) — eng ko'pi ${XL_MAX_BYTES/1024/1024} MB`;
  return null;
}
function xlRowsGuard(ws) {
  const n = Math.max(0, (ws && ws.actualRowCount || 0) - 1);   // sarlavha qatori hisobga olinmaydi
  return n > XL_MAX_ROWS ? `Faylda ${n} ta qator — bir yo'la eng ko'pi ${XL_MAX_ROWS} ta. Faylni bir necha qismga bo'lib yuklang` : null;
}
// Import qilinadigan varaq: «Shablon» (bizning fayl) yoki birinchi varaq (eski/boshqa fayllar)
function xlDataSheet(wb) { return (typeof wb.getWorksheet === 'function' && wb.getWorksheet('Shablon')) || wb.worksheets[0]; }

// v24.5: formula in'eksiyasiga qarshi (himoya qatlami). ExcelJS oddiy satrni har doim MATN sifatida yozadi
// (t="s", <f> yo'q — P46 testi buni xlsx XML'ida tekshiradi), ya'ni «=HYPERLINK(...)» faylni ochganda formula
// bo'lib ishlamaydi. Qo'shimcha: = + - @ TAB CR bilan boshlanadigan matn katagiga «@» (Matn) formati beriladi —
// foydalanuvchi katakni tahrirlab Enter bossa ham Excel uni formula qilib qayta hisoblamaydi. Qiymat O'ZGARMAYDI.
const XL_FORMULA_RE = /^[=+\-@\t\r]/;
function fwXlGuard(wb) {
  wb.eachSheet(ws => ws.eachRow({ includeEmpty:false }, row => row.eachCell({ includeEmpty:false }, c => {
    if (typeof c.value === 'string' && XL_FORMULA_RE.test(c.value)) c.numFmt = '@';
  })));
  return wb;
}
async function fwXlSave(wb, filename) {
  fwXlGuard(wb);
  const buf = await wb.xlsx.writeBuffer();
  const blob = new Blob([buf], {type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
  const url = URL.createObjectURL(blob);
  const a=document.createElement('a'); a.href=url; a.download=filename; document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

