function printStock() {
  const w=fwDocWin();
  w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Qoldiq</title>
  <style>body{font-family:Arial,sans-serif;font-size:12px;margin:20px}table{width:100%;border-collapse:collapse}
  th{background:#1a2236;color:#f5a623;padding:7px;text-align:left;font-size:11px}td{padding:6px 7px;border-bottom:1px solid #eee}
  .low{color:red;font-weight:bold}.ok{color:green}</style></head><body>
  <h2>📦 Ombor Qoldiq Hisoboti</h2><p>${new Date().toLocaleString('uz-UZ')} | ${esc(fwBrand().name)}</p>
  <table><thead><tr><th>Kod</th><th>Nomi</th><th>Kategoriya</th><th>Qoldiq</th><th>Min</th><th>Tannarx ($)</th><th>Holat</th></tr></thead><tbody>
  ${S.products.map(p=>{const st=getStock(p.id),cost=getCostFIFO(p.id);const cls=st===0||st<=p.minStock?'low':'ok';
  return `<tr><td><code>${esc(p.sku)}</code></td><td>${esc(p.name)}</td><td>${esc(p.cat)}</td><td class="${cls}">${st}</td><td>${p.minStock}</td><td>${CUR.fmtUsd(cost)}</td><td class="${cls}">${st===0?'Tugagan':st<=p.minStock?'Kam!':'OK'}</td></tr>`;}).join('')}
  </tbody></table></body></html>`);
  w.document.close();w.print();
}

