function printDealerStatement(did) {
  const d=S.dealers.find(x=>x.id===did);if(!d)return;
  const x = dealerCardExtra(d);
  const txns=S.dealerTxns.filter(t=>t.dealerId===did).slice().reverse();
  const goodsTxns=txns.filter(t=>t.type==='send'||t.type==='return');
  const moneyTxns=txns.filter(t=>t.type==='sale'||t.type==='payment');
  const w=fwDocWin();
  w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Diller hisoboti</title>
  <style>body{font-family:Arial,sans-serif;font-size:12px;margin:24px}table{width:100%;border-collapse:collapse;margin-bottom:20px}
  th{background:#1a2236;color:#f5a623;padding:7px;text-align:left}td{padding:6px 7px;border-bottom:1px solid #eee}
  h3{margin-top:24px;border-bottom:2px solid #1a2236;padding-bottom:4px}</style></head><body>
  <h2>🚚 Diller hisoboti — ${esc(d.name)}</h2>
  <p>Hudud: ${esc(d.region||'—')} | Tel: ${esc(d.phone||'—')}</p>
  <p>Sotilgan: <b>${CUR.fmtUsd(d.totalSold||0)}</b> | To'langan: <b style="color:green">${CUR.fmtUsd(d.totalPaid||0)}</b> | Qarz: <b style="color:red">${CUR.fmtUsd(d.debt||0)}</b> | Umumiy foyda: <b style="color:green">${CUR.fmtUsd(x.totalProfit)}</b></p>
  <p>Kredit limiti: <b>${(d.creditLimitUsd||0)>0?CUR.fmtUsd(d.creditLimitUsd):'Belgilanmagan'}</b> | To'lov intizomi: <b>${x.discipline}</b></p>
  <p>Oxirgi savdo: <b>${x.lastSaleDate?fmtD(x.lastSaleDate):'—'}</b> | Oxirgi to'lov: <b>${x.lastPaymentDate?fmtD(x.lastPaymentDate):'—'}</b> | Oxirgi qaytarish: <b>${x.lastReturnDate?fmtD(x.lastReturnDate):'—'}</b></p>

  <h3>📦 Mahsulot oldi-berdi (ombor harakati)</h3>
  <table><thead><tr><th>Sana</th><th>Turi</th><th>Mahsulotlar</th></tr></thead><tbody>
  ${goodsTxns.map(t=>{
    const itemsTxt=(t.items||[]).map(i=>{const p=S.products.find(x=>x.id===i.pid);return `${esc(p?.sku||'')} ×${esc(String(i.qty))}`;}).join(', ');
    return `<tr><td>${fmtD(t.date)}</td><td>${t.type==='send'?'🚚 Yuborildi':'↩️ Qaytarildi'}</td><td>${itemsTxt}</td></tr>`;
  }).join('')||'<tr><td colspan="3">Harakat yo\'q</td></tr>'}
  </tbody></table>

  <h3>💰 Pul oldi-berdi (qarz va to'lov)</h3>
  <table><thead><tr><th>Sana</th><th>Turi</th><th>Summa</th></tr></thead><tbody>
  ${moneyTxns.map(t=>`<tr><td>${fmtD(t.date)}</td><td>${t.type==='sale'?'🧾 Sotdi (qarzga)':"💰 To'lov qildi"}</td><td style="color:${t.type==='sale'?'red':'green'}">${t.type==='sale'?'+':'−'}${CUR.fmtUsd(t.totalUsd)}</td></tr>`).join('')||'<tr><td colspan="3">Harakat yo\'q</td></tr>'}
  </tbody></table>
  <p style="margin-top:20px;font-size:11px;color:#999">Chop etildi: ${new Date().toLocaleString('uz-UZ')}</p>
  </body></html>`);
  w.document.close();w.print();
}

