function printAllImports() {
  const groups = {};
  S.batches.forEach(b=>{ (groups[b.bno] = groups[b.bno]||[]).push(b); });
  const bnos = Object.keys(groups).sort((a,b)=>new Date(groups[a][0].date)-new Date(groups[b][0].date));
  if (!bnos.length) { toast("Kirim yo'q!",'error'); return; }

  let grandTotal = 0, grandQty = 0;
  const sections = bnos.map(bno=>{
    const list = groups[bno];
    const first = list[0];
    const supp = first.suppId ? S.suppliers.find(s=>s.id===first.suppId) : null;
    const totalQty = list.reduce((s,b)=>s+b.qty,0);
    const totalVal = list.reduce((s,b)=>s+b.qty*(b.costUsd||0),0);
    grandTotal += totalVal; grandQty += totalQty;
    const isTransit = first.status==='transit';
    return `
      <h3 style="margin:26px 0 8px;padding-top:14px;border-top:2px solid #1a2236">📦 Partiya #${esc(bno)}
        ${first.consignment?'<span style="background:#eee;color:#7c3aed;padding:2px 8px;border-radius:10px;font-size:11px;margin-left:8px">📋 Konsignatsiya</span>':''}
        ${isTransit?'<span style="background:#eee;color:#7c3aed;padding:2px 8px;border-radius:10px;font-size:11px;margin-left:8px">🚚 Yo\'lda</span>':''}
      </h3>
      <div class="row"><span>Sana:</span><span>${fmtD(first.date)}</span></div>
      <div class="row"><span>Ta'minotchi (kimdan):</span><span>${esc(supp?supp.name:'— belgilanmagan —')}</span></div>
      <div class="row"><span>Valyuta:</span><span>${first.cur==='CNY'?'🇨🇳 Yuan':first.cur==='UZS'?"🇺🇿 So'm":'🇺🇸 Dollar'}</span></div>
      <table><thead><tr><th>Kod</th><th>Nomi</th><th>Dona</th><th>Tannarx/dona</th><th>Jami</th></tr></thead><tbody>
      ${list.map(b=>{const p=S.products.find(x=>x.id===b.pid);return `<tr><td>${esc(p?.sku||'')}</td><td>${esc(p?.name||'')}</td><td>${b.qty}</td><td>${CUR.fmtUsd(b.costUsd||0)}</td><td>${CUR.fmtUsd(b.qty*(b.costUsd||0))}</td></tr>`;}).join('')}
      </tbody></table>
      <div class="row"><span>Jami mahsulot turi:</span><span>${list.length} xil</span></div>
      <div class="row"><span>Jami dona:</span><span>${totalQty} dona</span></div>
      <div class="row tot"><span>PARTIYA QIYMATI:</span><span>${CUR.fmtUsd(totalVal)}</span></div>
    `;
  }).join('');

  const w=fwDocWin();
  w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Barcha kirimlar</title>
  <style>body{font-family:Arial,sans-serif;font-size:13px;margin:30px}.row{display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid #eee}
  table{width:100%;border-collapse:collapse;margin:10px 0}th{background:#1a2236;color:#f5a623;padding:7px;text-align:left;font-size:12px}td{padding:6px 7px;border-bottom:1px solid #eee;font-size:12px}
  .tot{font-weight:bold;font-size:14px;color:#f5a623}h2{margin-bottom:4px}h3{font-size:15px}</style></head><body>
  <h2>📋 Barcha Kirimlar — To'liq Hisobot</h2>
  <p style="color:#999;font-size:11px;margin-top:0">Jami ${bnos.length} ta partiya</p>
  ${sections}
  <div class="row tot" style="border-top:3px double #1a2236;padding-top:12px;margin-top:20px"><span>UMUMIY JAMI (barcha partiyalar):</span><span>${CUR.fmtUsd(grandTotal)} — ${grandQty} dona</span></div>
  <p style="margin-top:20px;font-size:11px;color:#999">Chop etildi: ${new Date().toLocaleString('uz-UZ')}</p>
  </body></html>`);
  w.document.close();w.print();
}

function printImport(bno) {
  const list = S.batches.filter(b=>String(b.bno)===String(bno));
  if (!list.length) return;
  const first = list[0];
  const supp = first.suppId ? S.suppliers.find(s=>s.id===first.suppId) : null;
  const totalQty = list.reduce((s,b)=>s+b.qty,0);
  const totalVal = list.reduce((s,b)=>s+b.qty*(b.costUsd||0),0);
  const totalBankFee = list.reduce((s,b)=>s+(b.bankFeeUsd||0),0);
  const w=fwDocWin();
  w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Partiya</title>
  <style>body{font-family:Arial,sans-serif;font-size:13px;margin:30px}.row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #eee}
  table{width:100%;border-collapse:collapse;margin:14px 0}th{background:#1a2236;color:#f5a623;padding:7px;text-align:left;font-size:12px}td{padding:6px 7px;border-bottom:1px solid #eee;font-size:12px}
  .tot{font-weight:bold;font-size:15px;color:#f5a623}</style></head><body>
  <h2>📦 Kirim Hujjati — #${esc(bno)}</h2>
  <div class="row"><span>Valyuta:</span><span>${first.cur==='CNY'?'🇨🇳 Yuan':first.cur==='UZS'?"🇺🇿 So'm":'🇺🇸 Dollar'}</span></div>
  <div class="row"><span>Kelib chiqqan:</span><span>${esc(first.origin)}</span></div>
  ${supp?`<div class="row"><span>Ta'minotchi:</span><span>${esc(supp.name)}</span></div>`:''}
  <div class="row"><span>Sana:</span><span>${fmtD(first.date)}</span></div>
  <div class="row"><span>Kurs:</span><span>1$ = ${(first.rates?.usdUzs||CUR.usdUzs).toLocaleString('en-US').replace(/,/g,' ')} UZS</span></div>
  ${totalBankFee>0?`<div class="row"><span>Bank 0.6% (jami):</span><span>${CUR.fmtUsd(totalBankFee)}</span></div>`:''}
  <table><thead><tr><th>Kod</th><th>Nomi</th><th>Dona</th><th>Tannarx/dona</th><th>Jami</th></tr></thead><tbody>
  ${list.map(b=>{const p=S.products.find(x=>x.id===b.pid);return `<tr><td>${esc(p?.sku||'')}</td><td>${esc(p?.name||'')}</td><td>${b.qty}</td><td>${CUR.fmtUsd(b.costUsd||0)}</td><td>${CUR.fmtUsd(b.qty*(b.costUsd||0))}</td></tr>`;}).join('')}
  </tbody></table>
  <div class="row"><span>Jami mahsulot turi:</span><span>${list.length} xil</span></div>
  <div class="row"><span>Jami dona:</span><span>${totalQty} dona</span></div>
  <div class="row tot"><span>JAMI QIYMAT:</span><span>${CUR.fmtUsd(totalVal)}</span></div>
  <p style="margin-top:20px;font-size:11px;color:#999">Chop etildi: ${new Date().toLocaleString('uz-UZ')}</p>
  </body></html>`);
  w.document.close();w.print();
}

