document.addEventListener('DOMContentLoaded', async () => {
  _initCloud();
  injectIcons();
  initSidebarState();

  // Bitta kirish ekrani: login + parol (admin/sotuvchi/diller — tizim o'zi aniqlaydi)
  if (sessionStorage.getItem('bp_auth_ok') !== '1') {
    // v25: tez kirish — shu qurilmada avval kirilgan bo'lsa, PIN yoki barmoq izi (internetsiz ham)
    if (typeof fwQuickGet === 'function' && fwQuickGet()) {
      let uid = null, has = false;
      try { const { data: { session } } = await _db.auth.getSession(); uid = session?.user?.id || null; has = !!session; } catch (_) {}
      if (has || navigator.onLine === false) { const info = await fwQuickUnlock(uid); if (info) { fwEnterWithInfo(info); return; } }
      else fwQuickClear();   // sessiya tugagan — login va parol kerak
    }
    await showUnifiedLogin();
    return;
  }

  // Filial tanlash (Baza / 729) — parol bilan, har safar ilova ochilganda
  const chosenBranch = sessionStorage.getItem('bp_branch_ok');
  if (!BRANCHES[chosenBranch]) {
    await showBranchScreen();
    return;
  }
  S.branch = chosenBranch;
  localStorage.setItem('bp_active_branch', chosenBranch);

  // Loading
  const mainEl = document.getElementById('main-content-area');
  const loadEl = document.getElementById('bp-loading');
  if (mainEl) mainEl.style.display='none';
  if (loadEl) loadEl.style.display='flex';

  await initData();

  // Oxirgi tanlangan filialni tiklash (parolsiz — bu faqat shu qurilmadagi holat)
  const savedBranch = localStorage.getItem('bp_active_branch');
  if (savedBranch && BRANCHES[savedBranch]) S.branch = savedBranch;
  renderBranchBadge();

  if (loadEl) loadEl.style.display='none';
  if (mainEl) mainEl.style.display='';

  // Sana + soat
  const dateEl=document.getElementById('topbar-date');
  if(dateEl) dateEl.textContent=new Date().toLocaleDateString('uz-UZ',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
  setInterval(()=>{ const cl=document.getElementById('topbar-clock'); if(cl) cl.textContent=new Date().toLocaleTimeString('uz-UZ'); },1000);

  document.querySelector('.hamburger')?.addEventListener('click',()=>{ document.querySelector('.sidebar').classList.toggle('open'); });

  document.addEventListener('click',(e)=>{
    if(!e.target.closest('#savdo-q')&&!e.target.closest('#savdo-dropdown')){const dd=document.getElementById('savdo-dropdown');if(dd)dd.style.display='none';}
    if(!e.target.closest('#s-custq')&&!e.target.closest('#s-cust-dd')){const dd=document.getElementById('s-cust-dd');if(dd)dd.style.display='none';}
    if(!e.target.closest('#ds-q')&&!e.target.closest('#ds-dd')){const dd=document.getElementById('ds-dd');if(dd)dd.style.display='none';}
    if(!e.target.closest('#do-q')&&!e.target.closest('#do-dd')){const dd=document.getElementById('do-dd');if(dd)dd.style.display='none';}
    if(!e.target.closest('#dr-q')&&!e.target.closest('#dr-dd')){const dd=document.getElementById('dr-dd');if(dd)dd.style.display='none';}
    if(!e.target.closest('[id^="dsrow-q-"]')&&!e.target.closest('[id^="dsrow-dd-"]')){document.querySelectorAll('[id^="dsrow-dd-"]').forEach(dd=>dd.style.display='none');}
    if(!e.target.closest('[id^="dlsrow-q-"]')&&!e.target.closest('[id^="dlsrow-dd-"]')){document.querySelectorAll('[id^="dlsrow-dd-"]').forEach(dd=>dd.style.display='none');}
    if(!e.target.closest('[id^="osrow-q-"]')&&!e.target.closest('[id^="osrow-dd-"]')){document.querySelectorAll('[id^="osrow-dd-"]').forEach(dd=>dd.style.display='none');}
    if(!e.target.closest('#dls-q')&&!e.target.closest('#dls-dd')){const dd=document.getElementById('dls-dd');if(dd)dd.style.display='none';}
    if(!e.target.closest('#os-q')&&!e.target.closest('#os-dd')){const dd=document.getElementById('os-dd');if(dd)dd.style.display='none';}
    if(window.innerWidth<=1024){const sb=document.querySelector('.sidebar');if(sb&&!sb.contains(e.target)&&!e.target.classList.contains('hamburger')&&!e.target.closest('.m-bn-item'))sb.classList.remove('open');}
  });

  // RBAC sessiyasi: agar staff sifatida kirilgan bo'lsa — uning ruxsatlarini yuklaymiz,
  // aks holda (PIN orqali) to'liq huquqli Owner sessiyasi.
  const _staffId = sessionStorage.getItem('bp_staff_id');
  if (_staffId) { await loadCurrentUserPermissions(Number(_staffId)); }
  else { setOwnerSession(); }

  const _startPage = location.hash.slice(1);
  const _wantedPage = _startPage && document.getElementById('pg-'+_startPage) ? _startPage : 'dashboard';
  go((PAGE_VIEW_PERMISSION[_wantedPage] && !hasPerm(PAGE_VIEW_PERMISSION[_wantedPage])) ? 'dashboard' : _wantedPage);
  updateSidebarUser();
  if (CUR.lastRateDate !== td()) { setTimeout(()=>openRateModal(false), 500); }
  // v25: «Onlayn rejim faol» xabari har ochilishda pastki tugmani yopardi — endi faqat oflayn/onlayn o'zgarganda (pastdagi belgi)

  // Brauzer "orqaga/oldinga" tugmalari sahifalar bo'yicha ishlashi uchun
  // v24.5: brauzer tarixi bo'yicha bo'limlarga o'tilmaydi (eski yozuvlar orqali qaytish yo'q) — faqat manzil
  // qo'lda o'zgartirilsa (yangi yozuv) o'sha bo'lim ochiladi
  window.addEventListener('hashchange', () => {
    if (_hashLock) { _hashLock = false; return; }
    if (history.state && history.state.fwBack) return;
    const p = location.hash.slice(1);
    if (p && p !== S.page && document.getElementById('pg-'+p)) go(p);
  });

  // Yakunlanmagan savdo (savatda tovar) bo'lsa — fayl/oyna yopilishidan ogohlantiradi
  window.addEventListener('beforeunload', (e) => {
    if (S.cart && S.cart.length) { e.preventDefault(); e.returnValue = ''; return ''; }
  });
});

// PWA — service worker endi js/shared.js da ro'yxatdan o'tadi (admin, sotuvchi va diller sahifalari uchun)

// v25: tasdiqlangan (oflayn parol / PIN / barmoq izi) kirish — o'z sahifasiga
function fwEnterWithInfo(info) {
  if (info.dest === 'seller') {
    try { sessionStorage.setItem('fw_fast_staff', JSON.stringify({ uid: info.uid, t: Date.now(), staff: info.staff, offline: navigator.onLine === false })); } catch (_) {}
    location.replace('sotuvchi.html'); return;
  }
  sessionStorage.setItem('bp_auth_ok', '1');
  sessionStorage.setItem('bp_branch_ok', info.branch || 'baza');
  if (info.staffId != null) sessionStorage.setItem('bp_staff_id', String(info.staffId));
  localStorage.setItem('bp_active_branch', info.branch || 'baza');
  location.reload();
}

function showUnifiedLogin() {
  return new Promise(resolve => {
    const body = document.body;
    body.innerHTML = `
      <div class="fw-brand-bg" style="min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px">
        <div class="fw-login-card" style="background:#fff;border-radius:18px;padding:36px 30px;width:100%;max-width:340px;box-shadow:0 14px 36px rgba(15,23,42,0.14);text-align:center">
          <div style="margin-bottom:16px">${brandLoginLogo()}</div>
          <div style="font-size:18px;font-weight:800;color:#1c2433;margin-bottom:4px">Xush kelibsiz</div>
          <div style="font-size:12.5px;color:#8b95a5;margin-bottom:20px">${esc(fwBrand().name)} tizimiga kiring</div>
          <input id="ul-login" placeholder="Login" autocomplete="username"
            style="width:100%;padding:13px 14px;font-size:14px;border:1.5px solid #e1e6ed;border-radius:10px;margin-bottom:10px;outline:none;box-sizing:border-box">
          <div class="fw-pw-f" style="margin-bottom:14px"><input id="ul-pass" type="password" placeholder="Parol" autocomplete="current-password"
            style="width:100%;padding:13px 48px 13px 14px;font-size:14px;border:1.5px solid #e1e6ed;border-radius:10px;outline:none;box-sizing:border-box"
            onkeydown="if(event.key==='Enter')_ulSubmit()">${_fwPwEye('ul-pass')}</div>
          <button id="ul-go" style="width:100%;padding:13px;background:linear-gradient(135deg,#B8700C,#8A5208);color:#fff;border:none;border-radius:10px;font-size:14px;font-weight:700;cursor:pointer">Kirish →</button>
          <div id="ul-err" style="color:#e23d3d;font-size:12px;margin-top:8px;min-height:16px"></div>
          <button type="button" class="fw-forgot" onclick="fwPwForgot(document.getElementById('ul-login')?.value||'')">Parolni unutdingizmi?</button>
          ${_ulContactHtml()}
        </div>
      </div>`;
    document.getElementById('ul-go').addEventListener('click', () => _ulSubmit());

    // So'rov juda uzoq osilib qolmasligi uchun — belgilangan vaqtdan keyin
    // "server javob bermayapti" xabari bilan to'xtatadi (login abadiy "kutmaydi")
    function withTimeout(promise, ms, label) {
      let timer;
      const timeout = new Promise((_, reject) => {
        timer = setTimeout(() => reject(Object.assign(new Error('timeout'), { isTimeout:true })), ms);
      });
      return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
    }

    window._ulSubmit = async () => {
      const login = (document.getElementById('ul-login')?.value||'').trim();
      const pass = document.getElementById('ul-pass')?.value||'';
      const errEl = document.getElementById('ul-err');
      const btn = document.getElementById('ul-go');
      if (!login || !pass) { errEl.textContent = 'Login va parolni kiriting'; return; }
      btn.disabled = true; btn.textContent = 'Tekshirilmoqda...'; errEl.textContent = '';
      const cleanLogin = login.toLowerCase().replace(/\s+/g,'');
      let technicalError = null; // agar texnik sabab aniqlansa — shu yerda saqlanadi (parol xatosi emas)
      // v25: internet yo'q — shu qurilmada oxirgi kirgan xodim o'z paroli bilan oflayn kiradi
      const _offlineLogin = async () => {
        const info = await fwOffAuthCheck(cleanLogin, pass);
        if (!info) return false;
        if (info.dest !== 'seller') resolve();
        fwEnterWithInfo(info); return true;
      };
      if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        if (await _offlineLogin()) return;
        btn.disabled = false; btn.textContent = 'Kirish →';
        errEl.textContent = "Internet yoʻq. Oflayn kirish faqat shu qurilmada oxirgi 30 kun ichida internet bilan kirgan login va parol bilan ishlaydi.";
        return;
      }

      // Supabase/tarmoq xatosini tasniflaydi: 429 (juda ko'p urinish), tarmoq xatosi,
      // yoki haqiqiy "login/parol noto'g'ri" (bu holda null qaytaradi — davom etamiz)
      function classifyAuthError(err) {
        if (!err) return null;
        const status = err.status || err.code;
        const msg = (err.message||'').toLowerCase();
        if (status === 429 || msg.includes('rate limit') || msg.includes('too many')) {
          return "⏳ Juda ko'p urinish qilindi. Iltimos, 1 daqiqadan keyin qayta urinib ko'ring.";
        }
        if (status >= 500 || msg.includes('fetch') || msg.includes('network')) {
          return "🌐 Server bilan bog'lanib bo'lmadi. Internet aloqangizni tekshirib, qayta urining.";
        }
        return null; // haqiqiy invalid-credentials — bu parol xatosi bo'lishi mumkin, davom etamiz
      }

      // 1) Kirish — v24.9 (38): server orqali (xodim, keyin diller); noto'g'ri parol sanaladi va bloklanadi
      let lg, loginMsg = null;
      try {
        lg = await withTimeout(fwStaffLogin(_db, cleanLogin, pass, 'auto'), 20000);
      } catch(e) {
        technicalError = e.isTimeout
          ? "🌐 Server javob bermayapti. Iltimos, birozdan keyin qayta urining."
          : "🌐 Server bilan bog'lanib bo'lmadi. Internet aloqangizni tekshiring.";
        lg = { error: e };
        if (!e.isTimeout && typeof fwIsNetErr === 'function' && fwIsNetErr(e) && await _offlineLogin()) return;
      }
      if (lg.error && !technicalError) {
        const st = lg.error.status;
        if (st === 423 || st === 429 || st === 502 || st === 401) loginMsg = lg.error.message;   // server matni: blok / qolgan urinishlar
        else technicalError = classifyAuthError(lg.error);
      }
      const staffAuth = lg.kind === 'staff' ? { data: lg.data, error: null } : { error: lg.error || { message: 'diller' } };

      if (!staffAuth.error && staffAuth.data?.user) {
        // Server tomonda token tasdiqlanadi va shu foydalanuvchiga tegishli staff qatori qaytariladi
        // (staff jadvaliga endi brauzerdan to'g'ridan-to'g'ri kirish yo'q). Token — authFetch()
        // orqali "Authorization: Bearer ..." headerida avtomatik yuboriladi (joriy sessiyadan olinadi).
        let whoamiRes;
        try {
          whoamiRes = await withTimeout(authFetch('/.netlify/functions/staff-whoami', {
            method:'POST'
          }), 12000);
        } catch(e) { whoamiRes = null; if (e.isTimeout) technicalError = "🌐 Server javob bermayapti. Birozdan keyin qayta urining."; }
        if (whoamiRes && !whoamiRes.ok && whoamiRes.status !== 404) {
          // Function javob berdi, lekin xato bilan (401 bo'lsa token/sessiya muammosi, 500 — server) —
          // bu ANIQ texnik nosozlik, "parol noto'g'ri" emas
          technicalError = whoamiRes.status === 429
            ? "⏳ Juda ko'p urinish qilindi. Birozdan keyin qayta urining."
            : "🌐 Serverga ulanishda muammo. Birozdan keyin qayta urining.";
        } else if (!whoamiRes) {
          technicalError = "🌐 Server bilan bog'lanib bo'lmadi. Internet aloqangizni tekshiring.";
        }
        const whoamiData = whoamiRes && whoamiRes.ok ? await whoamiRes.json() : null;
        const staffRow = whoamiData?.staff || null;
        // v24.9 (38): admin parolni tiklagan — avval yangi parol (server ham boshqa amallarni rad etadi)
        if (staffRow && whoamiData.mustChangePw) { btn.textContent = 'Yangi parol…'; await fwPwForce(staffRow.name); }
        if (staffRow) {
          // RBAC: xodim qanday rol(lar)ga ega ekanini tekshiramiz.
          // "employee" (yoki hech qanday RBAC roli yo'q, faqat eski 'sotuvchi') — yengil sotuvchi.html portaliga,
          // boshqa har qanday rol (branch_manager/cashier/accountant va h.k.) — asosiy admin panelga, menyu cheklangan holda.
          let roleKeys = [];
          if (Array.isArray(whoamiData.roleKeys)) roleKeys = whoamiData.roleKeys;   // v24.6: whoami javobida — alohida so'rov yo'q
          else try {
            const rbacRes = await authFetch('/.netlify/functions/rbac-staff-roles-get', {
              method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ staffId: staffRow.id })
            }).catch(()=>null);
            const rbacData = rbacRes && rbacRes.ok ? await rbacRes.json() : null;
            roleKeys = (rbacData?.roles||[]).map(r=>r?.key).filter(Boolean);
          } catch(e) { /* RBAC migratsiya hali ishga tushmagan bo'lishi mumkin — eski xatti-harakatga tushamiz */ }
          const onlyEmployee = roleKeys.length>0 && roleKeys.every(k=>k==='employee'||k==='dealer');   // v24.7: «dealer» roli boshqaruv paneliga olib kirmaydi
          const goToAdminPanel = staffRow.role === 'admin' || (roleKeys.length>0 && !onlyEmployee);
          if (goToAdminPanel) {
            // v10 (J2): server qaytargan filialga ishonamiz — yangi qurilmada BRANCHES ro'yxati
            // hali bulutdan yuklanmagan bo'ladi (avval qo'shilgan filial xodimi "Baza"ga tushardi)
            const myBranch = (typeof staffRow.filial === 'string' && /^[A-Za-z0-9_-]{1,40}$/.test(staffRow.filial)) ? staffRow.filial : 'baza';
            const _qi = { dest: 'admin', branch: myBranch, staffId: staffRow.role !== 'admin' ? staffRow.id : null, uid: staffAuth.data.user.id, name: staffRow.name };
            await fwOffAuthSave(cleanLogin, pass, _qi);
            await fwQuickSetupOffer(_qi);   // v25: keyingi safar PIN / barmoq izi bilan
            sessionStorage.setItem('bp_auth_ok', '1');
            sessionStorage.setItem('bp_branch_ok', myBranch); // o'z filialiga avtomatik kiradi — qayta so'ralmaydi
            if (staffRow.role !== 'admin') sessionStorage.setItem('bp_staff_id', String(staffRow.id)); // RBAC menyu cheklovi uchun
            localStorage.setItem('bp_active_branch', myBranch);
            resolve();
            location.reload();
          } else {
            // v24.6 (tez kirish): tasdiqlangan xodim ma'lumoti sotuvchi sahifasiga uzatiladi (u yerda whoami qayta so'ralmaydi;
            // server baribir har so'rovda tokenni tekshiradi). Faqat shu tab, 2 daqiqa.
            try { sessionStorage.setItem('fw_fast_staff', JSON.stringify({ uid: staffAuth.data.user.id, t: Date.now(), staff: staffRow })); } catch (_) {}
            const _qs = { dest: 'seller', uid: staffAuth.data.user.id, staff: staffRow, name: staffRow.name };
            await fwOffAuthSave(cleanLogin, pass, _qs);
            await fwQuickSetupOffer(_qs);   // v25: keyingi safar PIN / barmoq izi bilan
            btn.textContent = 'Kirilmoqda…';
            location.replace('sotuvchi.html'); // sessiya umumiy — u yerda qayta so'ralmaydi
          }
          return;
        }
        await _db.auth.signOut().catch(()=>{});
      }

      // 2) Diller (server bitta so'rovda ikkalasini tekshiradi)
      const dealerAuth = lg.kind === 'dealer' ? { data: lg.data, error: null } : { error: lg.error || { message: 'xodim' } };
      if (!dealerAuth.error && dealerAuth.data?.user) {
        const { data: dealerRow } = await _db.from('dealers').select('id').eq('auth_user_id', dealerAuth.data.user.id).maybeSingle();
        if (dealerRow) { btn.textContent = 'Kirilmoqda…'; location.replace('diller.html'); return; }
        await _db.auth.signOut().catch(()=>{});
      }

      btn.disabled = false; btn.textContent = 'Kirish →';
      errEl.textContent = technicalError || loginMsg || "Login yoki parol noto'g'ri";
    };
    setTimeout(()=>document.getElementById('ul-login')?.focus(), 100);
    // v24.6 (tez kirish): login yozilayotganda sotuvchi/diller sahifalari va skriptlari oldindan yuklanadi —
    // sotuvchi yoki diller kirganda ikkinchi sahifa keshdan darhol ochiladi
    setTimeout(() => { try { ['sotuvchi.html', 'js/sotuvchi.js', 'js/pos.js', 'diller.html', 'js/diller.js'].forEach(h => {
      if (document.querySelector(`link[rel="prefetch"][href="${h}"]`)) return;
      const l = document.createElement('link'); l.rel = 'prefetch'; l.href = h; document.head.appendChild(l); }); } catch (_) {} }, 600);
  });
}

function showPinScreen() {
  return new Promise(resolve => {
    const body = document.body;
    const orig = body.innerHTML;
    let pin = '';
    // v24.8: PIN o'rnatilmagan — standart yo'q, majburan yangi PIN (ikki marta kiritiladi)
    let setMode = !getAppPin(), first = '';
    const render = () => {
      const plen = setMode ? 4 : Math.max(4, Math.min(10, getAppPin().length||4));
      const dots = Array.from({length:plen}, (_,i)=>`<span style="width:14px;height:14px;border-radius:50%;display:inline-block;margin:0 6px;
        background:${i<pin.length?'#B8700C':'#e1e6ed'};transition:background .15s"></span>`).join('');
      body.innerHTML = `
      <div class="fw-brand-bg" style="min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px">
        <div class="fw-login-card" style="background:#fff;border-radius:20px;padding:36px 28px;width:100%;max-width:330px;box-shadow:0 18px 42px rgba(15,23,42,0.16);text-align:center">
          <div style="margin-bottom:20px">${brandLoginLogo()}</div>
          <div style="font-size:13px;color:#8b95a5;margin:4px 0 26px">${setMode ? (first ? 'Yangi PIN — qayta kiriting' : 'PIN hali oʻrnatilmagan — yangi 4 xonali PIN oʻylab toping') : 'Boshqaruv paneliga kirish uchun PIN kiriting'}</div>
          <div style="margin-bottom:22px">${dots}</div>
          <div id="pin-numpad" style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:8px">
            ${[1,2,3,4,5,6,7,8,9].map(n=>`<button data-num="${n}" style="padding:16px 0;font-size:19px;font-weight:700;border:1.5px solid #eef0f4;background:#fafbfc;border-radius:12px;cursor:pointer;color:#1c2433">${n}</button>`).join('')}
            <button id="pin-clear" style="padding:16px 0;font-size:13px;font-weight:700;border:none;background:transparent;border-radius:12px;cursor:pointer;color:#8b95a5">Tozalash</button>
            <button data-num="0" style="padding:16px 0;font-size:19px;font-weight:700;border:1.5px solid #eef0f4;background:#fafbfc;border-radius:12px;cursor:pointer;color:#1c2433">0</button>
            <button id="pin-back" style="padding:16px 0;font-size:18px;font-weight:700;border:none;background:transparent;border-radius:12px;cursor:pointer;color:#8b95a5">⌫</button>
          </div>
          <button id="pin-go" style="width:100%;padding:12px;margin-top:6px;background:linear-gradient(135deg,#B8700C,#8A5208);color:#fff;border:none;border-radius:10px;font-size:14px;font-weight:700;cursor:pointer">Kirish →</button>
          <div id="pin-err" style="color:#e23d3d;font-size:12px;min-height:16px;margin-top:8px"></div>
        </div>
      </div>`;
      body.querySelectorAll('[data-num]').forEach(btn=>{
        btn.addEventListener('click', ()=>{
          if (pin.length>=plen) return;
          pin += btn.dataset.num;
          render();
          if (pin.length===plen) setTimeout(check, 120);
        });
      });
      document.getElementById('pin-back')?.addEventListener('click', ()=>{ pin=pin.slice(0,-1); render(); });
      document.getElementById('pin-clear')?.addEventListener('click', ()=>{ pin=''; render(); });
      document.getElementById('pin-go')?.addEventListener('click', check);
    };
    const check = () => {
      if (setMode) {
        if (!first) { first = pin; pin = ''; render(); return; }
        if (pin !== first) { first = ''; pin = ''; render(); const e = document.getElementById('pin-err'); if (e) e.textContent = 'PIN mos kelmadi — qaytadan'; return; }
        localStorage.setItem('koma_admin_pin', pin);
        setMode = false;
      }
      if (pin.length && pin === getAppPin()) {
        sessionStorage.setItem('bp_pin_ok', getAppPin());
        sessionStorage.setItem('bp_auth_ok', '1');
        body.innerHTML = orig;
        resolve();
        location.reload();
      } else {
        const e=document.getElementById('pin-err'); if(e) e.textContent="PIN noto'g'ri! Qayta urining.";
        pin=''; render();
      }
    };
    render();
  });
}

function showBranchScreen() {
  return new Promise(resolve => {
    const body = document.body;
    const renderChoice = () => {
      body.innerHTML = `
        <div class="fw-brand-bg" style="min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px">
          <div class="fw-login-card" style="background:#fff;border-radius:18px;padding:36px 32px;width:100%;max-width:380px;box-shadow:0 14px 36px rgba(15,23,42,0.14);text-align:center">
            <div style="margin-bottom:20px">${brandLoginLogo()}</div>
            <div style="font-size:13px;color:#8b95a5;margin-bottom:28px">Qaysi filialga kirmoqchisiz?</div>
            <div style="display:flex;flex-direction:column;gap:12px">
              ${Object.keys(BRANCHES).filter(isBranchActive).map(key=>{
                const b = BRANCHES[key];
                const colorBg = key==='baza' ? 'rgba(138,82,8,0.1)' : 'rgba(242,33,28,0.1)';
                const sub = key==='baza' ? 'Asosiy ombor va hisob' : 'Filial ombor va hisob';
                return `<button data-branch="${key}" style="display:flex;align-items:center;gap:14px;width:100%;padding:16px 18px;background:#fff;border:1.5px solid #e6eaf0;border-radius:14px;font-size:15px;font-weight:700;color:#1c2433;cursor:pointer;text-align:left">
                <span style="width:42px;height:42px;flex-shrink:0;border-radius:12px;background:${colorBg};display:flex;align-items:center;justify-content:center;font-size:20px">${b.icon}</span>
                <span>${getBranchNameCached(key)}<br><span style="font-size:12px;font-weight:500;color:#8b95a5">${sub}</span></span>
              </button>`;
              }).join('')}
            </div>
          </div>
        </div>`;
      body.querySelectorAll('[data-branch]').forEach(btn => {
        btn.addEventListener('mouseenter', () => { btn.style.borderColor = '#B8700C'; btn.style.background = '#f5faff'; });
        btn.addEventListener('mouseleave', () => { btn.style.borderColor = '#e6eaf0'; btn.style.background = '#fff'; });
        btn.addEventListener('click', () => renderPinStep(btn.dataset.branch));
      });
    };
    // v24.8: parol bu qurilmada saqlanmagan bo'lsa — avval bulutdan olinadi; u yerda ham yo'q bo'lsa
    // (filialga hali parol o'rnatilmagan) — majburan yangi parol so'raladi. Standart parol yo'q.
    const renderPinStep = async (key) => {
      if (!getBranchPinCached(key)) {
        try {
          const d = await _cloudLoad();
          const bp = d && d.settings && d.settings.branchPin;
          if (bp && typeof bp === 'object') Object.keys(bp).forEach(k => { if (fwPinValid(String(bp[k] || ''))) localStorage.setItem('bp_branch_pin_' + k, bp[k]); });
        } catch (_) { /* tarmoq yo'q — quyida yangi parol so'raladi */ }
        if (!getBranchPinCached(key)) return renderSetStep(key);
      }
      const b = BRANCHES[key];
      body.innerHTML = `
        <div class="fw-brand-bg" style="min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px">
          <div class="fw-login-card" style="background:#fff;border-radius:16px;padding:40px 32px;width:300px;box-shadow:0 14px 36px rgba(15,23,42,0.14);text-align:center">
            <div style="font-size:32px;margin-bottom:10px">${b.icon}</div>
            <div style="font-size:18px;font-weight:800;margin-bottom:4px">${getBranchNameCached(key)}</div>
            <div style="font-size:13px;color:#8b95a5;margin-bottom:20px">Filial paroli</div>
            <input type="password" id="branch-pin-inp" maxlength="10" placeholder="••••"
              style="width:100%;padding:14px;font-size:22px;text-align:center;letter-spacing:8px;border:2px solid #e1e6ed;border-radius:10px;outline:none;margin-bottom:12px;box-sizing:border-box"
              autofocus>
            <button id="branch-pin-go" style="width:100%;padding:14px;background:linear-gradient(135deg,#B8700C,#8A5208);color:#fff;border:none;border-radius:10px;font-size:15px;font-weight:700;cursor:pointer;margin-bottom:8px">Kirish →</button>
            <button id="branch-pin-back" style="width:100%;padding:10px;background:transparent;color:#8b95a5;border:none;font-size:13px;cursor:pointer">← Orqaga</button>
            <div id="branch-pin-err" style="color:#e23d3d;font-size:12px;margin-top:6px;min-height:16px"></div>
          </div>
        </div>`;
      const submit = () => {
        const val = document.getElementById('branch-pin-inp')?.value||'';
        if (val === getBranchPinCached(key)) {
          sessionStorage.setItem('bp_branch_ok', key);
          localStorage.setItem('bp_active_branch', key);
          resolve();
          location.reload();
        } else {
          const e=document.getElementById('branch-pin-err'); if(e) e.textContent="Parol noto'g'ri! Qayta urining.";
          document.getElementById('branch-pin-inp').value='';
          document.getElementById('branch-pin-inp').focus();
        }
      };
      document.getElementById('branch-pin-go').addEventListener('click', submit);
      document.getElementById('branch-pin-inp').addEventListener('keydown', e=>{ if(e.key==='Enter') submit(); });
      document.getElementById('branch-pin-back').addEventListener('click', renderChoice);
      setTimeout(()=>document.getElementById('branch-pin-inp')?.focus(), 100);
    };
    const renderSetStep = (key) => {
      const b = BRANCHES[key];
      body.innerHTML = `
        <div class="fw-brand-bg" style="min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px">
          <div class="fw-login-card" style="background:#fff;border-radius:16px;padding:36px 28px;width:320px;box-shadow:0 14px 36px rgba(15,23,42,0.14);text-align:center">
            <div style="font-size:32px;margin-bottom:10px">${b.icon}</div>
            <div style="font-size:18px;font-weight:800;margin-bottom:4px">${getBranchNameCached(key)}</div>
            <div style="font-size:13px;color:#8b95a5;margin-bottom:18px">Bu filialga hali parol oʻrnatilmagan — yangi parol kiriting (4–10 belgi)</div>
            <input type="password" id="branch-pin-new" maxlength="10" placeholder="Yangi parol" autocomplete="new-password"
              style="width:100%;padding:12px;font-size:18px;text-align:center;border:2px solid #e1e6ed;border-radius:10px;outline:none;margin-bottom:10px;box-sizing:border-box">
            <input type="password" id="branch-pin-new2" maxlength="10" placeholder="Yangi parol — qayta" autocomplete="new-password"
              style="width:100%;padding:12px;font-size:18px;text-align:center;border:2px solid #e1e6ed;border-radius:10px;outline:none;margin-bottom:12px;box-sizing:border-box">
            <button id="branch-pin-set" style="width:100%;padding:14px;background:linear-gradient(135deg,#B8700C,#8A5208);color:#fff;border:none;border-radius:10px;font-size:15px;font-weight:700;cursor:pointer;margin-bottom:8px">Parolni oʻrnatish →</button>
            <button id="branch-pin-back" style="width:100%;padding:10px;background:transparent;color:#8b95a5;border:none;font-size:13px;cursor:pointer">← Orqaga</button>
            <div id="branch-pin-err" style="color:#e23d3d;font-size:12px;margin-top:6px;min-height:16px"></div>
          </div>
        </div>`;
      const submit = () => {
        const a = document.getElementById('branch-pin-new')?.value || '', c = document.getElementById('branch-pin-new2')?.value || '';
        const e = document.getElementById('branch-pin-err');
        if (!fwPinValid(a)) { if (e) e.textContent = 'Parol 4 dan 10 belgigacha boʻlishi kerak'; return; }
        if (a !== c) { if (e) e.textContent = 'Ikkala parol bir xil boʻlishi kerak'; return; }
        localStorage.setItem('bp_branch_pin_' + key, a);
        fwSetPendingBranchPin(key, a);   // ma'lumot yuklangach bulutga yoziladi (init → fwApplyPendingBranchPins)
        sessionStorage.setItem('bp_branch_ok', key);
        localStorage.setItem('bp_active_branch', key);
        resolve();
        location.reload();
      };
      document.getElementById('branch-pin-set').addEventListener('click', submit);
      document.getElementById('branch-pin-new2').addEventListener('keydown', ev => { if (ev.key === 'Enter') submit(); });
      document.getElementById('branch-pin-back').addEventListener('click', renderChoice);
      setTimeout(() => document.getElementById('branch-pin-new')?.focus(), 100);
    };
    renderChoice();
  });
}

// ════════════════════════════════════════════════════════════════════════════
// v24.6 (36-migratsiya) — FILIALLAR O'TKAZMASI: so'rov → jo'natish → yo'lda → sanab qabul
// Egasi qarorlari: tovar qabul qiluvchi omboriga U SANAB QABUL QILGANDA tushadi; Baza → filial, filial → filial,
// filial → Baza (qaytarish); so'rov qisman bajarilsa qolgani ochiq; Baza foydasi — filial sotganda.
// Ombor amallari serverda (branch-transfer → branch_transfer_op) BITTA tranzaksiyada. 36 qo'llanmagan bo'lsa —
// avvalgi oynalar (openSendTo729 / openRequestFromBaza) ochiladi.
// ════════════════════════════════════════════════════════════════════════════
const FR = { list: [], tab: 'in', pending: false, loaded: false, form: null, income: null };
const FR_ST = { open: ['Ochiq', 'sky'], done: ['Bajarildi', 'emerald'], closed: ['Yopilgan', 'text-muted'] };
const FR_SH = { transit: ['Yoʻlda', 'purple'], received: ['Qabul qilindi', 'emerald'], diff: ['Farq — hal qilinmagan', 'red'], resolved: ['Hal qilindi', 'amber'] };
const FR_KIND = { request: 'Soʻrov', send: 'Yuborish', return: 'Qaytarish' };
const frN = v => (Math.round((+v || 0) * 1000) / 1000).toLocaleString('en-US').replace(/,/g, ' ');
const frRoute = t => `${esc(branchName(t.from))} → ${esc(branchName(t.to))}`;
const frActive = t => t.status === 'open' || (t.shipments || []).some(s => s.status === 'transit' || s.status === 'diff');
function frProd(pid, it) { const p = S.products.find(x => x.id === +pid); return { name: (p && p.name) || (it && it.name) || ('#' + pid), sku: (p && p.sku) || (it && it.sku) || '' }; }
function frStockIn(filial, pid) {   // boshqa filial qoldig'i — faqat ma'lumot yuklangan bo'lsa (admin)
  const L = filial === S.branch ? S : (S._store && S._store[filial]);
  if (!L || !Array.isArray(L.batches)) return null;
  return L.batches.filter(b => b.pid === +pid && b.status !== 'empty' && b.status !== 'transit' && b.status !== 'deleted').reduce((s, b) => s + (b.qty - b.sold), 0);
}
function frSold30(pid) {
  const from = new Date(Date.now() - 30 * 864e5).toISOString().slice(0, 10);
  return (S.sales || []).filter(s => s.date >= from && !s.isFilialTransfer).reduce((t, s) => t + (s.items || []).filter(i => i.pid === +pid).reduce((a, i) => a + (+i.qty || 0), 0), 0);
}
async function frFetch(kind, payload) {
  const r = await authFetch('/.netlify/functions/branch-transfer', { method: 'POST', body: JSON.stringify({ kind, payload: payload || {}, filial: S.branch }) });
  const d = await r.json().catch(() => ({}));
  if (r.status === 409 && d.trPending) { FR.pending = true; return null; }
  if (!r.ok) throw new Error(d.error || 'Server xatosi');
  return d;
}
async function frLoad() {
  const d = await frFetch('list'); if (!d) return false;
  FR.list = Array.isArray(d.transfers) ? d.transfers : []; FR.loaded = true; FR.pending = false;
  return true;
}
// Yozish amali: kalit bilan idempotent (tarmoq uzilsa — qayta urinish ikki marta yozmaydi); javobdagi partiyalar qo'llanadi
async function frOp(kind, payload) {
  const d = await fwLedgerCall('branch-transfer', { kind, payload });
  if (d && d.transfer) { const i = FR.list.findIndex(t => t.id === d.transfer.id); if (i >= 0) FR.list[i] = d.transfer; else FR.list.unshift(d.transfer); }
  try { save(); } catch (_) {}
  if (S.page === 'ombor') try { pgOmbor(); } catch (_) {}
  return d;
}
async function openTransfers(tab) {
  if (typeof fwLedgerRemote === 'function' && !fwLedgerRemote()) { return S.branch === 'baza' ? openSendTo729() : openRequestFromBaza(); }
  if (tab) FR.tab = tab;
  openSheet({ ic: 'swap', c: 'sky', title: 'Filiallar oʻtkazmasi', sub: 'Soʻrov → joʻnatish → yoʻlda → sanab qabul', body: '<div class="fr-empty">Yuklanmoqda…</div>' });
  try { if (!(await frLoad())) { closeSheet(); toast("Oʻtkazmalar hali yoqilmagan (36-migratsiya) — avvalgi oyna ochildi", 'warning'); return S.branch === 'baza' ? openSendTo729() : openRequestFromBaza(); } }
  catch (e) { toast('⛔ ' + e.message, 'error'); closeSheet(); return; }
  if (S.branch === 'baza' && (typeof hasPerm !== 'function' || CURRENT_USER?.kind !== 'staff')) {
    const now = new Date(), from = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().slice(0, 10);
    frFetch('income', { from, to: td() }).then(d => { FR.income = d && d.income; if (document.querySelector('.fr-hub')) frHub(); }).catch(() => {});
  }
  frHub();
}
function frHub() {
  const me = S.branch, L = FR.list;
  const inL = L.filter(t => t.to === me && frActive(t)), outL = L.filter(t => t.from === me && frActive(t)), doneL = L.filter(t => !frActive(t));
  const transit = L.filter(t => t.to === me).reduce((n, t) => n + (t.shipments || []).filter(s => s.status === 'transit').length, 0);
  const reqs = L.filter(t => t.from === me && t.kind === 'request' && t.status === 'open').length;
  const diffs = L.reduce((n, t) => n + (t.from === me || t.to === me ? (t.shipments || []).filter(s => s.status === 'diff').length : 0), 0);
  const list = FR.tab === 'out' ? outL : FR.tab === 'done' ? doneL : inL;
  const inc = FR.income ? Object.entries(FR.income) : [];
  const incT = inc.reduce((a, [, v]) => ({ r: a.r + (+v.revenueUsd || 0), p: a.p + (+v.profitUsd || 0) }), { r: 0, p: 0 });
  const tab = (k, l, n) => `<button class="${FR.tab === k ? 'on' : ''}" onclick="FR.tab='${k}';frHub()">${l}${n != null ? ` (${n})` : ''}</button>`;
  openSheet({ ic: 'swap', c: 'sky', title: 'Filiallar oʻtkazmasi', sub: 'Soʻrov → joʻnatish → yoʻlda → sanab qabul', body: `<div class="fr-hub">
    <div class="fr-sum"><div class="fr-sum-h"><b>${esc(branchName(me))} — oʻtkazmalar</b><span class="fr-chip" style="--c:var(--sky)">Shu filial</span></div>
      <div class="fr-sum-3"><button onclick="FR.tab='in';frHub()"><b>${transit}</b><span>Yoʻlda</span></button><button onclick="FR.tab='out';frHub()"><b>${reqs}</b><span>Soʻrovlar (menga)</span></button><button onclick="FR.tab='${diffs ? (L.some(t => t.from === me && (t.shipments || []).some(s => s.status === 'diff')) ? 'out' : 'in') : FR.tab}';frHub()"><b style="${diffs ? 'color:var(--red)' : ''}">${diffs}</b><span>Farq</span></button></div>
      ${inc.length ? `<div class="fr-inc">Bu oy filiallar sotgan (Bazadan kelgan tovar): <b>${CUR.fmtUsd(incT.r)}</b> · Baza foydasi: <b style="color:var(--emerald)">${CUR.fmtUsd(incT.p)}</b></div>` : ''}</div>
    <div class="fr-acts"><button class="fr-act" style="--c:var(--blue)" onclick="frRequestForm()">${ICONF.inbox}<span>Tovar soʻrash</span></button>
      <button class="fr-act" style="--c:var(--emerald)" onclick="frShipForm(null)">${ICONF.send}<span>${me === 'baza' ? 'Filialga yuborish' : 'Yuborish / qaytarish'}</span></button></div>
    <div class="bs-seg fr-tabs">${tab('in', 'Menga', inL.length)}${tab('out', 'Mendan', outL.length)}${tab('done', 'Yopilgan')}</div>
    ${list.length ? list.map(frCardHtml).join('') : `<div class="fr-empty">${FR.tab === 'in' ? 'Sizga keladigan ochiq oʻtkazma yoʻq' : FR.tab === 'out' ? 'Sizdan ketadigan ochiq oʻtkazma yoʻq' : 'Yopilgan oʻtkazma yoʻq'}</div>`}
  </div>` });
}
function frCardHtml(t) {
  const st = FR_ST[t.status] || FR_ST.open, req = (t.items || []).reduce((a, i) => a + (+i.qty || 0), 0), sh = (t.items || []).reduce((a, i) => a + (+i.shipped || 0), 0);
  const tr = (t.shipments || []).filter(s => s.status === 'transit').length, df = (t.shipments || []).filter(s => s.status === 'diff').length;
  return `<button class="fr-card" onclick="frDetail(${+t.id})"><div class="fr-card-h"><b>${esc(t.no)}</b><span>${frRoute(t)}</span><span class="fr-chip" style="--c:var(--${st[1]})">${st[0]}</span></div>
    <div class="fr-card-s">${FR_KIND[t.kind] || ''} · ${fmtD(String(t.createdAt || '').slice(0, 10))} · ${esc(t.createdBy || '')}${t.priority === 'urgent' ? ' · <b style="color:var(--red)">Shoshilinch</b>' : ''}</div>
    <div class="fr-card-s">${frN(req)} soʻraldi · ${frN(sh)} joʻnatildi${tr ? ` · <b style="color:var(--purple)">${tr} ta yoʻlda</b>` : ''}${df ? ` · <b style="color:var(--red)">${df} ta farq</b>` : ''}</div></button>`;
}
function frDetail(id) {
  const t = FR.list.find(x => x.id === +id); if (!t) return;
  const me = S.branch, st = FR_ST[t.status] || FR_ST.open, ships = t.shipments || [];
  const recvOf = pid => ships.filter(s => s.status !== 'transit').reduce((a, s) => a + (s.lines || []).filter(l => +l.pid === +pid).reduce((b, l) => b + (+l.recv || 0), 0), 0);
  const rows = (t.items || []).map(it => { const pr = frProd(it.pid, it), rem = t.status === 'open' ? Math.max(0, (+it.qty || 0) - (+it.shipped || 0)) : 0;
    return `<tr><td><b>${esc(pr.sku ? pr.sku + ' ' : '')}${esc(pr.name)}</b></td><td>${frN(it.qty)}</td><td>${frN(it.shipped)}</td><td>${frN(recvOf(it.pid))}</td><td style="color:var(--sky);font-weight:700">${rem ? frN(rem) : '—'}</td></tr>`; }).join('');
  const shipHtml = ships.slice().reverse().map(s => {
    const ss = FR_SH[s.status] || FR_SH.transit;
    const byPid = {}; (s.lines || []).forEach(l => { const k = +l.pid; byPid[k] = byPid[k] || { q: 0, r: 0 }; byPid[k].q += +l.qty || 0; byPid[k].r += +l.recv || 0; });
    const lines = Object.entries(byPid).map(([pid, v]) => `<div class="fr-sl"><span>${esc(frProd(pid).name)}</span><b>${frN(v.q)}${s.status !== 'transit' ? ` → <em style="color:var(--${v.r < v.q ? 'red' : 'emerald'})">${frN(v.r)}</em>` : ''}</b></div>`).join('');
    const acts = [];
    if (s.status === 'transit' && t.to === me) acts.push(`<button class="fw-btn ok" onclick="frReceiveForm(${+t.id},${+s.id})">${ICONF.check}<span>Sanab qabul qilish</span></button>`);
    if (s.status === 'diff' && t.from === me) acts.push(`<button class="fw-btn ok" onclick="frResolve(${+t.id},${+s.id},'returned')">Omborga qaytdi</button><button class="fw-btn danger" onclick="frResolve(${+t.id},${+s.id},'loss')">Yoʻqotish</button>`);
    if (s.status === 'diff' && t.to === me) acts.push(`<span class="fr-wait">Farq joʻnatuvchiga yuborildi — u hal qiladi</span>`);
    acts.push(`<button class="fw-btn" onclick="frPrint(${+t.id},${+s.id})">${ICONF.receipt}<span>Nakladnoy · PDF</span></button>`);
    return `<div class="fr-ship"><div class="fr-ship-h"><b>${+s.seq}-joʻnatma</b><span class="fr-chip" style="--c:var(--${ss[1]})">${ss[0]}</span><time>${fmtD(String(s.shippedAt || '').slice(0, 10))} · ${esc(s.shippedBy || '')}</time></div>
      ${lines}${s.recvNote ? `<div class="fr-note">Qabul izohi: ${esc(s.recvNote)}</div>` : ''}
      ${s.resolution ? `<div class="fr-note">Yechim: ${s.resolution === 'loss' ? `yoʻqotish — <b>${CUR.fmtUsd(+s.lossUsd || 0)}</b>` : 'omborga qaytdi'}</div>` : ''}
      <div class="fr-ship-a">${acts.join('')}</div></div>`; }).join('');
  const foot = [];
  if (t.status === 'open' && t.from === me) foot.push(`<button class="bs-btn" onclick="frShipForm(${+t.id})">${ICONF.truck} Joʻnatish${ships.length ? ' (qolganini)' : ''}</button>`);
  if (t.status === 'open' && (t.from === me || t.to === me)) foot.push(`<button class="bs-btn ghost" onclick="frClose(${+t.id})">Qolganini yopish</button>`);
  openSheet({ ic: 'swap', c: 'sky', title: `${esc(t.no)} — ${frRoute(t)}`, body: `<div class="fr-det">
    <div class="fr-meta"><span class="fr-chip" style="--c:var(--${st[1]})">${st[0]}</span> ${FR_KIND[t.kind] || ''} · ${fmtD(String(t.createdAt || '').slice(0, 10))} · ${esc(t.createdBy || '')}${t.priority === 'urgent' ? ' · <b style="color:var(--red)">Shoshilinch</b>' : ''}${t.needBy ? ` · ${fmtD(String(t.needBy).slice(0, 10))} gacha` : ''}</div>
    ${t.note ? `<div class="fr-note">${esc(t.note)}</div>` : ''}${t.closeNote ? `<div class="fr-note">Yopildi: ${esc(t.closeNote)}</div>` : ''}
    <div class="table-wrap"><table class="fr-tbl"><thead><tr><th>Mahsulot</th><th>Soʻralgan</th><th>Joʻnatilgan</th><th>Qabul</th><th>Qolgan</th></tr></thead><tbody>${rows}</tbody></table></div>
    <div class="st-eyebrow" style="margin-top:12px">Joʻnatmalar</div>${shipHtml || '<div class="fr-empty">Hali joʻnatilmagan</div>'}
    <button class="fr-back" onclick="frHub()">← Barcha oʻtkazmalar</button></div>`, foot: foot.length ? `<div class="fr-foot">${foot.join('')}</div>` : '' });
}
// ── Tovar so'rash (qabul qiluvchi) ──
function frRequestForm() {
  const others = Object.keys(BRANCHES).filter(k => k !== S.branch);
  if (!others.length) { toast('Boshqa filial yoʻq', 'error'); return; }
  FR.form = { type: 'req', from: others.includes('baza') ? 'baza' : others[0], items: [], prio: 'normal', needBy: '', note: '' };
  frFormRender();
}
// ── Jo'natish (jo'natuvchi): so'rov bo'yicha (qolgani) yoki to'g'ridan-to'g'ri ──
function frShipForm(tid, toKey) {
  const t = tid ? FR.list.find(x => x.id === +tid) : null;
  const others = Object.keys(BRANCHES).filter(k => k !== S.branch);
  if (!t && !others.length) { toast('Boshqa filial yoʻq', 'error'); return; }
  const toK = t ? t.to : toKey && toKey !== S.branch ? toKey : (S.branch === 'baza' ? others.find(k => k !== 'baza') || others[0] : 'baza');
  FR.form = { type: 'ship', tid: t ? t.id : null, to: toK, note: '',
    mode: S.branch === 'baza' && toK !== 'baza' && typeof flIsOwn === 'function' && flIsOwn(toK) ? 'debt' : 'consign',   // v25: mustaqil — asosan «Qarzga»
    items: t ? (t.items || []).map(it => ({ pid: +it.pid, qty: Math.max(0, Math.min((+it.qty || 0) - (+it.shipped || 0), getStock(+it.pid))), max: Math.max(0, (+it.qty || 0) - (+it.shipped || 0)) })).filter(i => i.max > 0) : [] };
  frFormRender();
}
// v25: Bazadan filialga narx — «Qarzga»: optom narx; «Sotish uchun»: optom − filial xizmat foizi (mahsulotda alohida bo'lsa — o'shasi)
function frBranchPrice(pid, to, mode) {
  const p = S.products.find(x => x.id === pid) || {}, opt = optPrice(p, getCostFIFO(pid));
  const pct = mode === 'debt' ? 0 : (typeof flItemPct === 'function' ? flItemPct(to, pid) : 0);
  return Math.round(opt * (1 - pct / 100) * 10000) / 10000;
}
function frFormRender() {
  const f = FR.form; if (!f) return;
  const isReq = f.type === 'req', me = S.branch, src = isReq ? f.from : me;
  const others = Object.keys(BRANCHES).filter(k => k !== me);
  const chips = (cur, on) => `<div class="fr-chips">${others.map(k => `<button class="${k === cur ? 'on' : ''}" onclick="FR.form.${on}='${k}';${on === 'to' ? `FR.form.mode=(S.branch==='baza'&&'${k}'!=='baza'&&flIsOwn('${k}'))?'debt':'consign';` : ''}frFormRender()">${esc(branchName(k))}${on === 'to' && k !== 'baza' && flIsOwn(k) ? ' · mustaqil' : ''}</button>`).join('')}</div>`;
  const rows = f.items.map((it, i) => {
    const pr = frProd(it.pid), srcSt = frStockIn(src, it.pid), mine = isReq ? frStockIn(me, it.pid) : getStock(it.pid);
    const cap = isReq ? 1e7 : Math.min(getStock(it.pid), it.max != null ? it.max : 1e7);
    const price = !isReq && me === 'baza' && f.to !== 'baza' ? frBranchPrice(it.pid, f.to, f.mode) : null;
    return `<div class="fr-it"><div class="fr-it-t"><b>${esc(pr.sku ? pr.sku + ' ' : '')}${esc(pr.name)}</b>
        <small>${isReq ? `${srcSt != null ? `${esc(branchName(src))}da: <b>${frN(srcSt)}</b> · ` : ''}menda: ${frN(mine || 0)} · 30 kunda sotildi: ${frN(frSold30(it.pid))}`
          : `Omborda: <b>${frN(mine)}</b>${it.max != null ? ` · soʻralgan qolgani: ${frN(it.max)}` : ''}${price != null ? ` · ${f.mode === 'debt' ? 'narx' : 'filial narxi (optom − %)'}: ${CUR.fmtUsd(price)}` : ''}`}</small></div>
      <span class="pos-step"><button onclick="frQty(${i},-1)" aria-label="Kamaytirish">−</button><input type="number" inputmode="decimal" min="0" max="${cap}" value="${it.qty}" onchange="frQty(${i},0,this.value)"><button onclick="frQty(${i},1)" aria-label="Koʻpaytirish">+</button></span>
      <button class="fr-x" onclick="FR.form.items.splice(${i},1);frFormRender()" aria-label="Olib tashlash">${ICONF.close}</button></div>`; }).join('');
  const t = f.tid ? FR.list.find(x => x.id === f.tid) : null;
  const body = `<div class="fr-form">
    ${isReq ? `<div class="st-eyebrow">Qayerdan soʻraladi</div>${chips(f.from, 'from')}<p class="bs-note">Soʻrov ${esc(branchName(f.from))}ga keladi. Joʻnatuvchi qisman joʻnatishi mumkin; tovar siz sanab qabul qilganingizda omboringizga tushadi.</p>`
      : t ? `<p class="bs-note">${esc(t.no)} soʻrovi boʻyicha ${esc(branchName(t.to))}ga. Tovar yoʻlga chiqadi — qabul qiluvchi sanab qabul qilganda uning omboriga tushadi.</p>`
      : `<div class="st-eyebrow">Qayerga yuboriladi</div>${chips(f.to, 'to')}<p class="bs-note">${f.to === 'baza' ? 'Bazaga qaytarish.' : 'Tovar yoʻlga chiqadi.'} Qabul qiluvchi sanab qabul qilganda uning omboriga tushadi.</p>`}
    ${!isReq && me === 'baza' && f.to !== 'baza' ? `<div class="st-eyebrow">Hisob turi</div>
      <div class="fr-mode">
        <button class="${f.mode !== 'debt' ? 'on' : ''}" onclick="FR.form.mode='consign';frFormRender()"><b>Sotish uchun</b><small>Qarz — filial <b>sotganda</b>, optom − ${typeof flPct === 'function' ? flPct(f.to) : 0}% xizmat. Sotilmagani qaytariladi.</small></button>
        <button class="${f.mode === 'debt' ? 'on' : ''}" onclick="FR.form.mode='debt';frFormRender()"><b>Qarzga</b><small>Qarz — filial <b>qabul qilganda</b>, optom narxda. Tovar filialniki.</small></button>
      </div>` : ''}
    ${t ? '' : `<div class="st-eyebrow">Mahsulotlar</div><div class="kr-search">${ICONF.search}<input type="search" id="fr-q" placeholder="Nomi, kodi yoki shtrix-kod" autocomplete="off" oninput="frSearch(this.value)"></div><div id="fr-res" class="fr-res"></div>`}
    ${rows || `<div class="fr-empty">${t ? 'Joʻnatiladigan qolgan mahsulot yoʻq' : 'Mahsulot qoʻshing'}</div>`}
    ${isReq ? `<div class="fr-2"><div><div class="st-eyebrow">Muhimlik</div><div class="bs-seg"><button class="${f.prio === 'normal' ? 'on' : ''}" onclick="FR.form.prio='normal';frFormRender()">Oddiy</button><button class="${f.prio === 'urgent' ? 'on' : ''}" onclick="FR.form.prio='urgent';frFormRender()">Shoshilinch</button></div></div>
      <div><div class="st-eyebrow">Qachongacha kerak</div><input class="form-control" type="date" value="${esc(f.needBy)}" onchange="FR.form.needBy=this.value"></div></div>` : ''}
    <div class="st-eyebrow">Izoh</div><input class="form-control" id="fr-note" maxlength="500" placeholder="${isReq ? 'Masalan: aksiya uchun' : 'Ixtiyoriy'}" value="${esc(f.note)}" oninput="FR.form.note=this.value">
  </div>`;
  openSheet({ ic: isReq ? 'inbox' : 'send', c: isReq ? 'blue' : 'emerald', title: isReq ? 'Tovar soʻrash' : (t ? `${esc(t.no)} — joʻnatish` : 'Yuborish'), body,
    foot: `<div class="fr-foot"><button class="bs-btn ghost" onclick="${t ? `frDetail(${+t.id})` : 'frHub()'}">Bekor</button><button class="bs-btn" id="fr-submit" onclick="frSubmit()">${isReq ? `${ICONF.send} Soʻrov yuborish` : `${ICONF.truck} Joʻnatish`}</button></div>` });
}
function frSearch(q) {
  const f = FR.form, box = document.getElementById('fr-res'); if (!f || !box) return;
  q = String(q || '').trim(); if (!q) { box.innerHTML = ''; return; }
  const base = S.products.filter(p => !p.archived && !p.directSale && (f.type === 'req' || getStock(p.id) > 0));
  const res = productSearchMatch(base, q).slice(0, 8);
  box.innerHTML = res.length ? res.map(p => `<button onclick="frAdd(${p.id})"><b>${esc(p.name)}</b><small>${esc(p.sku || '')}${f.type === 'ship' ? ` · omborda ${frN(getStock(p.id))}` : ''}</small></button>`).join('') : '<div class="fr-empty">Topilmadi</div>';
}
function frAdd(pid) {
  const f = FR.form; if (!f) return;
  const it = f.items.find(i => i.pid === pid);
  if (it) it.qty = f.type === 'ship' ? Math.min(getStock(pid), it.qty + 1) : it.qty + 1;
  else f.items.push({ pid, qty: 1 });
  frFormRender();
  setTimeout(() => document.getElementById('fr-q')?.focus(), 30);
}
function frQty(i, d, v) {
  const f = FR.form, it = f && f.items[i]; if (!it) return;
  let q = v != null ? parseAmt(v) : (+it.qty || 0) + d;
  const p = S.products.find(x => x.id === it.pid);
  if ((p?.unit || 'dona') === 'dona') q = Math.round(q);
  q = Math.max(0, q);
  if (f.type === 'ship') q = Math.min(q, getStock(it.pid), it.max != null ? it.max : Infinity);
  it.qty = q; frFormRender();
}
async function frSubmit() {
  const f = FR.form; if (!f) return;
  const items = f.items.filter(i => +i.qty > 0);
  if (!items.length) { toast('Mahsulot va miqdorni kiriting', 'error'); return; }
  const btn = document.getElementById('fr-submit'); if (btn) btn.disabled = true;
  try {
    let d;
    if (f.type === 'req') {
      d = await frOp('tr_request', { from: f.from, priority: f.prio, needBy: f.needBy || null, note: f.note || null,
        items: items.map(i => { const pr = frProd(i.pid); return { pid: i.pid, qty: +i.qty, sku: pr.sku, name: pr.name }; }) });
      auditLog(`Tovar soʻraldi: ${d.transfer.no} — ${branchName(f.from)}dan, ${items.length} xil`);
      toast(`📨 ${d.transfer.no} soʻrovi ${branchName(f.from)}ga yuborildi`);
    } else {
      for (const i of items) if (+i.qty > getStock(i.pid) + 1e-9) { toast(`Omborda yetarli emas: ${frProd(i.pid).name}`, 'error'); if (btn) btn.disabled = false; return; }
      const priced = S.branch === 'baza' && f.to !== 'baza';
      d = await frOp('tr_ship', { ...(f.tid ? { transferId: f.tid } : { to: f.to }), note: f.note || null,
        items: items.map(i => { const p = S.products.find(x => x.id === i.pid) || {}; const pr = frProd(i.pid);
          return { pid: i.pid, qty: +i.qty, sku: pr.sku, name: pr.name, ...(priced ? { priceUsd: frBranchPrice(i.pid, f.to, f.mode) } : {}) }; }),
        ...(priced ? { mode: f.mode === 'debt' ? 'debt' : 'consign' } : {}) });
      auditLog(`Oʻtkazma joʻnatildi: ${d.transfer.no} — ${branchName(d.transfer.from)} → ${branchName(d.transfer.to)}, ${items.length} xil${priced ? (f.mode === 'debt' ? ' (qarzga)' : ' (sotish uchun)') : ''}`);
      toast(`🚚 ${d.transfer.no}: yoʻlga chiqdi — ${branchName(d.transfer.to)} sanab qabul qiladi`);
    }
    FR.form = null; frDetail(d.transfer.id);
  } catch (e) { toast('⛔ ' + e.message, 'error'); if (btn) btn.disabled = false; }
}
// ── Sanab qabul (qabul qiluvchi) ──
function frReceiveForm(tid, sid) {
  const t = FR.list.find(x => x.id === +tid), s = t && (t.shipments || []).find(x => x.id === +sid); if (!s) return;
  const byPid = {}; (s.lines || []).forEach(l => { byPid[+l.pid] = (byPid[+l.pid] || 0) + (+l.qty || 0); });
  const rows = Object.entries(byPid).map(([pid, q]) => `<div class="fr-it fr-rc"><div class="fr-it-t"><b>${esc(frProd(pid).name)}</b><small>Joʻnatilgan: <b>${frN(q)}</b></small></div>
    <input class="form-control fr-rq" type="number" inputmode="decimal" min="0" max="${q}" data-pid="${pid}" data-q="${q}" value="${q}" oninput="frRecvCheck()"></div>`).join('');
  openSheet({ ic: 'check', c: 'blue', title: `${esc(t.no)} — sanab qabul qilish`, body: `<div class="fr-form">
    <p class="bs-note">${esc(branchName(t.from))}dan ${+s.seq}-joʻnatma. Haqiqatda kelgan sonni kiriting — omboringizga aynan shu son tushadi. Kam boʻlsa — sababini yozing.</p>
    ${rows}<div id="fr-rdiff"></div>
    <div class="st-eyebrow">Izoh (kam kelgan boʻlsa — majburiy)</div><input class="form-control" id="fr-rnote" maxlength="500" placeholder="Masalan: bittasi singan">
  </div>`, foot: `<div class="fr-foot"><button class="bs-btn ghost" onclick="frDetail(${+t.id})">Bekor</button><button class="bs-btn" id="fr-rsub" onclick="frReceiveSubmit(${+t.id},${+s.id})">${ICONF.check} Qabul qilish</button></div>` });
  frRecvCheck();
}
function frRecvCheck() {
  let short = 0, bad = false;
  document.querySelectorAll('.fr-rq').forEach(el => { const v = parseAmt(el.value), q = +el.dataset.q; if (!(v >= 0) || v > q) bad = true; else short += q - v; });
  const box = document.getElementById('fr-rdiff'); if (!box) return;
  box.innerHTML = bad ? `<div class="fr-warn">${ICONF.warning}<span>Kelgan son 0 dan kam yoki joʻnatilganidan koʻp boʻlishi mumkin emas.</span></div>`
    : short > 0 ? `<div class="fr-warn">${ICONF.warning}<span><b>${frN(short)} dona kam.</b> Farq joʻnatuvchiga yuboriladi — u «omborga qaytdi» yoki «yoʻqotish» deb hal qiladi.</span></div>` : '';
}
async function frReceiveSubmit(tid, sid) {
  const items = []; let short = 0;
  for (const el of document.querySelectorAll('.fr-rq')) { const v = parseAmt(el.value), q = +el.dataset.q; if (!(v >= 0) || v > q) { toast('Kelgan sonni toʻgʻri kiriting', 'error'); return; } items.push({ pid: +el.dataset.pid, qty: v }); short += q - v; }
  const note = (document.getElementById('fr-rnote')?.value || '').trim();
  if (short > 0 && note.length < 2) { toast('Kam kelgan boʻlsa — sababini izohda yozing', 'error'); document.getElementById('fr-rnote')?.focus(); return; }
  const btn = document.getElementById('fr-rsub'); if (btn) btn.disabled = true;
  try {
    const d = await frOp('tr_receive', { shipmentId: sid, items, note: note || null });
    auditLog(`Oʻtkazma qabul qilindi: ${d.transfer.no}${short > 0 ? ` — ${frN(short)} dona kam (${note})` : ''}`);
    toast(short > 0 ? `✅ Qabul qilindi — ${frN(short)} dona farq joʻnatuvchiga yuborildi` : '✅ Qabul qilindi — omboringizga tushdi');
    frDetail(tid);
  } catch (e) { toast('⛔ ' + e.message, 'error'); if (btn) btn.disabled = false; }
}
// ── Farq yechimi (jo'natuvchi) ──
async function frResolve(tid, sid, res) {
  const t = FR.list.find(x => x.id === +tid), s = t && (t.shipments || []).find(x => x.id === +sid); if (!s) return;
  const short = (s.lines || []).reduce((a, l) => a + Math.max(0, (+l.qty || 0) - (+l.recv || 0)), 0);
  const loss = (s.lines || []).reduce((a, l) => a + Math.max(0, (+l.qty || 0) - (+l.recv || 0)) * (+l.srcCost || 0), 0);
  if (!confirm(res === 'loss' ? `${frN(short)} dona kam — YOʻQOTISH deb yozilsinmi? (tannarxda ${CUR.fmtUsd(loss)})\nQabul izohi: ${s.recvNote || '—'}`
    : `${frN(short)} dona kam — OMBORINGIZGA QAYTDI deb yozilsinmi? (tovar sizning omboringizga qaytariladi)`)) return;
  try {
    const d = await frOp('tr_resolve', { shipmentId: sid, resolution: res });
    auditLog(`Oʻtkazma farqi hal qilindi: ${d.transfer.no} — ${res === 'loss' ? `yoʻqotish ${CUR.fmtUsd(+d.lossUsd || 0)}` : 'omborga qaytdi'}`);
    toast(res === 'loss' ? `Yoʻqotish yozildi: ${CUR.fmtUsd(+d.lossUsd || 0)}` : '✅ Omborga qaytarildi');
    frDetail(tid);
  } catch (e) { toast('⛔ ' + e.message, 'error'); }
}
async function frClose(tid) {
  const t = FR.list.find(x => x.id === +tid); if (!t) return;
  const note = prompt(`${t.no}: joʻnatilmagan qolgan qism yopilsinmi? Sababini yozing (ixtiyoriy):`, '');
  if (note === null) return;
  try { const d = await frOp('tr_close', { transferId: tid, note: note || null }); auditLog(`Oʻtkazma yopildi: ${d.transfer.no}`); toast('Qolgan qism yopildi'); frDetail(tid); }
  catch (e) { toast('⛔ ' + e.message, 'error'); }
}
// ── Nakladnoy (jo'natma hujjati) ──
function frPrint(tid, sid) {
  const t = FR.list.find(x => x.id === +tid), s = t && (t.shipments || []).find(x => x.id === +sid); if (!s) return;
  const byPid = {}; (s.lines || []).forEach(l => { const k = +l.pid; byPid[k] = byPid[k] || { q: 0, r: 0, v: 0 }; byPid[k].q += +l.qty || 0; byPid[k].r += +l.recv || 0; byPid[k].v += (+l.qty || 0) * (+l.cost || 0); });
  const done = s.status !== 'transit';
  const w = fwDocWin();
  w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Nakladnoy ${esc(t.no)}-${+s.seq}</title>
  <style>body{font-family:Arial,sans-serif;font-size:13px;margin:30px}.row{display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid #eee}
  table{width:100%;border-collapse:collapse;margin:14px 0}th{background:#1a2236;color:#fff;padding:7px;text-align:left;font-size:12px}td{padding:6px 7px;border-bottom:1px solid #eee;font-size:12px}
  .sign{margin-top:40px;display:flex;justify-content:space-between}.sl{border-top:1px solid #333;width:200px;text-align:center;padding-top:4px;font-size:11px}</style></head><body>
  <h2>Yuk xati (nakladnoy) — ${esc(t.no)}, ${+s.seq}-joʻnatma</h2>
  <div class="row"><span>Joʻnatuvchi:</span><b>${esc(branchName(t.from))}</b></div><div class="row"><span>Qabul qiluvchi:</span><b>${esc(branchName(t.to))}</b></div>
  <div class="row"><span>Joʻnatildi:</span><span>${fmtD(String(s.shippedAt || '').slice(0, 10))} · ${esc(s.shippedBy || '')}</span></div>
  ${done ? `<div class="row"><span>Qabul qilindi:</span><span>${fmtD(String(s.receivedAt || '').slice(0, 10))} · ${esc(s.receivedBy || '')}</span></div>` : ''}
  <table><thead><tr><th>#</th><th>Kod</th><th>Mahsulot</th><th>Joʻnatildi</th>${done ? '<th>Qabul</th>' : ''}<th>Qiymati</th></tr></thead><tbody>
  ${Object.entries(byPid).map(([pid, v], i) => { const pr = frProd(pid); return `<tr><td>${i + 1}</td><td>${esc(pr.sku)}</td><td>${esc(pr.name)}</td><td>${frN(v.q)}</td>${done ? `<td>${frN(v.r)}</td>` : ''}<td>${CUR.fmtUsd(v.v)}</td></tr>`; }).join('')}
  </tbody></table>
  ${s.recvNote ? `<p>Qabul izohi: ${esc(s.recvNote)}</p>` : ''}${s.resolution ? `<p>Farq yechimi: ${s.resolution === 'loss' ? 'yoʻqotish — ' + CUR.fmtUsd(+s.lossUsd || 0) : 'omborga qaytdi'}</p>` : ''}
  <div class="sign"><div class="sl">Topshirdi: ___________</div><div class="sl">Qabul qildi: ___________</div></div></body></html>`);
  w.document.close();
}


// ════════════════════════════════════════════════════════════════════════════
// v24.6 (egasi talabi) — INVESTOR (HAMKOR) HISOBOTI: oylik / yillik ko'chirma — PDF va investorning Telegramiga.
// Telegram bot foydalanuvchiga @username yoki telefon raqami bo'yicha yoza olmaydi: investorga havola yuboriladi
// (t.me/<bot>?start=<kod>), u «Start» bosadi — «Tekshirish» chat ID ni topib saqlaydi. Keyin hisobot bir tugma bilan.
// ════════════════════════════════════════════════════════════════════════════
const PRT = { pid: null, mode: 'month', ym: '', y: '' };
async function prtTg(action, extra) {
  const r = await authFetch('/.netlify/functions/telegram-file', { method: 'POST', body: JSON.stringify({ action, ...(extra || {}) }) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || j.ok === false) throw new Error(j.error || 'Server xatosi');
  return j;
}
function prtRange(mode, ym, y) {
  if (mode === 'year') return [`${y}-01-01`, `${y}-12-31`, `${y}-yil`];
  const [Y, M] = ym.split('-').map(Number), last = new Date(Y, M, 0).getDate();
  return [`${ym}-01`, `${ym}-${String(last).padStart(2, '0')}`, monthLabel(ym)];
}
// Davr ko'chirmasi: boshlang'ich hisob, kirim, xarajat, foyda ulushi (taqsimot), yakuniy hisob + yozuvlar
function partnerStatement(pid, start, end) {
  const p = brPartner(pid); if (!p) return null;
  const ev = partnerLedger(pid);
  const now = p.invested || 0;
  const after = ev.filter(e => e.date > end).reduce((a, e) => a + e.delta, 0);
  const inP = ev.filter(e => e.date >= start && e.date <= end);
  const closing = now - after, opening = closing - inP.reduce((a, e) => a + e.delta, 0);
  const isDist = e => String(e.desc).startsWith('📊');
  const pers = brPeriods().filter(per => per.end >= start && per.end <= end).map(per => ({ per, row: per.rows.find(r => r.pid === pid) })).filter(x => x.row)
    .sort((a, b) => (a.per.end < b.per.end ? -1 : 1));
  const all = brPartners(), tot = all.reduce((a, x) => a + (x.invested || 0), 0);
  return { p, opening, closing, events: inP, share: tot > 0 ? now / tot * 100 : 0,
    kirim: inP.filter(e => !isDist(e) && e.delta > 0).reduce((a, e) => a + e.delta, 0),
    xarajat: inP.filter(e => !isDist(e) && e.delta < 0).reduce((a, e) => a - e.delta, 0),
    foyda: inP.filter(isDist).reduce((a, e) => a + e.delta, 0), pers };
}
function openPartnerReport(pid, mode) {
  const p = brPartner(pid); if (!p) return;
  if (PRT.pid !== pid) { const d = new Date(); d.setDate(0); PRT.ym = d.toISOString().slice(0, 7); PRT.y = String(new Date().getFullYear()); }
  PRT.pid = pid; if (mode) PRT.mode = mode;
  const [start, end, label] = prtRange(PRT.mode, PRT.ym, PRT.y);
  const st = partnerStatement(pid, start, end);
  const row = (l, v, c) => `<div class="dk-kv"><span>${l}</span><b${c ? ` style="color:var(--${c})"` : ''}>${v}</b></div>`;
  const years = Array.from({ length: 5 }, (_, i) => String(new Date().getFullYear() - i));
  openSheet({ ic: 'receipt', c: 'amber', title: `${esc(p.name)} — hisobot`, sub: `${p.isFounder ? 'Taʼsischi' : 'Investor'} · ulush ${st.share.toFixed(1)}%`, body: `<div class="fr-form">
    <div class="bs-seg"><button class="${PRT.mode === 'month' ? 'on' : ''}" onclick="openPartnerReport(${pid},'month')">Oylik</button><button class="${PRT.mode === 'year' ? 'on' : ''}" onclick="openPartnerReport(${pid},'year')">Yillik</button></div>
    ${PRT.mode === 'month' ? `<input class="form-control" type="month" value="${esc(PRT.ym)}" max="${td().slice(0, 7)}" onchange="PRT.ym=this.value||PRT.ym;openPartnerReport(${pid})">`
      : `<div class="fr-chips">${years.map(y => `<button class="${y === PRT.y ? 'on' : ''}" onclick="PRT.y='${y}';openPartnerReport(${pid})">${y}</button>`).join('')}</div>`}
    <div class="bs-card">${row('Davr', esc(label))}${row('Boshida hisobi', CUR.fmtUsd(st.opening))}${row('Kirim (qoʻshgan)', '+' + CUR.fmtUsd(st.kirim), 'emerald')}
      ${row('Xarajat / olgan', '−' + CUR.fmtUsd(st.xarajat), 'red')}${row('Foyda ulushi (taqsimot)', (st.foyda >= 0 ? '+' : '') + CUR.fmtUsd(st.foyda), st.foyda >= 0 ? 'emerald' : 'red')}
      ${row('Oxirida hisobi', CUR.fmtUsd(st.closing), 'gold')}</div>
    ${p.tgChat ? `<p class="bs-note">Telegram: ${esc(p.tgName || p.tgUser || 'ulangan')} — hisobot shu chatga yuboriladi.</p>` : `<p class="bs-note">Investor Telegramga hali ulanmagan — «Telegramga ulash» bilan havola yuboring.</p>`}
  </div>`, foot: `<div class="fr-foot"><button class="bs-btn ghost" onclick="partnerReportDoc(${pid})">${ICONF.receipt} PDF koʻrish</button>
    ${p.tgChat ? `<button class="bs-btn" onclick="partnerReportSend(${pid},this)">${ICONF.send} Investorga yuborish</button>` : `<button class="bs-btn" onclick="openPartnerTg(${pid})">${ICONF.send} Telegramga ulash</button>`}</div>` });
}
function partnerReportHtml(pid) {
  const [start, end, label] = prtRange(PRT.mode, PRT.ym, PRT.y);
  const st = partnerStatement(pid, start, end), p = st.p, B = fwBrand();
  return { title: `${p.name} — ${PRT.mode === 'year' ? 'yillik' : 'oylik'} hisobot (${label})`, file: `hisobot_${p.name}_${PRT.mode === 'year' ? PRT.y : PRT.ym}`,
    html: `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>${esc(p.name)} — ${esc(label)}</title>
  <style>body{font-family:Arial,sans-serif;font-size:12.5px;margin:28px;color:#111}h2{margin:0 0 4px}.mut{color:#666}.sum{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}
  .sum div{flex:1 1 140px;border:1px solid #e5e7eb;border-radius:10px;padding:8px 10px}.sum b{display:block;font-size:15px;margin-top:2px}
  table{width:100%;border-collapse:collapse;margin-top:10px}th{background:#1a2236;color:#fff;padding:7px;text-align:left;font-size:11.5px}td{padding:6px 7px;border-bottom:1px solid #eee}
  .p{color:#0ea876;font-weight:bold}.m{color:#e23d3d;font-weight:bold}</style></head><body>
  <h2>${esc(B.name)} — investor hisoboti</h2><div class="mut">${esc(p.name)} · ${p.isFounder ? 'Taʼsischi' : 'Investor'} · ${esc(branchName(S.branch))} · ${esc(label)} (${fmtD(start)} – ${fmtD(end)})</div>
  <div class="sum"><div>Boshida hisobi<b>${CUR.fmtUsd(st.opening)}</b></div><div>Kirim<b class="p">+${CUR.fmtUsd(st.kirim)}</b></div><div>Xarajat / olgan<b class="m">−${CUR.fmtUsd(st.xarajat)}</b></div>
    <div>Foyda ulushi<b class="${st.foyda >= 0 ? 'p' : 'm'}">${st.foyda >= 0 ? '+' : ''}${CUR.fmtUsd(st.foyda)}</b></div><div>Oxirida hisobi<b>${CUR.fmtUsd(st.closing)}</b></div><div>Ulush (hozir)<b>${st.share.toFixed(2)}%</b></div></div>
  ${st.pers.length ? `<h3>Foyda taqsimoti</h3><table><thead><tr><th>Oy</th><th>Korxona foydasi</th><th>Ulush</th><th>Sizga</th></tr></thead><tbody>
    ${st.pers.map(({ per, row }) => `<tr><td>${fmtD(per.start)} – ${fmtD(per.end)}</td><td>${CUR.fmtUsd(per.totalProfit || 0)}</td><td>${(+row.pct || 0).toFixed(2)}%</td><td class="${row.foydaPlus >= 0 ? 'p' : 'm'}">${row.foydaPlus >= 0 ? '+' : ''}${CUR.fmtUsd(row.foydaPlus || 0)}</td></tr>`).join('')}</tbody></table>` : ''}
  <h3>Harakatlar</h3><table><thead><tr><th>Sana</th><th>Izoh</th><th>Miqdor</th><th>Hisobi</th></tr></thead><tbody>
  ${st.events.length ? st.events.map(e => `<tr><td>${fmtD(e.date)}</td><td>${esc(String(e.desc).replace(/^[^\wА-Яа-яЁёʻ'"]+\s*/u, ''))}</td><td class="${e.delta >= 0 ? 'p' : 'm'}">${e.delta >= 0 ? '+' : ''}${CUR.fmtUsd(e.delta)}</td><td>${CUR.fmtUsd(e.balance)}</td></tr>`).join('') : '<tr><td colspan="4" style="text-align:center">Bu davrda harakat yoʻq</td></tr>'}
  </tbody></table><p class="mut" style="margin-top:16px">Tuzildi: ${new Date().toLocaleString('uz-UZ')}</p></body></html>` };
}
function partnerReportDoc(pid) {
  const p = brPartner(pid); if (!p) return;
  const d = partnerReportHtml(pid);
  closeSheet();
  fwDoc({ html: d.html, title: d.title, file: d.file, kind: 'a4', botLabel: p.tgChat ? 'Investorga' : null,
    bot: p.tgChat && _cloudEnabled ? async (blob, filename, title) => { await prtTg('partner_doc', { partnerId: p.id, filename, b64: await fwBlobToB64(blob), caption: title }); } : null });
}
async function partnerReportSend(pid, btn) {
  const p = brPartner(pid); if (!p || !p.tgChat) return;
  const d = partnerReportHtml(pid);
  if (btn) btn.disabled = true;
  try {
    const blob = await fwHtmlToPdfBlob(d.html, 'a4', fwDocName(d.file));
    if (blob.size > 4 * 1024 * 1024) throw new Error('Fayl juda katta (4 MB dan ortiq)');
    await prtTg('partner_doc', { partnerId: p.id, filename: d.file, b64: await fwBlobToB64(blob), caption: d.title });
    auditLog(`Investor hisoboti Telegramga yuborildi: ${p.name} — ${d.title}`);
    toast(`✅ ${p.name}ga Telegram orqali yuborildi`);
  } catch (e) { toast('⛔ ' + e.message, 'error'); }
  finally { if (btn) btn.disabled = false; }
}
// ── Telegramga ulash ──
function openPartnerTg(pid) {
  const p = brPartner(pid); if (!p) return;
  if (!_cloudEnabled) { toast('Telegram — faqat bulut (internet) rejimida', 'error'); return; }
  const linked = !!p.tgChat;
  openSheet({ ic: 'send', c: 'sky', title: `${esc(p.name)} — Telegram`, sub: linked ? 'Ulangan' : 'Investor hisobotlari uchun', body: `<div class="fr-form" id="prt-tg">
    ${linked ? `<div class="bs-card"><div class="dk-kv"><span>Ulangan</span><b>${esc(p.tgName || '')} ${esc(p.tgUser || '')}</b></div></div>
      <p class="bs-note">Oylik va yillik hisobotlar shu chatga yuboriladi (Hamkor → Hisobot → «Investorga yuborish»).</p>`
    : `<p class="bs-note">1) Havolani investorga yuboring (Telegram, SMS yoki boshqa). 2) Investor havolani ochib botda <b>«Start»</b> ni bossin. 3) Bu yerda <b>«Tekshirish»</b> ni bosing.<br>Telegram bot @username yoki telefon raqami boʻyicha oʻzi yoza olmaydi — shuning uchun investor bir marta «Start» bosishi kerak.</p>
      <div id="prt-link" class="fr-empty">Havola tayyorlanmoqda…</div>`}
  </div>`, foot: linked ? `<div class="fr-foot"><button class="bs-btn ghost" onclick="partnerTgUnlink(${pid})">Uzish</button><button class="bs-btn" onclick="openPartnerReport(${pid})">${ICONF.receipt} Hisobot</button></div>`
    : `<div class="fr-foot"><button class="bs-btn" id="prt-check" onclick="partnerTgCheck(${pid},this)">${ICONF.check} Tekshirish</button></div>` });
  if (!linked) partnerTgLink(pid);
}
async function partnerTgLink(pid) {
  const p = brPartner(pid), box = document.getElementById('prt-link'); if (!p || !box) return;
  try {
    if (!/^inv[A-Za-z0-9]{8,24}$/.test(String(p.tgCode || ''))) {
      const a = new Uint8Array(9); crypto.getRandomValues(a);
      p.tgCode = 'inv' + Array.from(a, x => 'abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789'[x % 56]).join('');
      p.updatedAt = Date.now(); save();
    }
    const { bot } = await prtTg('tg_link');
    const url = `https://t.me/${bot}?start=${p.tgCode}`;
    const text = `${fwBrand().name}: investor hisobotlarini Telegramda olish uchun havolani oching va «Start» ni bosing`;
    box.className = ''; box.innerHTML = `<div class="bs-card"><code style="word-break:break-all">${esc(url)}</code></div>
      <div class="fr-acts" style="margin-top:8px"><a class="fr-act" style="--c:var(--sky);text-decoration:none" target="_blank" rel="noopener" href="https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(text)}">${ICONF.send}<span>Telegram orqali yuborish</span></a>
      <button class="fr-act" style="--c:var(--emerald)" onclick="navigator.clipboard&&navigator.clipboard.writeText('${escJsAttr(url)}').then(()=>toast('Nusxalandi'))">${ICONF.receipt}<span>Nusxalash</span></button></div>`;
  } catch (e) { box.textContent = '⛔ ' + e.message; }
}
async function partnerTgCheck(pid, btn) {
  const p = brPartner(pid); if (!p || !p.tgCode) return;
  if (btn) btn.disabled = true;
  try {
    const r = await prtTg('tg_link_check', { code: p.tgCode });
    if (!r.found) { toast('Hali «Start» bosilmagan — investor havolani ochib «Start» ni bossin', 'warning'); return; }
    Object.assign(p, { tgChat: r.chatId, tgName: r.name || '', tgUser: r.user || '', updatedAt: Date.now() }); delete p.tgCode;
    save(); auditLog(`Hamkor Telegramga ulandi: ${p.name} (${r.name || ''} ${r.user || ''})`);
    toast(`✅ ${p.name} Telegramga ulandi`); openPartnerTg(pid); if (S.page === 'hamkorlar') pgHamkorlar();
  } catch (e) { toast('⛔ ' + e.message, 'error'); }
  finally { if (btn) btn.disabled = false; }
}
function partnerTgUnlink(pid) {
  const p = brPartner(pid); if (!p) return;
  if (!confirm(`${p.name}: Telegram ulanishi uzilsinmi? Hisobotlar endi yuborilmaydi.`)) return;
  delete p.tgChat; delete p.tgName; delete p.tgUser; p.updatedAt = Date.now();
  save(); auditLog(`Hamkor Telegramdan uzildi: ${p.name}`); closeSheet(); if (S.page === 'hamkorlar') pgHamkorlar();
}

// Kirish oynasi pastidagi «administratorga murojaat» kontakti — js/brand.js (FW_BRAND.contactTelegram / contactPhone).
// Ikkalasi ham bo'sh bo'lsa, blok umuman chiqmaydi (boshqa firmaning kontakti qolib ketmasin).
function _ulContactHtml() {
  const b = (typeof window !== 'undefined' && window.FW_BRAND) || {};
  const tg = String(b.contactTelegram || '').trim().replace(/^@/, '');
  const ph = String(b.contactPhone || '').trim();
  const links = [];
  if (/^[A-Za-z0-9_]{3,32}$/.test(tg)) links.push(`<a href="https://t.me/${tg}" target="_blank" rel="noopener" style="color:#B8700C;text-decoration:none;font-weight:700">@${tg}</a>`);
  const tel = ph.replace(/[^0-9+]/g, '');
  if (tel.length >= 7) links.push(`<a href="tel:${tel}" style="color:#B8700C;text-decoration:none;font-weight:700">${esc(ph)}</a>`);
  if (!links.length) return '';
  return `<div style="margin-top:10px;padding-top:12px;border-top:1px solid #eef0f4;font-size:11.5px;color:#8b95a5;line-height:1.7">
            Telegram ulanmagan boʻlsa —<br>administratorga murojaat qiling<br>
            ${links.join('&nbsp;·&nbsp;')}
          </div>`;
}
